/* =========================================================
   Forecast：業務機會追蹤
   - Stage 1~5
   - 狀態：進行中 / Win / Lost
   - 最新進度自動帶日期
   - 完整進度歷史存於 forecasts/{id}/progress
   - 不要求預計成交日期，也不直接異動庫存
   ========================================================= */
let forecastCache = [];
let forecastCursor = null;
let forecastHasMore = true;
// 全系統寫入按鍵共用狀態：立即顯示處理中、防止重複點擊，完成或失敗後一致恢復。
function productOperationErrorMessage(action, err) {
    const code = String(err?.code || '').replace(/^firestore\//, '');
    if (code === 'permission-denied') return `${action}失敗：目前帳號沒有權限。請聯絡管理員確認。`;
    if (code === 'unauthenticated') return `${action}失敗：登入已失效。請重新登入後再試。`;
    if (['unavailable', 'deadline-exceeded', 'resource-exhausted'].includes(code))
        return `${action}未完成：連線或服務暫時無法使用。請稍後重試。`;
    const detail = !code && /[\u3400-\u9fff]/.test(String(err?.message || '')) ? err.message : '';
    return `${action}失敗${detail ? '：' + detail : '。'}請確認資料後重試；若仍失敗，請聯絡管理員。`;
}

function beginActionButton(button, busyText = '處理中…') {
    if (!button || button.dataset.actionBusy === '1') return null;
    const state = { text: button.textContent, disabled: button.disabled };
    button.dataset.actionBusy = '1';
    button.disabled = true;
    button.setAttribute('aria-busy', 'true');
    if (busyText) button.textContent = busyText;
    return state;
}
function endActionButton(button, state, finalText = '') {
    if (!button || !state) return;
    button.dataset.actionBusy = '';
    button.removeAttribute('aria-busy');
    button.disabled = state.disabled;
    button.textContent = finalText || state.text;
}
function actionButtonFromEventOrSelector(selector = '') {
    const eventButton = window.event?.currentTarget?.closest?.('button');
    return eventButton || (selector ? document.querySelector(selector) : null);
}

// One authoritative order document commit. Features own drafts, IDs and presentation;
// inventory initialization and delayed quote/source synchronization remain checkpoints.
async function commitOrderCreation(orderId,data,{actorUid=currentUser?.uid,actorRole=currentUserRole,linkForecast=false,expectedForecastUpdatedAt=''}={}) {
    const assertActor=()=>{
        if(!actorUid||actorUid!==currentUser?.uid||actorRole!==currentUserRole)throw new Error('登入帳號或角色已變更，請以原身分確認建單結果。');
        if(!['admin','sales','engineer','purchaser'].includes(actorRole))throw new Error('目前沒有建立訂單權限。');
    };
    assertActor();
    if(typeof orderId!=='string'||!orderId.trim()||orderId.includes('/'))throw new Error('缺少有效的建單識別碼。');
    if(!data||data.createdByUid!==actorUid||data.status!==BUSINESS_STATUS.ACTIVE)throw new Error('建單身分或初始狀態不正確。');
    const snapshot=JSON.parse(JSON.stringify(data));
    const reorder=snapshot.returnReorderSource;
    if(reorder!==undefined&&(!reorder||typeof reorder!=='object'||Array.isArray(reorder)
        ||Object.keys(reorder).length!==1||typeof reorder.orderId!=='string'||!reorder.orderId
        ||reorder.orderId!==reorder.orderId.trim()||reorder.orderId.includes('/')||reorder.orderId.length>160
        ||reorder.orderId===orderId||linkForecast||snapshot.sourceType||snapshot.sourceId))
        throw new Error('退貨重新下單的來源關聯不正確。');
    if(linkForecast&&(snapshot.sourceType!==DOCUMENT_TYPES.FORECAST||!snapshot.sourceId||snapshot.sourceDocumentSyncStatus!=='completed'))
        throw new Error('Forecast 建單來源與同步狀態不符。');
    if(!linkForecast&&snapshot.sourceDocumentSyncStatus==='completed')throw new Error('來源同步完成必須具有同交易的來源連結。');
    let savedData;
    const ref=db.collection('orders').doc(orderId);
    await runRoleTransaction(async tx=>{
        assertActor();savedData=undefined;
        const existing=await tx.get(ref);
        assertActor();
        if(existing.exists){
            const live=existing.data();
            if(live.createdByUid!==actorUid||live.status!==BUSINESS_STATUS.ACTIVE||['cancelled','voided'].includes(live.orderStatus))
                throw new Error('待確認的訂單已由其他流程變更，請先檢查訂單清單。');
            if(linkForecast&&(live.sourceType!==snapshot.sourceType||live.sourceId!==snapshot.sourceId))
                throw new Error('建單識別碼已用於其他來源，請先核對原訂單。');
            if(JSON.stringify(live.returnReorderSource||null)!==JSON.stringify(reorder||null))
                throw new Error('建單識別碼已用於其他退貨來源，請先核對原訂單。');
            // Preserve the existing pending-ID contract: resume authoritative saved
            // facts, not a modified/stale form, and never overwrite fulfillment progress.
            savedData=live;return;
        }
        let forecastRef=null;
        if(reorder){
            const source=await tx.get(db.collection('orders').doc(reorder.orderId));assertActor();
            if(!source.exists)throw new Error('原退貨訂單不存在，請重新核對來源。');
            const original=source.data();
            if((!['admin','purchaser'].includes(actorRole)&&original.ownerUid!==actorUid)
                ||original.customerName!==snapshot.customerName)throw new Error('原退貨訂單的負責人或客戶不符。');
            if(!Array.isArray(original.returnRecords)||!original.returnRecords.some(row=>row?.settlement==='CLOSE'
                &&Number.isFinite(Number(row.qty))&&Number(row.qty)>0))throw new Error('原訂單尚無實收結案退貨，不能由此重新下單。');
        }
        if(linkForecast){
            if(!['sales','admin'].includes(actorRole))throw new Error('目前沒有 Forecast 轉單權限。');
            forecastRef=db.collection('forecasts').doc(snapshot.sourceId);
            const source=await tx.get(forecastRef);assertActor();
            if(!source.exists)throw new Error('來源 Forecast 已不存在，不能建立未連結的訂單。');
            const forecast=source.data();
            if(normalizedOrderStatus(forecast)!=='normal')throw new Error('來源 Forecast 已取消／作廢，不能轉單。');
            if((actorRole!=='admin'&&forecast.ownerUid&&forecast.ownerUid!==actorUid)
                ||snapshot.ownerUid!==(forecast.ownerUid||actorUid))throw new Error('Forecast 與訂單負責人不符，請重新核對來源。');
            if(expectedForecastUpdatedAt&&forecast.updatedAt!==expectedForecastUpdatedAt)throw new Error('Forecast 已變更，請重新整理後核對轉單內容。');
        }
        assertActor();
        tx.set(ref,snapshot);
        if(forecastRef)tx.update(forecastRef,{
            linkedDocuments:firebase.firestore.FieldValue.arrayUnion(documentLink(DOCUMENT_TYPES.ORDER,orderId,'created')),
            updatedAt:snapshot.createdAt
        });
        savedData=snapshot;
    });
    try{assertActor();}catch(err){err.orderCommitted=true;err.orderId=orderId;throw err;}
    return {id:orderId,data:savedData};
}
let forecastLoading = false;
let forecastSaveInProgress = false;
let forecastProgressSaveInProgress = false;

function forecastStatusLabel(status) {
    return ({ active: '進行中', won: 'Win', lost: 'Lost' })[status] || status || '進行中';
}

function forecastStageLabel(stage) {
    return ({
        stage1: 'Stage 1',
        stage2: 'Stage 2',
        stage3: 'Stage 3',
        stage4: 'Stage 4',
        stage5: 'Stage 5'
    })[stage] || '未設定';
}

function forecastTodayLabel(date = new Date()) {
    const mm = String(date.getMonth() + 1).padStart(2, '0');
    const dd = String(date.getDate()).padStart(2, '0');
    return `${mm}/${dd}`;
}

function forecastNowIso() {
    return new Date().toISOString();
}

function buildForecastProgressText(text, fallback = '立案') {
    const content = String(text || '').trim() || fallback;
    return `${forecastTodayLabel()} ${content}`;
}

function normalizeForecastBrand(value) {
    return resolveBrandName(value);
}

let forecastBrandFilterSignature = '';
let forecastSalesFilterSignature = '';

function populateForecastBrandFilter() {
    const select = document.getElementById('forecastBrandFilter');
    if (!select) return [];

    const current = select.value;
    const brands = getPrimaryBrandNames();
    const signature = JSON.stringify(brands);
    if (signature !== forecastBrandFilterSignature) {
        select.innerHTML = '<option value="">全部廠牌</option>' + brands.map(brand =>
            `<option value="${escapeAttr(brand)}">${escapeHtml(brand)}</option>`
        ).join('') + `<option value="${OTHER_BRAND_OPTION_KEY}">其他廠牌</option>`;
        forecastBrandFilterSignature = signature;
    }

    if (brands.includes(current) || current === OTHER_BRAND_OPTION_KEY) select.value = current;
    else if (current) select.value = '';
    return brands;
}

function forecastOwnSalesName() {
    return stripPhoneSuffix(currentUserName || '').trim();
}

function forecastSalesCodeForName(name) {
    const normalizedName = stripPhoneSuffix(name || '').trim();
    if (!normalizedName) return '';
    if (normalizedName === forecastOwnSalesName() && currentUserCode) return String(currentUserCode);
    const match = salesList.find(person =>
        String(person.role || 'sales').toLowerCase() === 'sales'
        && stripPhoneSuffix(person.name || '') === normalizedName
        && person.active !== false
    );
    return String(match?.code || '');
}

function populateForecastSalesFilter() {
    const select = document.getElementById('forecastSalesFilter');
    if (!select) return;

    const canSeeAll = canViewAllData('forecast');
    const ownName = forecastOwnSalesName();

    if (!canSeeAll) {
        const label = ownName || '我的案件';
        const signature = JSON.stringify(['own', ownName, label]);
        if (signature !== forecastSalesFilterSignature) {
            select.innerHTML = `<option value="${escapeAttr(ownName)}">${escapeHtml(label)}</option>`;
            forecastSalesFilterSignature = signature;
        }
        select.value = ownName;
        select.disabled = true;
        return;
    }

    const current = select.value;
    const names = new Set();

    salesList
        .filter(person => String(person.role || 'sales').toLowerCase() === 'sales' && person.active !== false)
        .forEach(person => {
            const name = stripPhoneSuffix(person.name || '');
            if (name) names.add(name);
        });

    const forecastRows = forecastHistorySearchActive ? forecastHistorySearchResults : forecastCache;
    forecastRows.forEach(item => {
        const name = stripPhoneSuffix(item.salesName || '');
        if (name) names.add(name);
    });

    select.disabled = false;
    const sortedNames = [...names].sort((a, b) => a.localeCompare(b, 'zh-Hant'));
    const signature = JSON.stringify(['all', sortedNames]);

    if (signature !== forecastSalesFilterSignature) {
        select.innerHTML = '<option value="">全部負責業務</option>' + sortedNames.map(name =>
            `<option value="${escapeAttr(name)}">${escapeHtml(name)}</option>`
        ).join('');
        forecastSalesFilterSignature = signature;
    }

    if ([...select.options].some(option => option.value === current)) select.value = current;
    else select.value = '';
}

