// One row is an atomic checkpoint; batch presentation and recovery IDs belong to the Feature.
async function commitManualInventoryAdjustment(input,{actorUid=currentUser?.uid,actorRole=currentUserRole,actorName=currentUserName||currentUser?.email||'',onStockCommitted=null}={}) {
    const assertActor=()=>{
        if(!actorUid||actorUid!==currentUser?.uid||actorRole!==currentUserRole)throw new Error('登入帳號或角色已變更，請以原身分確認庫存異動結果。');
        if(!['admin','purchaser','warehouse'].includes(actorRole))throw new Error('目前沒有人工庫存異動權限。');
    };
    assertActor();
    const request=JSON.parse(JSON.stringify(input||{})),{type,productKey:key,warehouseId,operationId}=request;
    const row=request.row||{},validId=value=>typeof value==='string'&&value.trim()!==''&&!value.includes('/');
    if(!['initial','adjustment','scrap'].includes(type)||!validId(key)||!validId(warehouseId)||!validId(operationId))throw new Error('缺少有效的異動類型、產品、倉庫或操作識別碼。');
    if(typeof row.qty!=='number'||!Number.isFinite(row.qty)||row.qty===0||(type==='initial'&&row.qty<0))throw new Error('庫存異動數量不正確；新增庫存必須是正數。');
    const delta=type==='scrap'?-Math.abs(row.qty):row.qty,lotNo=String(row.lotNo||'').trim(),expiryDate=String(row.expiryDate||'').trim();
    if(expiryDate&&(!/^\d{4}-\d{2}-\d{2}$/.test(expiryDate)||!Number.isFinite(Date.parse(expiryDate))||new Date(expiryDate).toISOString().slice(0,10)!==expiryDate))throw new Error('效期格式不正確。');
    const writesCost=type==='initial'&&['admin','purchaser'].includes(actorRole);
    if(writesCost&&(String(row.unitCost??'').trim()===''||!['number','string'].includes(typeof row.unitCost)||!Number.isFinite(Number(row.unitCost))||Number(row.unitCost)<0))throw new Error('手動新增庫存請填寫實際單位成本，零成本請明確填 0。');
    const intent={type,productKey:key,warehouseId,delta,lotNo,expiryDate};
    const stock=data=>{
        const result={};
        for(const field of ['onHand','reserved','incoming']){
            const value=data[field]===undefined?0:data[field];
            if(!['number','string'].includes(typeof value)||String(value).trim()===''||!Number.isFinite(Number(value))||Number(value)<0)throw new Error('原庫存數量不正確，請先核對資料。');
            result[field]=Number(value);
        }
        if(result.reserved>result.onHand)throw new Error('已預留超過現有數量，請先核對庫存。');
        return result;
    };
    const identity=(data,warehouse='')=>{
        if((data.productKey&&data.productKey!==key)||(data.productId&&data.productId!==key)||(warehouse&&data.warehouseId&&data.warehouseId!==warehouse))throw new Error('產品或倉庫識別不符，請先核對資料。');
    };
    const ref=db.collection('inventory').doc(encodeURIComponent(key)),whRef=db.collection('warehouseStocks').doc(warehouseStockDocId(warehouseId,key));
    const movementRef=db.collection('inventoryMovements').doc(operationId),balanceRef=db.collection('inventoryLots').doc(operationId+'-balance'),addedRef=db.collection('inventoryLots').doc(operationId+'-added');
    const costRef=db.collection('inventoryLotCosts').doc(addedRef.id),now=new Date().toISOString();
    let result;
    await runRoleTransaction(async tx=>{
        assertActor();result=undefined;
        const prior=await tx.get(movementRef);assertActor();
        if(prior.exists){
            const saved=prior.data();
            if(saved.operation!=='manual-adjustment'||saved.sourceId!==operationId||saved.actorUid!==actorUid||saved.actorRole!==actorRole
                ||saved.type!==type||saved.qty!==delta||saved.productKey!==key||saved.warehouseId!==warehouseId
                ||!Object.keys(intent).every(field=>saved.adjustmentIntent?.[field]===intent[field]))throw new Error('此操作識別碼已用於不同內容或身分，請先確認原異動。');
            if(writesCost){
                const cost=await tx.get(costRef);assertActor();
                if(!cost.exists||cost.data().unitCost!==Number(row.unitCost)||cost.data().lotId!==addedRef.id||cost.data().productKey!==key)throw new Error('原新增庫存成本已變更或不符，請先確認原異動。');
            }
            result={operationId,productKey:key,warehouseId,delta,replayed:true};return;
        }
        const productSnap=await tx.get(db.collection('products').doc(key)),warehouseSnap=await tx.get(db.collection('warehouses').doc(warehouseId));
        const invSnap=await tx.get(ref),whSnap=await tx.get(whRef);assertActor();
        if(!productSnap.exists||productSnap.data().active===false||productSnap.data().status==='INACTIVE')throw new Error('產品主檔不存在或已停用。');
        if(!warehouseSnap.exists||warehouseSnap.data().active===false||warehouseSnap.data().systemCustody||warehouseSnap.data().warehouseType==='CUSTODY'||warehouseId.startsWith('custody-'))throw new Error('請選擇有效的實體倉庫，不可直接異動保管庫存。');
        const product=productSnap.data();
        if(['service','services','服務'].includes(String(product.productType||'').trim().toLowerCase()))throw new Error('服務品項不可建立實體庫存異動。');
        if((product.productId&&product.productId!==key)||(product.lotTracked&&!lotNo)||(product.expiryTracked&&!expiryDate))throw new Error('產品識別或必填批號／效期不符。');
        const old=invSnap.exists?invSnap.data():{},oldWh=whSnap.exists?whSnap.data():{};identity(old);identity(oldWh,warehouseId);
        const n=stock(old),wh=stock(oldWh);
        if(wh.onHand>n.onHand||n.onHand+delta<n.reserved||wh.onHand+delta<wh.reserved)throw new Error('異動後庫存不足以支撐已預留數量，或公司與分倉數量不符。');
        const query=await firestoreReadWithTimeout(db.collection('inventoryLots').where('productKey','==',key).limit(201).get(),'人工異動批次');assertActor();
        if(query.size>200)throw new Error('此產品批次超過安全處理上限。');
        const snaps=await Promise.all(query.docs.map(doc=>tx.get(doc.ref)));
        const allLots=snaps.filter(doc=>doc.exists).map(doc=>({...doc.data(),id:doc.id}));
        for(const lot of allLots){identity(lot);if(!validId(lot.warehouseId))throw new Error('批次缺少有效的倉庫識別。');const qty=lot.remainingQty??lot.qty??0;if(!['number','string'].includes(typeof qty)||String(qty).trim()===''||!Number.isFinite(Number(qty))||Number(qty)<0)throw new Error('批次數量不正確。');}
        const balance=await tx.get(balanceRef),added=await tx.get(addedRef),cost=writesCost?await tx.get(costRef):null;assertActor();
        if(balance.exists||added.exists||cost?.exists)throw new Error('庫存異動的批次或成本識別碼衝突。');
        const currentLots=allLots.filter(lot=>lot.warehouseId===warehouseId);
        const plan=YushinInventory.manualAdjustmentLots(currentLots,wh.onHand,delta,wh.reserved,{lotNo,expiryDate,balanceId:balanceRef.id,addedId:addedRef.id});
        const brand=resolveBrandName(product.brandName||product.brand||row.brand||'');
        const metadata={productKey:key,productId:key,itemCode:product.manufacturerPartNo||product.model||row.itemCode||'',itemName:product.productName||product.nameCn||product.nameEn||row.itemName||'',brand,brandId:product.brandId||brandIdForName(brand)};
        // Legacy list/search mirror is a projection of operational lots, never an independent delta ledger.
        const lots=[...allLots.filter(lot=>lot.warehouseId!==warehouseId),...plan.lots.map(lot=>({...lot,warehouseId}))].map(lot=>({warehouseId:lot.warehouseId,lotNo:lot.lotNo||'',expiryDate:lot.expiryDate||'',qty:Number(lot.remainingQty??lot.qty??0)}));
        const nextInventory={...old,...metadata,onHand:n.onHand+delta,reserved:n.reserved,incoming:n.incoming,lots,updatedAt:now};
        nextInventory.searchTokens=buildInventorySearchTokens(nextInventory);assertActor();
        for(const lot of plan.lots){
            const existing=currentLots.find(row=>row.id===lot.id),lotRef=db.collection('inventoryLots').doc(lot.id);
            if(existing){if(Number(existing.remainingQty??existing.qty??0)!==lot.remainingQty)tx.update(lotRef,{remainingQty:lot.remainingQty,updatedAt:now});}
            else tx.set(lotRef,{productKey:key,productId:key,warehouseId,lotNo:lot.lotNo||'',expiryDate:lot.expiryDate||'',receivedQty:lot.receivedQty,remainingQty:lot.remainingQty,unbatched:lot.unbatched===true,
                sourceType:lot.id===balanceRef.id?'MANUAL_STOCK_BALANCE':type==='initial'?'INITIAL_STOCK':'MANUAL_ADJUSTMENT',sourceId:operationId,receivedAt:now,createdBy:actorName});
        }
        if(type==='initial')tx.set(costRef,{lotId:addedRef.id,productKey:key,productId:key,warehouseId,...(writesCost?{unitCost:Number(row.unitCost)}:{costPending:true}),sourceType:'INITIAL_STOCK',sourceId:operationId,createdAt:now,createdBy:actorName});
        tx.set(ref,nextInventory,{merge:true});
        tx.set(whRef,{...metadata,warehouseId,onHand:wh.onHand+delta,reserved:wh.reserved,incoming:wh.incoming,updatedAt:now},{merge:true});
        tx.set(movementRef,{type,qty:delta,...metadata,warehouseId,lotNo,expiryDate,lotId:delta>0?addedRef.id:'',lotAllocations:plan.allocations,operation:'manual-adjustment',adjustmentIntent:intent,
            actorUid,actorRole,sourceType:'manual',sourceId:operationId,createdAt:now,createdBy:actorName});
        result={operationId,productKey:key,warehouseId,delta,replayed:false};
    });
    try{assertActor();onStockCommitted?.(key,warehouseId);}catch(err){err.manualAdjustmentCommitted=true;err.operationId=operationId;throw err;}
    return result;
}
// Planning/list flags never mutate physical stock. Audit IDs are operation receipts.
async function commitInventoryPlanningSettings(inventoryId,policy,safetyStock=0,{operationId,actorUid=currentUser?.uid,actorRole=currentUserRole}={}) {
    const assertActor=()=>{
        if(!actorUid||currentUser?.uid!==actorUid||currentUserRole!==actorRole)throw new Error('登入身分已變更，請以原身分確認庫存設定。');
        if(!['admin','purchaser'].includes(actorRole))throw new Error('只有管理員或採購可以調整庫存策略。');
    };
    assertActor();
    const settings=YushinInventory.planningSettings(policy,safetyStock);
    if(typeof inventoryId!=='string'||!inventoryId.trim()||inventoryId.length>128||inventoryId.includes('/'))throw new Error('庫存識別碼不正確。');
    if(typeof operationId!=='string'||!operationId.trim()||operationId.length>128||operationId.includes('/'))throw new Error('缺少有效的庫存設定操作識別碼。');
    const ref=db.collection('inventory').doc(inventoryId),auditRef=db.collection('auditLogs').doc(operationId),at=new Date().toISOString();
    let result;
    await runRoleTransaction(async tx=>{
        assertActor();result=undefined;
        const audit=await tx.get(auditRef),snapshot=await tx.get(ref);assertActor();
        if(!snapshot.exists)throw new Error('找不到庫存品項，請更新清單。');
        const live=snapshot.data();
        if(audit.exists){
            const saved=audit.data();
            if(saved.action!=='inventory_policy_set'||saved.inventoryId!==inventoryId||saved.actorUid!==actorUid||saved.actorRole!==actorRole
                ||saved.stockPolicy!==settings.stockPolicy||saved.safetyStock!==settings.safetyStock)throw new Error('此設定操作識別碼已用於其他內容或身分，請先確認原作業。');
            // The receipt proves the earlier intent, not that the policy never changed again.
            const current=YushinInventory.planningSettings(YushinInventory.stockPolicyFor(live),live.safetyStock??0);
            result={patch:{...current,...(live.updatedAt?{updatedAt:live.updatedAt}:{})},replayed:true,changed:false,operationId};return;
        }
        const changed=live.stockPolicy!==settings.stockPolicy||live.safetyStock!==settings.safetyStock;
        const patch={...settings,updatedAt:at};
        if(changed)tx.update(ref,patch);
        tx.set(auditRef,{action:'inventory_policy_set',inventoryId,actorUid,actorRole,...settings,
            previousStockPolicy:live.stockPolicy??null,previousSafetyStock:live.safetyStock??null,changed,createdAt:at});
        result={patch:changed?patch:{...settings,...(live.updatedAt?{updatedAt:live.updatedAt}:{})},replayed:false,changed,operationId};
    });
    try{assertActor();}catch(err){err.inventoryPlanningCommitted=true;err.operationId=operationId;throw err;}
    return result;
}

async function commitInventoryListArchive({inventoryId,productKey,archived,operationId},{actorUid=currentUser?.uid,actorRole=currentUserRole}={}) {
    const assertActor=()=>{
        if(!actorUid||currentUser?.uid!==actorUid||currentUserRole!==actorRole)throw new Error('登入身分已變更，請以原身分確認庫存列表。');
        if(actorRole!=='admin'||trueUserRole!=='admin')throw new Error('只有管理員視角可以移出或恢復庫存品項。');
    };
    assertActor();
    const valid=value=>typeof value==='string'&&value.trim()!==''&&value.length<=128&&!value.includes('/');
    if(!valid(inventoryId)||!productKey||typeof productKey!=='string'||!valid(operationId)||typeof archived!=='boolean')throw new Error('庫存列表操作資料不正確。');
    const ref=db.collection('inventory').doc(inventoryId),auditRef=db.collection('auditLogs').doc(operationId),at=new Date().toISOString();
    let result;
    await runRoleTransaction(async tx=>{
        assertActor();result=undefined;
        const audit=await tx.get(auditRef),snapshot=await tx.get(ref);assertActor();
        if(!snapshot.exists)throw new Error('找不到庫存品項，請更新清單。');
        const live=snapshot.data();
        if((live.productKey||live.productId||inventoryId)!==productKey)throw new Error('品項識別已變更，請先核對資料。');
        if(audit.exists){
            const saved=audit.data();
            if(saved.action!==(archived?'inventory_list_archive':'inventory_list_restore')||saved.inventoryId!==inventoryId||saved.productKey!==productKey
                ||saved.archived!==archived||saved.actorUid!==actorUid||saved.actorRole!==actorRole)throw new Error('此列表操作識別碼已用於其他內容或身分，請先確認原作業。');
            const patch={listArchived:live.listArchived===true};
            for(const key of ['listArchiveChangedAt','listArchiveChangedByUid','listArchiveAuditId','updatedAt'])if(live[key]!==undefined)patch[key]=live[key];
            result={patch,replayed:true,changed:false,operationId};return;
        }
        if(archived){
            if(!YushinInventory.stockIsEmpty({...live,lots:[]}))throw new Error('庫存、預留、在途或調撥數量不為零，不能移出。');
            // Repeat discovery on every callback attempt, then re-read each document
            // transactionally. Inactive warehouses are deliberately included.
            const [warehouses,lots]=await Promise.all([
                firestoreReadWithTimeout(db.collection('warehouseStocks').where('productKey','==',productKey).limit(201).get(),'移出前檢查倉庫庫存'),
                firestoreReadWithTimeout(db.collection('inventoryLots').where('productKey','==',productKey).limit(201).get(),'移出前檢查實際批次')
            ]);assertActor();
            if(warehouses.size>200||lots.size>200)throw new Error('批次或倉庫紀錄超過安全檢查上限。');
            for(const doc of lots.docs){
                const lot=await tx.get(doc.ref);assertActor();
                if(!lot.exists)continue;
                const data=lot.data(),qty='remainingQty' in data?data.remainingQty:data.qty;
                if(data.productKey!==productKey||qty===undefined||!YushinInventory.stockIsEmpty({onHand:qty}))throw new Error('仍有實際批次剩餘量或無效批次，不能移出。');
            }
            for(const doc of warehouses.docs){
                const stock=await tx.get(doc.ref);assertActor();
                if(stock.exists&&(stock.data().productKey!==productKey||!YushinInventory.stockIsEmpty(stock.data())))throw new Error('仍有倉庫庫存、預留、在途或無效數量，不能移出。');
            }
        }
        assertActor();
        const changed=(live.listArchived===true)!==archived;
        const patch=changed?{listArchived:archived,listArchiveChangedAt:at,listArchiveChangedByUid:actorUid,listArchiveAuditId:operationId,updatedAt:at}:{listArchived:archived};
        if(changed)tx.update(ref,patch);
        tx.set(auditRef,{action:archived?'inventory_list_archive':'inventory_list_restore',inventoryId,productKey,actorUid,actorRole,createdAt:at,
            itemCode:live.itemCode||'',itemName:live.itemName||'',archived,changed});
        result={patch,replayed:false,changed,operationId};
    });
    try{assertActor();}catch(err){err.inventoryListCommitted=true;err.operationId=operationId;throw err;}
    return result;
}
// Preview-only bridge to the authenticated Cloud Function. The normal
// per-item Service remains unchanged until complete Preview acceptance.
// This bridge uses the same Reservation Core for initial quantity proposals;
// the server must independently reread and validate ALL authoritative data.
let groupedReservationFunctionsScriptPromise = null;
function groupedReservationPreviewEnabled() {
    return APP_ENVIRONMENT === 'preview'
        && globalThis.YUSHIN_PREVIEW_GROUPED_RESERVATION === true;
}
function initialGroupedReservationCandidates(order) {
    if (!groupedReservationPreviewEnabled()
        || order?.inventoryReservationStatus !== 'pending'
        || !/^[a-zA-Z0-9_-]{12,80}$/.test(String(order.inventoryReservationAttemptId||''))
        || normalizedOrderStatus(order) !== 'normal'
        || !Array.isArray(order.items)) return [];
    const groups = new Map();
    for (const [index, item] of order.items.entries()) {
        if (!item || (item.fulfillmentType||'WAREHOUSE') !== 'WAREHOUSE'
            || String(item.productType||'').toUpperCase() === 'SERVICE'
            || !item.warehouseId || String(item.warehouseId).startsWith('custody-')) continue;
        const untouched = ['reservedQty','deliveredQty','returnedQty','supplyOrderedQty',
            'receivedQty','dispatchPreparedQty'].every(key=>Number(item[key]||0)===0);
        const requested = Number(item.qty??item.orderedQty);
        if (!untouched || item.transferPendingId || item.custodyTransferId
            || !Number.isSafeInteger(requested) || requested<=0 || requested>1000000) continue;
        const productKey=inventoryProductKey(item);
        if (!productKey || !item.productId) continue;
        const itemId=String(item.itemId||`item-${index+1}`);
        if (!groups.has(productKey)) groups.set(productKey,[]);
        groups.get(productKey).push({itemId,warehouseId:item.warehouseId,requested});
    }
    return [...groups].filter(([,rows])=>rows.length>=2&&rows.length<=5
        && new Set(rows.map(row=>row.itemId)).size===rows.length
        && new Set(rows.map(row=>row.warehouseId)).size===2)
        .map(([productKey,rows])=>({productKey,rows}));
}
async function groupedReservationPreviewCallable() {
    if (!firebase.functions) {
        if (!groupedReservationFunctionsScriptPromise) {
            groupedReservationFunctionsScriptPromise=new Promise((resolve,reject)=>{
                const script=document.createElement('script');
                script.src='https://www.gstatic.com/firebasejs/10.8.0/firebase-functions-compat.js';
                script.onload=resolve;
                script.onerror=()=>reject(new Error('無法載入 Firebase Functions，跨倉同步未提交。'));
                document.head.appendChild(script);
            }).catch(error=>{groupedReservationFunctionsScriptPromise=null;throw error;});
        }
        await groupedReservationFunctionsScriptPromise;
    }
    if (!firebase.functions) throw new Error('Firebase Functions 尚未初始化，跨倉同步未提交。');
    return firebase.app().functions('asia-east1').httpsCallable('commitGroupedWarehouseReservation');
}
async function commitInitialGroupedReservationPreview(orderId,liveOrder,actorUid) {
    const groups=initialGroupedReservationCandidates(liveOrder);
    if (!groups.length) return false;
    if (!actorUid || currentUser?.uid!==actorUid)
        throw new Error('登入身分已變更，停止跨倉庫存同步。');
    if (!globalThis.YushinReservation?.planReservation || !globalThis.YushinInventory?.normalizeStock)
        throw new Error('預留或庫存核心尚未載入。');
    const operationAttempt=liveOrder.inventoryReservationAttemptId;
    let committed=false;
    for (const [groupIndex,group] of groups.entries()) {
        const {productKey,rows}=group;
        const warehouses=[...new Set(rows.map(row=>row.warehouseId))].sort();
        const companyRef=db.collection('inventory').doc(encodeURIComponent(productKey));
        const warehouseRefs=warehouses.map(wh=>db.collection('warehouseStocks').doc(warehouseStockDocId(wh,productKey)));
        const snaps=await Promise.all([companyRef,...warehouseRefs].map(ref=>
            firestoreReadWithTimeout(ref.get(),'讀取雙倉庫存')));
        if (!snaps[0].exists || warehouseRefs.some((_,i)=>!snaps[i+1].exists))
            throw new Error('雙倉預留缺少公司或實體分倉庫存，請先核對庫存。');
        const balance = data=>{
            const stock=globalThis.YushinInventory.normalizeStock(data);
            for (const field of ['onHand','reserved','transferFreeInTransit']) {
                const value=Number(data[field]||0);
                if (!Number.isSafeInteger(value)||value<0)
                    throw new Error('雙倉庫存來源數量不正確，停止自動預留。');
            }
            if (Number(data.reserved||0)+Number(data.transferFreeInTransit||0)>Number(data.onHand||0))
                throw new Error('雙倉庫存來源預留及途中帳目超過實貨。');
            return stock.available;
        };
        let companyAvailable=balance(snaps[0].data());
        const byWarehouse=new Map(warehouses.map((wh,i)=>[wh,balance(snaps[i+1].data())]));
        const items=[];
        for(const row of rows) {
            const plan=globalThis.YushinReservation.planReservation({
                requestedQty:row.requested,existingQty:0,sameStock:true,
                availableQty:Math.min(companyAvailable,byWarehouse.get(row.warehouseId)),
                inTransitQty:0
            });
            if (!Number.isSafeInteger(plan.reservedQty))
                throw new Error('雙倉預留計算結果不是整數。');
            companyAvailable-=plan.reservedQty;
            byWarehouse.set(row.warehouseId,byWarehouse.get(row.warehouseId)-plan.reservedQty);
            items.push({itemId:row.itemId,quantity:plan.reservedQty});
        }
        // No stock to hold; use the existing item-level Service to publish
        // the shortage and procurement demand without adding server writes.
        if (!items.some(row=>row.quantity>0)) continue;
        if (currentUser?.uid!==actorUid || !groupedReservationPreviewEnabled())
            throw new Error('登入身分或測試環境已變更，停止跨倉庫存同步。');
        const callable=await groupedReservationPreviewCallable();
        // Derive a stable per-product-group ID from the persisted order sync
        // attempt. Never create a new ID on network retry.
        const attemptId=operationAttempt+'_group_'+groupIndex;
        const reply=await callable({orderId,attemptId,syncAttemptId:operationAttempt,items});
        if (!['applied','already-applied'].includes(reply?.data?.status))
            throw new Error('雙倉交易回覆不明確；請重新讀取訂單後使用相同識別碼重試。');
        committed=true;
        if (currentUser?.uid!==actorUid)
            throw new Error('跨倉交易可能已提交，但登入身分已變更；請重新讀取結果。');
        for (const warehouseId of warehouses)
            invalidateWarehouseStockCache(productKey,warehouseId);
    }
    if(committed)invalidateProcurementDemandQueue();
    return committed;
}
async function reserveSingleOrderItem(orderId, order, item, itemIndex, actorUid = currentUser?.uid) {
    const itemId=String(item.itemId||`item-${itemIndex+1}`);
    if(!globalThis.YushinReservation?.planReservation){
        throw new Error('Reservation core 未載入，無法計算庫存預留。');
    }
    const orderRef=db.collection('orders').doc(orderId);
    const syncUid=actorUid;
    const syncAttemptId=String(order.inventoryReservationAttemptId||'');
    const actor=currentUserName||currentUser?.email||'';
    let result,stockToInvalidate=null;
    let releasedStock=null;

    await runRoleTransaction(async tx=>{
        result=undefined;stockToInvalidate=null;releasedStock=null;
        // Read the current source in every retry. Never publish a caller's full-item snapshot.
        const orderSnap=await tx.get(orderRef);
        if(currentUser?.uid!==syncUid)throw new Error('登入身份已變更，請以原帳號重試同步。');
        if(!orderSnap.exists)throw new Error('訂單已不存在，無法同步庫存。');
        order={id:orderId,...orderSnap.data()};
        if(normalizedOrderStatus(order)!=='normal')throw new Error('已取消／作廢的訂單不可同步庫存。');
        itemIndex=(order.items||[]).findIndex((row,index)=>String(row.itemId||`item-${index+1}`)===itemId);
        if(itemIndex<0)throw new Error('訂單品項已變更，請重新讀取後重試同步。');
        item={...order.items[itemIndex],itemId};
        if(order.inventoryReservationStatus==='completed'){result=item;return;}
        if(syncAttemptId&&(order.inventoryReservationStatus!=='pending'||String(order.inventoryReservationAttemptId||'')!==syncAttemptId))
            throw new Error('已有較新的庫存同步工作，請更新這筆訂單後確認結果。');
        if(item.transferPendingId)throw new Error('調撥途中不可重新配置訂單庫存。');
        const normalized=normalizedOrderItems(order)[itemIndex];
        const orderedQty=Math.max(0,Number(normalized.qty||0));
        const effectiveDelivered=Math.max(0,Number(normalized.deliveredQty||0)-Number(normalized.returnedQty||0));
        const requested=Math.max(0,orderedQty-effectiveDelivered);
        const productKey=inventoryProductKey(item);
        let warehouseId=item.warehouseId||order.warehouseId||defaultWarehouse()?.id||'';
        const now=new Date().toISOString();
        const demandId=globalThis.YushinProcurementDemand.demandIdForSource({sourceType:'SALES_ORDER',sourceId:orderId,sourceItemId:itemId});
        const demandRef=procurementDemandRef(demandId);
        const demandSnap=await tx.get(demandRef);
        const currentDemand=demandSnap.exists?demandSnap.data():null;
        const publish=nextItem=>{
            if(currentUser?.uid!==syncUid)throw new Error('登入身份已變更，請以原帳號重試同步。');
            result=nextItem;
            const items=order.items.map((row,index)=>index===itemIndex?nextItem:row);
            const nextOrder={...order,items};
            const updates={items,itemCount:items.length,orderSchemaVersion:2,...orderWorkIndexFields(nextOrder),updatedAt:now};
            const demandDoc=orderItemProcurementDemandDocument(nextOrder,nextItem,currentDemand,now);
            if(currentDemand||demandDoc.requestedQty>0||demandDoc.orderedQty>0||demandDoc.receivedQty>0)tx.set(demandRef,demandDoc,{merge:true});
            tx.update(orderRef,updates);
        };
        // Service master data is not physical stock. Verify it against the live
        // product document before skipping warehouse reservation and procurement.
        // An old physical/supplier commitment must be audited, not erased.
        if(String(item.productType||'').trim().toUpperCase()==='SERVICE'){
            const productId=String(item.productId||'').trim();
            if(!productId||productId.includes('/'))throw new Error('服務型品項缺少有效產品主檔。');
            if((item.fulfillmentType||'WAREHOUSE')!=='WAREHOUSE')
                throw new Error('服務型品項尚不支援原廠直送或實貨履約入口。');
            const [productSnap,reservationSnap]=await Promise.all([
                tx.get(db.collection('products').doc(productId)),
                tx.get(db.collection('inventoryReservations').doc(`${orderId}__${itemId}`))
            ]);
            if(!productSnap.exists||productSnap.data().active===false
                ||String(productSnap.data().productType||productSnap.data().type||'').trim().toUpperCase()!=='SERVICE')
                throw new Error('服務型品項與啟用的產品主檔不符，不能建立虛擬實貨。');
            const hasProgress=[reservationSnap.exists?reservationSnap.data().quantity:0,
                item.reservedQty,item.dispatchPreparedQty,item.warehouseShippedQty,
                item.supplyOrderedQty,item.receivedQty,currentDemand?.orderedQty,currentDemand?.receivedQty]
                .some(value=>value!==undefined&&value!==null&&Number(value)!==0);
            if(hasProgress)throw new Error('服務型品項已有實貨預留或供應進度，請先稽核，不能自動抹除。');
            publish({...item,orderedQty,reservedQty:0,shortageQty:0,
                inventoryProductKey:'',warehouseId:'',reservationStatus:'not_required'});
            return;
        }
        // Verify the inverse case, too: a Service product must not be disguised
        // as Goods and accidentally allocated company stock. Only live master
        // data, re-read inside the transaction, can determine this boundary.
        if(item.productId){
            const productId=String(item.productId).trim();
            if(!productId||productId.includes('/'))throw new Error('產品主檔識別碼不正確。');
            const productSnap=await tx.get(db.collection('products').doc(productId));
            if(productSnap.exists&&String(productSnap.data().productType||productSnap.data().type||'').trim().toUpperCase()==='SERVICE')
                throw new Error('產品主檔為服務型，訂單品項不可冒充商品預留實貨；請修正產品類型後重試。');
        }
        if(!productKey){publish({...item,orderedQty,reservedQty:0,shortageQty:requested,inventoryProductKey:'',reservationError:'missing_product_master'});return;}
        if((item.fulfillmentType||'WAREHOUSE')==='DIRECT_SHIP'){
            publish({...item,orderedQty,reservedQty:0,shortageQty:0,inventoryProductKey:productKey,warehouseId:'',reservationStatus:'not_required'});return;
        }
        if(!warehouseId)throw new Error('找不到有效倉庫，無法安全配置庫存。');
        const aggregateRef=inventoryRefFor(item);
        const reservationRef=db.collection('inventoryReservations').doc(`${orderId}__${itemId}`);
        const aggregateSnap=aggregateRef?await tx.get(aggregateRef):null;
        const reservationSnap=await tx.get(reservationRef);
        const aggregate=inventoryNumbers(aggregateSnap?.exists?aggregateSnap.data():{});
        const existing=reservationSnap.exists?reservationSnap.data():{};
        const canChoose=globalThis.YushinReservation.reservationLocationCanChange({...item,
            deliveredQty:Math.max(Number(item.deliveredQty||0),Number(normalized.deliveredQty||0)),
            returnedQty:Math.max(Number(item.returnedQty||0),Number(normalized.returnedQty||0))},existing,currentDemand||{});
        const candidateIds=[...new Set([warehouseId,...(canChoose?warehouseMasterCache
            .filter(w=>w.active!==false&&!w.systemCustody&&!String(w.id).startsWith('custody-')).map(w=>w.id):[])])].filter(Boolean);
        const warehouseContexts=await Promise.all(candidateIds.map(async id=>{
            const ref=db.collection('warehouseStocks').doc(warehouseStockDocId(id,productKey));
            const [master,snapshot]=await Promise.all([tx.get(db.collection('warehouses').doc(id)),tx.get(ref)]);
            return {id,ref,snapshot,master:master.exists?{...master.data(),id}:null};
        }));
        if(canChoose){
          const eligibleLocations=warehouseContexts.filter(row=>row.master&&globalThis.YushinReservation.physicalWarehouse(row.master));
          const availableAtEligibleLocations=eligibleLocations
              .reduce((sum,row)=>sum+inventoryNumbers(row.snapshot.exists?row.snapshot.data():{}).available,0);
          if(eligibleLocations.length&&aggregateSnap?.exists&&aggregate.available>availableAtEligibleLocations+1e-8)
              throw new Error('公司可用庫存與啟用分倉可用量不一致，請先核對分倉庫存或停用倉庫，避免誤列待採購。');
          const selection=globalThis.YushinReservation.selectSingleWarehouse({
            warehouses:warehouseContexts.map(row=>row.master).filter(Boolean),
            stocks:Object.fromEntries(warehouseContexts.map(row=>[row.id,row.snapshot.exists?row.snapshot.data():{}])),
            currentWarehouseId:warehouseId,requestedQty:requested,aggregateAvailableQty:aggregateSnap?.exists?aggregate.available:0
          });
          if(selection.requiresMultipleLocations){
            // Read-only diagnostic from the existing reservation Core. This plan is
            // not a reservation ledger and must not mutate stock or demand.
            const preview=globalThis.YushinReservation.planMultiWarehouseReservation({
              warehouses:eligibleLocations.map(row=>row.master),
              stocks:Object.fromEntries(eligibleLocations.map(row=>[row.id,row.snapshot.exists?row.snapshot.data():{}])),
              currentWarehouseId:warehouseId,requestedQty:requested,
              aggregateStock:aggregateSnap?.exists?aggregateSnap.data():{onHand:0,reserved:0}
            });
            const names=new Map(eligibleLocations.map(row=>[row.id,row.master.warehouseName||row.id]));
            const detail=preview.allocations.map(row=>String(names.get(row.warehouseId)||row.warehouseId)+' '+row.qty).join('、');
            throw new Error('此品項需要多倉分配：需求 '+requested+'、目前各倉可配置 '+preview.allocatedQty
              +(detail?'（'+detail+'）':'')+'、仍缺 '+preview.shortageQty
              +'。現行系統尚未啟用同一品項的多倉預留及分批出貨；請先核對並完成實體倉庫調撥後重試，未變更任何預留或採購需求。');
          }
          warehouseId=selection.warehouseId;
        }
        const selected=warehouseContexts.find(row=>row.id===warehouseId);
        if(!selected?.master||!globalThis.YushinReservation.physicalWarehouse(selected.master))throw new Error('找不到啟用的庫存倉庫，請先確認倉庫主檔後重試。');
        const warehouseRef=selected.ref,warehouseSnap=selected.snapshot;
        const warehouse=inventoryNumbers(warehouseSnap.exists?warehouseSnap.data():{});
        const existingQty=existing.quantity===undefined?0:existing.quantity;
        const oldProductKey=String(existing.productKey||'');
        const oldWarehouseId=String(existing.warehouseId||'');
        const sameStock=oldProductKey===productKey&&oldWarehouseId===warehouseId;
        if(existingQty>0&&sameStock&&(!aggregateSnap?.exists||!warehouseSnap?.exists)){
            throw new Error('既有預留缺少對應公司或分倉庫存，請先稽核後重試。');
        }

        const plan=globalThis.YushinReservation.planReservation({
            requestedQty:requested,
            existingQty,
            sameStock,
            availableQty:aggregateSnap?.exists?Math.min(warehouse.available,aggregate.available+(oldProductKey===productKey&&!sameStock?existingQty:0)):0,
            inTransitQty:Math.max(0,Number(item.supplyOrderedQty||0)-Number(item.receivedQty||0))
        });

        let oldAggregateRef=null,oldAggregateSnap=null,oldAggregate=null;
        let oldWarehouseRef=null,oldWarehouseSnap=null,oldWarehouse=null;
        if(plan.releaseQty>0&&!sameStock){
            if(!oldProductKey||!oldWarehouseId){
                throw new Error('舊庫存預留缺少產品或倉庫資訊，無法安全重新分配。');
            }
            oldAggregateRef=oldProductKey===productKey
                ? aggregateRef
                : db.collection('inventory').doc(encodeURIComponent(oldProductKey));
            oldWarehouseRef=db.collection('warehouseStocks').doc(warehouseStockDocId(oldWarehouseId,oldProductKey));
            oldAggregateSnap=oldProductKey===productKey
                ? aggregateSnap
                : await tx.get(oldAggregateRef);
            oldWarehouseSnap=await tx.get(oldWarehouseRef);
            if(!oldWarehouseSnap?.exists){
                throw new Error('找不到舊庫存預留所在倉庫，無法安全重新分配。');
            }
            oldAggregate=inventoryNumbers(oldAggregateSnap?.exists?oldAggregateSnap.data():{});
            oldWarehouse=inventoryNumbers(oldWarehouseSnap.data());
        }

        // Share the lifecycle balance contract; raw snapshots must be checked
        // before any clamping or release can hide a corrupt reservation account.
        if(!sameStock)globalThis.YushinReservation.validateReservationBalance({
            existingQty:0,
            aggregateStock:aggregateSnap?.exists?aggregateSnap.data():undefined,
            warehouseStock:warehouseSnap.exists?warehouseSnap.data():undefined
        });
        globalThis.YushinReservation.validateReservationBalance({
            existingQty,itemReservedQty:Object.hasOwn(item,'reservedQty')?item.reservedQty:existingQty,
            aggregateStock:sameStock?(aggregateSnap?.exists?aggregateSnap.data():undefined):oldAggregateSnap?.data(),
            warehouseStock:sameStock?(warehouseSnap.exists?warehouseSnap.data():undefined):oldWarehouseSnap?.data()
        });

        if(aggregateRef&&aggregateSnap?.exists){
            let nextReserved=aggregate.reserved;
            if(plan.releaseQty>0&&oldProductKey===productKey)nextReserved=nextReserved-plan.releaseQty;
            nextReserved+=plan.additionalReserveQty;
            if(nextReserved!==aggregate.reserved)tx.update(aggregateRef,{reserved:nextReserved,updatedAt:now});
        }
        if(plan.releaseQty>0&&oldProductKey&&oldProductKey!==productKey&&oldAggregateRef&&oldAggregateSnap?.exists){
            tx.update(oldAggregateRef,{reserved:oldAggregate.reserved-plan.releaseQty,updatedAt:now});
        }

        if(warehouseRef&&warehouseSnap?.exists){
            let nextReserved=warehouse.reserved;
            if(plan.releaseQty>0&&sameStock)nextReserved=nextReserved-plan.releaseQty;
            nextReserved+=plan.additionalReserveQty;
            if(nextReserved!==warehouse.reserved)tx.update(warehouseRef,{reserved:nextReserved,updatedAt:now});
        }
        if(plan.releaseQty>0&&!sameStock&&oldWarehouseRef&&oldWarehouseSnap?.exists){
            tx.update(oldWarehouseRef,{reserved:oldWarehouse.reserved-plan.releaseQty,updatedAt:now});
            releasedStock={productKey:oldProductKey,warehouseId:oldWarehouseId};
        }

        if(plan.releaseQty>0){
            tx.set(db.collection('inventoryMovements').doc(),inventoryMovementRecord(
                'release',-plan.releaseQty,orderId,oldProductKey||productKey,actor,
                {
                    reason:'reservation_reconcile',warehouseId:oldWarehouseId||warehouseId,itemId,
                    fulfillmentType:'WAREHOUSE',ownerUid:order.ownerUid||currentUser?.uid||'',
                    salesCode:order.salesCode||salesCodeForName(order.salesName)||''
                }
            ));
        }
        if(plan.additionalReserveQty>0){
            tx.set(db.collection('inventoryMovements').doc(),inventoryMovementRecord(
                'reserve',plan.additionalReserveQty,orderId,productKey,actor,
                {
                    warehouseId,itemId,fulfillmentType:'WAREHOUSE',
                    ownerUid:order.ownerUid||currentUser?.uid||'',
                    salesCode:order.salesCode||salesCodeForName(order.salesName)||''
                }
            ));
        }

        tx.set(reservationRef,{
            orderId,itemId,orderNo:order.orderNo||order.quoteNo||orderId,productKey,
            itemCode:item.itemCode||'',itemName:item.itemName||'',customerName:order.customerName||'',
            ownerUid:order.ownerUid||currentUser?.uid||'',
            salesCode:order.salesCode||salesCodeForName(order.salesName),salesName:order.salesName||'',
            orderDate:order.orderDate||'',quantity:plan.reservedQty,shortageQty:plan.shortageQty,
            status:plan.status,warehouseId,updatedAt:now
        },{merge:true});

        publish({...item,itemId,orderedQty,reservedQty:plan.reservedQty,shortageQty:plan.shortageQty,inventoryProductKey:productKey,warehouseId});
        stockToInvalidate={productKey,warehouseId};
    });

    if(releasedStock)invalidateWarehouseStockCache(releasedStock.productKey,releasedStock.warehouseId);
    if(stockToInvalidate)invalidateWarehouseStockCache(stockToInvalidate.productKey,stockToInvalidate.warehouseId);
    invalidateProcurementDemandQueue();
    return result;
}
function orderReservationSummary(order) {
    const items=normalizedOrderItems(order);
    return {
        reservedQty:items.reduce((sum,item)=>sum+Math.max(0,Number(item.reservedQty||0)),0),
        shortageQty:items.reduce((sum,item)=>sum+Math.max(0,Number(item.shortageQty||0)),0)
    };
}

function orderItemProcurementDemandDocument(order, item, currentDemand, now) {
    const dispatch=globalThis.YushinFulfillment.dispatchState(normalizedOrderItems(order).find(row=>row.itemId===item.itemId)||item);
    const demand=procurementDemandForOrderItem(order,item,dispatch);
    // A historical mismatch must be audited, not repaired by erasing supplier facts.
    if(currentDemand&&(Number(currentDemand.orderedQty||0)>demand.orderedQty||Number(currentDemand.receivedQty||0)>demand.receivedQty)){
        throw new Error('採購需求與訂單供應進度不一致，請先稽核供應紀錄後重試。');
    }
    return procurementDemandDocument(demand,{
        productId:item.productId||'',productKey:inventoryProductKey(item),
        itemCode:item.itemCode||'',itemName:item.itemName||'',brand:item.brand||'',
        fulfillmentType:item.fulfillmentType||order.fulfillmentType||'WAREHOUSE',
        warehouseId:(item.fulfillmentType||order.fulfillmentType||'WAREHOUSE')==='DIRECT_SHIP'
            ? '' : (item.warehouseId||order.warehouseId||defaultWarehouse()?.id||''),
        ownerUid:order.ownerUid||'',salesCode:order.salesCode||'',salesName:order.salesName||'',
        // Existing demand dates are independent of supplier ETA.
        scheduleDate:currentDemand?.scheduleDate||demand.scheduleDate||item.requiredByDate||item.scheduleDate||order.requiredByDate||order.expectedDate||''
    },{createdAt:currentDemand?.createdAt||order.createdAt||now,updatedAt:now});
}

async function persistOrderProcurementDemands(orderId, order, items = [], initialization = null) {
    const orderRef=db.collection('orders').doc(orderId);
    // The arguments carry identity only; live quantities and lifecycle always come from Firestore.
    const itemIds=items.map((item,index)=>String(item.itemId||`item-${index+1}`));
    for(const itemId of itemIds){
        const demandId=globalThis.YushinProcurementDemand.demandIdForSource({sourceType:'SALES_ORDER',sourceId:orderId,sourceItemId:itemId});
        const ref=procurementDemandRef(demandId);
        await runRoleTransaction(async tx=>{
            const orderSnap=await tx.get(orderRef);
            if(!orderSnap.exists)throw new Error('訂單已不存在，無法同步採購需求。');
            const liveOrder={id:orderId,...orderSnap.data()};
            // Only initialization transports supply this fence. Cancellation and
            // restoration retain their existing live-source demand projection.
            if(initialization){
                if(currentUser?.uid!==initialization.actorUid)throw new Error('登入身份已變更，請以原帳號重試同步。');
                if(!initialization.syncAttemptId||liveOrder.inventoryReservationStatus!=='pending'
                    ||String(liveOrder.inventoryReservationAttemptId||'')!==initialization.syncAttemptId)
                    throw new Error('已有較新的庫存同步工作，請更新這筆訂單後確認結果。');
                if(normalizedOrderStatus(liveOrder)!=='normal')throw new Error('訂單已取消／作廢，停止後續同步。');
            }
            const currentSnap=await tx.get(ref);
            const current=currentSnap.exists?currentSnap.data():null;
            const item=normalizedOrderItems(liveOrder).find(row=>row.itemId===itemId);
            if(!item)throw new Error('訂單品項已變更，請重新讀取後重試同步。');
            const now=new Date().toISOString();
            if(normalizedOrderStatus(liveOrder)!=='normal'){
                if(current){
                    const cancelled=globalThis.YushinProcurementDemand.cancelDemand(current);
                    tx.set(ref,procurementDemandDocument({...current,...cancelled},{},{createdAt:current.createdAt||now,updatedAt:now}),{merge:true});
                }
                return;
            }
            const doc=orderItemProcurementDemandDocument(liveOrder,item,current,now);
            // Do not create empty demands, but clear an existing demand when stock covers it.
            if(current||doc.requestedQty>0||doc.orderedQty>0||doc.receivedQty>0)tx.set(ref,doc,{merge:true});
        });
    }
    invalidateProcurementDemandQueue();
}

async function syncOrderProcurementDemandLifecycle(orderId, order, lifecycleStatus) {
    // Cancellation and restoration use the same live-source projection, not competing batch formulas.
    await persistOrderProcurementDemands(orderId,order,normalizedOrderItems(order));
}

async function reserveInventoryForNewOrder(orderId, order, actorUid = currentUser?.uid) {
    const orderRef=db.collection('orders').doc(orderId);
    const snapshot=await firestoreReadWithTimeout(orderRef.get(),'讀取待同步訂單');
    if(!snapshot.exists)throw new Error('訂單已不存在，無法同步庫存。');
    const liveOrder={id:orderId,...snapshot.data()};
    const expectedAttemptId=String(order.inventoryReservationAttemptId||'');
    if(expectedAttemptId&&liveOrder.inventoryReservationStatus!=='completed'
        &&(liveOrder.inventoryReservationStatus!=='pending'||String(liveOrder.inventoryReservationAttemptId||'')!==expectedAttemptId))
        throw new Error('已有較新的庫存同步工作，請更新這筆訂單後確認結果。');
    const items=normalizedOrderItems(liveOrder);
    if(!items.length)throw new Error('訂單缺少正式 items 品項資料，請重新建立訂單。');
    if(items.some(item=>(item.fulfillmentType||'WAREHOUSE')!=='DIRECT_SHIP'
        &&String(item.productType||'').trim().toUpperCase()!=='SERVICE')){
        await loadWarehouseMaster(true);
        if(!warehouseMasterLoadPromise)throw new Error('倉庫主檔讀取失敗，請重試同步。');
    }
    if(currentUser?.uid!==actorUid)throw new Error('登入身份已變更，請以原帳號重試同步。');
    // Preview-only grouped initial reservation; all existing per-item demand
    // reconciliation still runs using fresh snapshots and original checkpoints.
    // Historical isolated Service tests do not load the optional adapter.
    // In the real built app it is defined immediately before this Service.
    if(typeof commitInitialGroupedReservationPreview==='function')
        await commitInitialGroupedReservationPreview(orderId,liveOrder,actorUid);
    for(let i=0;i<items.length;i++)await reserveSingleOrderItem(orderId,liveOrder,items[i],i,actorUid);
    // Each item transaction has already published stock, reservation, order and demand atomically.
    // Read the result for self-order processing and UI; never overwrite the source with reservedItems.
    const latest=await firestoreReadWithTimeout(orderRef.get(),'讀取庫存同步結果');
    if(!latest.exists)throw new Error('訂單已不存在。');
    if(currentUser?.uid!==actorUid)throw new Error('登入身份已變更，請以原帳號重試同步。');
    Object.assign(order,{id:orderId,...latest.data()});
    if(normalizedOrderStatus(order)!=='normal')throw new Error('訂單已取消／作廢，停止後續自行訂貨。');
    await registerInitialSelfOrders(orderId,order,actorUid);
    return {...orderReservationSummary(order),items:order.items};
}

// All writes go through the existing server Service; this transport never writes Firestore.
function serviceCaseTransport(){
    const local=h=>['localhost','127.0.0.1'].includes(h);
    if(globalThis.YUSHIN_SERVICE_CASE_EMULATOR!==true||!local(globalThis.location?.hostname))
        throw Error('服務案件目前僅限本機 Emulator。');
    const auth=firebase.auth(),functions=firebase.app().functions('asia-east1');
    const uid=currentUser?.uid,role=currentUserRole;
    const check=()=>{
        if(!uid||auth.currentUser?.uid!==uid||currentUser?.uid!==uid||currentUserRole!==role
            ||!['admin','sales','warehouse','engineer'].includes(role))throw Error('登入身分或服務作業權限已變更。');
    };
    if(auth.app?.options?.projectId!=='demo-yushin'||functions.app?.options?.projectId!=='demo-yushin'
        ||!local(auth.emulatorConfig?.host)||auth.emulatorConfig?.port!==9099)
        throw Error('服務案件只允許本機 demo-yushin Auth／Functions Emulator。');
    check();functions.useEmulator('127.0.0.1',5001);
    return {uid,role,check,call:async(name,input)=>{
        check();const reply=await functions.httpsCallable(name)(input);check();return reply.data;
    }};
}
function serviceCasePendingKey(uid){return 'service-case-pending:'+encodeURIComponent(uid);}
function normalizeServiceCaseIntent(input,uid){
    if(!input||Object.keys(input).some(k=>!['orderId','itemId','caseId','serviceQty','event'].includes(k)))throw Error('服務操作格式不正確。');
    for(const key of ['orderId','itemId','caseId']){
        const value=input[key];
        if(typeof value!=='string'||!value||value!==value.trim()||value.includes('/')||value.length>160)throw Error('服務操作識別碼不正確。');
    }
    const event=YushinServiceWork.normalizedEvent({...input.event,actorUid:uid});
    // Identity is supplied by Firebase Auth, never submitted as an authority field.
    delete event.actorUid;
    return {orderId:input.orderId,itemId:input.itemId,caseId:input.caseId,
        serviceQty:YushinServiceWork.serviceQuantity(input.serviceQty),event};
}
function pendingServiceCaseIntent(){
    const raw=sessionStorage.getItem(serviceCasePendingKey(currentUser?.uid||''));if(!raw)return null;
    try{
        const saved=JSON.parse(raw),intent=normalizeServiceCaseIntent(saved.intent,currentUser.uid);
        if(saved.uid!==currentUser.uid||saved.role!==currentUserRole||JSON.stringify(intent)!==JSON.stringify(saved.intent))throw Error('mismatch');
        return {...saved,intent};
    }catch(_){throw Error('前次服務操作暫存無法核對，請保留原分頁並使用原帳號與角色確認。');}
}
async function readServiceCases(input){
    const transport=serviceCaseTransport();return transport.call('getServiceCaseStatus',input);
}
async function commitServiceCaseIntent(input){
    const t=serviceCaseTransport(),key=serviceCasePendingKey(t.uid);
    let saved=pendingServiceCaseIntent();
    const intent=input===undefined?saved?.intent:normalizeServiceCaseIntent(input,t.uid);
    if(!intent)throw Error('沒有待確認的服務操作。');
    if(saved&&JSON.stringify(saved.intent)!==JSON.stringify(intent))throw Error('請先確認前次服務操作結果。');
    if(!saved){
        saved={uid:t.uid,role:t.role,intent};const raw=JSON.stringify(saved);
        sessionStorage.setItem(key,raw);
        if(sessionStorage.getItem(key)!==raw)throw Error('無法保存原服務操作，尚未送出。');
    }
    t.check();
    const result=await t.call('commitServiceCaseEvent',saved.intent);
    if(!['committed','already-applied'].includes(result?.status)||result.orderId!==intent.orderId
        ||result.itemId!==intent.itemId||result.caseId!==intent.caseId||result.serviceQty!==intent.serviceQty)
        throw Error('服務操作回覆無法核對，請以原資料確認。');
    const proof=await t.call('getServiceCaseStatus',{orderId:intent.orderId,itemId:intent.itemId,caseId:intent.caseId});
    const expected=YushinServiceWork.normalizedEvent({...intent.event,actorUid:t.uid});
    const event=proof?.events?.find(e=>e.id===intent.event.id);
    if(!proof.exists||proof.orderId!==intent.orderId||proof.itemId!==intent.itemId||proof.caseId!==intent.caseId
        ||proof.serviceQty!==intent.serviceQty||!event
        ||Object.keys({...expected,...event}).some(k=>expected[k]!==event[k]))
        throw Error('服務操作已回覆，但事件憑證尚未核對，請保留原操作確認。');
    t.check();
    const current=sessionStorage.getItem(key);
    if(current!==null&&current!==JSON.stringify(saved))throw Error('待確認操作已變更，請保留暫存核對。');
    sessionStorage.removeItem(key);return proof;
}
let serviceCaseView=null;
const SERVICE_EVENT_LABELS={SAMPLE_RECEIVED:'收取檢體',DEVICE_RECEIVED:'收取器材',
    EXPERIMENT_COMPLETED:'實驗完成',REPORT_SENT:'報告已交付',VENDOR_SENT:'寄送委外單位',
    VENDOR_RETURNED:'委外返件',CUSTOMER_RETURNED:'器材交還客戶',
    CUSTOMER_DELIVERED:'成果交付客戶',REPAIR_COMPLETED:'維修完成'};
const SERVICE_CUSTODY_LABELS={NOT_RECEIVED:'尚未收件',IN_HOUSE:'公司保管',AT_VENDOR:'委外單位保管',
    RETURNED_TO_CUSTOMER:'已交還客戶',CUSTOMER_SITE:'客戶現場'};
function serviceCaseEntryEnabled(){
    return globalThis.YUSHIN_SERVICE_CASE_EMULATOR===true
        &&['admin','sales','warehouse','engineer'].includes(currentUserRole);
}
function serviceCaseActionHtml(order){
    return serviceCaseEntryEnabled()&&(order.items||[]).some(i=>String(i.productType||'').trim().toUpperCase()==='SERVICE')
        ?`<button type="button" class="btn-small btn-secondary" onclick="openServiceCases(${inlineJsValue(order.id)})">服務案件</button>`:'';
}
function renderServiceCaseEntry(){
    const button=document.getElementById('serviceCaseEntry');if(button)button.hidden=!serviceCaseEntryEnabled();
}
function serviceCaseCurrent(view){
    if(serviceCaseView!==view||view.uid!==currentUser?.uid||view.role!==currentUserRole
        ||view.generation!==sessionDataGeneration)throw Error('登入身分或服務畫面已變更，請重新開啟。');
}
window.resetServiceCaseView=function(){
    serviceCaseView=null;const overlay=document.getElementById('serviceCaseOverlay');
    overlay?.classList.remove('active');if(overlay)overlay.innerHTML='';
};
window.closeServiceCases=function(){if(!serviceCaseView?.busy)resetServiceCaseView();};
function serviceCaseShell(){
    let overlay=document.getElementById('serviceCaseOverlay');
    if(!overlay){overlay=document.createElement('div');overlay.id='serviceCaseOverlay';overlay.className='modal-overlay';document.body.appendChild(overlay);}
    overlay.innerHTML='<div class="modal" role="dialog" aria-modal="true" aria-labelledby="serviceCaseTitle">'
        +'<h3 id="serviceCaseTitle">服務案件</h3><div id="serviceCaseBody"></div><p id="serviceCaseMessage" role="status"></p>'
        +'<button type="button" class="btn-secondary" onclick="closeServiceCases()">關閉</button></div>';
    overlay.classList.add('active');
}
window.openServiceCases=async function(orderId){
    if(serviceCaseView?.busy)return;
    let view;
    try{
        const {uid,role}=serviceCaseTransport();
        view={uid,role,generation:sessionDataGeneration,busy:false,request:0};serviceCaseView=view;
        serviceCaseShell();
        const pending=pendingServiceCaseIntent();
        if(pending){renderServiceCasePending(view,pending);return;}
        const order=orderId?(ordersCache||[]).find(o=>o.id===orderId):null;
        if(order){view.order={orderId:order.id,orderNo:order.orderNo,customerName:order.customerName,
            items:(order.items||[]).filter(i=>String(i.productType||'').trim().toUpperCase()==='SERVICE')};}
        renderServiceCaseOrder(view);
        if(view.order?.items.length)await loadServiceCaseItem(view.order.items[0].itemId);
    }catch(error){if(view&&serviceCaseView===view)serviceCaseMessage(view,error.message);else if(!view)alert(error.message);}
};
function serviceCaseMessage(view,message){
    serviceCaseCurrent(view);document.getElementById('serviceCaseMessage').textContent=message;
}
function renderServiceCaseOrder(view){
    serviceCaseCurrent(view);
    document.getElementById('serviceCaseBody').innerHTML=
        '<label for="serviceOrderNo">訂單編號</label><input id="serviceOrderNo" maxlength="160">'
        +'<button type="button" onclick="findServiceCaseOrder()">查詢服務訂單</button>'
        +(view.order?`<p>${escapeHtml(view.order.customerName||'')}｜${escapeHtml(view.order.orderNo||'')}</p>`
        +`<label for="serviceItemChoice">服務品項</label><select id="serviceItemChoice" onchange="loadServiceCaseItem(this.value)">${view.order.items.map(i=>`<option value="${escapeAttr(i.itemId)}">${escapeHtml(i.itemName||'服務品項')}</option>`).join('')}</select><div id="serviceItemBody"></div>`:'');
    if(view.order)document.getElementById('serviceOrderNo').value=view.order.orderNo||'';
}
window.findServiceCaseOrder=async function(){
    const view=serviceCaseView;if(!view||view.busy)return;
    let seq;
    try{
        serviceCaseCurrent(view);seq=++view.request;
        const order=await readServiceCases({orderNo:document.getElementById('serviceOrderNo').value.trim()});
        serviceCaseCurrent(view);if(seq!==view.request)return;
        view.order=order;renderServiceCaseOrder(view);await loadServiceCaseItem(order.items[0].itemId);
    }catch(error){if(serviceCaseView===view&&seq===view.request&&view.uid===currentUser?.uid&&view.role===currentUserRole
        &&view.generation===sessionDataGeneration)serviceCaseMessage(view,error.message);}
};
window.loadServiceCaseItem=async function(itemId){
    const view=serviceCaseView;if(!view||view.busy)return;
    serviceCaseCurrent(view);const seq=++view.request;
    document.getElementById('serviceItemBody').textContent='讀取案件中…';view.data=null;view.itemId=itemId;
    try{
        const data=await readServiceCases({orderId:view.order.orderId,itemId});serviceCaseCurrent(view);
        if(seq!==view.request)return;view.data=data;view.needsReload=false;
        if(data.items)Object.assign(view.order,{items:data.items,orderNo:data.orderNo,customerName:data.customerName});
        renderServiceCaseItem(view);
        serviceCaseMessage(view,'');
    }catch(error){if(serviceCaseView===view&&seq===view.request&&view.uid===currentUser?.uid&&view.role===currentUserRole&&view.generation===sessionDataGeneration){
        document.getElementById('serviceItemBody').textContent='無法載入案件，請重新選擇品項。';serviceCaseMessage(view,error.message);
    }}
};
function renderServiceCaseItem(view){
    serviceCaseCurrent(view);const data=view.data,p=data.itemProgress;
    document.getElementById('serviceItemBody').innerHTML=`<p>訂單數量 ${p.orderedQty}｜已開案 ${p.allocatedQty}｜完成 ${p.completedQty}｜待完成 ${p.remainingQty}</p>`
        +data.cases.map(row=>`<details><summary>${escapeHtml(row.caseId)}｜數量 ${row.serviceQty}｜${row.completed?'流程完成':escapeHtml(SERVICE_EVENT_LABELS[row.nextEvent]||'待處理')}｜${escapeHtml(SERVICE_CUSTODY_LABELS[row.custody]||row.custody)}</summary><ol>${row.events.map(e=>`<li>${escapeHtml(SERVICE_EVENT_LABELS[e.type]||e.type)} ${escapeHtml(e.occurredAt)}${e.partyName?'｜'+escapeHtml(e.partyName):''}${e.receivedBy?'｜'+escapeHtml(e.receivedBy):''}${e.reportRef?'｜'+escapeHtml(e.reportRef):''}${e.deliveryRef?'｜'+escapeHtml(e.deliveryRef):''}${e.workSummary?'｜'+escapeHtml(e.workSummary):''}${e.notes?'｜'+escapeHtml(e.notes):''}</li>`).join('')}</ol></details>`).join('')
        +`<label for="serviceCaseChoice">作業案件</label><select id="serviceCaseChoice" onchange="renderServiceCaseAction()"><option value="">${data.canStart?'新增服務案件':'請選擇可執行的案件'}</option>${data.cases.filter(c=>c.canAdvance).map(c=>`<option value="${escapeAttr(c.caseId)}">${escapeHtml(c.caseId)}｜${escapeHtml(SERVICE_EVENT_LABELS[c.nextEvent])}</option>`).join('')}</select><div id="serviceCaseAction"></div>`;
    renderServiceCaseAction();
}
window.renderServiceCaseAction=function(){
    const view=serviceCaseView;if(!view?.data||view.busy)return;serviceCaseCurrent(view);
    const selected=document.getElementById('serviceCaseChoice').value;
    const row=view.data.cases.find(c=>c.caseId===selected);view.selected=row||null;
    const permitted=row?row.canAdvance:view.data.canStart&&view.data.itemProgress.unassignedQty>0;
    if(!permitted){document.getElementById('serviceCaseAction').textContent='目前沒有可執行的作業，可查閱上方案件歷程。';return;}
    const type=row?row.nextEvent:YushinServiceWork.STEPS[view.data.kind][0];view.eventType=type;
    const field={VENDOR_SENT:['partyName','委外收件單位'],CUSTOMER_RETURNED:['receivedBy','客戶領收人'],
        REPORT_SENT:['reportRef','報告憑證／檔案編號'],CUSTOMER_DELIVERED:['deliveryRef','成果交付憑證'],REPAIR_COMPLETED:['workSummary','維修內容']}[type];
    document.getElementById('serviceCaseAction').innerHTML='<fieldset id="serviceCaseFields">'
        +(!row?'<label for="serviceNewCaseId">案件／檢體／器材編號</label><input id="serviceNewCaseId" maxlength="160">'
        +'<label for="serviceNewQty">對應訂單數量</label><input id="serviceNewQty" type="number" min="0" step="any"><small>依本案件對應的訂購量填寫。</small>':'')
        +'<label for="serviceOccurredAt">實際作業時間</label><input id="serviceOccurredAt" type="datetime-local" step="1">'
        +(field?`<label for="serviceEvidence">${field[1]}</label><input id="serviceEvidence" maxlength="1000">`:'')
        +'<label for="serviceNotes">備註</label><textarea id="serviceNotes" maxlength="1000"></textarea>'
        +`<button type="button" id="serviceCaseSave" onclick="saveServiceCaseAction()">確認${escapeHtml(SERVICE_EVENT_LABELS[type])}</button></fieldset>`;
    const now=new Date();document.getElementById('serviceOccurredAt').value=new Date(now.getTime()-now.getTimezoneOffset()*60000).toISOString().slice(0,19);
    view.evidenceField=field?.[0];
};
function renderServiceCasePending(view,saved){
    serviceCaseCurrent(view);view.pending=true;
    document.getElementById('serviceCaseBody').innerHTML=`<p>前次服務操作結果待確認，請以原資料確認。</p><p>案件：${escapeHtml(saved.intent.caseId)}｜數量：${saved.intent.serviceQty}｜${escapeHtml(SERVICE_EVENT_LABELS[saved.intent.event.type]||saved.intent.event.type)}</p><button type="button" id="serviceCaseRetry" onclick="saveServiceCaseAction()">確認前次服務操作結果</button>`;
}
window.saveServiceCaseAction=async function(){
    const view=serviceCaseView;if(!view||view.busy||view.needsReload)return;
    let confirmed=false;
    try{
        serviceCaseCurrent(view);let intent;
        if(!pendingServiceCaseIntent()){
            const at=new Date(document.getElementById('serviceOccurredAt').value);
            if(!Number.isFinite(at.getTime()))throw Error('請填寫有效的實際作業時間。');
            const event={id:crypto.randomUUID(),type:view.eventType,occurredAt:at.toISOString(),notes:document.getElementById('serviceNotes').value};
            if(view.evidenceField)event[view.evidenceField]=document.getElementById('serviceEvidence').value;
            intent={orderId:view.order.orderId,itemId:view.itemId,caseId:view.selected?.caseId||document.getElementById('serviceNewCaseId').value.trim(),
                serviceQty:view.selected?.serviceQty??Number(document.getElementById('serviceNewQty').value),event};
        }
        view.busy=true;document.getElementById('serviceCaseFields')?.setAttribute('disabled','');
        const retry=document.getElementById('serviceCaseRetry');if(retry)retry.disabled=true;
        const proof=await commitServiceCaseIntent(intent);confirmed=true;serviceCaseCurrent(view);
        view.busy=false;view.pending=false;view.needsReload=true;
        // Reload minimal server-authorized service data, including after a recovered page.
        if(view.order?.orderId!==proof.orderId)view.order={orderId:proof.orderId,items:[{itemId:proof.itemId,itemName:'服務品項'}]};
        renderServiceCaseOrder(view);await loadServiceCaseItem(proof.itemId);serviceCaseCurrent(view);
        if(!view.data)throw Error('案件進度重新載入失敗，請重新開啟查詢。');
        renderServiceCaseOrder(view);document.getElementById('serviceItemChoice').value=proof.itemId;renderServiceCaseItem(view);
        serviceCaseMessage(view,'服務操作已確認。');
    }catch(error){
        if(serviceCaseView===view&&view.uid===currentUser?.uid&&view.role===currentUserRole&&view.generation===sessionDataGeneration){
            view.busy=false;
            try{const saved=pendingServiceCaseIntent();if(saved)renderServiceCasePending(view,saved);else document.getElementById('serviceCaseFields')?.removeAttribute('disabled');}
            catch(storageError){document.getElementById('serviceCaseBody').textContent=storageError.message;}
            serviceCaseMessage(view,(confirmed?'服務操作已確認；':'')+error.message);
        }
    }finally{if(serviceCaseView===view)view.busy=false;}
};
// Transaction service shared by both dispatch UI entrances. A frozen attempt
// identifies paperwork only; inventory, shipment and customer delivery do not change.
async function prepareV2OrderDispatchEmulator(orderId,itemId,intent,assertActor) {
    const local=host=>['localhost','127.0.0.1'].includes(host);
    if(globalThis.YUSHIN_V2_DISPATCH_EMULATOR!==true||!local(globalThis.location?.hostname)
        ||typeof firebase==='undefined'||!firebase.auth||!firebase.functions)
        throw new Error('v2 打單傳輸僅限明確啟用的本機 Emulator。');
    const auth=firebase.auth(),functions=firebase.app().functions('asia-east1');
    if(auth.app?.options?.projectId!=='demo-yushin'||functions.app?.options?.projectId!=='demo-yushin'
        ||!local(auth.emulatorConfig?.host)||auth.emulatorConfig?.port!==9099)
        throw new Error('v2 打單須使用 demo-yushin 的本機登入與 Functions Emulator。');
    const assertSession=()=>{assertActor();if(auth.currentUser?.uid!==intent.actorUid)
        throw new Error('實際登入帳號已變更，請以原身分確認打單結果。');};
    assertSession();
    if(typeof intent.syncAttemptId!=='string'||!intent.syncAttemptId||intent.syncAttemptId.length>96)
        throw new Error('缺少原 v2 同步識別碼，請保留原作業並重新核對。');
    functions.useEmulator('127.0.0.1',5001);
    let reply;
    try{reply=await functions.httpsCallable('prepareV2OrderDispatch')({orderId,itemId,
        quantity:intent.quantity,operationId:intent.operationId,syncAttemptId:intent.syncAttemptId,
        expectedPreparedQty:intent.expectedPreparedQty});}
    catch(error){
        if(error.code==='functions/failed-precondition'&&error.details?.reason==='dispatch-stale'){
            const stale=new Error(error.message);stale.code='dispatch-stale';throw stale;
        }
        throw error;
    }
    assertSession();const result=reply?.data;
    if(!['applied','already-applied'].includes(result?.status)||result.orderId!==orderId||result.itemId!==itemId
        ||result.qty!==intent.quantity||result.recordId!=='v2-'+intent.operationId)
        throw new Error('v2 打單回覆不明確，請保留原識別碼重試。');
    // Refresh actual source data; never synthesize an order from result counters.
    const source=await db.collection('orders').doc(orderId).get();assertSession();
    if(!source.exists)throw new Error('打單可能已提交，但找不到最新訂單，請以原識別碼重試。');
    return source.data();
}
async function prepareOrderDispatch(orderId,itemId,attempt) {
    const actorUid=currentUser?.uid,actorRole=currentUserRole;
    const assertActor=()=>{
        if(!actorUid||currentUser?.uid!==actorUid||currentUserRole!==actorRole
            ||!['admin','purchaser'].includes(actorRole))throw new Error('登入帳號或角色已變更，請以原身分確認打單結果。');
    };
    assertActor();
    if(!attempt||!/^dispatch-ui-[a-zA-Z0-9_-]{12,80}$/.test(attempt.operationId||'')
        ||attempt.orderId!==orderId||attempt.itemId!==itemId||attempt.actorUid!==actorUid||attempt.actorRole!==actorRole
        ||!Number.isFinite(attempt.quantity)||attempt.quantity<=0
        ||!Number.isFinite(attempt.expectedPreparedQty)||attempt.expectedPreparedQty<0)
        throw new Error('打單作業資料不正確，請以原身分重新核對。');
    const intent={...attempt};
    if(globalThis.YUSHIN_V2_DISPATCH_EMULATOR===true)
        return prepareV2OrderDispatchEmulator(orderId,itemId,intent,assertActor);
    if(intent.syncAttemptId!==undefined)throw new Error('原 v2 打單作業不可改用一般交易重送。');
    let saved;
    await runRoleTransaction(async tx=>{
        assertActor();
        const ref=db.collection('orders').doc(orderId);
        const dispatchRef=db.collection('dispatchRecords').doc(intent.operationId);
        const snap=await tx.get(ref),prior=await tx.get(dispatchRef);
        assertActor();
        if(!snap.exists)throw new Error('找不到訂單。');
        const order=snap.data();
        if(prior.exists){
            const record=prior.data();
            if(record.orderId!==orderId||record.itemId!==itemId||record.preparedByUid!==actorUid
                ||record.actorRole!==actorRole||record.qty!==intent.quantity
                ||record.expectedPreparedQty!==intent.expectedPreparedQty||record.operationId!==intent.operationId)
                throw new Error('打單操作識別碼已用於其他作業。');
            saved=order;return;
        }
        if(normalizedOrderStatus(order)!=='normal')throw new Error('已取消訂單不能打單。');
        const tradeValidation=globalThis.YushinOrderEntry.validateTrade(order);
        if(!tradeValidation.valid)throw new Error(tradeValidation.message);
        const items=normalizedOrderItems(order),index=items.findIndex(item=>item.itemId===itemId);
        if(index<0)throw new Error('找不到訂單品項。');
        const item=items[index];
        if((item.fulfillmentType||'WAREHOUSE')!=='WAREHOUSE'
            ||String(item.productType||item.type||'').toUpperCase()==='SERVICE')
            throw new Error('此品項不屬於實體倉庫打單。');
        // Do not route the Emulator-only multi-location contract through scalar UI.
        // The existing stock wrapper rejects ALL unsupported location markers on read.
        await tx.get(db.collection('inventoryReservations').doc(orderId+'__'+itemId));
        assertActor();
        const state=itemDispatchState(order,item);
        if(state.prepared!==intent.expectedPreparedQty||state.pending<intent.quantity){
            const error=new Error('待打單資料已變更，請更新訂單後重新確認數量。');
            error.code='dispatch-stale';throw error;
        }
        const now=new Date().toISOString(),actor=deliveryActor();
        items[index]={...item,dispatchPreparedQty:state.prepared+intent.quantity};
        tx.set(dispatchRef,{
            orderId,itemId,qty:intent.quantity,operationId:intent.operationId,
            expectedPreparedQty:intent.expectedPreparedQty,actorRole,
            ownerUid:order.ownerUid||'',salesCode:order.salesCode||'',
            customerName:order.customerName||'',itemCode:item.itemCode||'',itemName:item.itemName||'',
            preparedByUid:actorUid,preparedBy:actor,createdAt:now
        });
        const nextOrder={...order,items,updatedAt:now};
        assertActor();
        tx.update(ref,{items,...orderWorkIndexFields(nextOrder),updatedAt:now});
        saved=nextOrder;
    });
    assertActor();
    return saved;
}
// Shared supplier commitment workflow for initial and manual self-orders.
async function registerInitialSelfOrderSupply(orderId,itemId,details) {
    return (await commitSelfOrderSupply(orderId,itemId,{...details,initial:true})).order;
}

async function commitSelfOrderSupply(orderId,itemId,{supplier,qty,unitCost,orderDate,notes='',actorUid=currentUser?.uid,actorRole=currentUserRole,initial=false,operationId=''}) {
        if(typeof supplier!=='string'||!supplier.trim()||!Number.isFinite(qty)||qty<=0||!Number.isFinite(unitCost)||unitCost<0||typeof notes!=='string')
            throw new Error('請填寫供應商、有效訂貨數量與實際單位成本（可填 0）。');
        if(typeof orderDate!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(orderDate)||!Number.isFinite(Date.parse(orderDate+'T00:00:00Z'))||new Date(orderDate+'T00:00:00Z').toISOString().slice(0,10)!==orderDate)
            throw new Error('請填寫正確的訂貨日期。');
        if(!initial&&(typeof operationId!=='string'||!operationId.trim()||operationId.includes('/')))
            throw new Error('缺少有效自行訂貨作業識別碼，請重新開啟表單。');
        supplier=supplier.trim();notes=notes.trim();
        const role=actorRole,actor=deliveryActor(),now=new Date().toISOString();
        const assertActor=()=>{if(currentUser?.uid!==actorUid||currentUserRole!==role)throw new Error('登入身份已變更，請以原帳號重試同步。');};
        assertActor();
        const supplyRef=supplyOrdersCollection().doc(initial?`self-${encodeURIComponent(orderId)}-${encodeURIComponent(itemId)}`:operationId);
        let savedOrder,internalNo='';
        await runRoleTransaction(async tx=>{
            const orderRef=db.collection('orders').doc(orderId);
            const snap=await tx.get(orderRef);
            assertActor();
            if(!snap.exists)throw new Error('找不到訂單。');
            const order=snap.data();

            if(!initial&&orderInventorySyncIncomplete(order))throw new Error('訂單庫存尚未同步完成');
            if(!canBusinessSelfOrder(order)&&!(initial&&canCreatePurchaseOrderCapability()))throw new Error('只有此訂單負責業務可自行訂貨。');
            if(normalizedOrderStatus(order)!=='normal')throw new Error('已取消訂單不能自行訂貨。');
            const items=normalizedOrderItems(order);
            const index=items.findIndex(row=>row.itemId===itemId);
            if(index<0)throw new Error('找不到訂單品項。');
            const item=items[index];
            if ((item.procurementType || order.procurementType || 'PURCHASING_PO') !== 'SALES_SELF_ORDER') throw new Error('此品項設定為交由採購，不能自行訂貨。');
            const existingSupply=await tx.get(supplyRef);
            assertActor();
            if(existingSupply.exists){
                const prior=existingSupply.data();
                if(prior.type!=='SALES_SELF_ORDER'||prior.sourceId!==orderId||prior.sourceItemId!==itemId
                    ||Number(prior.qty)!==qty||Number(prior.unitCost)!==unitCost||prior.supplier!==supplier
                    ||prior.orderDate!==orderDate||String(prior.notes||'')!==notes)
                    throw new Error('自行訂貨作業識別碼衝突，請先核對原訂貨紀錄。');
                savedOrder=order;internalNo=prior.internalNo;return;
            }
            const already=Math.max(0,Number(item.supplyOrderedQty||0));
            const demand=procurementDemandForOrderItem({...order,id:orderId},item);
            const remaining=demand.remainingToOrderQty;
            if(qty>remaining+1e-9)throw new Error(`目前尚未訂貨數量只有 ${remaining}。`);
            internalNo=`SO-${orderDate.replace(/-/g,'')}-${initial?`${orderId.slice(-6)}-${itemId.slice(-6)}`.toUpperCase():supplyRef.id.slice(-6).toUpperCase()}`;
            const demandOrderPlan=globalThis.YushinProcurementDemand.applyOrder(demand,qty);
            if(demandOrderPlan.appliedQty!==qty)throw new Error('採購需求數量已變更，請重新整理後再試。');
            const demandRef=procurementDemandRef(demand.demandId);
            const demandDoc=procurementDemandDocument(demandOrderPlan.demand,{
                productId:item.productId||'',
                productKey:inventoryProductKey(item),
                itemCode:item.itemCode||'',
                itemName:item.itemName||'',
                brand:item.brand||'',
                fulfillmentType:item.fulfillmentType||'WAREHOUSE',
                warehouseId:(item.fulfillmentType||'WAREHOUSE')==='DIRECT_SHIP'?'':(item.warehouseId||defaultWarehouse()?.id||''),
                ownerUid:order.ownerUid||currentUser?.uid||'',
                salesCode:order.salesCode||currentUserCode||'',
                salesName:order.salesName||currentUserName||'',
                scheduleDate:item.scheduleDate||order.expectedDate||''
            },{
                createdAt:order.createdAt||now,
                updatedAt:now
            });
            const record={
                type:'SALES_SELF_ORDER',method:'SALES_SELF_ORDER',
                sourceType:'SALES_ORDER',sourceId:orderId,sourceItemId:itemId,demandId:demand.demandId||'',
                internalNo,status:'ORDERED',orderId,itemId,
                ownerUid:order.ownerUid||currentUser?.uid||'',salesCode:order.salesCode||currentUserCode||'',
                salesName:order.salesName||currentUserName||'',
                customerName:order.customerName||'',productId:item.productId||'',productKey:inventoryProductKey(item),
                itemCode:item.itemCode||'',itemName:item.itemName||'',brand:item.brand||'',
                qty,receivedQty:0,supplier,unitCost,orderDate,notes,
                fulfillmentType:item.fulfillmentType||'WAREHOUSE',
                warehouseId:(item.fulfillmentType||'WAREHOUSE')==='DIRECT_SHIP' ? '' : (item.warehouseId||defaultWarehouse()?.id||''),
                createdAt:now,createdByUid:actorUid,createdBy:actor,createdByRole:role
            };
            if(!globalThis.YushinSupply?.validate)throw new Error('供應核心未載入，無法登記自行訂貨。');
            const validation=globalThis.YushinSupply.validate(record);
            if(!validation.valid)throw new Error('自行訂貨資料不完整：'+validation.errors.join(', '));
            assertActor();
            tx.set(supplyRef,record);
            if(demandRef)tx.set(demandRef,demandDoc,{merge:true});
            items[index]={
                ...item,
                supplyOrderedQty:already+qty,
                supplier,costPrice:unitCost,
                selfOrderNos:[...new Set([...(item.selfOrderNos||[]),internalNo])],
                orderedAt:item.orderedAt && item.orderedAt < orderDate ? item.orderedAt : orderDate,
                orderEvents:[
                    ...(item.orderEvents||[]).filter(event=>event.id!==supplyRef.id),
                    {id:supplyRef.id,type:'SALES_SELF_ORDER',at:now,date:orderDate,qty,documentNo:internalNo,by:actor}
                ]
            };
            savedOrder={...order,items,itemCount:items.length,orderSchemaVersion:2,updatedAt:now};
            tx.update(orderRef,{items,itemCount:items.length,orderSchemaVersion:2,...orderWorkIndexFields(savedOrder),updatedAt:now});
        });
    return {order:savedOrder,internalNo};
}

async function registerInitialSelfOrders(orderId,order,actorUid=currentUser?.uid,actorRole=currentUserRole) {
    if(order.selfOrderAtCreation!==true)return;
    let changed=false;
    try{
        for(const item of normalizedOrderItems(order)){
            if((item.procurementType||order.procurementType)!=='SALES_SELF_ORDER'||item.selfOrderConfirmed!==true)continue;
            const qty=remainingProcurementQty(order,item);
            if(qty<=0)continue;
            const saved=await registerInitialSelfOrderSupply(orderId,item.itemId,{supplier:item.supplier,qty,unitCost:Number(item.costPrice),orderDate:order.orderDate,actorUid,actorRole});
            Object.assign(order,saved);
            changed=true;
        }
    }finally{
        // Refresh the pending demand once per order, even if a later line fails.
        if(changed)invalidateProcurementDemandQueue();
    }
}
function normalizedOrderItems(order) {
    const source = Array.isArray(order?.items) ? order.items : [];
    const deliveryRecords = Array.isArray(order?.deliveryRecords) ? order.deliveryRecords : null;
    const returnRecords = Array.isArray(order?.returnRecords) ? order.returnRecords : null;
    const singleItem = source.length === 1;
    const singleItemId = singleItem ? String(source[0]?.itemId || 'item-1') : '';
    const deliveryQtyByItemId = new Map();
    const returnQtyByItemId = new Map();

    // 一張訂單先各掃一次送貨／退貨紀錄，再由 itemId O(1) 取值。
    // 避免多品項＋多次分批送貨時，每個品項都重新 filter 整份紀錄。
    if (deliveryRecords) {
        deliveryRecords.forEach(row => {
            const itemId = String(row?.itemId || singleItemId || '');
            if (!itemId) return;
            deliveryQtyByItemId.set(itemId,
                (deliveryQtyByItemId.get(itemId) || 0) + Math.max(0, Number(row?.qty || 0)));
        });
    }
    if (returnRecords) {
        returnRecords.forEach(row => {
            const itemId = String(row?.itemId || singleItemId || '');
            if (!itemId || row.settlement === 'CLOSE') return;
            returnQtyByItemId.set(itemId,
                (returnQtyByItemId.get(itemId) || 0) + Math.max(0, Number(row?.qty || 0)));
        });
    }

    return source.map((item, index) => {
        const itemId = String(item.itemId || `item-${index + 1}`);
        // 送貨／退貨紀錄是實際履約的權威來源。若只使用 items 內舊的累計欄位，
        // 「已全數送貨 → 退貨 → 補送」時會把已送過的數量重新誤判成缺貨。
        const grossDeliveredQty = deliveryRecords
            ? (deliveryQtyByItemId.get(itemId) || 0)
            : Math.max(0,Number(item.deliveredQty||0));
        const returnedQty = returnRecords
            ? (returnQtyByItemId.get(itemId) || 0)
            : Math.max(0,Number(item.returnedQty||0));
        const brandIdentity = brandIdentityForRecord(item);
        const base = {
            ...item,
            itemId,
            itemCodeKey: item.itemCodeKey || normalizeHistoryItemCode(item.itemCode || ''),
            brand: brandIdentity.brand,
            brandId: brandIdentity.brandId,
            qty: Number(item.qty || item.orderedQty || 0),
            unitPrice: parseMoney(item.unitPrice || 0),
            totalPrice: parseMoney(item.totalPrice || 0),
            fulfillmentType: item.fulfillmentType || 'WAREHOUSE',
            warehouseId: item.fulfillmentType === 'DIRECT_SHIP' ? '' : (item.warehouseId || ''),
            deliveredQty: grossDeliveredQty,
            returnedQty
        };
        const normalized = window.YushinFulfillment ? window.YushinFulfillment.normalizeItem(base, index) : base;
        // 僅在記憶體標記這個物件的送貨／退貨量已由 deliveryRecords / returnRecords 索引完成。
        // non-enumerable 不會被 spread / JSON / Firestore 寫回，避免快照欄位變成持久資料。
        try {
            Object.defineProperty(normalized, '__fulfillmentSnapshot', {
                value:true, enumerable:false, configurable:true
            });
        } catch (_) {}
        return normalized;
    });
}

function ensureOrderItemCompatibility(order) {
    const items = normalizedOrderItems(order);
    order.items = items;
    order.productIds = productIdsFromItems(items);
    order.orderSchemaVersion = 2;
    order.itemCount = items.length;
    return order;
}

function orderQuantity(order, normalizedItems = null) {
    return (normalizedItems || normalizedOrderItems(order))
        .reduce((sum,item)=>sum+Math.max(0,Number(item.qty||0)),0);
}

function savedDeliveryRecords(order) {
    return Array.isArray(order?.deliveryRecords) ? order.deliveryRecords : [];
}

function deliveredQuantity(order, normalizedItems = null) {
    const records = savedDeliveryRecords(order);
    if (records.length) return records.reduce((sum, record) => sum + (parseFloat(record.qty) || 0), 0);
    // 舊資料只有「已送貨」布林值：視為全數送貨，但不在未確認前改寫雲端資料。
    return order?.isDelivered ? orderQuantity(order, normalizedItems) : 0;
}

// One projection for both the delivery card and lifecycle status. CLOSED
// returns do not require replacement stock; never deduct them twice.
function orderDeliveryProjection(order, normalizedItems = null) {
    if (!globalThis.YushinFulfillment?.projectOrderDelivery)
        throw new Error('Fulfillment core 未載入，無法計算有效交付數量。');
    return globalThis.YushinFulfillment.projectOrderDelivery({
        grossDeliveredQty: deliveredQuantity(order, normalizedItems),
        returnedQty: returnedQuantity(order),
        returnRecords: savedReturnRecords(order)
    });
}

function deliveryProgressInfo(order, normalizedItems = null) {
    const total = orderQuantity(order, normalizedItems);
    const {grossDelivered,returned,effectiveDelivered} = orderDeliveryProjection(order, normalizedItems);
    const delivered = Math.min(effectiveDelivered, total || effectiveDelivered);
    const remaining = Math.max(0, total - delivered);
    const isLegacyEstimated = !!order?.isDelivered && savedDeliveryRecords(order).length === 0;
    const state = total > 0 && delivered >= total ? 'complete' : delivered > 0 ? 'partial' : 'none';
    const label = state === 'complete' ? `已送 ${delivered}/${total}` : state === 'partial' ? `部分 ${delivered}/${total}` : `未送 0/${total || 0}`;
    return { total, delivered, grossDelivered, returned, remaining, state, label, isLegacyEstimated };
}

function savedReturnRecords(order) {
    return Array.isArray(order?.returnRecords) ? order.returnRecords : [];
}

function returnedQuantity(order) {
    return savedReturnRecords(order).reduce((sum, record) => sum + (parseFloat(record.qty) || 0), 0);
}

function normalizedOrderStatus(order) {
    // UI 將取消／作廢視為同一個「不可繼續履約」狀態；底層 status 仍保留 cancelled / voided 以利稽核。
    const canonical = order?.status || '';
    const legacy = order?.orderStatus || '';
    if ([BUSINESS_STATUS.CANCELLED, BUSINESS_STATUS.VOIDED, 'cancelled', 'voided'].includes(canonical)
        || ['cancelled', 'voided'].includes(legacy)) return 'cancelled';
    return 'normal';
}

function orderLifecycleInfo(order, normalizedItems = null) {
    const {grossDelivered:delivered,returned,effectiveDelivered} = orderDeliveryProjection(order, normalizedItems);
    const status = normalizedOrderStatus(order);
    if (status === 'cancelled') return { status, label: '已取消', css: 'invalid', delivered, returned, effectiveDelivered };
    if (savedReturnRecords(order).some(r=>r.settlement==='CLOSE')) return {status,label:'退貨已收貨・不補送',css:'returned',delivered,returned,effectiveDelivered};
    if (returned > 0 && effectiveDelivered <= 0) return { status, label: '全數退貨・待補送', css: 'returned', delivered, returned, effectiveDelivered };
    if (returned > 0) return { status, label: '部分退貨・待補送', css: 'returned', delivered, returned, effectiveDelivered };
    return { status, label: '正常', css: 'normal', delivered, returned, effectiveDelivered };
}

function purchaseProgressInfo(order) {
    const items=normalizedOrderItems(order);
    if (!items.length) return {state:'not_required',label:'無需採購'};
    let pending=0,inTransit=0,everOrdered=0;
    let allDirect=true;
    items.forEach(item=>{
        const direct=(item.fulfillmentType||order.fulfillmentType||'WAREHOUSE')==='DIRECT_SHIP';
        if(!direct) allDirect=false;
        const dispatch=itemDispatchState(order,item);
        const returnedQty=direct?dispatch.returned:Number(item.returnedQty??dispatch.returned??0);
        if (!globalThis.YushinWorkflow?.procurementQuantities) {
            throw new Error('Workflow core 未載入，無法計算採購進度。');
        }
        const quantities=globalThis.YushinWorkflow.procurementQuantities({
            orderedQty:item.orderedQty??item.qty,
            fulfillmentType:item.fulfillmentType||order.fulfillmentType||'WAREHOUSE',
            productType:item.productType||order.productType||'',
            reservedQty:item.reservedQty,
            shortageQty:item.shortageQty,
            supplyOrderedQty:item.supplyOrderedQty,
            receivedQty:item.receivedQty,
            deliveredQty:dispatch.grossDelivered,
            effectiveDeliveredQty:dispatch.delivered,
            returnedQty
        });
        pending+=quantities.remainingToOrderQty;
        inTransit+=quantities.inTransitQty;
        everOrdered+=quantities.supplyOrderedQty;
    });
    if(pending>0&&inTransit>0)return {state:'partial',label:`待採購 ${pending}／在途 ${inTransit}`};
    if(pending>0)return {state:'pending',label:`待採購 ${pending}`};
    if(inTransit>0)return {state:'ordered',label:`已採購・待到貨 ${inTransit}`};
    if(everOrdered>0)return {state:'ordered',label:'採購完成'};
    if(allDirect)return {state:'direct',label:'原廠直送'};
    return {state:'not_required',label:'無需採購'};
}

function fulfillmentProgressInfo(order, normalizedItems = null, dispatchStateByItem = null) {
    const allItems=normalizedItems || normalizedOrderItems(order);
    const items=allItems.filter(item=>(item.fulfillmentType||'WAREHOUSE')!=='DIRECT_SHIP'
        &&String(item.productType||'').trim().toUpperCase()!=='SERVICE');
    const total=items.reduce((s,item)=>s+Number(item.orderedQty||item.qty||0),0);
    const states=items.map(item=>{const state=dispatchStateByItem?.get(item) || itemDispatchState(order,item);return globalThis.YushinWarehouseLogistics?.businessDeliveryState?globalThis.YushinWarehouseLogistics.businessDeliveryState(order,item,state,defaultWarehouse()?.id||''):state;});
    const ready=states.reduce((s,state)=>s+state.reserved,0);
    const prepared=states.reduce((s,state)=>s+state.prepared,0);
    const delivered=states.reduce((s,state)=>s+state.delivered,0);
    const shippable=states.reduce((s,state)=>s+state.shippable,0);
    const pendingDispatch=states.reduce((s,state)=>s+state.pending,0);
    if(!items.length)return allItems.some(item=>String(item.productType||'').trim().toUpperCase()==='SERVICE')
        ? {state:'not_required',label:'無需實貨出貨',total:0,ready:0,prepared:0,delivered:0,shippable:0,pendingDispatch:0}
        : {state:'direct',label:'原廠直送',total:0,ready:0,prepared:0,delivered:0,shippable:0,pendingDispatch:0};
    if(total>0 && delivered>=total)return {state:'complete',label:'出貨完成',total,ready,prepared,delivered,shippable:0,pendingDispatch:0};
    if(shippable>0)return {state:'shippable',label:`可出貨 ${shippable}/${total}`,total,ready,prepared,delivered,shippable,pendingDispatch};
    if(pendingDispatch>0)return {state:ready>=Math.max(0,total-delivered)?'pending_dispatch':'partial_dispatch',label:`待打單 ${pendingDispatch}/${total}`,total,ready,prepared,delivered,shippable,pendingDispatch};
    const waiting=states.find(state=>state.deliveryWait);if(waiting&&ready>0)return {state:'pending',label:waiting.deliveryWait,total,ready,prepared,delivered,shippable,pendingDispatch};
    return {state:'pending',label:`待備貨 0/${total}`,total,ready,prepared,delivered,shippable,pendingDispatch};
}

const pendingDispatchOrderIds = new Set();

function itemDispatchState(order, item) {
    if(orderInventorySyncIncomplete(order))return {ordered:Number(item.orderedQty||item.qty||0),reserved:0,prepared:0,delivered:0,grossDelivered:0,returned:0,shippable:0,pending:0};
    if(globalThis.YUSHIN_V2_DISPATCH_EMULATOR===true){
        // The Emulator bridge consumes physical shipments, not acknowledgements.
        const source=order.items?.find(row=>row.itemId===item.itemId)||item;
        return {...globalThis.YushinFulfillment.warehouseShipmentState(source),
            delivered:source.deliveredQty??0,grossDelivered:source.deliveredQty??0,returned:source.returnedQty??0};
    }
    // deliveryRecords / returnRecords 仍由頁面層整理；所有物流數量公式交給 fulfillment-core。
    // 這樣訂單頁、採購頁與實際送貨動作不會各自維護一套「待打單／可出貨」算法。
    const hasSnapshot = item?.__fulfillmentSnapshot === true;
    const singleItem = Array.isArray(order?.items) && order.items.length === 1;
    const grossDelivered = hasSnapshot
        ? Math.max(0, Number(item.deliveredQty || 0))
        : savedDeliveryRecords(order).filter(r => ((!r.itemId && singleItem) || r.itemId === item.itemId))
            .reduce((sum, r) => sum + Number(r.qty || 0), 0);
    const returned = hasSnapshot
        ? Math.max(0, Number(item.returnedQty || 0))
        : savedReturnRecords(order).filter(r => r.settlement !== 'CLOSE' && ((!r.itemId && singleItem) || r.itemId === item.itemId))
            .reduce((sum, r) => sum + Number(r.qty || 0), 0);
    if (!globalThis.YushinFulfillment?.dispatchState) {
        throw new Error('Fulfillment core 未載入，無法計算出貨狀態。');
    }
    const dispatchState=globalThis.YushinFulfillment.dispatchState({
        ...item,
        orderedQty: item.orderedQty ?? item.qty,
        deliveredQty: grossDelivered,
        returnedQty: returned
    });
    return item.transferPendingId?{...dispatchState,shippable:0,pending:0,transferring:dispatchState.reserved}:dispatchState;
}

function orderLifecycleActionButtons(order, lifecycle, progress, actions) {
    if (!canManageOrderLifecycleCapability() || !canEditPage('orders.list')) return '';
    if (pendingLifecycleOrderIds.has(order.id)) return '<button type="button" disabled>處理中…</button>';
    const id = inlineJsValue(order.id);
    try{
        const retry=globalThis.YUSHIN_V2_LIFECYCLE_EMULATOR===true?pendingV2OrderLifecycle(order.id):null;
        if(retry)return `<button type="button" onclick="quickSetOrderLifecycle(${id}, ${inlineJsValue(retry.nextStatus)})">確認前次取消／恢復結果</button>`;
    }catch(err){return `<span role="alert">${escapeHtml(err.message)}</span>`;}
    const buttons = [];
    if (lifecycle.status === 'normal') {
        if (actions.showPartialDelivery) buttons.push(`<button type="button" onclick="openPartialDeliveryForOrder(${id})">分批交貨</button>`);
        if (progress.remaining > 0) buttons.push(`<button type="button" class="danger-menu-item" onclick="quickSetOrderLifecycle(${id}, 'cancelled')">${progress.delivered > 0 ? '取消剩餘未送貨數量' : '取消訂單'}</button>`);
    } else {
        buttons.push(`<button type="button" onclick="quickSetOrderLifecycle(${id}, 'normal')">恢復訂單</button>`);
    }
    if (actions.showReturn) buttons.push(`<button type="button" onclick="openReturnManagement(${id})">退貨</button>`);
    return buttons.join('');
}

// Only a fully ready single-item order is safe for one-click delivery.
// Multi-item and partly printed orders must choose an exact item and quantity.
function orderDeliveryRequiresItemForm(items, deliveryProgress, fulfillmentProgress) {
    return (items || []).length !== 1
        || Number(fulfillmentProgress?.shippable || 0) + 1e-9 < Number(deliveryProgress?.remaining || 0);
}

function orderContextActionState(order, normalizedItems = null, dispatchStateByItem = null) {
    const items = normalizedItems || normalizedOrderItems(order);
    const states = items.map(item => dispatchStateByItem?.get(item) || itemDispatchState(order, item));
    const grossDelivered = states.reduce((sum, state) => sum + Math.max(0, Number(state.grossDelivered || 0)), 0);
    const returned = states.reduce((sum, state) => sum + Math.max(0, Number(state.returned || 0)), 0);
    const netDelivered = Math.max(0, grossDelivered - returned);
    // 「分批交貨」只在真的有部分到貨品項時出現。
    // 全數到貨走一般送貨流程；尚未到貨則不提供分批交貨，避免操作選單過早出現。
    const hasPartialArrival = items.some((item, index) => {
        const ordered = Math.max(0, Number(item.orderedQty || item.qty || 0));
        const received = Math.max(0, Number(item.receivedQty || 0));
        const state = states[index];
        // 分批交貨不只要「部分到貨」，還必須真的有尚未交付、目前可出貨的數量。
        // 避免部分到貨紀錄存在，但該批已全數送出時仍顯示無效操作。
        return ordered > 0 && received > 0 && received < ordered && Number(state?.shippable || 0) > 0;
    });
    let showPartialDelivery=hasPartialArrival || (items.length > 1 && states.some(state => Number(state?.shippable || 0) > 0));
    if(globalThis.YUSHIN_V2_DELIVERY_EMULATOR===true){
        try{
            // Customer acknowledgement consumes shipped quota. Once all printed
            // goods leave the warehouse, shippable is zero but arrival is pending.
            const frozen=pendingV2DeliveryConfirmation(order.id);
            const projected=globalThis.YushinFulfillment.projectOrderShipmentReturns({orderId:order.id,items:order.items,
                shipments:order.warehouseShipmentRecords||[],deliveries:order.deliveryRecords||[],returns:order.returnRecords||[]});
            showPartialDelivery=!!frozen||(!orderInventorySyncIncomplete(order)
                &&(order.returnRecords||[]).every(row=>row.settlement==='CLOSE')&&projected.pendingDeliveryQty>0);
        }catch(_){showPartialDelivery=false;}
    }
    return {
        showPartialDelivery: normalizedOrderStatus(order) === 'normal'
            && showPartialDelivery,
        showReturn: netDelivered > 0
    };
}

function dispatchActionHtml(order, normalizedItems = null, dispatchStateByItem = null) {
    if(orderInventorySyncIncomplete(order))return '';
    if (!(currentUserRole === 'purchaser' || currentUserRole === 'admin')) return '';
    if (normalizedOrderStatus(order) !== 'normal') return '';
    return (normalizedItems || normalizedOrderItems(order))
        .filter(item=>(item.fulfillmentType||'WAREHOUSE')!=='DIRECT_SHIP')
        .map(item=>({item,state:dispatchStateByItem?.get(item) || itemDispatchState(order,item)}))
        .filter(x=>x.state.pending>0||pendingDispatchPreparation(order.id,x.item.itemId))
        .map(({item,state})=>`<button type="button" onclick="markOrderItemDispatchPrepared(${inlineJsValue(order.id)},${inlineJsValue(item.itemId)})" ${pendingDispatchOrderIds.has(order.id+'__'+item.itemId)?'disabled':''}>${pendingDispatchPreparation(order.id,item.itemId)?'確認打單結果':'待打單'}：${escapeHtml(item.itemCode||item.itemName||item.itemId)} × ${pendingDispatchPreparation(order.id,item.itemId)?.quantity||state.pending}</button>`)
        .join('');
}

// Frozen UI intents survive refresh and uncertain replies. Both pages use this
// same entry; quantities are proposals from itemDispatchState, never a new formula.
function dispatchPreparationStorageKey(orderId,itemId,uid=currentUser?.uid) {
    return 'yushin-dispatch-attempt:'+JSON.stringify([uid,orderId,itemId]);
}
function pendingDispatchPreparation(orderId,itemId) {
    try{return JSON.parse(sessionStorage.getItem(dispatchPreparationStorageKey(orderId,itemId))||'null');}
    catch(_){return null;}
}
window.markOrderItemDispatchPrepared = async function(orderId,itemId) {
    if (!(currentUserRole === 'purchaser' || currentUserRole === 'admin')) return;
    const actorUid=currentUser?.uid,actorRole=currentUserRole;
    if(!actorUid)return;
    const isCurrent=()=>currentUser?.uid===actorUid&&currentUserRole===actorRole;
    const key=orderId+'__'+itemId;
    if(pendingDispatchOrderIds.has(key))return;
    pendingDispatchOrderIds.add(key);
    try{
        const storageKey=dispatchPreparationStorageKey(orderId,itemId,actorUid);
        let attempt=pendingDispatchPreparation(orderId,itemId);
        if(!attempt){
            const order=ordersCache.find(o=>o.id===orderId)||purchasingDispatchCache.find(o=>o.id===orderId);
            const item=order&&normalizedOrderItems(order).find(i=>i.itemId===itemId);
            if(!item)throw new Error('找不到品項，請更新訂單後重試。');
            const state=itemDispatchState(order,item);
            if(state.pending<=0)throw new Error('此品項目前沒有待打單數量。');
            attempt={operationId:'dispatch-ui-'+db.collection('dispatchRecords').doc().id,
                orderId,itemId,actorUid,actorRole,quantity:state.pending,expectedPreparedQty:state.prepared};
            if(globalThis.YUSHIN_V2_DISPATCH_EMULATOR===true)attempt.syncAttemptId=order.inventoryReservationAttemptId;
            // If persistence is unavailable, do not submit an unresumable operation.
            sessionStorage.setItem(storageKey,JSON.stringify(attempt));
        }
        if (document.getElementById('order-system')?.classList.contains('active')) renderOrdersList();
        else if (document.getElementById('purchasing-system')?.classList.contains('active')) renderPurchasingDispatchOrders();
        let saved;
        try{saved=await prepareOrderDispatch(orderId,itemId,attempt);}
        catch(err){
            // This code is raised only after reading an absent receipt inside the
            // transaction. Unknown network/permission outcomes retain the intent.
            if(err.code==='dispatch-stale'&&isCurrent())sessionStorage.removeItem(storageKey);
            throw err;
        }
        if(!isCurrent())return;
        sessionStorage.removeItem(storageKey);
        const idx=ordersCache.findIndex(o=>o.id===orderId);
        const savedOrder={...saved,id:orderId};
        if(idx>=0)ordersCache[idx]=savedOrder;
        syncOrderIntoPurchasingCaches(savedOrder, { render:false });
        writeAppDataCache('orders', ordersCache);
    }catch(err){if(isCurrent())alert('打單結果待確認：'+err.message+'\n請更新清單後重試；未確認的作業會沿用原識別碼與數量。');}
    finally{
        pendingDispatchOrderIds.delete(key);
        if(isCurrent()){
            if (document.getElementById('order-system')?.classList.contains('active')) renderOrdersList();
            if (document.getElementById('purchasing-system')?.classList.contains('active')) renderPurchasingView();
            if(currentDeliveryOrderId===orderId)renderDeliveryModal();
        }
    }
};


async function refreshAffectedOrderCaches(orderIds = []) {
    const ids=[...new Set(orderIds.filter(Boolean))];
    if(!ids.length)return;
    const cacheUid=currentUser?.uid||'',cacheRole=currentUserRole;
    const refreshedOrders=await readDocumentsByIds('orders',ids);
    if(!cacheUid||currentUser?.uid!==cacheUid||currentUserRole!==cacheRole)throw new Error('登入帳號或角色已變更，請重新載入訂單清單。');
    refreshedOrders.forEach(order=>{
        const index=ordersCache.findIndex(row=>row.id===order.id);
        if(index>=0)ordersCache[index]=order;else ordersCache.unshift(order);
        syncOrderIntoPurchasingCaches(order, { render:false });
    });
    ordersCache.sort((a,b)=>(b.orderDate||'').localeCompare(a.orderDate||''));
    writeAppDataCache('orders',ordersCache);
    if (document.getElementById('order-system')?.classList.contains('active')) renderOrdersList();
    if (document.getElementById('purchasing-system')?.classList.contains('active')) renderPurchasingView();
}

function canBusinessSelfOrder(order = null) {
    if (currentUserRole === 'admin') return true;
    if (!canSelfOrderCapability(currentUserRole)) return false;
    if (!order) return true;
    return (order.ownerUid && order.ownerUid === currentUser?.uid)
        || (order.salesCode && currentUserCode && order.salesCode === currentUserCode);
}


function selfOrderActionHtml(order, normalizedItems = null, dispatchStateByItem = null) {
    if(!canBusinessSelfOrder(order)||normalizedOrderStatus(order)!=='normal'||orderInventorySyncIncomplete(order))return '';
    return (normalizedItems||normalizedOrderItems(order)).filter(item=>(item.procurementType||order.procurementType)==='SALES_SELF_ORDER'&&remainingProcurementQty(order,item)>0)
        .map(item=>`<button type="button" class="btn-small btn-secondary" onclick="openSelfOrderModal(${inlineJsValue(order.id)},${inlineJsValue(item.itemId)})">確認自行訂貨・${escapeHtml(item.itemCode||item.itemName)}</button>`).join('');
}

function directShipReceiptActionHtml(order, items = normalizedOrderItems(order)) {
    if(normalizedOrderStatus(order)!=='normal'||orderInventorySyncIncomplete(order)||!canConfirmSupplyReceipt({...order,fulfillmentType:'DIRECT_SHIP'}))return '';
    return items.filter(item=>item.fulfillmentType==='DIRECT_SHIP'&&Number(item.supplyOrderedQty||0)>Number(item.receivedQty||0))
        .map(item=>`<button type="button" class="btn-small btn-secondary" onclick="openOrderDirectShipReceipt(${inlineJsValue(order.id)},${inlineJsValue(item.itemId)},this)">確認直送到貨・${escapeHtml(item.itemCode||item.itemName)}</button>`).join('');
}
window.openOrderDirectShipReceipt = async function(orderId,itemId,button) {
    const order=ordersCache.find(row=>row.id===orderId);
    if(!order||!canConfirmSupplyReceipt({...order,fulfillmentType:'DIRECT_SHIP'}))return;
    const uid=currentUser?.uid,role=currentUserRole,state=beginActionButton(button,'讀取中…');
    if(button&&!state)return;
    try{
        let query=db.collection('receivingSupplyOrders').where('orderId','==',orderId).where('itemId','==',itemId).where('fulfillmentType','==','DIRECT_SHIP');
        if(role!=='admin')query=query.where('ownerUid','==',uid);
        const records=await readQueryInBatches(query,50);
        if(uid!==currentUser?.uid||role!==currentUserRole)return;
        const supply=records.filter(row=>canConfirmSupplyReceipt(row)&&!isPurchaseTerminalStatus(row.status)&&Number(row.qty||0)>Number(row.receivedQty||0))
            .sort((a,b)=>String(a.orderDate||'').localeCompare(String(b.orderDate||''))||String(a.id).localeCompare(String(b.id)))[0];
        if(!supply)throw new Error('沒有可確認的直送供應紀錄，請更新訂單後再試。');
        supplyReceivingCache=supplyReceivingCache.filter(row=>row.id!==supply.id).concat(supply);
        openSupplyReceipt(supply.id);
    }catch(err){showActionFeedback('直送到貨確認未開啟：'+err.message,'warning');}
    finally{endActionButton(button,state);}
};

let selfOrderSupplyAttempt = null;
window.openSelfOrderModal = function(orderId,itemId) {
    const order=ordersCache.find(row=>row.id===orderId);
    const item=normalizedOrderItems(order||{}).find(row=>row.itemId===itemId);
    if(!order||!item||orderInventorySyncIncomplete(order)||!canBusinessSelfOrder(order))return;
    const remaining=remainingProcurementQty(order,item);
    if(remaining<=0){alert('此品項目前沒有尚未訂貨的缺貨數量。');return;}
    selfOrderSupplyAttempt=null;
    document.getElementById('selfOrderOrderId').value=orderId;
    document.getElementById('selfOrderItemId').value=itemId;
    document.getElementById('selfOrderSupplier').value=item.supplier||'';
    document.getElementById('selfOrderQty').value=remaining;
    document.getElementById('selfOrderQty').max=remaining;
    document.getElementById('selfOrderUnitCost').value=item.costPrice??'';
    document.getElementById('selfOrderDate').value=localDateString();
    document.getElementById('selfOrderNotes').value='';
    const directShip=(item.fulfillmentType||'WAREHOUSE')==='DIRECT_SHIP';
    document.getElementById('selfOrderStatus').innerText=directShip ? `尚未訂貨 ${remaining}；原廠直送不入庫，到貨後直接更新訂單交貨進度。` : `尚缺 ${remaining}；自行訂貨後會進入待入庫。`;
    document.getElementById('selfOrderItemSummary').innerHTML=`<strong>${escapeHtml(item.itemCode||'')}</strong> ${escapeHtml(item.itemName||'')}<br><span style="color:#666;">客戶：${escapeHtml(order.customerName||'')}</span>`;
    document.getElementById('selfOrderOverlay').classList.add('active');
};

window.closeSelfOrderModal = function() {
    document.getElementById('selfOrderOverlay')?.classList.remove('active');
};

window.saveSelfOrder = async function() {
    if(!canBusinessSelfOrder())return;
    const orderId=document.getElementById('selfOrderOrderId').value;
    const itemId=document.getElementById('selfOrderItemId').value;
    const supplier=document.getElementById('selfOrderSupplier').value.trim();
    const qty=Number(document.getElementById('selfOrderQty').value||0);
    const unitCostText=document.getElementById('selfOrderUnitCost').value.trim();
    const unitCost=Number(unitCostText);
    const orderDate=document.getElementById('selfOrderDate').value||localDateString();
    const notes=document.getElementById('selfOrderNotes').value.trim();
    if(!supplier||!Number.isFinite(qty)||qty<=0||unitCostText===''||!Number.isFinite(unitCost)||unitCost<0){alert('請填寫供應商、有效訂貨數量與實際單位成本（可填 0）。');return;}
    const button=document.getElementById('saveSelfOrderBtn');
    if(button.disabled)return;
    const fingerprint=JSON.stringify([currentUser?.uid,orderId,itemId,supplier,qty,unitCost,orderDate,notes]);
    if(selfOrderSupplyAttempt?.fingerprint!==fingerprint)selfOrderSupplyAttempt={fingerprint,operationId:lifecycleRecordId()};
    button.disabled=true;button.innerText='建立中…';
    try{
        const {order:savedOrder,internalNo}=await commitSelfOrderSupply(orderId,itemId,{supplier,qty,unitCost,orderDate,notes,operationId:selfOrderSupplyAttempt.operationId});
        selfOrderSupplyAttempt=null;
        const index=ordersCache.findIndex(row=>row.id===orderId);
        const committedOrder={id:orderId,...savedOrder};
        if(index>=0)ordersCache[index]=committedOrder;else ordersCache.unshift(committedOrder);
        syncOrderIntoPurchasingCaches(committedOrder, { render:false });
        writeAppDataCache('orders', ordersCache);
        invalidateProcurementDemandQueue();
        closeSelfOrderModal();
        if (document.getElementById('order-system')?.classList.contains('active')) renderOrdersList();
        if (document.getElementById('purchasing-system')?.classList.contains('active')) renderPurchasingView();
        alert(`自行訂貨已建立：${internalNo}`);
    }catch(err){alert('自行訂貨失敗：'+err.message + '\n請確認目前這筆資料及連線／權限，重試前先查詢作業結果；若持續失敗，請聯絡管理員。');}
    finally{button.disabled=false;button.innerText='確認自行訂貨';}
};

function isDeletableOrderDraft(order) {
    if (!order || order.quoteNo || order.purchaseOrderNo) return false;
    const items = normalizedOrderItems(order);
    const hasProcurementEvidence = items.some(item =>
        Math.max(0, Number(item.supplyOrderedQty || 0)) > 0
        || (Array.isArray(item.purchaseDocumentNos) && item.purchaseDocumentNos.some(Boolean))
    ) || (Array.isArray(order.linkedDocuments) && order.linkedDocuments.some(link =>
        link?.type === DOCUMENT_TYPES.PURCHASE_ORDER && link?.id
    ));
    if (hasProcurementEvidence) return false;
    if (order.isDelivered || order.isBilled) return false;
    if (savedDeliveryRecords(order).length || savedReturnRecords(order).length) return false;
    if ((order.statusHistory || []).length || (order.deliveryHistory || []).length || (order.returnHistory || []).length || (order.orderLifecycleHistory || []).length) return false;
    return normalizedOrderStatus(order) === 'normal';
}

function orderWorkCategory(order) {
    // 整張訂單狀態只由各品項的唯一狀態推導，避免另一套 aggregate 判斷
    // 與列表／圖卡／Firestore workCategories 出現不同答案。
    const categories=orderWorkCategories(order);
    if(categories.includes('closed'))return 'closed';
    const priority=['ordering','arrival','delivery','billing','complete'];
    return priority.find(category=>categories.includes(category))||'ordering';
}

function orderItemWorkCategory(order, item, lifecycleOverride = null, dispatchOverride = null) {
    const lifecycle=lifecycleOverride || orderLifecycleInfo(order);
    const dispatch=dispatchOverride || itemDispatchState(order,item);
    const input={
        lifecycleStatus:lifecycle.status,
        returnedQty:dispatch.returned,
        effectiveDeliveredQty:dispatch.delivered,
        orderedQty:item.orderedQty??item.qty,
        deliveredQty:dispatch.grossDelivered,
        isBilled:!!order.isBilled,
        fulfillmentType:item.fulfillmentType||order.fulfillmentType||'WAREHOUSE',
        productType:item.productType||order.productType||'',
        reservedQty:item.reservedQty,
        shortageQty:item.shortageQty,
        supplyOrderedQty:item.supplyOrderedQty,
        receivedQty:item.receivedQty
    };
    // 單一權威來源：畫面、圖卡、採購與 workCategories 全部交給 workflow-core 判斷。
    return YushinWorkflow.itemWorkCategory(input);
}

// 倉庫品項的採購／到貨／送貨仍共用原本的資料狀態；訂單頁依已打單量
// 把可出貨前的工作分成待打單與待出貨，不另建會與庫存紀錄脫節的旗標。
function orderItemDisplayCategory(order, item, lifecycleOverride = null, dispatchOverride = null) {
    const dispatch = dispatchOverride || itemDispatchState(order, item);
    const category = orderItemWorkCategory(order, item, lifecycleOverride, dispatch);
    if (category !== 'delivery') return category;
    if (String(item.productType||'').trim().toUpperCase()==='SERVICE') return category;
    if ((item.fulfillmentType || order.fulfillmentType || 'WAREHOUSE') === 'DIRECT_SHIP') return 'shipping';
    return dispatch.pending > 0 ? 'dispatch' : 'shipping';
}

function orderItemDisplayCategories(order, item, lifecycleOverride = null, dispatchOverride = null) {
    const dispatch = dispatchOverride || itemDispatchState(order, item);
    const category=orderItemDisplayCategory(order,item,lifecycleOverride,dispatch);
    if(category!=='closed'&&['pending','failed'].includes(order?.inventoryReservationStatus))return [];
    const warehouse=(item.fulfillmentType||order.fulfillmentType||'WAREHOUSE')!=='DIRECT_SHIP'
        &&String(item.productType||'').trim().toUpperCase()!=='SERVICE';
    // A single line can be partly printed and partly awaiting paperwork/arrival.
    // Keep both work queues visible, but never present unprinted quantities to sales.
    if(!warehouse || category==='closed' || category==='billing' || category==='complete')return [category];
    const categories=[category];
    if(['ordering','arrival'].includes(category) && dispatch.pending>0)categories.push('dispatch');
    if(category!=='shipping' && dispatch.shippable>0)categories.push('shipping');
    return categories;
}

function orderWorkCategories(order) {
    const lifecycle=orderLifecycleInfo(order);
    if(lifecycle.status!=='normal')return ['closed'];
    const items=normalizedOrderItems(order);
    const categories=[...new Set(items.flatMap(item=>{
        const category=orderItemWorkCategory(order,item);
        const warehouse=(item.fulfillmentType||order.fulfillmentType||'WAREHOUSE')!=='DIRECT_SHIP'
            &&String(item.productType||'').trim().toUpperCase()!=='SERVICE';
        return warehouse && ['ordering','arrival','delivery'].includes(category) && itemDispatchState(order,item).pending>0
            ? [category,'dispatch'] : [category];
    }))];
    if(!categories.length)return ['ordering'];
    return categories;
}

function orderWorkIndexFields(order) {
    const categories=orderWorkCategories(order);
    return {
        workCategories:categories,
        workCategoryUpdatedAt:new Date().toISOString()
    };
}

function orderItemWorkAmount(order, item, category, totalQtyOverride = null, dispatchOverride = null) {
    const qty=Number(item.orderedQty||item.qty||0);
    const totalQty=totalQtyOverride === null ? orderQuantity(order) : totalQtyOverride;
    const explicitSales=[item.unitPrice,item.salesPrice].find(value=>value!==null&&value!==undefined&&String(value).trim()!==''&&Number.isFinite(Number(value)));
    const unitSales=explicitSales!==undefined?Number(explicitSales):(totalQty?salesAmount(order)/totalQty:(parseFloat(order.unitPrice)||0));
    const state=dispatchOverride || itemDispatchState(order,item);
    // Work-card amounts represent quantities in each action queue, not the full
    // order line repeated when the same line is partly printed or partly waiting.
    if(category==='dispatch')return Math.max(0,Number(state.pending||0))*unitSales;
    if(category==='shipping')return Math.max(0,Number(state.shippable||0))*unitSales;
    if(category==='delivery')return Math.max(0,qty-state.delivered)*unitSales;
    if(category==='billing'||category==='complete')return Math.min(qty,state.delivered)*unitSales;
    if(category==='ordering')return Math.max(0,Number(procurementDemandForOrderItem(order,item,state).remainingToOrderQty||0))*unitSales;
    return qty*unitSales;
}

function buildOrderItemWorkMetrics(orders, categories, include = null, normalizedItemsByOrder = null, dispatchStatesByOrder = null, lifecyclesByOrder = null) {
    const metrics = Object.fromEntries(categories.map(category => [category, { count:0, amount:0 }]));
    (orders || []).forEach(order => {
        const items = normalizedItemsByOrder?.get(order.id) || normalizedOrderItems(order);
        const totalQty = items.reduce((sum, item) => sum + Math.max(0, Number(item.qty || 0)), 0);
        const lifecycle = lifecyclesByOrder?.get(order.id) || orderLifecycleInfo(order, items);
        const orderDispatchStates = dispatchStatesByOrder?.get(order.id) || null;
        items.forEach(item => {
            // 工作圖卡同一品項只掃一次送貨／退貨紀錄；分類與金額共用同一份 dispatch state。
            const dispatch = orderDispatchStates?.get(item) || itemDispatchState(order, item);
            orderItemDisplayCategories(order,item,lifecycle,dispatch).forEach(category => {
                if (!metrics[category]) return;
                if (include && !include(order,item,category)) return;
                metrics[category].count++;
                metrics[category].amount += orderItemWorkAmount(order,item,category,totalQty,dispatch);
            });
        });
    });
    return metrics;
}

const OPEN_ORDER_WORK_CATEGORIES = ['ordering','arrival','delivery','dispatch','billing'];
let orderWorkQueueCache = [], orderWorkQueueReady = false, orderWorkQueueError = '';
let orderWorkQueuePromise = null, orderWorkQueueGeneration = 0;
let orderWorkQueueLoadedAt = 0, orderWorkQueueLoadedScope = '';
function pendingOrderWorkQuery() {
    let query = db.collection('orders').where('status','==',BUSINESS_STATUS.ACTIVE)
        .where('workCategories','array-contains-any',OPEN_ORDER_WORK_CATEGORIES);
    if (!canViewAllData('orders') && !canReceiveInventoryCapability()) query = query.where('ownerUid','==',currentUser?.uid || '');
    return query.orderBy('orderDate','desc');
}
async function loadOrderWorkQueue(force = false) {
    if (!canAccessPage('orders.list') && !canAccessPage('orders.po') && !(canAccessPage('inventory') && canReceiveInventoryCapability())) return;
    if (orderWorkQueuePromise && !force) return orderWorkQueuePromise;
    const scope = JSON.stringify([currentUser?.uid || '', currentUserRole]);
    if (!force && orderWorkQueueReady && orderWorkQueueLoadedScope === scope && Date.now() - orderWorkQueueLoadedAt < 15000) return;
    const generation = ++orderWorkQueueGeneration, uid = currentUser?.uid, role = currentUserRole;
    orderWorkQueueReady = false; orderWorkQueueError = '';
    const request = (async () => {
        try {
            const records = await readQueryInBatches(pendingOrderWorkQuery(), 200);
            if (generation !== orderWorkQueueGeneration || uid !== currentUser?.uid || role !== currentUserRole) return;
            const ids = new Set(records.map(row=>row.id));
            const finishedIds = orderWorkQueueCache.filter(row=>!ids.has(row.id)).map(row=>row.id);
            const finished = finishedIds.length ? await readDocumentsByIds('orders', finishedIds) : [];
            if (generation !== orderWorkQueueGeneration || uid !== currentUser?.uid || role !== currentUserRole) return;
            orderWorkQueueCache = records.filter(row=>orderWorkCategories(row).some(category=>OPEN_ORDER_WORK_CATEGORIES.includes(category)));
            const merged = new Map(ordersCache.map(row=>[row.id,row]));
            records.concat(finished).forEach(row=>merged.set(row.id,row));
            finishedIds.filter(id=>!finished.some(row=>row.id===id)).forEach(id=>merged.delete(id));
            ordersCache = [...merged.values()];
            await window.loadV2WarehouseShipmentLocations?.(orderWorkQueueCache);
            if (generation !== orderWorkQueueGeneration || uid !== currentUser?.uid || role !== currentUserRole) return;
            orderWorkQueueReady = true;
            orderWorkQueueLoadedAt = Date.now(); orderWorkQueueLoadedScope = scope;
        } catch (err) {
            if (generation !== orderWorkQueueGeneration || uid !== currentUser?.uid || role !== currentUserRole) return;
            orderWorkQueueError = '未完成工作讀取失敗，請重試';
            mainPageLoadFailed('orders.list'); mainPageLoadFailed('orders.po');
            console.error('未完成訂單讀取失敗：',err);
        } finally {
            if (generation === orderWorkQueueGeneration && uid === currentUser?.uid && role === currentUserRole) {
                if (document.getElementById('order-system')?.classList.contains('active')) renderOrdersList();
                if (document.getElementById('purchasing-system')?.classList.contains('active')) renderPurchasingView();
                if (document.getElementById('inventory-system')?.classList.contains('active')) window.renderInventoryShipping?.();
            }
        }
    })();
    orderWorkQueuePromise = request;
    try { return await request; } finally { if (orderWorkQueuePromise === request) orderWorkQueuePromise = null; }
}
window.setOrderWorkFilter = function(filter) {
    activeOrderWorkFilter = activeOrderWorkFilter === filter && filter !== 'all' ? 'all' : filter;
    if (!orderWorkQueueReady) loadOrderWorkQueue();
    renderOrdersList();
};

function renderOrderWorkCards(orders, normalizedItemsByOrder = null, dispatchStatesByOrder = null, lifecyclesByOrder = null) {
    const container = document.getElementById('orderWorkCards');
    if (!container) return;
    const definitions = [
        ['ordering', '待採購'],
        ['arrival', '待到貨'],
        ['dispatch', '待打單'],
        ['shipping', '已打單'],
        ['billing', '待核銷'],
        ['complete', '已完成（已載入）']
    ];
    const metrics = buildOrderItemWorkMetrics(
        orders,
        definitions.map(([key]) => key),
        (order, item, category) => category !== 'complete' || orderMatchesWorkPeriod(order, category),
        normalizedItemsByOrder,
        dispatchStatesByOrder,
        lifecyclesByOrder
    );
    container.innerHTML = definitions.map(([key, label]) => `<button type="button" class="order-work-card ${activeOrderWorkFilter === key ? 'active' : ''}" onclick="setOrderWorkFilter('${key}')"><span>${label}</span><strong>${key !== 'complete' && !orderWorkQueueReady ? (orderWorkQueueError || '讀取中…') : metrics[key].count + ' 筆'}</strong><small>${formatStatsMoney(metrics[key].amount)}</small></button>`).join('');
}

function createOrderPaginationState() {
    const sources = [];
    if (canViewAllData('orders')) {
        sources.push({
            cursor: null,
            exhausted: false,
            query: () => db.collection('orders').orderBy('orderDate', 'desc')
        });
    } else if (currentUser?.uid) {
        // 新版訂單一律寫入 ownerUid。近期列表以 Firebase UID 為唯一權威歸屬，
        // 避免每次進頁為了相容舊 salesCode / salesName 而串行執行 2～3 個重複 Query。
        sources.push({
            cursor: null,
            exhausted: false,
            query: () => db.collection('orders').where('ownerUid', '==', currentUser.uid).orderBy('orderDate', 'desc')
        });
    }
    return { sources, sourceIndex: 0 };
}

function updateOrderLoadMoreButton() {
    const button = document.getElementById('orderLoadMoreBtn');
    const refreshButton = document.getElementById('orderRefreshBtn');
    const hasMore = !!orderPaginationState && orderPaginationState.sourceIndex < orderPaginationState.sources.length;
    if (button) {
        button.style.display = (hasMore || !!orderLoadErrorMessage) ? '' : 'none';
        button.disabled = orderPageLoading;
        button.innerText = orderPageLoading ? '載入中…' : orderLoadErrorMessage || '載入更多（每次 50 筆）';
    }
    if (refreshButton) {
        refreshButton.disabled = orderPageLoading;
        refreshButton.textContent = orderPageLoading ? '更新中…' : '↻ 更新';
    }
}

async function loadOrderPage(reset, options = {}) {
    if (orderPageLoading) {
        if (!options.force) {
            if (reset) orderReloadRequested = true;
            return;
        }
        // iOS 切到背景時，Firestore 的舊 Promise 可能永遠不完成。讓舊代次失效，
        // 新查詢可以立即開始；舊 Promise 之後即使回來也不能覆蓋新畫面。
        orderLoadGeneration++;
        orderPageLoading = false;
        orderReloadRequested = false;
    }
    if (getDataScope('orders') === 'none') {
        ordersCache = [];
        orderPaginationState = null;
        if (document.getElementById('order-system')?.classList.contains('active')) renderOrdersList();
        else if (document.getElementById('purchasing-system')?.classList.contains('active')) renderPurchasingView();
        updateOrderLoadMoreButton();
        return;
    }
    if (reset || !orderPaginationState) {
        orderPaginationState = createOrderPaginationState();
    }
    const generation = ++orderLoadGeneration;
    orderPageLoading = true;
    orderLoadErrorMessage = '';
    const requestedRole = currentUserRole, requestedUid = currentUser?.uid;
    updateOrderLoadMoreButton();
    // 重新整理期間保留舊畫面，避免慢網路時先清空成整頁白色。
    const records = new Map((reset ? [] : ordersCache).map(order => [order.id, order]));
    let remainingReads = DEFAULT_LIST_LIMIT;
    try {
        while (remainingReads > 0 && orderPaginationState.sourceIndex < orderPaginationState.sources.length) {
            const source = orderPaginationState.sources[orderPaginationState.sourceIndex];
            const requested = remainingReads;
            let query = source.query().limit(requested);
            if (source.cursor) query = query.startAfter(source.cursor);
            const snapshot = await firestoreReadWithTimeout(query.get(), '訂單');
            if (generation !== orderLoadGeneration || requestedUid !== currentUser?.uid) return;
            if (requestedRole !== currentUserRole || requestedUid !== currentUser?.uid) {
                orderReloadRequested = true;
                return;
            }
            if (!snapshot.empty) {
                source.cursor = snapshot.docs[snapshot.docs.length - 1];
                snapshot.forEach(doc => records.set(doc.id, { id: doc.id, ...doc.data() }));
                ordersCache = [...records.values()];
            }
            remainingReads -= snapshot.size;
            if (snapshot.size < requested) {
                source.exhausted = true;
                orderPaginationState.sourceIndex++;
            }
        }
        if (generation !== orderLoadGeneration || requestedUid !== currentUser?.uid) return;
        orderWorkQueueCache.forEach(row => { if(!records.has(row.id)) records.set(row.id,row); });
        ordersCache = [...records.values()].sort((a, b) => compareBusinessRecordsNewestFirst(a, b, 'orderDate', 'id'));
        writeAppDataCache('orders', ordersCache);
        // 訂單頁與採購頁共用同一份 ordersCache；只要這次雲端訂單讀取已成功，
        // 採購頁第一次切入待採購／待打單時就直接沿用，不再重查同一批 orders。
        purchasingOrdersReady = true;
        if (!options.skipRender) {
            if (document.getElementById('order-system')?.classList.contains('active')) renderOrdersList();
            else if (document.getElementById('purchasing-system')?.classList.contains('active')) renderPurchasingView();
        }
    } catch (err) {
        if (generation !== orderLoadGeneration || requestedUid !== currentUser?.uid) return;
        mainPageLoadFailed('orders.list');
        console.error("讀取訂單失敗：", err);
        if (records.size) {
            ordersCache = [...records.values()].sort((a, b) => compareBusinessRecordsNewestFirst(a, b, 'orderDate', 'id'));
        }
        if (!options.skipRender) {
            if (document.getElementById('order-system')?.classList.contains('active')) renderOrdersList();
            else if (document.getElementById('purchasing-system')?.classList.contains('active')) renderPurchasingView();
        }
        if (err?.code === 'firestore-read-timeout') {
            orderLoadErrorMessage = '連線逾時，點此重試';
        } else {
            orderLoadErrorMessage = '讀取失敗，點此重試';
            if (!options.silent) alert('讀取訂單資料失敗，請確認網路或 Firestore 權限設定。');
        }
    } finally {
        if (generation !== orderLoadGeneration || requestedUid !== currentUser?.uid) return;
        orderPageLoading = false;
        updateOrderLoadMoreButton();
        if (orderReloadRequested) {
            orderReloadRequested = false;
            loadOrderPage(true);
        }
    }
}

// 訂單資料範圍由固定角色權限決定：業務/工程師只看自己，採購/倉管查看全部。
// 首次與重新整理只載入 50 筆；歷史資料由「載入更多」明確取得，避免資料增加後
// 每次進入訂單頁都在背景掃完整個 orders 集合。
window.loadOrdersFromCloud = function() {
    return loadOrderPage(true);
};

window.loadMoreOrders = function() {
    return loadOrderPage(false);
};

function normalizeFullHistorySearchValue(value) {
    return String(value || '')
        .normalize('NFKC')
        .toLocaleLowerCase()
        .replace(/[\s\-_.\/\\,，。:：;；()（）\[\]{}]+/g, '');
}

function normalizeHistoryItemCode(value) {
    return String(value || '').trim().toUpperCase().replace(/\s+/g, '');
}

function fullHistorySearchValues(type, record = {}) {
    if (type === 'equipment') {
        return [
            record.assetId, record.customerName, record.brand, record.model,
            record.serialNo, record.salesName, record.location, record.notes
        ];
    }
    if (type === 'forecast') {
        return [
            record.customerName, record.brand, record.productName, record.latestProgress,
            record.salesName, forecastStageLabel(record.stage), forecastStatusLabel(record.status)
        ];
    }
    if (type === 'quote') {
        return [
            record.quoteNo, record.clientName, record.ordererName, record.salesName, record.remarks,
            ...(Array.isArray(record.items) ? record.items.flatMap(item => [
                item.brand, item.model, item.nameCn, item.nameEn, item.spec,
                item.origin, item.leadTime, item.hospitalItemCode,
                ...(Array.isArray(item.customFields) ? item.customFields.flatMap(field => [field.label, field.value]) : [])
            ]) : [])
        ];
    }
    return [
        record.id, record.orderNo, record.quoteNo, record.customerName, record.brand,
        record.itemCode, record.itemName, record.salesName, record.purchaseOrderNo,
        record.invoiceTitle, record.productLine, record.spec,
        ...(Array.isArray(record.items) ? record.items.flatMap(item => [
            item.itemId, item.brand, item.itemCode, item.itemName, item.productLine,
            item.productType, item.spec, ...(Array.isArray(item.purchaseOrderNos) ? item.purchaseOrderNos : [])
        ]) : [])
    ];
}

function fullHistoryBaseTokens(type, record = {}) {
    const tokens = new Set();
    const MAX_BASE_TOKENS = 180;
    for (const raw of fullHistorySearchValues(type, record)) {
        const normalized = normalizeFullHistorySearchValue(raw);
        if (!normalized) continue;
        tokens.add(normalized);
        const maxGram = Math.min(6, normalized.length);
        for (let size = 1; size <= maxGram; size += 1) {
            for (let i = 0; i + size <= normalized.length; i += 1) {
                tokens.add(normalized.slice(i, i + size));
                if (tokens.size >= MAX_BASE_TOKENS) return [...tokens];
            }
        }
    }
    return [...tokens];
}

function buildFullHistorySearchTokens(type, record = {}) {
    const base = fullHistoryBaseTokens(type, record);
    const tokens = new Set(base);
    const salesCode = String(record.salesCode || '').trim();
    const ownerUid = String(record.ownerUid || '').trim();
    const salesName = normalizeFullHistorySearchValue(record.salesName || '');
    base.forEach(token => {
        if (salesCode) tokens.add(`sc:${salesCode}:${token}`);
        if (ownerUid) tokens.add(`uid:${ownerUid}:${token}`);
        if (salesName) tokens.add(`sn:${salesName}:${token}`);
    });
    return [...tokens].slice(0, 700);
}

function fullHistoryServerToken(keyword) {
    const normalized = normalizeFullHistorySearchValue(keyword);
    return normalized.length > 6 ? normalized.slice(0, 6) : normalized;
}

function fullHistoryQueryToken(type, keyword) {
    const token = fullHistoryServerToken(keyword);
    if (!token) return '';
    const canViewAll = type === 'quote' ? canViewAllData('quotes')
        : type === 'forecast' ? canViewAllData('forecast')
        : type === 'equipment' ? canViewAllEquipment()
        : canViewAllData('orders');
    if (canViewAll) return token;
    if (currentUserCode) return `sc:${currentUserCode}:${token}`;
    if (currentUser?.uid) return `uid:${currentUser.uid}:${token}`;
    if (currentUserName) return `sn:${normalizeFullHistorySearchValue(currentUserName)}:${token}`;
    return '';
}

function scopedHistorySearchQuery(collectionName, queryToken) {
    let query = db.collection(collectionName).where('searchTokens', 'array-contains', queryToken);
    const scopeKey = collectionName === 'quotes' ? 'quotes' : collectionName === 'forecasts' ? 'forecast' : 'orders';
    if (!canViewAllData(scopeKey)) {
        if (currentUserCode) query = query.where('salesCode', '==', currentUserCode);
        else if (currentUser?.uid) query = query.where('ownerUid', '==', currentUser.uid);
    }
    return query;
}

function fullHistoryRecordMatches(type, record, keyword) {
    const needle = normalizeFullHistorySearchValue(keyword);
    if (!needle) return true;
    return fullHistorySearchValues(type, record)
        .some(value => normalizeFullHistorySearchValue(value).includes(needle));
}

/*
 * 統一全歷史搜尋：估價單／訂單使用 searchTokens 後端索引；
 * 一般列表仍每次只載入 50 筆，搜尋則自動逐頁讀完符合索引的候選資料。
 */
let orderHistorySearchActive = false;
let orderHistorySearchLoading = false;
let orderHistorySearchKeyword = '';
let orderHistorySearchResults = [];
let orderHistorySearchTimer = null;
let orderHistorySearchGeneration = 0;

function updateOrderHistorySearchUi(message = '') {
    const status = document.getElementById('orderHistorySearchStatus');
    if (status) status.innerText = message;
}

async function runOrderHistorySearch() {
    const generation = ++orderHistorySearchGeneration;
    const input = document.getElementById('orderSearch');
    const rawKeyword = input?.value || '';
    const normalized = normalizeFullHistorySearchValue(rawKeyword);
    if (!normalized) {
        orderHistorySearchActive = false;
        orderHistorySearchLoading = false;
        orderHistorySearchKeyword = '';
        orderHistorySearchResults = [];
        updateOrderHistorySearchUi('');
        renderOrdersList();
        return;
    }
    const queryToken = fullHistoryQueryToken('order', rawKeyword);
    if (!queryToken) {
        orderHistorySearchActive = false;
        orderHistorySearchLoading = false;
        orderHistorySearchResults = [];
        updateOrderHistorySearchUi('目前帳號缺少可用的資料歸屬資訊，無法進行全歷史搜尋。');
        renderOrdersList();
        return;
    }

    orderHistorySearchLoading = true;
    orderHistorySearchActive = true;
    orderHistorySearchKeyword = rawKeyword;
    orderHistorySearchResults = [];
    const records = new Map();
    let cursor = null;
    let checked = 0;
    let lastIntermediateRenderAt = 0;
    updateOrderHistorySearchUi('正在搜尋全部歷史訂單…');
    renderOrdersList();

    try {
        while (true) {
            let query = scopedHistorySearchQuery('orders', queryToken).limit(DEFAULT_LIST_LIMIT);
            if (cursor) query = query.startAfter(cursor);
            const snapshot = await firestoreReadWithTimeout(query.get(), '訂單索引搜尋');
            if (generation !== orderHistorySearchGeneration) return;

            checked += snapshot.size;
            snapshot.forEach(doc => {
                const data = { id: doc.id, ...doc.data() };
                if (fullHistoryRecordMatches('order', data, rawKeyword)) records.set(doc.id, data);
            });
            const now = Date.now();
            if (now - lastIntermediateRenderAt >= 100 || snapshot.size < DEFAULT_LIST_LIMIT) {
                lastIntermediateRenderAt = now;
                orderHistorySearchResults = [...records.values()]
                    .sort((a,b)=>compareBusinessRecordsNewestFirst(a,b,'orderDate','id'));
                renderOrdersList();
            }
            updateOrderHistorySearchUi(`全歷史搜尋中：已檢查 ${checked} 筆候選資料，找到 ${records.size} 筆…`);

            if (snapshot.size < DEFAULT_LIST_LIMIT) break;
            cursor = snapshot.docs[snapshot.docs.length - 1];
            await Promise.resolve();
        }
        if (generation !== orderHistorySearchGeneration) return;
        orderHistorySearchResults = [...records.values()]
            .sort((a,b)=>compareBusinessRecordsNewestFirst(a,b,'orderDate','id'));
        updateOrderHistorySearchUi(`全歷史搜尋完成：找到 ${records.size} 筆`);
    } catch (err) {
        if (generation !== orderHistorySearchGeneration) return;
        console.error('訂單全歷史搜尋失敗：', err);
        orderHistorySearchActive = false;
        orderHistorySearchResults = [];
        updateOrderHistorySearchUi('全歷史搜尋索引尚未補齊，請管理員到資料庫管理執行搜尋索引補建。');
        renderOrdersList();
    } finally {
        if (generation === orderHistorySearchGeneration) {
            orderHistorySearchLoading = false;
            renderOrdersList();
        }
    }
}

window.scheduleOrderHistorySearch = function() {
    clearTimeout(orderHistorySearchTimer);
    const keyword = document.getElementById('orderSearch')?.value || '';
    if (!normalizeFullHistorySearchValue(keyword)) return runOrderHistorySearch();
    orderHistorySearchTimer = scheduleListSearch(orderHistorySearchTimer, () => runOrderHistorySearch());
};

window.searchAllOrderHistory = function() { return runOrderHistorySearch(); };
window.clearOrderHistorySearch = function() {
    clearTimeout(orderHistorySearchTimer);
    orderHistorySearchGeneration++;
    orderHistorySearchLoading = false;
    orderHistorySearchActive = false;
    orderHistorySearchKeyword = '';
    orderHistorySearchResults = [];
    const input = document.getElementById('orderSearch');
    if (input) input.value = '';
    updateOrderHistorySearchUi('');
    renderOrdersList();
};

// 依「成本」跟「單價（售價）」計算利潤%// 依「成本」跟「單價（售價）」計算利潤% = (售價－成本) / 成本 × 100，也就是以成本為基準的加成率
function formatProfitPercent(unitPrice, costPrice) {
    const price = parseFloat(unitPrice);
    const cost = parseFloat(costPrice);
    if (!isFinite(price) || !isFinite(cost) || cost <= 0) return '－';
    const percent = ((price - cost) / cost) * 100;
    return percent.toFixed(1) + '%';
}

// 輸入含稅成本的當下（還沒存雲端前），先在畫面上即時算出利潤%，打字就能馬上看到，不用等存檔
window.updateOrderProfitDisplay = function(orderId, costValue) {
    const o = ordersCache.find(x => x.id === orderId);
    if (!o) return;
    const span = document.getElementById('orderProfit_' + orderId);
    if (span) span.innerText = formatProfitPercent(o.unitPrice, costValue);
};

// 能查看所有人訂單的身份，可依業務與廠牌篩選。
function orderBrandFilterValue(value, selectableBrands) {
    const key = normalizeBrandLookupKey(resolveBrandName(value));
    if (!key) return '';
    return selectableBrands.find(brand => normalizeBrandLookupKey(brand) === key) || OTHER_BRAND_OPTION_KEY;
}

let orderFilterOptionsSignature = '';

function workflowSalesFilterNames() {
    return [...new Set(salesList.map(person => stripPhoneSuffix(person.name)).filter(Boolean))]
        .sort((a, b) => a.localeCompare(b, 'zh-Hant'));
}

function workflowPurchasingBrandNames() {
    // 訂單／採購篩選與估價／訂單輸入共用同一份「獨立統計」主要廠牌清單。
    return getPrimaryBrandNames();
}

function populatePurchaserOrderFilters() {
    const wrap = document.getElementById('purchaserOrderFilters');
    const salesSelect = document.getElementById('orderSalesFilter');
    const brandSelect = document.getElementById('orderBrandFilter');
    if (!wrap || !salesSelect || !brandSelect) return;

    const enabled = canViewAllData('orders');
    wrap.style.display = enabled ? '' : 'none';
    if (!enabled) {
        salesSelect.value = '';
    }

    const salesValue = salesSelect.value;
    const brandValue = brandSelect.value;
    const sales = workflowSalesFilterNames();
    const brands = workflowPurchasingBrandNames();
    const signature = JSON.stringify([enabled, sales, brands]);

    // 訂單頁與採購頁都用正式人員名單，不再依目前載入的 50 筆訂單臨時產生選項。
    // 選項沒變時也不要每次 render 都重建 select DOM。
    if (signature !== orderFilterOptionsSignature) {
        if (enabled) {
            salesSelect.innerHTML = '<option value="">全部負責業務</option>' + sales.map(name =>
                `<option value="${escapeAttr(name)}">${escapeHtml(name)}</option>`).join('');
        }
        brandSelect.innerHTML = '<option value="">全部廠牌</option>' + brands.map(brand =>
            `<option value="${escapeAttr(brand)}">${escapeHtml(brand)}</option>`).join('')
            + `<option value="${OTHER_BRAND_OPTION_KEY}">其他廠牌</option>`;
        orderFilterOptionsSignature = signature;
    }
    if (enabled && sales.includes(salesValue)) salesSelect.value = salesValue;
    else if (enabled && salesSelect.value && !sales.includes(salesSelect.value)) salesSelect.value = '';
    if (brands.includes(brandValue) || brandValue === OTHER_BRAND_OPTION_KEY) brandSelect.value = brandValue;
    else if (brandSelect.value && !brands.includes(brandSelect.value)) brandSelect.value = '';
    return brands;
}


window.renderOrdersList = function() {
    window.renderServiceCaseEntry?.();
    const tbody = document.getElementById('ordersBody');
    const searchInput = document.getElementById('orderSearch');
    if (!tbody || !searchInput) return;

    const canManageOrderOps = currentUserRole === 'purchaser' || currentUserRole === 'admin';
    const canEditOrders = canEditPage('orders.list');
    const canManageOrderLifecycle = canManageOrderLifecycleCapability();
    const canConfirmOrderDelivery = canManageOrderLifecycle;
    const costHeader = document.getElementById('orderCostHeader');
    if (costHeader) costHeader.style.display = '';

    const selectableBrands = populatePurchaserOrderFilters() || [];
    const salesFilter = document.getElementById('orderSalesFilter')?.value || '';
    const brandFilter = document.getElementById('orderBrandFilter')?.value || '';
    const keyword = (searchInput.value || '').toLowerCase();
    tbody.innerHTML = '';
    const fragment = document.createDocumentFragment();
    let shown = 0;

    const visibleOrderSource = orderHistorySearchActive ? orderHistorySearchResults : ordersCache;
    // 同一次列表 render 每筆訂單只 normalize 一次，避免搜尋、廠牌篩選、狀態卡片與產品欄重複處理 items。
    const normalizedItemsByOrder = new Map(visibleOrderSource.map(o => [o.id, normalizedOrderItems(o)]));
    const baseOrders = visibleOrderSource.filter(o => {
        const orderItems = normalizedItemsByOrder.get(o.id) || [];
        if (!orderHistorySearchActive && keyword) {
            const itemSearchable = orderItems.flatMap(item => [
                item.brand, item.itemCode, item.itemName, item.productLine, item.productType, item.spec
            ]).join(' ');
            const searchable = `${o.customerName || ''} ${o.brand || ''} ${o.itemCode || ''} ${o.itemName || ''} ${o.quoteNo || ''} ${o.salesName || ''} ${itemSearchable}`.toLowerCase();
            if (!searchable.includes(keyword)) return false;
        }
        if (salesFilter && stripPhoneSuffix(o.salesName) !== salesFilter) return false;
        if (brandFilter && !orderItems.some(item => orderBrandFilterValue(item.brand, selectableBrands) === brandFilter)
            && orderBrandFilterValue(o.brand, selectableBrands) !== brandFilter) return false;
        return true;
    });
    // 工作圖卡與下方訂單列共用同一份 dispatch snapshot；
    // 每個品項在一次 render 內只掃一次送貨／退貨紀錄。
    const dispatchStatesByOrder = new Map(baseOrders.map(order => {
        const items = normalizedItemsByOrder.get(order.id) || [];
        return [order.id, new Map(items.map(item => [item, itemDispatchState(order, item)]))];
    }));
    const lifecyclesByOrder = new Map(baseOrders.map(order => [
        order.id,
        orderLifecycleInfo(order, normalizedItemsByOrder.get(order.id) || [])
    ]));
    renderOrderWorkCards(baseOrders, normalizedItemsByOrder, dispatchStatesByOrder, lifecyclesByOrder);

    baseOrders.forEach(o => {
        const allOrderItems = normalizedItemsByOrder.get(o.id) || [];
        const lifecycle = lifecyclesByOrder.get(o.id) || orderLifecycleInfo(o, allOrderItems);
        const dispatchStateByItem = dispatchStatesByOrder.get(o.id) || new Map();
        const displayCategoriesByItem = new Map(
            allOrderItems.map(item => [item, orderItemDisplayCategories(o, item, lifecycle, dispatchStateByItem.get(item))])
        );
        const categories=[...new Set(allOrderItems.flatMap(item=>displayCategoriesByItem.get(item) || []))];
        if(activeOrderWorkFilter!=='all'&&!categories.includes(activeOrderWorkFilter))return;
        if (activeOrderWorkFilter === 'complete' && !orderMatchesWorkPeriod(o,'complete')) return;
        // 工作圖卡是以「品項」計數；套用狀態篩選後，產品欄也只顯示該狀態品項，
        // 避免同一張多品項訂單把其他狀態的品項一起帶進來造成誤判。
        const orderItems=activeOrderWorkFilter==='all'
            ? allOrderItems
            : allOrderItems.filter(item=>(displayCategoriesByItem.get(item) || []).includes(activeOrderWorkFilter));
        shown++;

        const tr = document.createElement('tr');
        if (canManageOrderOps && (o.procurementType || 'PURCHASING_PO') !== 'SALES_SELF_ORDER') {
            loadVisibleProductCost(findPriceItemForOrder(o) || {productId:o.productId}).then(cost => {
                if (!tr.isConnected || cost === null || !Number.isFinite(cost)) return;
                const input = tr.querySelector('.order-cost-input');
                if (input) input.value = String(Number(cost.toFixed(2)));
                const profit = tr.querySelector('[id^="orderProfit_"]');
                if (profit) profit.textContent = formatProfitPercent(o.unitPrice, cost);
            });
        }
        // 這些摘要共用上方已算好的 dispatch state，不再各自掃描送貨／退貨紀錄。
        const deliveryProgress = deliveryProgressInfo(o, allOrderItems);
        const fulfillmentProgress = canConfirmOrderDelivery ? fulfillmentProgressInfo(o, allOrderItems, dispatchStateByItem) : null;
        const contextActions = orderContextActionState(o, allOrderItems, dispatchStateByItem);
        const useBatchDelivery = orderDeliveryRequiresItemForm(allOrderItems, deliveryProgress, fulfillmentProgress);
        const deliveryPending = pendingDeliveryOrderIds.has(o.id);
        const billingPending = pendingOrderStatusKeys.has(o.id + ':isBilled');
        if (lifecycle.status !== 'normal') {
            tr.classList.add('order-row-closed');
        }
        bindListRowSelection(tr);
        tr.innerHTML = `
            <td class="order-date-cell" data-th="訂單日期">${escapeHtml(o.orderDate || '')}</td>
            <td class="order-customer-cell" data-th="客戶名稱"><div class="record-reference">客戶訂單${o.orderNo ? `・${escapeHtml(o.orderNo)}` : o.quoteNo ? `・來源估價單 ${escapeHtml(o.quoteNo)}` : ''}</div>${o.customerName ? `<button type="button" class="btn-small btn-secondary" onclick="showCustomerOrderHistory(${inlineJsValue(o.customerName)})">${escapeHtml(o.customerName)}</button>` : ''}</td>
            <td class="order-sales-cell" data-th="負責業務">${escapeHtml(stripPhoneSuffix(o.salesName))}</td>
            <td data-th="產品資訊" class="order-product-cell">${orderItems.map((item,index)=>{const displayCategories=displayCategoriesByItem.get(item)||[];const primaryStatus=displayCategories[0]||'ordering';const itemStatus=['dispatch','shipping'].includes(activeOrderWorkFilter)&&displayCategories.includes(activeOrderWorkFilter)?activeOrderWorkFilter:primaryStatus;const itemStatusMap={ordering:'待採購',arrival:'待到貨',dispatch:'待打單',shipping:'已打單',billing:'待核銷',complete:'已完成',closed:lifecycle.label};const waiting=primaryStatus==='arrival'?waitingDaysFromDate(item.orderedAt):'';const state=dispatchStateByItem.get(item)||itemDispatchState(o,item);const parallelDispatch=primaryStatus!=='dispatch'&&state.pending>0;return `<div style="${index?'margin-top:5px;padding-top:5px;border-top:1px solid #eee;':''}"><strong>${escapeHtml(item.itemName || '－')}</strong><small>${escapeHtml(item.brand || '未分類')}${item.itemCode ? `・${escapeHtml(item.itemCode)}` : ''}・${activeOrderWorkFilter==='shipping'?`已打單 ${state.shippable}／訂單數量 ${Number(item.orderedQty||item.qty||0)}`:activeOrderWorkFilter==='dispatch'?`待打單 ${state.pending}／訂單數量 ${Number(item.orderedQty||item.qty||0)}`:Number(item.orderedQty||item.qty||0)}</small><small class="order-item-work-status">訂單狀態：<span class="order-progress-badge">${escapeHtml(((lifecycle.status==='normal'&&orderInventorySyncIncomplete(o)) ? (o.inventoryReservationStatus==='failed'?'庫存同步未完成':'庫存同步中…') : ((String(item.productType||'').trim().toUpperCase()==='SERVICE'&&lifecycle.status==='normal'&&primaryStatus==='delivery'?'待服務處理':(lifecycle.status==='normal'&&globalThis.YushinWarehouseLogistics?.shippingStatus(o,item,state)))||itemStatusMap[itemStatus]||'待採購')))}</span>${waiting?`・已等 ${escapeHtml(waiting)}`:''}${parallelDispatch&&itemStatus!=='dispatch'?`・另有 ${escapeHtml(state.pending)} 待打單`:''}${state.shippable>0?`・已有 ${escapeHtml(state.shippable)} 可出貨`:''}</small></div>`}).join('')}</td>
            <td data-th="訂單總額" class="order-money-cell"><strong>NT$ ${escapeHtml(Number(parseFloat(String(o.totalPrice ?? '').replace(/,/g, '')) || 0).toLocaleString())}</strong><small>${o.isBilled ? '已核銷' : '未核銷'}</small></td>
            <td class="order-details-cell">
                <div class="order-text-summary">${escapeHtml([o.transactionType ? `交易：${o.transactionType}` : '', o.invoiceTitle || '', o.isBilled && orderBillingDate(o) ? `核銷日期：${orderBillingDate(o)}` : '', o.remarks || ''].filter(Boolean).join('・'))}</div>
                <details class="order-detail-panel">
                    <summary>查看明細${canEditOrders ? '／編輯' : ''}</summary>
                    <div class="order-detail-content">
                        <div class="order-item-prices">${allOrderItems.map(item => `<div>${escapeHtml(item.itemName || item.itemCode || '品項')}：NT$ ${escapeHtml(Number(item.unitPrice || 0).toLocaleString())} × ${escapeHtml(Number(item.orderedQty || item.qty || 0))}</div>`).join('')}</div>
            ${canManageOrderOps ? `
            <div class="no-print order-cost-profit-cell"><label>單位成本</label><input type="number" step="0.01" class="order-cost-input" data-order-id="${o.id}" ${(o.procurementType || 'PURCHASING_PO') !== 'SALES_SELF_ORDER' ? 'readonly title="標準成本由產品成本資料帶入"' : ''} value="${o.procurementType === 'SALES_SELF_ORDER' ? (o.costPrice == null ? '' : Number(Number(o.costPrice).toFixed(2))) : ''}" oninput="updateOrderProfitDisplay('${o.id}', this.value)" onchange="updateOrderField('${o.id}','costPrice', this.value === '' ? null : parseFloat(this.value))"><small>毛利：<span id="orderProfit_${o.id}">${formatProfitPercent(o.unitPrice, o.costPrice)}</span></small></div>` : ''}
            <div class="order-transaction-cell"><label>交易資訊</label>
                <select onchange="updateOrderField('${o.id}','transactionType',this.value)">
                    <option value="" ${!o.transactionType ? 'selected' : ''}>未選擇</option>
                    <option value="直" ${o.transactionType === '直' ? 'selected' : ''}>直</option>
                    <option value="借" ${o.transactionType === '借' ? 'selected' : ''}>借</option>
                    <option value="扣" ${o.transactionType === '扣' ? 'selected' : ''}>扣</option>
                </select>
                ${o.transactionType === '直' ? `<input type="text" aria-label="發票抬頭" placeholder="發票抬頭" value="${escapeAttr(o.invoiceTitle || '')}" onchange="updateOrderField('${o.id}','invoiceTitle',this.value)">` : ''}
                ${o.isBilled ? `<label class="order-invoice-date-label">核銷日期<input type="date" aria-label="核銷日期" value="${escapeAttr(orderBillingDate(o))}" onchange="updateOrderBillingDate('${o.id}',this.value)"></label>` : ''}
            </div>
            <label class="order-remarks-editor">備註<input type="text" value="${escapeAttr(o.remarks || '')}" placeholder="備註" onchange="updateOrderField('${o.id}','remarks',this.value)"></label>
                    </div>
                </details>
            </td>
            <td class="no-print" data-th="操作">
                ${orderInventorySyncStatusHtml(o)}
                <div class="order-compact-actions">
                    ${window.serviceCaseActionHtml?.(o)||''}
                    ${selfOrderActionHtml(o, allOrderItems, dispatchStateByItem)}
                    ${directShipReceiptActionHtml(o, allOrderItems)}
                    
                    ${canConfirmOrderDelivery && lifecycle.status === 'normal' && deliveryProgress.state !== 'complete' && (fulfillmentProgress.shippable>0 || deliveryPending) ? `<button type="button" class="btn-small" onclick="${useBatchDelivery ? 'openPartialDeliveryForOrder' : 'quickCompleteDelivery'}(${inlineJsValue(o.id)})" ${orderInventorySyncIncomplete(o) || lifecycle.status !== 'normal' || deliveryPending || deliveryProgress.state === 'complete' || fulfillmentProgress.shippable<=0 ? 'disabled' : ''}>${deliveryPending ? '處理中…' : useBatchDelivery ? '已送貨（分批）' : '已送貨'}</button>` : ''}
                    ${canBusinessSelfOrder(o) ? `<button type="button" class="btn-small ${o.isBilled ? 'btn-secondary' : ''}" onclick="toggleOrderStatus('${o.id}', 'isBilled', ${!o.isBilled})" ${lifecycle.status !== 'normal' || billingPending ? 'disabled' : ''}>${billingPending ? '儲存中…' : o.isBilled ? '已核銷' : '核銷'}</button>` : ''}
                    <details class="order-more-menu">
                        <summary title="更多操作">⋯</summary>
                        <div class="order-more-menu-popover">
                            ${orderLifecycleActionButtons(o, lifecycle, deliveryProgress, contextActions)}
                            <button type="button" onclick="copyOrderAsNew('${o.id}')">複製成新訂單</button>
                            <button type="button" onclick="openOrderStatusHistory('${o.id}')">紀錄</button>
                            ${trueUserRole === 'admin' && currentUserRole === 'admin' ? `<button type="button" class="danger-menu-item" onclick="permanentlyDeleteOrder(${inlineJsValue(o.id)})" ${pendingLifecycleOrderIds.has(o.id) ? 'disabled aria-busy="true"' : ''}>${pendingLifecycleOrderIds.has(o.id) ? '處理中…' : '永久刪除'}</button>` : ''}
                        </div>
                    </details>
                </div>
            </td>
        `;
        if (!canEditOrders) {
            tr.querySelectorAll('.order-transaction-cell select, .order-transaction-cell input, .order-remarks-editor input').forEach(control => {
                control.disabled = true;
                control.setAttribute('aria-readonly', 'true');
            });
            tr.querySelectorAll('.order-more-menu-popover button').forEach(button => {
                const action = button.getAttribute('onclick') || '';
                if (!action.includes('openOrderStatusHistory(')) button.remove();
            });
        }
        fragment.appendChild(tr);
    });
    tbody.appendChild(fragment);
    document.getElementById('ordersEmptyHint').style.display = shown === 0 ? 'block' : 'none';
    document.getElementById('ordersEmptyHint').textContent = orderHistorySearchLoading || !orderWorkQueueReady ? (orderWorkQueueError || '正在讀取訂單…') : '查無符合條件的訂單。';
    // 採購頁打開時才重算其工作卡；切頁時會用同一份 ordersCache 立即產生。
    if (document.getElementById('purchasing-system')?.classList.contains('active')) renderPurchasingView();
};

function orderSourceSyncIncomplete(order) {
    return ['pending','failed'].includes(order?.sourceDocumentSyncStatus);
}
function canRetrySourceDocumentSync(order) {
    return canRetryOrderInventorySync(order) && (order.sourceType!==DOCUMENT_TYPES.FORECAST
        || currentUserRole==='admin' || (currentUserRole==='sales'&&order.ownerUid===currentUser?.uid));
}
async function syncNewOrderSourceDocuments(orderId,data,actorUid) {
    if(currentUser?.uid!==actorUid)return new Error('登入身份已變更，來源文件同步待確認');
    const orderRef=db.collection('orders').doc(orderId);
    let sourceType='',sourceId='',quotePatch=null;
    try{
        const saved=await runRoleTransaction(async tx=>{
            const snap=await tx.get(orderRef);
            if(currentUser?.uid!==actorUid)throw new Error('登入身份已變更');
            if(!snap.exists)throw new Error('訂單已不存在');
            const order={id:orderId,...snap.data()};
            sourceType=order.sourceType||'';sourceId=order.sourceId||'';
            if(![DOCUMENT_TYPES.QUOTE,DOCUMENT_TYPES.FORECAST].includes(sourceType)||!sourceId)return order;
            if(normalizedOrderStatus(order)!=='normal')throw new Error('訂單已取消／作廢，停止來源文件同步');
            if(orderInventorySyncIncomplete(order))throw new Error('庫存尚未同步完成，來源文件稍後再同步');
            if(order.sourceDocumentSyncStatus==='completed')return order;
            if(!canRetrySourceDocumentSync(order))throw new Error('來源文件請由負責業務或管理員同步');
            const ref=db.collection(sourceType===DOCUMENT_TYPES.QUOTE?'quotes':'forecasts').doc(sourceId);
            const source=await tx.get(ref);
            if(!source.exists)throw new Error('來源文件已不存在，不能重新建立來源文件');
            if(normalizedOrderStatus(source.data())!=='normal')throw new Error('來源文件已取消／作廢，請先確認訂單關聯');
            if(currentUser?.uid!==actorUid)throw new Error('登入身份已變更');
            const now=new Date().toISOString();
            const patch={linkedDocuments:firebase.firestore.FieldValue.arrayUnion(documentLink(DOCUMENT_TYPES.ORDER,orderId,'created')),updatedAt:now};
            if(sourceType===DOCUMENT_TYPES.QUOTE){
                quotePatch={dealClosed:true,dealClosedAt:source.data().dealClosedAt||localDateString(),status:BUSINESS_STATUS.COMPLETED};
                Object.assign(patch,quotePatch);
            }
            tx.update(ref,patch);
            const updates={sourceDocumentSyncStatus:'completed',sourceDocumentSyncError:'',sourceDocumentSyncUpdatedAt:now,updatedAt:now};
            tx.update(orderRef,updates);
            return {...order,...updates};
        });
        if(currentUser?.uid===actorUid){
            Object.assign(data,saved);
            if(quotePatch){
                const cached=myQuotesCache.find(q=>q.quoteNo===sourceId);if(cached)Object.assign(cached,quotePatch);
                const searched=quoteHistorySearchResults.find(q=>q.quoteNo===sourceId);if(searched)Object.assign(searched,quotePatch);
                writeAppDataCache('quotes',myQuotesCache);
            }
        }
        return null;
    }catch(err){
        // The source update and completion checkpoint are atomic. Lost replies must not downgrade completion.
        const latest=await runRoleTransaction(async tx=>{
            const snap=await tx.get(orderRef);
            if(currentUser?.uid!==actorUid||!snap.exists)return null;
            const order={id:orderId,...snap.data()};
            if(!canRetryOrderInventorySync(order))return null;
            if(order.sourceType!==sourceType||order.sourceId!==sourceId||!sourceId)return null;
            if(normalizedOrderStatus(order)!=='normal'||orderInventorySyncIncomplete(order))return order;
            if(order.sourceDocumentSyncStatus==='completed')return order;
            const updates={sourceDocumentSyncStatus:'failed',sourceDocumentSyncError:String(err?.message||err).slice(0,1000),sourceDocumentSyncUpdatedAt:new Date().toISOString()};
            tx.update(orderRef,updates);
            return {...order,...updates};
        }).catch(markErr=>{console.error('來源文件同步結果尚未確認：',markErr);return null;});
        if(latest&&currentUser?.uid===actorUid)Object.assign(data,latest);
        return latest?.sourceDocumentSyncStatus==='completed'?null:err;
    }
}

const pendingOrderReservationIds = new Set();
function orderInventorySyncIncomplete(order) {
    return ['pending','failed'].includes(order?.inventoryReservationStatus);
}
function canRetryOrderInventorySync(order) {
    return currentUserRole==='admin'||currentUserRole==='purchaser'
        ||(['sales','engineer'].includes(currentUserRole)&&!!currentUser?.uid&&order?.ownerUid===currentUser.uid);
}
async function writeOrderInventorySyncState(orderId, status, expectedAttemptId, uid, error = '') {
    if(!['pending','completed','failed'].includes(status))throw new Error('不支援的庫存同步狀態。');
    const ref=db.collection('orders').doc(orderId);
    const nextAttemptId=status==='pending'?db.collection('orders').doc().id:'';
    return runRoleTransaction(async tx=>{
        const snap=await tx.get(ref);
        if(currentUser?.uid!==uid)throw new Error('登入身份已變更，請以原帳號重試同步。');
        if(!snap.exists)throw new Error('訂單已不存在。');
        const order={id:orderId,...snap.data()};
        if(!canRetryOrderInventorySync(order))throw new Error('無權同步這筆訂單。');
        const attemptId=String(order.inventoryReservationAttemptId||'');
        if(normalizedOrderStatus(order)!=='normal'||order.inventoryReservationStatus==='completed'||attemptId!==String(expectedAttemptId||'')){
            return {applied:false,order};
        }
        if(status!=='pending'&&order.inventoryReservationStatus!=='pending')return {applied:false,order};
        const updates={inventoryReservationStatus:status,inventoryReservationError:status==='failed'?String(error).slice(0,1000):'',
            inventoryReservationAttemptId:status==='pending'?nextAttemptId:attemptId,inventoryReservationUpdatedAt:new Date().toISOString()};
        Object.assign(updates,orderWorkIndexFields({...order,...updates}));
        tx.update(ref,updates);
        return {applied:true,order:{...order,...updates}};
    });
}
async function synchronizeOrderInventory(orderId, order, uid = currentUser?.uid) {
    const started=await writeOrderInventorySyncState(orderId,'pending',order.inventoryReservationAttemptId||'',uid);
    Object.assign(order,started.order);
    if(normalizedOrderStatus(order)!=='normal')throw new Error('已取消／作廢的訂單不可同步庫存。');
    if(order.inventoryReservationStatus==='completed')return orderReservationSummary(order);
    if(!started.applied)throw new Error('已有較新的庫存同步工作，請更新這筆訂單後確認結果。');
    const attemptId=order.inventoryReservationAttemptId;
    try{
        await reserveInventoryForNewOrder(orderId,order,uid);
        const finished=await writeOrderInventorySyncState(orderId,'completed',attemptId,uid);
        Object.assign(order,finished.order);
        if(normalizedOrderStatus(order)!=='normal')throw new Error('訂單已取消／作廢，停止後續同步。');
        if(order.inventoryReservationStatus!=='completed')throw new Error('已有較新的庫存同步工作，請更新這筆訂單後確認結果。');
        return {...orderReservationSummary(order),items:order.items};
    }catch(err){
        const failed=await writeOrderInventorySyncState(orderId,'failed',attemptId,uid,String(err?.message||err))
            .catch(markErr=>{console.error('標記庫存同步結果失敗：',markErr);return null;});
        if(failed)Object.assign(order,failed.order);
        // Another attempt may already have completed while this older callback failed.
        if(failed&&normalizedOrderStatus(order)==='normal'&&order.inventoryReservationStatus==='completed')return {...orderReservationSummary(order),items:order.items};
        throw err;
    }
}
function orderInventorySyncStatusHtml(order) {
    if(normalizedOrderStatus(order)!=='normal')return '';
    if(!orderInventorySyncIncomplete(order)&&!orderSourceSyncIncomplete(order))return '';
    const running=pendingOrderReservationIds.has(order.id);
    const label=running?'訂單同步中…':!orderInventorySyncIncomplete(order)?'來源文件同步未完成':order.inventoryReservationStatus==='failed'?'庫存同步未完成':'庫存同步待確認';
    const canRetry=orderInventorySyncIncomplete(order)?canRetryOrderInventorySync(order):canRetrySourceDocumentSync(order);
    return `<div class="inline-status" role="status">${label}${!running&&canRetry?` <button type="button" class="btn-small" onclick="retryOrderInventoryReservation(${inlineJsValue(order.id)})">重試同步</button>`:''}</div>`;
}
window.addEventListener('beforeunload',event=>{
    if(pendingOrderReservationIds.size){event.preventDefault();event.returnValue='';}
});
window.retryOrderInventoryReservation = async function(orderId) {
    const cachedOrder=ordersCache.find(row=>row.id===orderId);
    if(!cachedOrder||!canRetryOrderInventorySync(cachedOrder)||(!orderInventorySyncIncomplete(cachedOrder)&&!orderSourceSyncIncomplete(cachedOrder))||pendingOrderReservationIds.has(orderId))return;
    const uid=currentUser?.uid;
    pendingOrderReservationIds.add(orderId);
    renderOrdersList();
    let order=null;
    try{
        const snap=await firestoreReadWithTimeout(db.collection('orders').doc(orderId).get(),'讀取待同步訂單');
        if(!snap.exists)throw new Error('訂單已不存在');
        order={id:snap.id,...snap.data()};
        if(currentUser?.uid!==uid||!canRetryOrderInventorySync(order))throw new Error('登入身份或權限已變更');
        if(normalizedOrderStatus(order)!=='normal')throw new Error('已取消／作廢的訂單不可同步庫存');
        if(order.inventoryReservationStatus!=='completed'){
            await synchronizeOrderInventory(orderId,order,uid);
        }
        if(currentUser?.uid===uid){
            ordersCache=ordersCache.map(row=>row.id===orderId?order:row);
            syncOrderIntoPurchasingCaches(order);
            const sourceError=await syncNewOrderSourceDocuments(orderId,order,uid);
            if(currentUser?.uid===uid)showActionFeedback(sourceError?'庫存已同步；來源文件更新待確認：'+sourceError.message:'訂單庫存同步完成。',sourceError?'warning':'success');
        }
    }catch(err){
        if(order&&normalizedOrderStatus(order)==='normal'&&currentUser?.uid===uid&&canRetryOrderInventorySync(order)){
            Object.assign(cachedOrder,order);
        }
        if(currentUser?.uid===uid)showActionFeedback('庫存同步未完成，可在同一筆訂單重試：'+(err.message||err),'warning');
    }finally{
        pendingOrderReservationIds.delete(orderId);
        if(currentUser?.uid===uid){writeAppDataCache('orders',ordersCache);renderOrdersList();}
    }
};

// 採購主頁資料
let poListCache = [];
let poListCursor = null;
let poListHasMore = false;
let poListPageLoading = false;
let poHistorySearchResults = [];
let poHistorySearchActive = false;
let poHistorySearchLoading = false;
let poHistorySearchTimer = null;
let poHistorySearchGeneration = 0;
let purchaseHistorySupplyCache = new Map();
let supplyReceivingCache = [];
let supplyReceivingCursor = null;
let supplyReceivingHasMore = true;
let receivingSourceOrderStatusCache = new Map();
let receivingSourceOrderCache = new Map();
let purchasingOrderRefreshPromise = null;
let purchasingOrdersReady = false;
let purchasingReceivingLoadPromise = null;
let activeReceivingSupplyLoadPromise = null;
let activeReceivingSupplyReady=false, activeReceivingSupplyError='';
let purchasingReceivingReady = false;
let purchasingView = 'ordering';
let pendingPurchaseCursor = null;
let pendingPurchaseHasMore = true;
let pendingPurchaseLoading = false;
let pendingPurchaseCache = [];
let procurementDemandCache = [];
let procurementDemandCursor = null;
let procurementDemandHasMore = true;
let procurementDemandLoaded = false;
let procurementDemandSourceOrderCache = new Map();
const selectedPendingPurchaseDemandIds = new Set();

function invalidateProcurementDemandQueue(options = {}) {
    purchaseDemandSummaryReady=false;
    if(document.getElementById('purchasing-system')?.classList.contains('active'))loadPurchaseDemandSummary(true);
    markMainPageDirty('orders.po');
    if (options.preserveQueue) return;
    procurementDemandCache=[];
    procurementDemandCursor=null;
    procurementDemandHasMore=true;
    procurementDemandLoaded=false;
    procurementDemandSourceOrderCache=new Map();
    selectedPendingPurchaseDemandIds.clear();
    purchasingViewLoaded?.delete?.('ordering');
}

function syncCommittedQuickPurchaseDemand(demand, order) {
    // Keep loaded pages and their cursor: confirming one item must not reset the queue.
    if (demand?.id) {
        const index = procurementDemandCache.findIndex(row => row.id === demand.id);
        if (Number(demand.remainingToOrderQty || 0) > 0) {
            if (index >= 0) procurementDemandCache[index] = demand;
            else procurementDemandCache.unshift(demand);
        } else if (index >= 0) procurementDemandCache.splice(index, 1);
        selectedPendingPurchaseDemandIds.delete(demand.id);
    }
    if (order?.id) procurementDemandSourceOrderCache.set(order.id, order);
    invalidateProcurementDemandQueue({ preserveQueue:true });
}
let pendingPurchaseError = '';
let purchasingDispatchCache = [];
let purchasingDispatchCursor = null;
let purchasingDispatchHasMore = true;
let purchasingDispatchLoading = false;
let purchasingDispatchError = '';
let purchasingCompletedVisibleLimit = DEFAULT_LIST_LIMIT;
let purchasingAnalyticsRows = [];
let purchasingAnalyticsLoading = false;
let purchasingAnalyticsLoadedRangeKey = '';

const purchasingViewLoaded = new Set();

function refreshPurchasingOrderCache(reset = true, options = {}) {
    if (options.reuseOrders && purchasingOrdersReady) return Promise.resolve(ordersCache);
    if (purchasingOrderRefreshPromise) return purchasingOrderRefreshPromise;
    // 採購頁自己的 caller 會在資料更新後統一 render；
    // 背景共用 orders 查詢只更新 cache，不先重畫一次工作卡。
    purchasingOrderRefreshPromise = Promise.resolve(loadOrderPage(reset, { silent: true, skipRender: true }))
        .then(() => {
            purchasingOrdersReady = true;
            return ordersCache;
        })
        .finally(() => { purchasingOrderRefreshPromise = null; });
    return purchasingOrderRefreshPromise;
}

// 倉管供應檢視由 stock-permissions 在供應異動交易中同步；讀取頁面不寫資料。
async function loadActiveReceivingSupplyCache(reset = true) {
    if (!canAccessPage('orders.po') && !(canAccessPage('inventory') && canReceiveInventoryCapability())) return [];
    if (activeReceivingSupplyLoadPromise) return activeReceivingSupplyLoadPromise;
    const requestedRole = currentUserRole, requestedUid = currentUser?.uid;
    activeReceivingSupplyReady=false; activeReceivingSupplyError='';
    const request = (async () => {
        const records = new Map((reset ? [] : supplyReceivingCache).map(row => [row.id, row]));
        let cursor = null;
        while (true) {
            let query = supplyOrdersCollection()
                .where('status','in',['ORDERED','PARTIAL_RECEIPT'])
                .orderBy(firebase.firestore.FieldPath.documentId())
                .limit(200);
            if (cursor) query = query.startAfter(cursor);
            const snapshot = await firestoreReadWithTimeout(query.get(), '待到貨供應');
            snapshot.docs.forEach(doc => records.set(doc.id, { id:doc.id, ...doc.data() }));
            if (snapshot.size < 200) break;
            cursor = snapshot.docs[snapshot.docs.length - 1];
        }
        if (requestedRole !== currentUserRole || requestedUid !== currentUser?.uid || (!canAccessPage('orders.po') && !(canAccessPage('inventory') && canReceiveInventoryCapability()))) return [];

        const rows = [...records.values()]
            .sort((a,b)=>String(b.orderDate||b.createdAt||'').localeCompare(String(a.orderDate||a.createdAt||'')));
        supplyReceivingCache = rows;
        // 這裡已完整讀取「仍在途」的 active queue；待到貨工作不再受 50 筆歷史分頁影響。
        supplyReceivingCursor = null;
        supplyReceivingHasMore = false;

        const sourceOrderIds = [...new Set(rows.map(row=>String(row.orderId||'').trim()).filter(Boolean))];
        const cachedOrders = new Map(ordersCache.map(order=>[order.id,order]));
        const nextSourceOrders = new Map();
        const nextSourceStatuses = new Map();
        sourceOrderIds.forEach(id => {
            const cached = cachedOrders.get(id);
            if (!cached) return;
            nextSourceOrders.set(id,cached);
            nextSourceStatuses.set(id,normalizedOrderStatus(cached));
        });
        const missingSourceIds = sourceOrderIds.filter(id=>!nextSourceOrders.has(id));
        const sourceOrders = await readDocumentsByIds('orders', missingSourceIds);
        sourceOrders.forEach(order=>{nextSourceOrders.set(order.id,order);nextSourceStatuses.set(order.id,normalizedOrderStatus(order));});
        if (requestedRole !== currentUserRole || requestedUid !== currentUser?.uid || (!canAccessPage('orders.po') && !(canAccessPage('inventory') && canReceiveInventoryCapability()))) return [];
        receivingSourceOrderCache = nextSourceOrders;
        receivingSourceOrderStatusCache = nextSourceStatuses;
        activeReceivingSupplyReady=true;
        return rows;
    })().catch(err=>{
        if(requestedRole===currentUserRole&&requestedUid===currentUser?.uid){activeReceivingSupplyError='待到貨供應讀取失敗';mainPageLoadFailed('orders.po');if(document.getElementById('purchasing-system')?.classList.contains('active'))renderPurchasingView();}
        throw err;
    }).finally(() => {
        if(activeReceivingSupplyLoadPromise===request)activeReceivingSupplyLoadPromise = null;
    });
    activeReceivingSupplyLoadPromise=request;
    return request;
}

function loadPurchasingReceivingQueue(reset = true, options = {}) {
    if (purchasingReceivingLoadPromise) return purchasingReceivingLoadPromise;
    purchasingReceivingReady = false;
    if (options.reuseOrders) {
        const status = document.getElementById('poHistorySearchStatus');
        if (status) status.textContent = '待到貨資料載入中…';
    } else {
        renderPoList();
    }
    purchasingReceivingLoadPromise = Promise.allSettled([
        loadActiveReceivingSupplyCache(reset),
        getDataScope('orders') !== 'none' ? refreshPurchasingOrderCache(reset, options) : Promise.resolve()
    ]).then(results => {
        purchasingReceivingReady = true;
        const failed = results.filter(result => result.status === 'rejected');
        // 「全部採購單」歷史查詢與「待到貨」供應查詢分離，避免兩頁同時載入時共用 lock
        // 造成 supplyOrders 沒有真正查到、卻被誤標成已載入的 0 筆狀態。
        mergeReceivingSourceOrdersIntoOrderCache();
        renderPurchasingView();
        if (document.getElementById('inventory-system')?.classList.contains('active') && inventoryReceivingVisible) renderPurchasingReceivingWorkList(null, null, null, null, true);
        if (failed.length) throw failed[0].reason;
    }).finally(() => {
        purchasingReceivingLoadPromise = null;
    });
    return purchasingReceivingLoadPromise;
}

let purchasingFilterOptionsSignature = '';

function populatePurchasingFilters() {
    const salesSelect = document.getElementById('purchaseSalesFilter');
    const brandSelect = document.getElementById('purchaseBrandFilter');
    if (!salesSelect || !brandSelect) return;
    const salesValue = salesSelect.value;
    const brandValue = brandSelect.value;
    const sales = workflowSalesFilterNames();
    const brands = workflowPurchasingBrandNames();
    const signature = JSON.stringify([sales, brands]);

    // renderPurchasingView 會在切頁、篩選、背景更新時反覆呼叫；選項沒變就不要重建整個 select DOM。
    if (signature !== purchasingFilterOptionsSignature) {
        salesSelect.innerHTML = '<option value="">全部負責業務</option>' + sales.map(name =>
            `<option value="${escapeAttr(name)}">${escapeHtml(name)}</option>`).join('');
        brandSelect.innerHTML = '<option value="">全部廠牌</option>' + brands.map(brand =>
            `<option value="${escapeAttr(brand)}">${escapeHtml(brand)}</option>`).join('')
            + `<option value="${OTHER_BRAND_OPTION_KEY}">其他廠牌</option>`;
        purchasingFilterOptionsSignature = signature;
    }
    if (sales.includes(salesValue)) salesSelect.value = salesValue;
    else if (salesSelect.value && !sales.includes(salesSelect.value)) salesSelect.value = '';
    if (brands.includes(brandValue) || brandValue === OTHER_BRAND_OPTION_KEY) brandSelect.value = brandValue;
    else if (brandSelect.value && !brands.includes(brandSelect.value)) brandSelect.value = '';
}

function purchasePeriodRange() {
    if (['ordering', 'receiving', 'dispatch'].includes(purchasingView)) return { start:'', end:'' };
    const preset = document.getElementById('poPeriodFilter')?.value || 'this-year';
    if (preset === 'custom') return {
        start: document.getElementById('purchasePeriodStart')?.value || '',
        end: document.getElementById('purchasePeriodEnd')?.value || ''
    };
    return unifiedPeriodRange(preset);
}

function purchaseFilterContext() {
    const { start, end } = purchasePeriodRange();
    return {
        start,
        end,
        selectedSales: document.getElementById('purchaseSalesFilter')?.value || '',
        selectedBrand: document.getElementById('purchaseBrandFilter')?.value || '',
        selectableBrands: workflowPurchasingBrandNames()
    };
}

function purchaseLineMatchesFilters(date, salesName, brand, context = null) {
    const filters = context || purchaseFilterContext();
    const businessDate = normalizeBusinessDate(date);
    if ((filters.start || filters.end) && (!businessDate || (filters.start && businessDate < filters.start) || (filters.end && businessDate > filters.end))) return false;
    if (filters.selectedSales && stripPhoneSuffix(salesName) !== filters.selectedSales) return false;
    return !filters.selectedBrand || orderBrandFilterValue(brand, filters.selectableBrands) === filters.selectedBrand;
}

function procurementDemandForOrderItem(order, item, dispatchOverride = null) {
    const dispatch = dispatchOverride || itemDispatchState(order,item);
    const fulfillmentType = item.fulfillmentType || order.fulfillmentType || 'WAREHOUSE';
    const directShip = fulfillmentType === 'DIRECT_SHIP';
    const hasWarehouseShipments = Array.isArray(order.warehouseShipmentRecords) && order.warehouseShipmentRecords.length > 0;
    let source=item,warehouseShipmentContext;
    if(hasWarehouseShipments){
        // Validate every line before partitioning: a sibling's corrupt event
        // must not disappear when this page renders only the selected item.
        const projected=globalThis.YushinFulfillment.projectOrderShipmentReturns({orderId:order.id,items:order.items,
            shipments:order.warehouseShipmentRecords,deliveries:order.deliveryRecords??[],returns:order.returnRecords??[]});
        source=order.items.find(row=>row.itemId===item.itemId);
        if(!source||!projected.items.some(row=>row.itemId===item.itemId))throw Error('找不到原始採購需求品項。');
        // Presentation normalization measures pending acknowledgement. Physical
        // demand must retain the raw reservation/shortage after warehouse debit.
        warehouseShipmentContext={orderId:order.id,itemId:source.itemId,productKey:source.inventoryProductKey||source.productId,
            shipments:order.warehouseShipmentRecords.filter(row=>row.itemId===source.itemId),
            deliveries:(order.deliveryRecords??[]).filter(row=>row.itemId===source.itemId),
            returns:(order.returnRecords??[]).filter(row=>row.itemId===source.itemId)};
    }
    const quantities = globalThis.YushinWorkflow?.procurementQuantities({
        orderedQty:source.orderedQty ?? source.qty,
        fulfillmentType,
        productType:source.productType||item.productType||order.productType||'',
        ...(hasWarehouseShipments?{warehouseShipmentContext,warehouseShippedQty:source.warehouseShippedQty}:{}),
        reservedQty:source.reservedQty,
        shortageQty:source.shortageQty,
        supplyOrderedQty:item.supplyOrderedQty,
        receivedQty:item.receivedQty,
        deliveredQty:dispatch.grossDelivered,
        effectiveDeliveredQty:dispatch.delivered,
        // Normalized items exclude CLOSE returns for legacy replacement demand.
        // The v2 dispatch adapter reads the original cumulative return snapshot,
        // which Workflow checks against the authoritative shipment/return events.
        returnedQty:directShip || hasWarehouseShipments ? dispatch.returned : Number(item.returnedQty ?? dispatch.returned ?? 0)
    });
    if (!quantities) throw new Error('Workflow core 未載入，無法計算採購需求。');
    const demand = globalThis.YushinProcurementDemand?.fromSalesOrder({
        sourceId:order.id || '',
        sourceItemId:item.itemId || '',
        sourceItemIndex:(order.items||[]).findIndex((row,index)=>String(row.itemId||`item-${index+1}`)===String(item.itemId||'')),
        fulfillmentType,
        shortageQty:quantities.requiredSupplyQty,
        inTransitQty:quantities.inTransitQty,
        requiredSupplyQty:quantities.requiredSupplyQty,
        supplyOrderedQty:quantities.supplyOrderedQty,
        receivedQty:quantities.receivedQty,
        // Material Request / demand date: when the business needs the item.
        // Keep this separate from supplier ETA stored on supplyOrders.
        scheduleDate:item.requiredByDate||item.scheduleDate||order.requiredByDate||order.expectedDate||''
    });
    if (!demand) throw new Error('Procurement Demand core 未載入，無法計算採購需求。');
    return demand;
}

function procurementDemandRef(demandId) {
    const id=String(demandId||'').trim();
    return id ? db.collection('procurementDemands').doc(encodeURIComponent(id)) : null;
}

function procurementDemandDocument(demand={},context={},meta={}) {
    if (!globalThis.YushinProcurementDemand?.demandDocument) {
        throw new Error('Procurement Demand core 未載入，無法建立正式採購需求。');
    }
    return globalThis.YushinProcurementDemand.demandDocument({
        ...demand,
        ...context
    },meta);
}

function remainingProcurementQty(order, item, dispatchOverride = null) {
    return procurementDemandForOrderItem(order,item,dispatchOverride).remainingToOrderQty;
}

function purchasingLifecycleSnapshot(normalizedItemsByOrder, sourceOrders = ordersCache) {
    const itemMap = normalizedItemsByOrder || new Map(
        sourceOrders.map(order => [order.id, normalizedOrderItems(order)])
    );
    return new Map(
        sourceOrders.map(order => [order.id, orderLifecycleInfo(order, itemMap.get(order.id) || [])])
    );
}

function purchasingDispatchStateSnapshot(normalizedItemsByOrder, sourceOrders = ordersCache) {
    const itemMap = normalizedItemsByOrder || new Map(
        sourceOrders.map(order => [order.id, normalizedOrderItems(order)])
    );
    return new Map(
        sourceOrders.map(order => {
            const items = itemMap.get(order.id) || [];
            return [order.id, new Map(items.map(item => [item, itemDispatchState(order, item)]))];
        })
    );
}

function pendingProcurementDisplayLines(order, normalizedItems = null, dispatchStateByItem = null, lifecycleOverride = null) {
    if (normalizedOrderStatus(order) !== 'normal' || ['pending','failed'].includes(order?.inventoryReservationStatus)) return [];
    // 工作卡與明細只讀訂單本身；不要在 render 階段解析成本／Product Master。
    // 同一輪採購頁 render 可直接沿用已 normalize 的品項快照。
    // 真正按「已採購／產生採購單」時，pendingPurchaseLines() 才補齊正式採購資料。
    const items = normalizedItems || normalizedOrderItems(order);
    const lifecycle = lifecycleOverride || orderLifecycleInfo(order, items);
    return items.map((item, index) => {
        const dispatch = dispatchStateByItem?.get(item) || itemDispatchState(order, item);
        if (orderItemWorkCategory(order, item, lifecycle, dispatch) !== 'ordering') return null;
        const demand = procurementDemandForOrderItem(order, item, dispatch);
        const qty = demand.remainingToOrderQty;
        if (!(qty > 0)) return null;
        return {
            orderId: order.id,
            orderItemIndex: index,
            itemId: item.itemId || `item-${index + 1}`,
            itemName: item.itemName || '',
            itemCode: item.itemCode || '',
            productId: item.productId || '',
            brand: item.brand || '',
            productLine: item.productLine || '',
            supplier: item.supplier || '',
            warehouseId: item.warehouseId || '',
            qty,
            demandId:demand.demandId || '',
            sourceType:demand.sourceType || 'SALES_ORDER',
            sourceId:demand.sourceId || order.id || '',
            sourceItemId:demand.sourceItemId || item.itemId || '',
            demandStatus:demand.status,
            demandStatusLabel:globalThis.YushinProcurementDemand?.statusLabel(demand.status) || '待採購',
            salesName: order.salesName || '',
            fulfillmentType: item.fulfillmentType || order.fulfillmentType || 'WAREHOUSE',
            procurementType: item.procurementType || order.procurementType || 'PURCHASING_PO'
        };
    }).filter(Boolean);
}

function receivingSupplyMetrics(filters = purchaseFilterContext()) {
    const metrics = { count:0, amount:0, missingCost:0, quantity:0 };
    const seen = new Set();
    supplyReceivingCache.forEach(supply => {
        if (seen.has(supply.id)) return;
        seen.add(supply.id);
        const progress = globalThis.YushinSupply?.receiptProgress(supply);
        if (!progress || !['ORDERED', 'PARTIAL_RECEIPT'].includes(progress.status) || !(progress.remainingQty > 0)) return;
        const order = receivingSourceOrderForItem(supply);
        // Standalone company stock is shared; linked supplies retain their sales filter.
        // A cancelled customer order does not cancel the real supplier commitment.
        const effectiveFilters = supply.orderId ? filters : {...filters, selectedSales:''};
        if (!purchaseLineMatchesFilters(order?.orderDate || supply.orderDate || supply.createdAt,
            order?.salesName || supply.salesName || '', supply.brand, effectiveFilters)) return;
        metrics.count += 1;
        metrics.quantity += progress.remainingQty;
        const cost = tradeAnalysisCost(supply.unitCost);
        if (cost === null) metrics.missingCost += 1;
        else metrics.amount += progress.remainingQty * cost;
    });
    return metrics;
}

let purchaseDemandSummaryRows = [], purchaseDemandSummaryReady = false, purchaseDemandSummaryError = '';
let purchaseDemandSummaryPromise = null, purchaseDemandSummaryGeneration = 0;
async function loadPurchaseDemandSummary(force = false) {
    if (!canCreatePurchaseOrderCapability()) return;
    if (purchaseDemandSummaryPromise && !force) return purchaseDemandSummaryPromise;
    const generation = ++purchaseDemandSummaryGeneration, uid=currentUser?.uid, role=currentUserRole;
    purchaseDemandSummaryReady=false; purchaseDemandSummaryError='';
    const request=(async()=>{
        try {
            const rows=await readQueryInBatches(db.collection('procurementDemands').where('remainingToOrderQty','>',0).orderBy('remainingToOrderQty','desc'),200);
            const ids=rows.filter(row=>row.sourceType==='SALES_ORDER').map(row=>row.sourceId);
            const orders=await readDocumentsByIds('orders',ids);
            if(generation!==purchaseDemandSummaryGeneration || uid!==currentUser?.uid || role!==currentUserRole)return;
            orders.forEach(row=>procurementDemandSourceOrderCache.set(row.id,row));
            purchaseDemandSummaryRows=rows; purchaseDemandSummaryReady=true;
        } catch(err) {
            if(generation!==purchaseDemandSummaryGeneration || uid!==currentUser?.uid || role!==currentUserRole)return;
            purchaseDemandSummaryError='讀取失敗，請重試'; mainPageLoadFailed('orders.po');
        } finally { if(generation===purchaseDemandSummaryGeneration && document.getElementById('purchasing-system')?.classList.contains('active'))renderPurchasingView(); }
    })();
    purchaseDemandSummaryPromise=request;
    try{return await request;}finally{if(purchaseDemandSummaryPromise===request)purchaseDemandSummaryPromise=null;}
}
function renderPurchasingWorkCards(normalizedItemsByOrder = null, completedRows = null, filterContext = null, dispatchStatesByOrder = null, lifecyclesByOrder = null) {
    const definitions = [
        ['ordering', 'purchaseCountOrdering', 'purchaseAmountOrdering'],
        ['arrival', 'purchaseCountReceiving', 'purchaseAmountReceiving'],
        ['dispatch', 'purchaseCountDispatch', 'purchaseAmountDispatch']
    ];
    const historyFilters = filterContext || purchaseFilterContext();
    const filters = {...historyFilters,start:'',end:''};
    // 同一次採購頁 render 只 normalize 每張訂單一次，工作卡與「已完成」統計共用。
    const itemMap = normalizedItemsByOrder || new Map(
        ordersCache.map(order => [order.id, normalizedOrderItems(order)])
    );
    const stateMap = dispatchStatesByOrder || purchasingDispatchStateSnapshot(itemMap);
    const lifecycleMap = lifecyclesByOrder || purchasingLifecycleSnapshot(itemMap);
    // 訂單頁與採購頁共用完全相同的品項狀態與金額統計核心；
    // 採購頁只額外套自己的日期／業務／廠牌篩選，避免兩頁各算各的再次出現數字不一致。
    const metrics = buildOrderItemWorkMetrics(
        ordersCache,
        definitions.map(([category]) => category),
        (order, item) => purchaseLineMatchesFilters(order.orderDate, order.salesName, item.brand, filters),
        itemMap,
        stateMap,
        lifecycleMap
    );
    const receiving = receivingSupplyMetrics(filters);
    const demandOrderingRows=purchaseDemandSummaryReady ? purchaseDemandSummaryRows.filter(demand=>{
        if(!(Number(demand.remainingToOrderQty||0)>0))return false;
        const order=demand.sourceType==='SALES_ORDER'
            ? procurementDemandSourceOrderCache.get(String(demand.sourceId||'')) || null
            : null;
        if(order&&normalizedOrderStatus(order)!=='normal')return false;
        const date=order?.orderDate||String(demand.createdAt||'').slice(0,10);
        return purchaseLineMatchesFilters(date,demand.salesName||order?.salesName||'',demand.brand||'',filters);
    }) : null;
    const demandOrderingAmount=demandOrderingRows ? demandOrderingRows.reduce((sum,demand)=>{
        const order=demand.sourceType==='SALES_ORDER'
            ? procurementDemandSourceOrderCache.get(String(demand.sourceId||'')) || null
            : null;
        const item=order ? normalizedOrderItems(order).find(row=>String(row.itemId||'')===String(demand.sourceItemId||'')) : null;
        return sum + Number(item?.unitPrice||item?.salesPrice||0)*Number(demand.remainingToOrderQty||0);
    },0) : 0;

    definitions.forEach(([category, countId, amountId]) => {
        const count = document.getElementById(countId);
        const amount = document.getElementById(amountId);
        const useDemand=category==='ordering'&&demandOrderingRows;
        const baseCount=category === 'arrival' ? receiving.count : useDemand?demandOrderingRows.length:metrics[category].count;
        const baseAmount=category === 'arrival' ? receiving.amount : useDemand?demandOrderingAmount:metrics[category].amount;
        if (count) count.textContent = category === 'ordering' && !purchaseDemandSummaryReady ? (purchaseDemandSummaryError || '讀取中…') : category==='arrival' && !activeReceivingSupplyReady ? (activeReceivingSupplyError || '讀取中…') : !orderWorkQueueReady && category === 'dispatch' ? (orderWorkQueueError || '讀取中…') : `${baseCount} 筆`;
        if (amount) amount.textContent = category === 'arrival' && !activeReceivingSupplyReady ? (activeReceivingSupplyError || '讀取中…') : category === 'arrival' && !canCreatePurchaseOrderCapability()
            ? '成本不顯示'
            : formatStatsMoney(baseAmount) + (category === 'arrival' && receiving.missingCost ? `（${receiving.missingCost} 筆待補成本）` : '');
    });
    const stockingSummary = document.getElementById('purchaseStockingSummary');
    if (stockingSummary) {
        const receiving = document.getElementById('purchaseCountReceiving')?.textContent || '0 筆';
        const dispatch = document.getElementById('purchaseCountDispatch')?.textContent || '0 筆';
        stockingSummary.textContent = `待到貨 ${receiving}｜待打單 ${dispatch}`;
    }

    // 圖卡統計已載入資料中的全部已完成品項；50 筆限制只套在下方明細顯示，
    // 避免使用者按「載入更多」時圖卡數字跟著人為跳動。
    const completed = completedRows || purchasingCompletedRows(historyFilters, itemMap, stateMap, lifecycleMap);
    const completedCount = document.getElementById('purchaseCountCompleted');
    const completedAmount = document.getElementById('purchaseAmountCompleted');
    if (completedCount) completedCount.textContent = `${completed.length} 筆`;
    if (completedAmount) completedAmount.textContent = formatStatsMoney(completed.reduce((sum, row) =>
        sum + Number(row.item.unitPrice || row.item.salesPrice || 0) * Number(row.item.qty || row.item.orderedQty || 0), 0));
}

function purchasingCompletedRows(filters = purchaseFilterContext(), normalizedItemsByOrder = null, dispatchStatesByOrder = null, lifecyclesByOrder = null) {
    const rows = [];
    ordersCache.forEach(order => {
        const items = normalizedItemsByOrder?.get(order.id) || normalizedOrderItems(order);
        const lifecycle = lifecyclesByOrder?.get(order.id) || orderLifecycleInfo(order, items);
        if (lifecycle.status !== 'normal') return;
        const orderDispatchStates = dispatchStatesByOrder?.get(order.id) || null;
        items.forEach(item => {
            const state = orderDispatchStates?.get(item) || itemDispatchState(order, item);
            const category = orderItemWorkCategory(order, item, lifecycle, state);
            // 採購端只有在「待採購／待到貨」都結束後才算完成。
            // 倉庫品項還要確認出貨單已打完；原廠直送沒有打單步驟，到貨確認後採購工作即完成。
            if (['ordering', 'arrival', 'closed'].includes(category)) return;
            const directShip = (item.fulfillmentType || order.fulfillmentType || 'WAREHOUSE') === 'DIRECT_SHIP';
            if (!directShip && (Number(item.dispatchPreparedQty || 0) <= 0 || Number(state.pending || 0) > 0)) return;
            if (!purchaseLineMatchesFilters(order.orderDate, order.salesName, item.brand, filters)) return;
            rows.push({ order, item, state });
        });
    });
    return rows;
}

function renderPurchasingCompletedOrders(completedRows = null) {
    const body = document.getElementById('purchaseCompletedBody');
    const status = document.getElementById('purchaseCompletedStatus');
    if (!body) return;
    const allRows = completedRows || purchasingCompletedRows();
    const rows = allRows.slice(0, purchasingCompletedVisibleLimit);
    body.innerHTML = rows.map(({order, item, state}) => `<tr><td data-th="訂單日期">${escapeHtml(order.orderDate || '')}</td><td data-th="客戶">${escapeHtml(order.customerName || order.customer || '')}</td><td data-th="負責業務">${escapeHtml(order.salesName || '')}</td><td data-th="已完成採購品項">${escapeHtml(item.itemCode || item.itemName || item.itemId)} × ${Number(state.prepared || item.dispatchPreparedQty || item.qty || 0)}</td><td data-th="操作" class="no-print"><button type="button" class="btn-small btn-secondary" onclick="openOrderStatusHistory(${inlineJsValue(order.id)})">紀錄</button></td></tr>`).join('');
    if (status) status.textContent = rows.length
        ? `已顯示 ${rows.length} 筆採購已完成品項${purchasingDispatchHasMore || allRows.length > rows.length ? '；可載入更多' : ''}`
        : '目前沒有採購已完成品項';
    const more = document.getElementById('purchaseCompletedMoreBtn');
    if (more) {
        more.style.display = (allRows.length > rows.length || purchasingDispatchHasMore) ? '' : 'none';
        more.disabled = purchasingDispatchLoading;
        more.textContent = purchasingDispatchLoading ? '載入中…' : '載入更多（每次 50 筆）';
    }
}

window.loadMorePurchasingCompleted = async function() {
    if (purchasingDispatchLoading) return;
    purchasingCompletedVisibleLimit += DEFAULT_LIST_LIMIT;
    const filters = purchaseFilterContext();
    const normalizedItemsByOrder = new Map(
        ordersCache.map(order => [order.id, normalizedOrderItems(order)])
    );
    const dispatchStatesByOrder = purchasingDispatchStateSnapshot(normalizedItemsByOrder);
    const lifecyclesByOrder = purchasingLifecycleSnapshot(normalizedItemsByOrder);
    const loadedRows = purchasingCompletedRows(
        filters,
        normalizedItemsByOrder,
        dispatchStatesByOrder,
        lifecyclesByOrder
    );
    if (loadedRows.length < purchasingCompletedVisibleLimit && purchasingDispatchHasMore) {
        // loadPurchasingDispatchOrders() 完成時已統一更新工作卡與已完成明細；
        // 不再回到外層重畫第二次。
        await loadPurchasingDispatchOrders(false);
        return;
    }
    renderPurchasingWorkCards(
        normalizedItemsByOrder,
        loadedRows,
        filters,
        dispatchStatesByOrder,
        lifecyclesByOrder
    );
    renderPurchasingCompletedOrders(loadedRows);
};

function adminPurchaseAnalyticsFilterContext() {
    return {
        start: document.getElementById('salesStatsStart')?.value || '',
        end: document.getElementById('salesStatsEnd')?.value || '',
        selectedSales: stripPhoneSuffix(document.getElementById('salesStatsSalesFilter')?.value || ''),
        selectedBrand: document.getElementById('salesStatsBrandFilter')?.value || '',
        selectableBrands: workflowPurchasingBrandNames()
    };
}

function purchasingAnalyticsRangeKey(filters = adminPurchaseAnalyticsFilterContext()) {
    return JSON.stringify([filters.start || '', filters.end || '']);
}

function purchasingAnalyticsRowMatches(supply, filters = adminPurchaseAnalyticsFilterContext()) {
    const businessDate = normalizeBusinessDate(supply.orderDate || supply.createdAt);
    if ((filters.start || filters.end)
        && (!businessDate || (filters.start && businessDate < filters.start) || (filters.end && businessDate > filters.end))) return false;
    if (filters.selectedSales) {
        const code=String(supply.salesCode||'').trim();
        const codeOwner=code
            ? salesList.find(person=>String(person.code||'').trim()===code)
            : null;
        const resolvedName=stripPhoneSuffix(codeOwner?.name||supply.salesName||'');
        if (resolvedName !== filters.selectedSales) return false;
    }
    if (filters.selectedBrand
        && orderBrandFilterValue(supply.brand || '', filters.selectableBrands) !== filters.selectedBrand) return false;
    return true;
}

function statisticBrandForSupply(supply = {}) {
    const grouped = orderBrandFilterValue(
        supply.brand || supply.brandName || '',
        workflowPurchasingBrandNames()
    );
    return grouped || OTHER_BRAND_OPTION_KEY;
}

function purchasingAnalyticsMetrics(rows = purchasingAnalyticsRows, filters = adminPurchaseAnalyticsFilterContext()) {
    if (!globalThis.YushinPurchasingAnalytics?.summarize) {
        throw new Error('Purchasing analytics core 未載入，無法計算採購分析。');
    }
    const filtered=(rows||[])
        .filter(row=>purchasingAnalyticsRowMatches(row,filters))
        .map(row=>({ ...row, brand:statisticBrandForSupply(row) }));
    return globalThis.YushinPurchasingAnalytics.summarize(filtered);
}
window.loadPurchasingAnalytics = async function(force = false) {
    if (trueUserRole !== 'admin' || purchasingAnalyticsLoading) return purchasingAnalyticsRows;
    const filters = adminPurchaseAnalyticsFilterContext();
    const rangeKey = purchasingAnalyticsRangeKey(filters);
    if (!force && purchasingAnalyticsLoadedRangeKey === rangeKey) {
        renderUnifiedBrandAnalytics();
        return purchasingAnalyticsRows;
    }
    purchasingAnalyticsLoading = true;
    try {
        let query = supplyOrdersCollection();
        if (filters.start) query = query.where('orderDate', '>=', filters.start);
        if (filters.end) query = query.where('orderDate', '<=', filters.end);
        query = query.orderBy('orderDate', 'desc');

        purchasingAnalyticsRows = await readQueryInBatches(query);
        purchasingAnalyticsLoadedRangeKey = rangeKey;
        return purchasingAnalyticsRows;
    } catch (err) {
        console.error('進銷存採購資料讀取失敗：', err);
        throw err;
    } finally {
        purchasingAnalyticsLoading = false;
        renderUnifiedBrandAnalytics();
    }
};

window.renderPurchasingView = function() {
    renderFormalPurchaseRecovery();
    populatePurchasingFilters();
    if (purchasingView === 'suppliers') {
        renderSupplierMasterAdmin();
        renderSupplierMappingAdmin();
        return;
    }
    if (purchasingView === 'replenishment') {
        renderInventoryReplenishmentCenter();
        return;
    }
    if (purchasingView === 'history') {
        // 全部採購單不顯示工作卡；直接畫正式採購單歷史，
        // 不需要為了被隱藏的卡片掃描整批 ordersCache。
        renderPoList();
        return;
    }
    const filters = purchaseFilterContext();
    const normalizedItemsByOrder = new Map(
        ordersCache.map(order => [order.id, normalizedOrderItems(order)])
    );
    const dispatchStatesByOrder = purchasingDispatchStateSnapshot(normalizedItemsByOrder);
    const lifecyclesByOrder = purchasingLifecycleSnapshot(normalizedItemsByOrder);
    const completedRows = purchasingView === 'completed'
        ? purchasingCompletedRows(filters, normalizedItemsByOrder, dispatchStatesByOrder, lifecyclesByOrder)
        : null;
    renderPurchasingWorkCards(normalizedItemsByOrder, completedRows, filters, dispatchStatesByOrder, lifecyclesByOrder);
    if (purchasingView === 'ordering') renderPendingPurchaseOrders(normalizedItemsByOrder, filters, dispatchStatesByOrder, lifecyclesByOrder);
    else if (purchasingView === 'dispatch') renderPurchasingDispatchOrders(normalizedItemsByOrder, filters, dispatchStatesByOrder, lifecyclesByOrder);
    else if (purchasingView === 'completed') renderPurchasingCompletedOrders(completedRows);
    else renderPoList(normalizedItemsByOrder, filters, dispatchStatesByOrder, lifecyclesByOrder);
};

window.changePurchasePeriod = function(value) {
    const custom = document.getElementById('purchaseCustomPeriod');
    if (custom) custom.style.display = value === 'custom' ? 'flex' : 'none';
    if (value === 'custom') {
        const start = document.getElementById('purchasePeriodStart');
        const end = document.getElementById('purchasePeriodEnd');
        if (start && !start.value) start.value = `${new Date().getFullYear()}-01-01`;
        if (end && !end.value) end.value = dateOnlyFromTimestamp(new Date().toISOString());
    }
    renderPurchasingView();
};

window.switchPurchasingView = function(view, tab) {
    if (!canAccessPage('orders.po')) return;
    if (!['ordering', 'receiving', 'dispatch', 'completed', 'replenishment', 'history', 'suppliers'].includes(view)) return;
    if (currentUserRole === 'warehouse' && !['receiving','dispatch','completed'].includes(view)) return;
    if (view === 'ordering' && !canCreatePurchaseOrderCapability()) return;
    if (view === 'suppliers' && !canCreatePurchaseOrderCapability()) return;
    const previousPurchasingView = purchasingView;
    purchasingView = view;
    if (view === 'completed' && previousPurchasingView !== 'completed') purchasingCompletedVisibleLimit = DEFAULT_LIST_LIMIT;
    populatePurchasingFilters();
    const workflowView = !['history', 'suppliers'].includes(view);
    const filters = workflowView ? purchaseFilterContext() : null;
    const normalizedItemsByOrder = workflowView
        ? new Map(ordersCache.map(order => [order.id, normalizedOrderItems(order)]))
        : null;
    const dispatchStatesByOrder = workflowView
        ? purchasingDispatchStateSnapshot(normalizedItemsByOrder)
        : null;
    const lifecyclesByOrder = workflowView
        ? purchasingLifecycleSnapshot(normalizedItemsByOrder)
        : null;
    const completedRows = view === 'completed'
        ? purchasingCompletedRows(filters, normalizedItemsByOrder, dispatchStatesByOrder, lifecyclesByOrder)
        : null;
    if (workflowView) renderPurchasingWorkCards(normalizedItemsByOrder, completedRows, filters, dispatchStatesByOrder, lifecyclesByOrder);
    const orderingTab = document.getElementById('purchase-card-ordering');
    const replenishmentTab = document.getElementById('purchase-card-replenishment');
    if (orderingTab) orderingTab.style.display = canCreatePurchaseOrderCapability() ? '' : 'none';
    if (replenishmentTab) replenishmentTab.style.display = canCreatePurchaseOrderCapability() ? '' : 'none';
    const activeTaskId = view === 'ordering'
        ? 'purchase-card-ordering'
        : (view === 'replenishment'
            ? 'purchase-card-replenishment'
            : (['receiving', 'dispatch', 'completed'].includes(view) ? 'purchase-card-stocking' : ''));
    document.querySelectorAll('#purchaseWorkCards .order-work-card').forEach(el =>
        el.classList.toggle('active', !!activeTaskId && el.id === activeTaskId)
    );
    document.querySelectorAll('#purchaseFulfillmentTabs .purchase-stage-button').forEach(el =>
        el.classList.toggle('active', el.id === `purchase-card-${view}`)
    );
    document.getElementById('purchase-tab-work')?.classList.toggle('active', ['ordering','receiving','dispatch','completed'].includes(view));
    document.getElementById('purchase-tab-history')?.classList.toggle('active', view === 'history');
    document.getElementById('purchase-tab-suppliers')?.classList.toggle('active', view === 'suppliers');
    const cards = document.getElementById('purchaseWorkCards');
    if (cards) cards.style.display = 'none';
    const directButton = document.getElementById('purchaseDirectOrderBtn');
    if (directButton) directButton.style.display = canCreatePurchaseOrderCapability() ? '' : 'none';
    const directPanel=document.getElementById('purchaseDirectPanel');
    if(directPanel)directPanel.style.display=view==='ordering'&&canCreatePurchaseOrderCapability()?'':'none';
    ['purchase-tab-history','purchase-tab-suppliers'].forEach(id => { const el=document.getElementById(id); if(el)el.style.display=canCreatePurchaseOrderCapability()?'':'none'; });
    const businessTab = document.getElementById('purchase-tab-work');
    if (businessTab) {
        businessTab.style.display = canCreatePurchaseOrderCapability() || currentUserRole === 'warehouse' ? '' : 'none';
        businessTab.textContent = currentUserRole === 'warehouse' ? '外倉出貨' : '採購需求';
        businessTab.setAttribute('onclick', currentUserRole === 'warehouse' ? "switchPurchasingView('dispatch')" : "switchPurchasingView('ordering')");
    }
    const businessStages = document.getElementById('purchaseBusinessStages');
    if (businessStages) businessStages.style.display = ['ordering','receiving','dispatch','completed'].includes(view) ? '' : 'none';
    const documentStages = document.getElementById('purchaseDocumentStages');
    if (documentStages) documentStages.style.display = 'none';
    document.querySelectorAll('[data-purchase-stage]').forEach(el => el.classList.toggle('active', el.dataset.purchaseStage === view));
    const periodSelect = document.getElementById('poPeriodFilter');
    if (periodSelect) {
        const showPeriod = ['history','completed'].includes(view);
        periodSelect.style.display = showPeriod ? '' : 'none';
        const label = document.querySelector('label[for="poPeriodFilter"]');
        if (label) label.style.display = showPeriod ? '' : 'none';
        const custom = document.getElementById('purchaseCustomPeriod');
        if (custom) custom.style.display = showPeriod && periodSelect.value === 'custom' ? '' : 'none';
        const note = document.querySelector('#purchaseFilterToolbar .order-period-note');
        if (note) note.textContent = showPeriod ? '依選擇日期查詢歷史紀錄。' : '顯示跨年度未完成工作，避免漏掉舊需求。';
    }
    const filterToolbar = document.getElementById('purchaseFilterToolbar');
    if (filterToolbar) filterToolbar.style.display = (view === 'suppliers' || view === 'replenishment') ? 'none' : '';
    const fulfillmentTabs = document.getElementById('purchaseFulfillmentTabs');
    if (fulfillmentTabs) fulfillmentTabs.style.display = 'none';
    const pendingPanel=document.getElementById('purchasePendingPanel');
    const replenishmentPanel=document.getElementById('purchaseReplenishmentPanel');
    const poPanel=document.getElementById('poListPanel');
    const dispatchPanel=document.getElementById('purchaseDispatchPanel');
    const completedPanel=document.getElementById('purchaseCompletedPanel');
    const supplierPanel=document.getElementById('purchaseSupplierPanel');
    if(pendingPanel)pendingPanel.style.display=view==='ordering'?'':'none';
    if(replenishmentPanel)replenishmentPanel.style.display=(view==='ordering'||view==='replenishment')&&canCreatePurchaseOrderCapability()?'':'none';
    if(poPanel)poPanel.style.display=(view==='receiving'||view==='history')?'':'none';
    if(dispatchPanel)dispatchPanel.style.display=view==='dispatch'?'':'none';
    if(completedPanel)completedPanel.style.display=view==='completed'?'':'none';
    if(supplierPanel)supplierPanel.style.display=view==='suppliers'?'':'none';
    if (view === 'suppliers') {
        renderSupplierSettingsAdmin();
        renderProductSupplierMappingAdmin();
        if (!purchasingViewLoaded.has('suppliers')) {
            purchasingViewLoaded.add('suppliers');
            loadSupplierWarehouseMasters(false).catch(err => {
                purchasingViewLoaded.delete('suppliers');
                console.error('供應商主檔首次載入失敗：', err);
            });
        }
    } else if (view === 'replenishment') {
        renderInventoryReplenishmentCenter();
        loadInventoryReplenishmentCenter(false).catch(err => console.error('安全庫存補貨自動更新失敗：', err));
    } else if (view === 'ordering') {
        if (canCreatePurchaseOrderCapability()) {
            renderInventoryReplenishmentCenter();
            loadInventoryReplenishmentCenter(false).catch(err => console.error('安全庫存補貨讀取失敗：', err));
        }
        renderPendingPurchaseOrders();
        if (!purchasingViewLoaded.has('ordering')) {
            purchasingViewLoaded.add('ordering');
            loadPendingPurchaseOrders(true).catch(err => {
                purchasingViewLoaded.delete('ordering');
                console.error('待採購首次載入失敗：', err);
            });
        }
    } else if (view === 'receiving') {
        renderPoList(normalizedItemsByOrder, filters, dispatchStatesByOrder, lifecyclesByOrder);
        if (!purchasingViewLoaded.has('receiving')) {
            purchasingViewLoaded.add('receiving');
            loadPurchasingReceivingQueue(true, { reuseOrders:true }).catch(err => {
                purchasingViewLoaded.delete('receiving');
                console.error('待到貨首次載入失敗：', err);
            });
        }
    } else if (view === 'history') {
        // 全部採購單採 Gmail 式 stale-while-revalidate：
        // 先顯示上次快取，首次進入本次工作階段時才背景更新；切回此頁不重查第一頁。
        if (!poListCache.length) {
            const cached = readAppDataCache('purchase-history');
            if (cached?.records?.length) poListCache = cached.records;
        }
        renderPoList();
        if (!purchasingViewLoaded.has('history')) {
            purchasingViewLoaded.add('history');
            loadPurchaseOrderPage(true).catch(err => {
                purchasingViewLoaded.delete('history');
                console.error('採購單紀錄首次載入失敗：', err);
            });
        }
    } else if (view === 'dispatch') {
        loadWarehouseMaster();
        renderPurchasingDispatchOrders(normalizedItemsByOrder, filters, dispatchStatesByOrder, lifecyclesByOrder);
        if (!purchasingViewLoaded.has('dispatch')) {
            purchasingViewLoaded.add('dispatch');
            Promise.resolve(loadPurchasingDispatchOrders(true, { reuseOrders:true })).catch(err => {
                purchasingViewLoaded.delete('dispatch');
                console.error('待打單首次載入失敗：', err);
            });
        }
    } else renderPurchasingCompletedOrders(completedRows);
};

async function loadPurchasingDispatchOrders(reset=true, options={}) {
    if (!canAccessPage('orders.po') || purchasingDispatchLoading) return;
    // 切到待打單時若共用訂單 cache 已完成雲端讀取，畫面在 switchPurchasingView()
    // 已經算好並畫出，避免同一批資料立刻再跑一次 dispatch/lifecycle snapshot。
    if (options.reuseOrders && purchasingOrdersReady) {
        purchasingDispatchError = '';
        purchasingDispatchHasMore = !!orderPaginationState && orderPaginationState.sourceIndex < orderPaginationState.sources.length;
        return ordersCache;
    }
    purchasingDispatchError = '';
    purchasingDispatchLoading = true;
    let normalizedItemsByOrder = null;
    let dispatchStatesByOrder = null;
    let lifecyclesByOrder = null;
    let filters = null;
    let completedRows = null;
    const refreshButton = document.getElementById(purchasingView === 'completed'
        ? 'purchaseCompletedRefreshBtn'
        : 'purchaseDispatchRefreshBtn');
    if (refreshButton && reset) { refreshButton.disabled = true; refreshButton.textContent = '更新中…'; }
    if (options.reuseOrders) {
        const status = document.getElementById(purchasingView === 'completed'
            ? 'purchaseCompletedStatus'
            : 'purchaseDispatchStatus');
        if (status) status.textContent = '載入中…';
    } else if (purchasingView === 'completed') {
        renderPurchasingCompletedOrders();
    } else {
        renderPurchasingDispatchOrders();
    }
    try {
        await refreshPurchasingOrderCache(reset, options);
        normalizedItemsByOrder = new Map(
            ordersCache.map(order => [order.id, normalizedOrderItems(order)])
        );
        dispatchStatesByOrder = purchasingDispatchStateSnapshot(normalizedItemsByOrder);
        lifecyclesByOrder = purchasingLifecycleSnapshot(normalizedItemsByOrder);
        filters = purchaseFilterContext();
        purchasingDispatchCache = ordersCache.filter(order => {
            const items = normalizedItemsByOrder.get(order.id) || [];
            const lifecycle = lifecyclesByOrder.get(order.id) || orderLifecycleInfo(order, items);
            const states = dispatchStatesByOrder.get(order.id);
            return items.some(item =>
                orderItemDisplayCategories(order, item, lifecycle, states?.get(item)).includes('dispatch')
            );
        });
        purchasingDispatchHasMore = !!orderPaginationState && orderPaginationState.sourceIndex < orderPaginationState.sources.length;
        completedRows = purchasingView === 'completed'
            ? purchasingCompletedRows(filters, normalizedItemsByOrder, dispatchStatesByOrder, lifecyclesByOrder)
            : null;
        renderPurchasingWorkCards(normalizedItemsByOrder, completedRows, filters, dispatchStatesByOrder, lifecyclesByOrder);
    } catch (err) {
        purchasingDispatchError = `待打單清單讀取失敗，請重試：${String(err?.message || err).slice(0, 160)}`;
    } finally {
        purchasingDispatchLoading = false;
        if (refreshButton) { refreshButton.disabled = false; refreshButton.textContent = '↻ 更新'; }
        if (purchasingView === 'completed') renderPurchasingCompletedOrders(completedRows);
        else renderPurchasingDispatchOrders(normalizedItemsByOrder, filters, dispatchStatesByOrder, lifecyclesByOrder);
    }
}

window.loadPurchasingDispatchOrders=loadPurchasingDispatchOrders;

let dispatchListDraft=null;
window.openWarehouseDispatchList=async function(orderId,selectedWarehouseId=''){
    if(!canReceiveInventoryCapability()||!canAccessPage('inventory'))return;
    try{
        const [snapshot]=await Promise.all([
            firestoreReadWithTimeout(db.collection('orders').doc(orderId).get(),'出貨清單訂單'),loadWarehouseMaster()
        ]);
        if(!snapshot.exists)throw new Error('找不到訂單。');
        const order={...snapshot.data(),id:orderId};
        if(normalizedOrderStatus(order)!=='normal'||orderInventorySyncIncomplete(order))throw new Error('訂單已取消或庫存尚未同步完成。');
        const groups=new Map();
        normalizedOrderItems(order).forEach(item=>{
            if((item.fulfillmentType||'WAREHOUSE')==='DIRECT_SHIP')return;
            const state=itemDispatchState(order,item);
            // Include prepared but unshipped items too, so lists may be downloaded again.
            const qty=state.shippable;
            if(qty<=0)return;
            const warehouseId=item.warehouseId||order.warehouseId||defaultWarehouse()?.id||'';
            if(selectedWarehouseId&&warehouseId!==selectedWarehouseId)return;
            if(!warehouseId)throw new Error('品項尚未指定出貨倉庫。');
            const warehouse=warehouseMasterCache.find(row=>row.id===warehouseId);
            if(!groups.has(warehouseId))groups.set(warehouseId,{warehouseId,name:warehouse?.warehouseName||warehouseId,items:[]});
            groups.get(warehouseId).items.push({itemId:item.itemId,code:item.itemCode||'',name:item.itemName||'',qty,lotNo:''});
        });
        if(!groups.size)throw new Error('目前沒有可建立清單的庫存出貨品項。');
        dispatchListDraft={orderId,orderNo:order.orderNo||order.quoteNo||orderId,customer:order.customerName||'',groups:[...groups.values()],
            address:order.shippingAddress||order.deliveryAddress||'',contact:order.customerContact||'',phone:order.customerPhone||''};
        let overlay=document.getElementById('warehouseDispatchOverlay');
        if(!overlay){
            overlay=document.createElement('div');overlay.id='warehouseDispatchOverlay';overlay.className='eq-modal-overlay no-print';
            overlay.addEventListener('click',event=>{if(event.target===overlay)closeWarehouseDispatchList();});document.body.appendChild(overlay);
        }
        overlay.innerHTML=`<div class="eq-modal-box" style="max-width:880px"><h3>分倉出貨清單</h3>
            <p>${escapeHtml(dispatchListDraft.orderNo)}｜${escapeHtml(dispatchListDraft.customer)}</p>
            <p>下載後可提供給各倉庫。本清單不扣庫存、不登記送貨；批號請於實際出貨時核對。</p>
            <div class="dispatch-list-fields"><label>送貨地址<input id="dispatchListAddress" value="${escapeAttr(dispatchListDraft.address)}"></label>
            <label>聯絡人<input id="dispatchListContact" value="${escapeAttr(dispatchListDraft.contact)}"></label>
            <label>電話<input id="dispatchListPhone" value="${escapeAttr(dispatchListDraft.phone)}"></label><label>希望出貨日期<input type="date" id="dispatchListDate" value="${localDateString()}"></label><label>出貨備註<textarea id="dispatchListNotes" placeholder="例如冷藏、乾冰、指定時段"></textarea></label></div>
            ${dispatchListDraft.groups.map((group,gi)=>`<section><h4>${escapeHtml(group.name)}</h4><div class="table-wrap"><table><thead><tr><th>貨號</th><th>品名</th><th>數量</th><th>指定批號（選填）</th></tr></thead><tbody>${group.items.map((item,ii)=>`<tr><td>${escapeHtml(item.code)}</td><td>${escapeHtml(item.name)}</td><td><input type="number" min="0" step="any" aria-label="此次出貨數量" value="${item.qty}" data-dispatch-qty-group="${gi}" data-dispatch-qty-item="${ii}"></td><td><input aria-label="指定批號" data-dispatch-group="${gi}" data-dispatch-item="${ii}" placeholder="出貨時確認"></td></tr>`).join('')}</tbody></table></div></section>`).join('')}
            <div class="toolbar"><button class="btn-secondary" onclick="exportWarehouseDispatchList('pdf',this)">下載分倉 PDF</button><button class="btn-secondary" onclick="exportWarehouseDispatchList('excel',this)">下載 Excel</button><button class="btn-secondary" onclick="closeWarehouseDispatchList()">關閉</button></div></div>`;
        overlay.classList.add('active');
    }catch(err){showActionFeedback('出貨清單無法建立：'+err.message,'warning');}
};
window.closeWarehouseDispatchList=function(){document.getElementById('warehouseDispatchOverlay')?.classList.remove('active');dispatchListDraft=null;};
window.exportWarehouseDispatchList=async function(format,button){
    if(!dispatchListDraft||!canReceiveInventoryCapability()||!canAccessPage('inventory'))return;
    const draft=JSON.parse(JSON.stringify(dispatchListDraft));
    draft.address=document.getElementById('dispatchListAddress').value.trim();
    draft.contact=document.getElementById('dispatchListContact').value.trim();draft.phone=document.getElementById('dispatchListPhone').value.trim();
    draft.date=document.getElementById('dispatchListDate').value;draft.notes=document.getElementById('dispatchListNotes').value.trim();
    document.querySelectorAll('#warehouseDispatchOverlay [data-dispatch-qty-group]').forEach(input=>{draft.groups[Number(input.dataset.dispatchQtyGroup)].items[Number(input.dataset.dispatchQtyItem)].qty=Number(input.value);});
    document.querySelectorAll('#warehouseDispatchOverlay [data-dispatch-group]').forEach(input=>{draft.groups[Number(input.dataset.dispatchGroup)].items[Number(input.dataset.dispatchItem)].lotNo=input.value.trim();});
    if((!draft.address||!draft.contact||!draft.phone)&&!confirm('送貨地址、聯絡人或電話尚未填齊，仍要下載清單嗎？'))return;
    const state=beginActionButton(button,'製作中…');if(!state)return;
    let stage;
    try{
        const fresh=await firestoreReadWithTimeout(db.collection('orders').doc(draft.orderId).get(),'核對出貨清單');
        if(!fresh.exists||normalizedOrderStatus(fresh.data())!=='normal'||orderInventorySyncIncomplete(fresh.data()))throw new Error('訂單狀態已變更，請重新建立清單。');
        const order=fresh.data(),items=normalizedOrderItems(order);
        for(const group of draft.groups)for(const item of group.items){
            const current=items.find(row=>row.itemId===item.itemId),stock=current&&itemDispatchState(order,current);
            if(!current||!Number.isFinite(item.qty)||item.qty<=0||(current.warehouseId||order.warehouseId||defaultWarehouse()?.id)!==group.warehouseId||stock.shippable<item.qty)throw new Error('出貨數量或倉庫已變更，請重新建立清單。');
        }
        const safe=value=>String(value).replace(/[\\/:*?"<>|]/g,'_');
        const name=`出貨清單-${safe(draft.orderNo)}-${localDateString()}`;
        if(format==='excel'){
            await ensureXlsxLoaded();
            const wb=XLSX.utils.book_new();
            const rows=draft.groups.flatMap(group=>group.items.map(item=>({'倉庫':group.name,'訂單號':draft.orderNo,'客戶':draft.customer,'送貨地址':draft.address,'聯絡人':draft.contact,'電話':draft.phone,'貨號':item.code,'品名':item.name,'數量':item.qty,'指定批號（出貨時核對）':item.lotNo,'希望出貨日期':draft.date,'出貨備註':draft.notes})));
            XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),'分倉出貨清單');XLSX.writeFile(wb,name+'.xlsx');
        }else if(format==='pdf'){
            if(!window.jspdf?.jsPDF||typeof window.html2canvas!=='function')throw new Error('PDF 元件尚未載入。');
            stage=document.createElement('div');stage.style.cssText='position:fixed;left:-10000px;top:0;width:794px;background:white;';document.body.appendChild(stage);
            const pages=[];
            for(const group of draft.groups){
                for(let offset=0;offset<group.items.length;offset+=10){
                    const page=document.createElement('div');page.style.cssText='width:794px;padding:32px;box-sizing:border-box;background:white;color:#111;font-size:16px;';
                    page.innerHTML=`<h2>出貨清單｜${escapeHtml(group.name)}</h2><p>訂單：${escapeHtml(draft.orderNo)}　希望出貨日期：${escapeHtml(draft.date)}</p><p>出貨備註：${escapeHtml(draft.notes)}</p><p>客戶：${escapeHtml(draft.customer)}</p><p>地址：${escapeHtml(draft.address||'未填')}</p><p>聯絡人：${escapeHtml(draft.contact||'未填')}　電話：${escapeHtml(draft.phone||'未填')}</p><table style="width:100%;table-layout:fixed;border-collapse:collapse"><thead><tr><th>貨號</th><th>品名</th><th>數量</th><th>指定批號</th></tr></thead><tbody>${group.items.slice(offset,offset+10).map(item=>`<tr>${[item.code,item.name,item.qty,item.lotNo||'出貨時確認'].map(value=>`<td style="border:1px solid #999;padding:8px;overflow-wrap:anywhere">${escapeHtml(value)}</td>`).join('')}</tr>`).join('')}</tbody></table><p>請倉庫核對實際出貨批號與數量。本清單不代表已送貨。</p><small>本倉庫第 ${Math.floor(offset/10)+1}／${Math.ceil(group.items.length/10)} 頁</small>`;
                    stage.appendChild(page);pages.push(page);
                }
            }
            const pdf=new window.jspdf.jsPDF({orientation:'portrait',unit:'mm',format:'a4',compress:true});
            await addDocumentPagesToPdf(pdf,pages,{isolateRoot:stage});pdf.save(name+'.pdf');
        }else throw new Error('不支援的下載格式。');
        if(dispatchListDraft?.orderId===draft.orderId)closeWarehouseDispatchList();
    }catch(err){showActionFeedback('出貨清單下載失敗：'+err.message,'warning');}
    finally{stage?.remove();endActionButton(button,state);}
};

