function renderPurchasingDispatchOrders(normalizedItemsByOrder = null, filterContext = null, dispatchStatesByOrder = null, lifecyclesByOrder = null) {
    const body=document.getElementById('purchaseDispatchBody');
    const status=document.getElementById('purchaseDispatchStatus');
    const more=document.getElementById('purchaseDispatchMoreBtn');
    if(!body)return;
    body.innerHTML='';
    const fragment=document.createDocumentFragment();
    let shown=0;
    const sourceOrders = ordersCache.length ? ordersCache : purchasingDispatchCache;
    const filters=filterContext || purchaseFilterContext();
    sourceOrders.forEach(order=>{
        const items = normalizedItemsByOrder?.get(order.id) || normalizedOrderItems(order);
        const lifecycle = lifecyclesByOrder?.get(order.id) || orderLifecycleInfo(order, items);
        const states = dispatchStatesByOrder?.get(order.id) || null;
        const pending=items.map(item=>{
            const state = states?.get(item) || itemDispatchState(order,item);
            return (orderItemDisplayCategories(order, item, lifecycle, state).includes('dispatch')
                || pendingDispatchPreparation(order.id,item.itemId))
                ? {item,state}
                : null;
        }).filter(Boolean);
        pending.forEach(({item,state})=>{
            if (!purchaseLineMatchesFilters(order.orderDate, order.salesName, item.brand, filters)) return;
            const warehouseId = item.warehouseId || order.warehouseId || defaultWarehouse()?.id || '';
            const canPrepareDispatch = currentUserRole === 'purchaser' || currentUserRole === 'admin';
            const preparing = pendingDispatchOrderIds.has(order.id+'__'+item.itemId);
            const action = canPrepareDispatch
                ? `<button type="button" class="btn-small" onclick="markOrderItemDispatchPrepared(${inlineJsValue(order.id)},${inlineJsValue(item.itemId)})" ${preparing?'disabled':''}>${preparing?'處理中…':(pendingDispatchPreparation(order.id,item.itemId)?'確認打單結果':`已打單 × ${state.pending}`)}</button>`
                : '<span class="order-progress-badge">唯讀</span>';
            const tr=document.createElement('tr');
            tr.innerHTML=`<td data-th="訂單日期">${escapeHtml(order.orderDate||'')}</td><td data-th="客戶">${escapeHtml(order.customerName||order.customer||'')}</td><td data-th="負責業務">${escapeHtml(order.salesName||'')}</td><td data-th="待打單品項">${escapeHtml(item.itemCode||item.itemName||item.itemId)} × ${state.pending}</td><td data-th="操作">${action}</td>`;
            fragment.appendChild(tr);
            shown++;
        });
    });
    body.appendChild(fragment);
    if(status)status.textContent=purchasingDispatchLoading?'載入中…':purchasingDispatchError||(shown?`已顯示 ${shown} 筆待打單品項`:'目前沒有待打單品項');
    if(more){more.style.display=purchasingDispatchHasMore?'':'none';more.disabled=purchasingDispatchLoading;}
}

function pendingPurchaseLines(order) {
    if(orderInventorySyncIncomplete(order))return [];
    // 這個函式只代表「採購人員可以建立正式 PO 的品項」；
    // 顯示使用 pendingProcurementDisplayLines()，成本與供應商只在真正操作時解析。
    const displayByIndex = new Map(
        pendingProcurementDisplayLines(order)
            .filter(line => line.procurementType === 'PURCHASING_PO')
            .map(line => [Number(line.orderItemIndex), line])
    );
    if (!displayByIndex.size) return [];
    return purchaseItemsFromOrder(order)
        .filter(line => displayByIndex.has(Number(line.orderItemIndex)))
        .map(line => {
            const demand = displayByIndex.get(Number(line.orderItemIndex));
            return {
                ...line,
                qty:demand.qty,
                demandId:demand.demandId || '',
                sourceType:demand.sourceType || 'SALES_ORDER',
                sourceId:demand.sourceId || order.id || '',
                sourceItemId:demand.sourceItemId || line.itemId || ''
            };
        });
}

function syncOrderIntoPurchasingCaches(order, options = {}) {
    if (!order?.id) return;
    const sync = (cache, include) => {
        const index = cache.findIndex(row => row.id === order.id);
        if (include) {
            if (index >= 0) cache[index] = order;
            else cache.unshift(order);
        } else if (index >= 0) {
            cache.splice(index, 1);
        }
    };
    sync(pendingPurchaseCache, pendingProcurementDisplayLines(order).length > 0);
    sync(purchasingDispatchCache, normalizedOrderItems(order).some(item =>
        orderItemDisplayCategories(order,item).includes('dispatch')
    ));
    receivingSourceOrderStatusCache.set(order.id, normalizedOrderStatus(order));
    receivingSourceOrderCache.set(order.id, order);

    if (options.render === false || !document.getElementById('purchasing-system')?.classList.contains('active')) return;
    // 單筆訂單狀態更新後只走一次統一 renderer；
    // 工作卡與目前明細共用同一批 normalize / dispatch / lifecycle snapshot。
    renderPurchasingView();
}

function syncCommittedPurchaseOrderSources(orders) {
    for (const order of orders) {
        const index = ordersCache.findIndex(row => row.id === order.id);
        if (index >= 0) ordersCache[index] = order;
        else ordersCache.unshift(order);
        syncOrderIntoPurchasingCaches(order, { render:false });
    }
    writeAppDataCache('orders', ordersCache);
    if (document.getElementById('order-system')?.classList.contains('active')) renderOrdersList();
    if (document.getElementById('purchasing-system')?.classList.contains('active')) renderPurchasingView();
}

function updatePendingPurchaseBatchButton() {
    const button=document.getElementById('purchasePendingBatchPoBtn');
    if(!button)return;
    const count=selectedPendingPurchaseDemandIds.size;
    button.disabled=count<2;
    button.textContent=count ? `合併產生採購單（${count}）` : '合併產生採購單';
}

function clearPendingPurchaseSelection() {
    selectedPendingPurchaseDemandIds.clear();
    document.querySelectorAll('.pending-purchase-batch-select').forEach(input=>{ input.checked=false; });
    updatePendingPurchaseBatchButton();
}

window.togglePendingPurchaseSelection = function(demandId, checked) {
    const id=String(demandId||'');
    if(!id)return;
    if(checked)selectedPendingPurchaseDemandIds.add(id);
    else selectedPendingPurchaseDemandIds.delete(id);
    updatePendingPurchaseBatchButton();
};

function renderPendingPurchaseOrders() {
    const body = document.getElementById('purchasePendingBody');
    if (!body) return;
    body.innerHTML = '';
    const fragment = document.createDocumentFragment();
    const filters = purchaseFilterContext();
    let shown = 0;
    const visibleSelectableIds=new Set();

    const rows=[...procurementDemandCache]
        .filter(demand=>demand.sourceType==='SALES_ORDER')
        .filter(demand=>Number(demand.remainingToOrderQty||0)>0)
        .sort((a,b)=>String(a.scheduleDate||a.createdAt||'').localeCompare(String(b.scheduleDate||b.createdAt||'')));

    for(const demand of rows){
        const sourceType=String(demand.sourceType||'');
        const order=sourceType==='SALES_ORDER'
            ? procurementDemandSourceOrderCache.get(String(demand.sourceId||'')) || null
            : null;
        if(order&&normalizedOrderStatus(order)!=='normal')continue;
        const sourceItems=order ? normalizedOrderItems(order) : [];
        const item=sourceItems.find(row=>String(row.itemId||'')===String(demand.sourceItemId||'')) || {};
        const date=order?.orderDate || String(demand.createdAt||'').slice(0,10);
        const salesName=demand.salesName || order?.salesName || '';
        const brand=demand.brand || item.brand || '';
        if(!purchaseLineMatchesFilters(date,salesName,brand,filters))continue;

        const qty=Math.max(0,Number(demand.remainingToOrderQty||0));
        const statusLabel=globalThis.YushinProcurementDemand?.statusLabel(demand.status)||'待採購';
        let customer=order?.customerName||order?.customer||'';
        let actionHtml='';
        const selfOrder=!!order&&(item.procurementType||order.procurementType||'PURCHASING_PO')==='SALES_SELF_ORDER';
        const batchSelectable=sourceType==='SALES_ORDER'&&!!order&&!selfOrder;
        if(batchSelectable)visibleSelectableIds.add(String(demand.id||''));
        const selectionHtml=batchSelectable
            ? `<input type="checkbox" class="pending-purchase-batch-select" aria-label="選取合併採購" ${selectedPendingPurchaseDemandIds.has(String(demand.id||''))?'checked':''} onchange="togglePendingPurchaseSelection(${inlineJsValue(demand.id||'')},this.checked)">`
            : '';

        if(sourceType==='STOCK_REPLENISHMENT'){
            customer='備庫';
            actionHtml=`<button type="button" class="btn-small btn-secondary" onclick="openInventoryReplenishment(${inlineJsValue(demand.sourceId||demand.productKey||demand.productId||'')})">產生採購單</button>`;
        }else if(order){
            // Creation-time self-orders are recorded automatically. Pending rows are
            // synchronization exceptions, not a second routine ordering action.
            const autoSelfOrder = selfOrder && order.selfOrderAtCreation === true && item.selfOrderConfirmed === true;
            const syncState = String(order.inventoryReservationStatus||'');
            actionHtml=autoSelfOrder && syncState !== 'completed'
                ? `<span class="order-progress-badge">${syncState==='failed'?'自行訂貨同步失敗，請至訂單頁重試同步':'自行訂貨自動同步中…'}</span>`
                : selfOrder
                    ? (canBusinessSelfOrder(order)
                        ? `<button type="button" class="btn-small btn-secondary" onclick="openSelfOrderModal(${inlineJsValue(order.id)},${inlineJsValue(demand.sourceItemId||item.itemId||'')})">${autoSelfOrder?'補登異常訂貨':'登記自行訂貨'}</button>`
                        : '<span class="order-progress-badge">自行訂貨・由訂單負責業務處理</span>')
                    : `<button type="button" class="btn-small" onclick="markPurchaseItemOrdered(${inlineJsValue(order.id)},${inlineJsValue(demand.sourceItemId||item.itemId||'')},this)">已採購</button> <button type="button" class="btn-small btn-secondary" onclick="openOrderPurchaseDraft(${inlineJsValue(order.id)},${inlineJsValue(demand.sourceItemId||item.itemId||'')})">產生採購單</button>`;
        }else{
            actionHtml='<span class="order-progress-badge">來源訂單待同步</span>';
        }

        const row=document.createElement('tr');
        row.classList.add('procurement-demand-row');
        row.innerHTML=`<td data-th="合併" class="no-print" style="text-align:center;">${selectionHtml}</td><td data-th="需求日期">${escapeHtml(date)}</td><td data-th="客戶／用途">${escapeHtml(customer)}<div class="record-reference">${order?.orderNo ? `來源客戶訂單・${escapeHtml(order.orderNo)}` : order?.quoteNo ? `來源估價單・${escapeHtml(order.quoteNo)}` : '客戶訂單採購需求'}</div></td><td data-th="負責業務">${escapeHtml(salesName)}</td><td data-th="待採購品項"><strong>${escapeHtml(demand.itemCode||demand.itemName||demand.productKey||demand.demandId)} × ${qty}</strong><div style="font-size:11px;color:#667584;margin-top:3px;">${sourceType==='STOCK_REPLENISHMENT'?'備庫採購':'客戶訂單'}・${escapeHtml(statusLabel)}</div></td><td data-th="操作">${actionHtml}</td>`;
        fragment.appendChild(row);
        shown++;
    }

    for(const id of [...selectedPendingPurchaseDemandIds]){
        if(!visibleSelectableIds.has(id))selectedPendingPurchaseDemandIds.delete(id);
    }
    body.appendChild(fragment);
    updatePendingPurchaseBatchButton();
    const status=document.getElementById('purchasePendingStatus');
    if(status)status.textContent=pendingPurchaseLoading
        ? '載入中…'
        : pendingPurchaseError || (shown
            ? `已顯示 ${shown} 筆業務待採購品項${procurementDemandHasMore?'；尚有更多需求可載入':''}`
            : procurementDemandHasMore ? '目前這一批沒有符合篩選的需求，可載入更多' : '目前沒有待採購需求');
    const more=document.getElementById('purchasePendingMoreBtn');
    if(more){more.style.display=procurementDemandHasMore?'':'none';more.disabled=pendingPurchaseLoading;}
}

window.loadPendingPurchaseOrders = async function(reset = true) {
    if (!canCreatePurchaseOrderCapability() || !canAccessPage('orders.po') || pendingPurchaseLoading) return;
    pendingPurchaseError='';
    pendingPurchaseLoading=true;
    const refreshButton=document.getElementById('purchasePendingRefreshBtn');
    if(refreshButton&&reset){refreshButton.disabled=true;refreshButton.textContent='更新中…';}
    if(reset){
        procurementDemandCache=[];
        procurementDemandCursor=null;
        procurementDemandHasMore=true;
        procurementDemandLoaded=false;
        procurementDemandSourceOrderCache=new Map();
        selectedPendingPurchaseDemandIds.clear();
        updatePendingPurchaseBatchButton();
    }
    renderPendingPurchaseOrders();
    try{
        let query=db.collection('procurementDemands')
            .where('remainingToOrderQty','>',0)
            .orderBy('remainingToOrderQty','desc')
            .limit(DEFAULT_LIST_LIMIT);
        if(procurementDemandCursor)query=query.startAfter(procurementDemandCursor);
        const snapshot=await firestoreReadWithTimeout(query.get(),'正式採購需求');
        const fresh=snapshot.docs.map(doc=>({id:doc.id,...doc.data()}));
        procurementDemandCursor=snapshot.empty?null:snapshot.docs[snapshot.docs.length-1];
        procurementDemandHasMore=snapshot.size===DEFAULT_LIST_LIMIT;

        const byId=new Map((reset?[]:procurementDemandCache).map(row=>[row.id,row]));
        fresh.forEach(row=>byId.set(row.id,row));
        procurementDemandCache=[...byId.values()];

        const sourceOrderIds=[...new Set(procurementDemandCache
            .filter(row=>row.sourceType==='SALES_ORDER')
            .map(row=>String(row.sourceId||'')).filter(Boolean))];
        const missing=sourceOrderIds.filter(id=>!procurementDemandSourceOrderCache.has(id));
        if(missing.length){
            const sourceOrders=await readDocumentsByIds('orders',missing);
            sourceOrders.forEach(order=>procurementDemandSourceOrderCache.set(order.id,order));
        }
        pendingPurchaseHasMore=procurementDemandHasMore;
        procurementDemandLoaded=true;
    }catch(err){
        pendingPurchaseError=`待採購需求讀取失敗，請重試：${String(err?.message||err).slice(0,160)}`;
    }finally{
        pendingPurchaseLoading=false;
        if(refreshButton){refreshButton.disabled=false;refreshButton.textContent='↻ 更新';}
        renderPendingPurchaseOrders();
        renderPurchasingWorkCards();
    }
};

const pendingPurchaseOrderKeys = new Set();

function quickPurchaseSupplyId(orderId, itemId) {
    return `manual-${encodeURIComponent(String(orderId || ''))}-${encodeURIComponent(String(itemId || ''))}`;
}

let quickPurchaseConfirmation = null;
let quickPurchaseConfirmationGeneration = 0;

window.closeQuickPurchaseConfirmation = function() {
    quickPurchaseConfirmationGeneration++;
    document.getElementById('quickPurchaseConfirmationOverlay')?.classList.remove('active');
    if (quickPurchaseConfirmation) { quickPurchaseConfirmation(null); quickPurchaseConfirmation = null; }
};

window.confirmQuickPurchase = function() {
    const supplier = String(document.getElementById('quickPurchaseSupplier').value || '').trim();
    const unitCostText = String(document.getElementById('quickPurchaseCost').value).trim();
    const unitCost = Number(unitCostText);
    const expectedQty = Number(document.getElementById('quickPurchaseQty').value);
    if (!supplier || unitCostText === '' || !Number.isFinite(unitCost) || unitCost < 0 || !Number.isFinite(expectedQty) || expectedQty <= 0) {
        alert('請填寫供應商與實際單位成本（可填 0）。'); return;
    }
    const resolve = quickPurchaseConfirmation;
    quickPurchaseConfirmation = null;
    document.getElementById('quickPurchaseConfirmationOverlay').classList.remove('active');
    if (resolve) resolve({ supplier, unitCost, expectedQty });
};

async function requestQuickPurchaseDetails(orderId, itemId) {
    closeQuickPurchaseConfirmation();
    const generation = quickPurchaseConfirmationGeneration;
    const orderSnap = await firestoreReadWithTimeout(db.collection('orders').doc(orderId).get(), '讀取待採購品項');
    if (!orderSnap.exists) throw new Error('來源訂單已不存在。');
    const order = { id:orderId, ...orderSnap.data() };
    if (normalizedOrderStatus(order) !== 'normal') throw new Error('來源訂單已取消或作廢。');
    const item = normalizedOrderItems(order).find(row => row.itemId === itemId);
    if (!item || (item.procurementType || order.procurementType || 'PURCHASING_PO') === 'SALES_SELF_ORDER') throw new Error('此品項不能使用直接採購。');
    const qty = procurementDemandForOrderItem(order, item).remainingToOrderQty;
    if (!(qty > 0)) throw new Error('此品項已無待採購數量，請重新整理。');
    const productId = String(item.productId || order.productId || '').trim();
    const [supplySnap, costSnap] = await Promise.all([
        firestoreReadWithTimeout(supplyOrdersCollection().doc(quickPurchaseSupplyId(orderId,itemId)).get(), '讀取既有採購紀錄'),
        productId ? firestoreReadWithTimeout(db.collection('productCosts').doc(productId).get(), '讀取標準成本') : Promise.resolve(null)
    ]);
    if (generation !== quickPurchaseConfirmationGeneration) return null;
    const existing = supplySnap.exists ? supplySnap.data() : null;
    const cost = existing?.unitCost ?? (costSnap?.exists ? costSnap.data().standardCost : null);
    let overlay = document.getElementById('quickPurchaseConfirmationOverlay');
    if (!overlay) {
        overlay = document.createElement('div');
        overlay.id = 'quickPurchaseConfirmationOverlay'; overlay.className = 'eq-modal-overlay no-print';
        overlay.innerHTML = `<div class="eq-modal-box" style="max-width:560px;">
            <h3>確認已採購</h3><p id="quickPurchaseSummary"></p>
            <div class="form-grid">
                <div><label for="quickPurchaseSupplier">供應商 *</label><input id="quickPurchaseSupplier" type="text" autocomplete="off"></div>
                <div><label for="quickPurchaseQty">本次採購數量</label><input id="quickPurchaseQty" type="number" readonly></div>
                <div><label for="quickPurchaseCost">實際含稅單位成本 *</label><input id="quickPurchaseCost" type="number" min="0" step="any" inputmode="decimal"></div>
            </div><p id="quickPurchaseHint" style="color:#666;font-size:13px;"></p>
            <div style="display:flex;justify-content:flex-end;gap:8px;flex-wrap:wrap;">
                <button type="button" onclick="confirmQuickPurchase()">確認已採購</button>
                <button type="button" class="btn-secondary" onclick="closeQuickPurchaseConfirmation()">取消</button>
            </div></div>`;
        overlay.addEventListener('click', event => { if (event.target === overlay) closeQuickPurchaseConfirmation(); });
        document.body.appendChild(overlay);
    }
    document.getElementById('quickPurchaseSummary').textContent = `${item.itemCode || ''} ${item.itemName || ''}`;
    document.getElementById('quickPurchaseSupplier').value = existing?.supplier || item.supplier || order.supplier || '';
    document.getElementById('quickPurchaseQty').value = qty;
    document.getElementById('quickPurchaseCost').value = cost !== null && cost !== undefined && cost !== '' && Number.isFinite(Number(cost)) && Number(cost) >= 0 ? cost : '';
    document.getElementById('quickPurchaseHint').textContent = existing
        ? '追加採購沿用原紀錄的供應商與單價；不同供應商、單價或部分採購，請製作採購文件後按「確認已採購」。'
        : '成本由產品標準成本帶入，請確認本次實際進貨價。確認後列入待到貨，不產生 PDF。';
    overlay.classList.add('active');
    return new Promise(resolve => { quickPurchaseConfirmation = resolve; });
}

window.markPurchaseItemOrdered = async function(orderId, itemId, button) {
    if (!canCreatePurchaseOrderCapability() || !canAccessPage('orders.po')) return;
    const actionKey = `${orderId}::${itemId}`;
    if (pendingPurchaseOrderKeys.has(actionKey)) return;
    pendingPurchaseOrderKeys.add(actionKey);
    const originalLabel = button?.textContent || '已採購';
    if (button) { button.disabled = true; button.textContent = '處理中…'; }
    try {
        const actorUid=currentUser?.uid, actorRole=currentUserRole;
        const purchaseDetails = await requestQuickPurchaseDetails(orderId, itemId);
        if (!purchaseDetails) return;
        if (!canCreatePurchaseOrderCapability() || !canAccessPage('orders.po')) return;
        if (!purchaseDetails.supplier || !Number.isFinite(purchaseDetails.unitCost) || purchaseDetails.unitCost < 0) throw new Error('請確認供應商與有效的實際單位成本。');
        const { savedOrder, savedSupply, savedDemand, incomingProductKey, incomingWarehouseId } = await commitQuickPurchase(orderId, itemId, purchaseDetails, actorUid, actorRole);
        if (incomingProductKey && incomingWarehouseId) invalidateWarehouseStockCache(incomingProductKey,incomingWarehouseId);
        const index = ordersCache.findIndex(order => order.id === orderId);
        if (index >= 0 && savedOrder) ordersCache[index] = savedOrder;
        if (savedOrder) syncOrderIntoPurchasingCaches(savedOrder, { render:false });
        if (savedSupply) {
            const supplyIndex=supplyReceivingCache.findIndex(row=>row.id===savedSupply.id);
            if(supplyIndex>=0)supplyReceivingCache[supplyIndex]=savedSupply;
            else supplyReceivingCache.unshift(savedSupply);
        }
        writeAppDataCache('orders', ordersCache);
        syncCommittedQuickPurchaseDemand(savedDemand, savedOrder);
        if (document.getElementById('order-system')?.classList.contains('active')) renderOrdersList();
        if (document.getElementById('purchasing-system')?.classList.contains('active')) {
            renderPurchasingView();
        }
        showActionFeedback('已採購，品項已列入待到貨，可繼續處理下一筆。', 'success');
    } catch (err) {
        alert('切換為已採購失敗：' + err.message + '\n請確認目前這筆資料及連線／權限，重試前先查詢作業結果；若持續失敗，請聯絡管理員。');
    } finally {
        pendingPurchaseOrderKeys.delete(actionKey);
        if (button?.isConnected) { button.disabled = false; button.textContent = originalLabel; }
    }
};
window.openOrderPurchaseDraft = async function(orderId, itemId = '') {
    if (!canCreatePurchaseOrderCapability() || !canAccessPage('orders.po')) return;
    const openingGeneration = ++poDirectStockOpenGeneration;
    const openingUid = currentUser?.uid;
    const openingRole = currentUserRole;
    const isCurrent = () => openingGeneration === poDirectStockOpenGeneration
        && currentUser?.uid === openingUid && currentUserRole === openingRole;
    const button = [...document.querySelectorAll('#purchasePendingBody button')].find(el => {
        const action = el.getAttribute('onclick') || '';
        return action.includes('openOrderPurchaseDraft(') && action.includes(`'${orderId}'`);
    });
    if (button) { button.disabled = true; button.textContent = '開啟中…'; }
    try {
        // 待採購清單本身就是由 ordersCache 畫出來的，點擊時先直接使用同一筆資料。
        // 正式儲存 PO 的 transaction 仍會重新讀取來源訂單並 assertPurchaseLinesAvailable，
        // 因此不需要為了「開視窗」先做一個重複 Firestore read。
        let order = ordersCache.find(row => row.id === orderId) || null;
        if (!order) {
            const snapshot = await firestoreReadWithTimeout(
                db.collection('orders').doc(orderId).get(),
                '採購單來源訂單'
            );
            if (!isCurrent()) return;
            if (!snapshot.exists) throw new Error('找不到來源訂單');
            order = { id:snapshot.id, ...snapshot.data() };
        }
        if (normalizedOrderStatus(order) !== 'normal') throw new Error('訂單已取消或作廢');

        let pendingItems = pendingPurchaseLines(order);
        let items = itemId ? pendingItems.filter(item => item.itemId === itemId) : pendingItems.slice(0, 1);
        if (!items.length) throw new Error('此品項已無待採購數量');

        poDirectStockMode = false;
        poEditingId = null;
        poIncomingSyncPending = false;
        poItems = items;
        poAllItems = items;
        populatePoVendorSuggestions();
        document.getElementById('poVendorName').value = '';
        document.getElementById('poBuyerName').innerText = currentUserName || currentUser?.email || '';
        document.getElementById('poDate').value = localDateString();
    clearPoExpectedDate();
        switchPoCompany(bestPurchaseOrderCompany([order], items, order.company), null, true);
        generatePoNo();
        renderPoItemsTable();
        updatePoModeUI();
        setPoDraftLoading(true);
        updatePoSaveStatus('正在載入供應商與進貨成本…');
        document.getElementById('poModalOverlay').classList.add('active');

        // 視窗先出現，供應商／成本再補齊；只預載這次採購單真正選到的品項。
        await Promise.all([loadSupplierWarehouseMasters(), preloadPurchaseCostsForItems(items)]);
        if (!isCurrent() || !document.getElementById('poModalOverlay')?.classList.contains('active')) return;
        pendingItems = pendingPurchaseLines(order);
        items = itemId ? pendingItems.filter(item => item.itemId === itemId) : pendingItems.slice(0, 1);
        if (!items.length) {
            throw new Error('此品項已無待採購數量');
        }
        await preloadPurchaseCostsForItems(items);
        if (!isCurrent()) return;
        poItems = items;
        poAllItems = items;
        document.getElementById('poVendorName').value = '';
        await autoFillPoSupplier(items, isCurrent);
        if (!isCurrent()) return;
        switchPoCompany(bestPurchaseOrderCompany([order], items, order.company), null, true);
        renderPoItemsTable();
        updatePoModeUI();
        updatePoSaveStatus('這張採購單尚未建立。確認品項、供應商與單價後，即可列印 / 存為 PDF 並自動同步雲端。');
    } catch (err) {
        if (isCurrent()) { closePurchaseOrderModal(); alert('無法開啟採購單：' + err.message); }
    } finally {
        if (isCurrent()) setPoDraftLoading(false);
        if (button?.isConnected) { button.disabled = false; button.textContent = '產生採購單'; }
    }
};

window.openSelectedPurchaseDraft = async function() {
    if(!canCreatePurchaseOrderCapability()||!canAccessPage('orders.po'))return;
    const button=document.getElementById('purchasePendingBatchPoBtn');
    const selectedIds=[...selectedPendingPurchaseDemandIds];
    if(selectedIds.length<2){
        alert('請至少勾選 2 筆待採購需求。');
        return;
    }
    if(button){button.disabled=true;button.textContent='整理中…';}
    try{
        const selectedDemands=procurementDemandCache.filter(demand=>
            selectedPendingPurchaseDemandIds.has(String(demand.id||''))
            && Number(demand.remainingToOrderQty||0)>0
        );
        if(selectedDemands.length!==selectedIds.length)throw new Error('部分待採購需求已更新，請按「更新」後重新勾選。');

        const rows=selectedDemands.map(demand=>{
            if(String(demand.sourceType||'')!=='SALES_ORDER')throw new Error('目前批次合併只支援客戶訂單採購。');
            const order=procurementDemandSourceOrderCache.get(String(demand.sourceId||''));
            if(!order||normalizedOrderStatus(order)!=='normal')throw new Error('部分來源訂單已取消、作廢或尚未載入。');
            const item=pendingPurchaseLines(order).find(line=>String(line.itemId||'')===String(demand.sourceItemId||''));
            if(!item)throw new Error('部分勾選品項已無待採購數量，請更新後重試。');
            return {demand,order,item};
        });
        const initialItems=rows.map(row=>row.item);
        await Promise.all([
            loadSupplierWarehouseMasters(),
            preloadPurchaseCostsForItems(initialItems)
        ]);

        const refreshedRows=rows.map(row=>{
            const item=pendingPurchaseLines(row.order).find(line=>String(line.itemId||'')===String(row.demand.sourceItemId||''));
            if(!item)throw new Error('部分勾選品項已無待採購數量，請更新後重試。');
            return {...row,item};
        });
        const items=refreshedRows.map(row=>row.item);
        await preloadPurchaseCostsForItems(items);
        const selectedOrders=[...new Map(refreshedRows.map(row=>[row.order.id,row.order])).values()];

        if(items.some(item=>String(item.fulfillmentType||'WAREHOUSE').toUpperCase()==='DIRECT_SHIP')){
            throw new Error('原廠直送需依客戶地址分開處理，目前不合併成同一張採購單。');
        }
        const warehouseIds=new Set(items.map(item=>String(item.warehouseId||defaultWarehouse()?.id||'').trim()));
        if(warehouseIds.has(''))throw new Error('部分品項尚未指定入庫倉庫，請先完成倉庫設定。');
        if(warehouseIds.size!==1)throw new Error('不同入庫倉庫的需求不能合併成同一張採購單。');

        const companies=[...new Set(selectedOrders.map(order=>String(order.company||'').trim()).filter(Boolean))];
        if(companies.length>1)throw new Error('不同公司的來源訂單不能合併成同一張採購單。');

        const resolvedSuppliers=items.map(item=>supplierForProduct(
            item.brand,item.productLine,item.productId,item.itemCode
        ));
        if(resolvedSuppliers.some(supplier=>!supplier)){
            const missing=items.filter((item,index)=>!resolvedSuppliers[index]).map(item=>item.itemCode||item.itemName||'未命名品項');
            throw new Error('以下品項尚未設定供應來源：'+missing.join('、'));
        }
        const supplierIds=new Set(resolvedSuppliers.map(supplier=>String(supplier.id||supplier.supplierId||'').trim()).filter(Boolean));
        if(supplierIds.size!==1)throw new Error('勾選品項屬於不同供應商，請分開建立採購單。');
        const supplier=resolvedSuppliers[0];
        const supplierHeader=supplier.purchaseHeaderName||supplier.supplierName||'';
        if(!supplierHeader)throw new Error('供應商主檔缺少採購單抬頭。');

        poDirectStockMode=false;
        poEditingId=null;
        poIncomingSyncPending=false;
        poItems=items;
        poAllItems=items;
        populatePoVendorSuggestions();
        document.getElementById('poVendorName').value=supplierHeader;
        document.getElementById('poBuyerName').innerText=currentUserName||currentUser?.email||'';
        document.getElementById('poDate').value=localDateString();
        clearPoExpectedDate();
        await autoFillPoSupplier(items);
        const targetCompany=companies[0]||bestPurchaseOrderCompany(selectedOrders,items,currentCompany);
        switchPoCompany(targetCompany,null,true);
        generatePoNo();
        renderPoItemsTable();
        updatePoModeUI();
        updatePoSaveStatus(`已合併 ${items.length} 筆待採購需求；請確認數量、成本與預計到貨日後匯出 PDF。`);
        document.getElementById('poModalOverlay').classList.add('active');
        clearPendingPurchaseSelection();
    }catch(err){
        alert('無法合併建立採購單：'+(err?.message||err));
    }finally{
        updatePendingPurchaseBatchButton();
    }
};

// 「採購訂單」列出所有已經產生過的採購單紀錄（不分是誰產生的，只要是採購／管理員都看得到全部）
function updatePoLoadMoreButton() {
    const button = document.getElementById('poLoadMoreBtn');
    const refreshButton = document.getElementById('purchasePoRefreshBtn');
    const hasMore = purchasingView === 'receiving' ? supplyReceivingHasMore : poListHasMore;
    if (button) {
        button.style.display = hasMore ? '' : 'none';
        button.disabled = poListPageLoading;
        button.innerText = poListPageLoading ? '載入中…' : purchasingView === 'receiving' ? '載入更多待到貨資料' : '載入更多（每次 50 筆）';
    }
    if (refreshButton) {
        refreshButton.disabled = poListPageLoading;
        refreshButton.textContent = poListPageLoading ? '更新中…' : '↻ 更新';
    }
}

function mergeReceivingSourceOrdersIntoOrderCache() {
    if (!receivingSourceOrderCache.size) return;
    const mergedOrders = new Map(ordersCache.map(order => [order.id, order]));
    receivingSourceOrderCache.forEach((order, id) => mergedOrders.set(id, order));
    ordersCache = [...mergedOrders.values()]
        .sort((a,b)=>compareBusinessRecordsNewestFirst(a,b,'orderDate','id'));
    writeAppDataCache('orders', ordersCache);
}

async function loadPurchaseOrderPage(reset, options = {}) {
    if (!canAccessPage('orders.po')) return;
    const deferRender = options.deferRender === true;
    if (poListPageLoading) return;
    if (reset) {
        if (purchasingView === 'receiving') {
            supplyReceivingCursor = null;
            supplyReceivingHasMore = true;
            supplyReceivingCache = [];
            receivingSourceOrderCache = new Map();
        } else {
            poListCursor = null;
            poListHasMore = true;
            if (!poListCache.length) {
                const cached = readAppDataCache('purchase-history');
                if (cached?.records?.length) poListCache = cached.records;
            }
        }
    }
    if (!poListHasMore && (purchasingView !== 'receiving' || !supplyReceivingHasMore)) return;
    poListPageLoading = true;
    const requestedRole = currentUserRole, requestedUid = currentUser?.uid;
    const requestedView = purchasingView;
    updatePoLoadMoreButton();
    try {
        let query = poListHasMore && purchasingView !== 'receiving'
            ? db.collection('purchaseOrders').orderBy('poNo','desc').limit(DEFAULT_LIST_LIMIT)
            : null;
        if (query && poListCursor) query = query.startAfter(poListCursor);
        let supplyQuery = purchasingView === 'receiving' && supplyReceivingHasMore
            // Keep this on the single-field status index; page through mixed PO and
            // self-order documents rather than stopping at the first 50 matches.
            ? supplyOrdersCollection().where('status','in',['ORDERED','PARTIAL_RECEIPT']).limit(DEFAULT_LIST_LIMIT)
            : null;
        if (supplyQuery && supplyReceivingCursor) supplyQuery = supplyQuery.startAfter(supplyReceivingCursor);
        const [snapshot,supplySnapshot] = await Promise.all([
            query ? firestoreReadWithTimeout(query.get(), '採購單清單') : Promise.resolve({docs:[],size:0,empty:true}),
            supplyQuery ? firestoreReadWithTimeout(supplyQuery.get(), '待到貨供應') : Promise.resolve({docs:[],size:0,empty:true})
        ]);
        if (requestedRole !== currentUserRole || requestedUid !== currentUser?.uid || requestedView !== purchasingView || !canAccessPage('orders.po')) return;
        const freshSupply=supplySnapshot.docs.map(doc=>({id:doc.id,...doc.data()}));
        const supplyRecords=new Map((reset?[]:supplyReceivingCache).map(row=>[row.id,row]));
        freshSupply.forEach(row=>supplyRecords.set(row.id,row));
        // 倉庫型 PO 即使來源訂單取消仍待到貨；原廠直送與自行訂購維持原有篩選。
        const sourceOrderIds=purchasingView==='receiving'?[...new Set([
            ...freshSupply.map(row=>row.orderId).filter(Boolean)
        ])]:[];
        // Load More keeps earlier PO rows, so their source-order statuses must stay
        // available until the receiving list is reset.
        const nextSourceStatuses=reset?new Map():new Map(receivingSourceOrderStatusCache);
        const nextSourceOrders=reset?new Map():new Map(receivingSourceOrderCache);
        const cachedOrders=new Map(ordersCache.map(order=>[order.id,order]));
        sourceOrderIds.forEach(id=>{
            const cached=cachedOrders.get(id);
            if(!cached)return;
            nextSourceOrders.set(id,cached);
            nextSourceStatuses.set(id,normalizedOrderStatus(cached));
        });
        const missingSourceIds=sourceOrderIds.filter(id=>!nextSourceOrders.has(id));
        for(let i=0;i<missingSourceIds.length;i+=10){
            const batch=missingSourceIds.slice(i,i+10);
            const sourceSnap=await firestoreReadWithTimeout(
                db.collection('orders').where(firebase.firestore.FieldPath.documentId(),'in',batch).get(),
                '待到貨來源訂單'
            );
            sourceSnap.docs.forEach(doc=>{
                const sourceOrder={id:doc.id,...doc.data()};
                nextSourceOrders.set(doc.id,sourceOrder);
                nextSourceStatuses.set(doc.id,normalizedOrderStatus(sourceOrder));
            });
        }
        if (requestedRole !== currentUserRole || requestedUid !== currentUser?.uid || requestedView !== purchasingView || !canAccessPage('orders.po')) return;
        receivingSourceOrderStatusCache=nextSourceStatuses;
        receivingSourceOrderCache=nextSourceOrders;
        // loadPurchasingReceivingQueue() 以 deferRender 平行載入 orders + supply；
        // 該 caller 會在兩條查詢都完成後再 merge 一次，避免先 merge 後又被較晚完成的 orders refresh 覆蓋。
        // 單獨「載入更多待到貨」沒有 deferRender，仍在這裡立即 merge。
        if (!deferRender && purchasingView === 'receiving' && nextSourceOrders.size) {
            mergeReceivingSourceOrdersIntoOrderCache();
        }
        supplyReceivingCache=[...supplyRecords.values()]
            .sort((a,b)=>String(b.orderDate||'').localeCompare(String(a.orderDate||'')));
        if (!supplySnapshot.empty) supplyReceivingCursor = supplySnapshot.docs[supplySnapshot.docs.length - 1];
        if (purchasingView === 'receiving') supplyReceivingHasMore = supplySnapshot.size === DEFAULT_LIST_LIMIT;
        if (query) {
            if (!snapshot.empty) poListCursor = snapshot.docs[snapshot.docs.length - 1];
            const freshRecords = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
            const records = new Map((reset ? [] : poListCache).map(po => [po.id, po]));
            freshRecords.forEach(po => records.set(po.id, po));
            // reset 時雲端結果完整取代 stale cache；Load More 才追加。
            poListCache = [...records.values()].sort((a, b) => (b.poNo || '').localeCompare(a.poNo || ''));
            poListHasMore = snapshot.size === DEFAULT_LIST_LIMIT;
            await loadPurchaseHistorySupplyProjection(freshRecords, reset);
            if (requestedRole !== currentUserRole || requestedUid !== currentUser?.uid || requestedView !== purchasingView || !canAccessPage('orders.po')) return;
            writeAppDataCache('purchase-history', poListCache);
        }
        if (!deferRender) {
            if (purchasingView === 'receiving') renderPurchasingView();
            else renderPoList();
        }
    } catch (err) {
        console.error('讀取採購單／待到貨資料失敗：', err);
        const message = err?.message || String(err || '未知錯誤');
        alert('讀取採購單／待到貨資料失敗：' + message);
    } finally {
        poListPageLoading = false;
        updatePoLoadMoreButton();
    }
}

window.loadMyPurchaseOrders = function() {
    return purchasingView === 'receiving'
        ? loadPurchasingReceivingQueue(true)
        : loadPurchaseOrderPage(true);
};

window.loadMorePurchaseOrders = function() {
    return loadPurchaseOrderPage(false);
};

function waitingDaysFromDate(date) {
    const raw = String(date || '').trim();
    const match = raw.match(/^(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})/);
    if (!match) return '';
    const year = Number(match[1]), month = Number(match[2]), day = Number(match[3]);
    const start = new Date(year, month - 1, day);
    if (start.getFullYear() !== year || start.getMonth() !== month - 1 || start.getDate() !== day) return '';
    const today = new Date();
    const startDay = Date.UTC(year, month - 1, day);
    const todayDay = Date.UTC(today.getFullYear(), today.getMonth(), today.getDate());
    return Math.max(0, Math.round((todayDay - startDay) / 86400000)) + ' 天';
}

function poWaitingDays(po) {
    return waitingDaysFromDate(po.poDate);
}

async function loadPurchaseHistorySupplyProjection(poRows = [], reset = false) {
    if (reset) purchaseHistorySupplyCache = new Map();
    const ids = [...new Set((poRows || []).flatMap(po =>
        Array.isArray(po?.supplyOrderIds) ? po.supplyOrderIds : []
    ).map(id => String(id || '').trim()).filter(Boolean))];
    const missing = ids.filter(id => !purchaseHistorySupplyCache.has(id));
    if (!missing.length) return;
    const rows = await readDocumentsByIds('supplyOrders', missing);
    rows.forEach(row => purchaseHistorySupplyCache.set(row.id, row));
}

function isPurchaseTerminalStatus(status) {
    return ['CANCELLED','CLOSED'].includes(String(status || '').toUpperCase());
}

function purchaseOrderDocumentStatusLabel(po = {}) {
    const status=String(po.status || '').toUpperCase();
    if(status==='DRAFT' && po.documentOnly===true)return '文件已儲存／尚未採購';
    if(status==='CANCELLED')return '已取消';
    if(status==='CLOSED')return '已結案';
    return '已下單';
}

function purchaseHistoryItemReceiptProgress(po, itemIndex = 0) {
    if(po?.status==='DRAFT' && po.documentOnly===true)return {status:'DRAFT',label:'尚未採購',orderedQty:0,receivedQty:0,remainingQty:0,percent:0};
    const supplyId = Array.isArray(po?.supplyOrderIds) ? String(po.supplyOrderIds[itemIndex] || '') : '';
    const supply = supplyId ? purchaseHistorySupplyCache.get(supplyId) : null;
    if (supply && globalThis.YushinSupply?.receiptProgress) {
        return globalThis.YushinSupply.receiptProgress(supply);
    }
    if (isPurchaseTerminalStatus(po?.status)) {
        const closed=String(po?.status||'').toUpperCase()==='CLOSED';
        return { status:closed?'CLOSED':'CANCELLED', label:closed?'已結案':'未到貨已取消', orderedQty:0, receivedQty:0, remainingQty:0, percent:0 };
    }
    return { status:'UNKNOWN', label:'已建立', orderedQty:0, receivedQty:0, remainingQty:0, percent:0 };
}


function purchaseTimelineDateLabel(value='') {
    const raw=String(value||'').trim();
    if(!raw)return '—';
    if(/^\d{4}-\d{2}-\d{2}$/.test(raw))return raw;
    const date=new Date(raw);
    return Number.isNaN(date.getTime())?raw:date.toLocaleString('zh-TW',{hour12:false});
}

function purchaseTimelineSourceLabel(sourceType='') {
    return sourceType==='STOCK_REPLENISHMENT'?'備庫採購':sourceType==='SALES_ORDER'?'客戶訂單採購':'採購';
}

window.closePurchaseOrderTimeline = function() {
    document.getElementById('purchaseTimelineOverlay')?.classList.remove('active');
};

window.openPurchaseOrderTimeline = async function(poId) {
    if(!canAccessPage('orders.po')||!poId)return;
    const overlay=document.getElementById('purchaseTimelineOverlay');
    const title=document.getElementById('purchaseTimelineTitle');
    const summary=document.getElementById('purchaseTimelineSummary');
    const supplyBody=document.getElementById('purchaseTimelineSupplyBody');
    const eventsBody=document.getElementById('purchaseTimelineEvents');
    const status=document.getElementById('purchaseTimelineStatus');
    if(!overlay||!summary||!supplyBody||!eventsBody)return;
    overlay.classList.add('active');
    if(title)title.textContent='採購單追蹤';
    if(status)status.textContent='載入採購歷程中…';
    summary.innerHTML='';
    supplyBody.innerHTML='<tr><td colspan="6" style="color:#888;">載入中…</td></tr>';
    eventsBody.innerHTML='';

    try{
        let po=poListCache.find(row=>row.id===poId)||poHistorySearchResults.find(row=>row.id===poId)||null;
        if(!po){
            const snap=await firestoreReadWithTimeout(db.collection('purchaseOrders').doc(poId).get(),'採購單追蹤');
            if(!snap.exists)throw new Error('找不到這張採購單。');
            po={id:snap.id,...snap.data()};
        }

        const supplyIds=[...new Set((Array.isArray(po.supplyOrderIds)?po.supplyOrderIds:[]).map(String).filter(Boolean))];
        const supplyPromise=supplyIds.length?readDocumentsByIds('supplyOrders',supplyIds):Promise.resolve([]);
        const receiptPromise=firestoreReadWithTimeout(
            db.collection('receipts').where('purchaseDocumentId','==',po.id).get(),
            '採購單到貨歷程'
        );
        const communicationPromise=Promise.resolve(null);

        const [supplies,receiptSnapshot,communicationSnapshot]=await Promise.all([
            supplyPromise,receiptPromise,communicationPromise
        ]);
        const receipts=receiptSnapshot.docs.map(doc=>({id:doc.id,...doc.data()}));
        const communications=communicationSnapshot
            ? communicationSnapshot.docs.map(doc=>({id:doc.id,...doc.data()}))
            : [];

        if(title)title.textContent=`採購單追蹤｜${po.poNo||po.id}`;
        const contact=purchaseOrderSupplierContact(po);
        summary.innerHTML=`
            <strong>${escapeHtml(po.vendorName||contact.supplierName||'')}</strong>
            <span style="margin-left:12px;color:#667584;">採購日期：${escapeHtml(po.poDate||'—')}</span>
            <span style="margin-left:12px;color:#667584;">預計到貨：${escapeHtml(po.expectedDate||po.scheduleDate||'—')}</span>
            ${contact.email?`<span style="margin-left:12px;color:#667584;">Email：${escapeHtml(contact.email)}</span>`:''}
        `;

        supplyBody.innerHTML=supplies.length?supplies.map(supply=>{
            const progress=globalThis.YushinSupply?.receiptProgress(supply)||{
                orderedQty:Number(supply.qty||0),
                receivedQty:Number(supply.receivedQty||0),
                remainingQty:Math.max(0,Number(supply.qty||0)-Number(supply.receivedQty||0)),
                label:String(supply.status||'')
            };
            return `<tr>
                <td>${escapeHtml(supply.itemCode||supply.itemName||'')}</td>
                <td>${escapeHtml(purchaseTimelineSourceLabel(supply.sourceType))}</td>
                <td>${Number(progress.orderedQty||0)}</td>
                <td>${Number(progress.receivedQty||0)}</td>
                <td>${Number(progress.remainingQty||0)}</td>
                <td>${escapeHtml(progress.label||'')}</td>
            </tr>`;
        }).join(''):'<tr><td colspan="6" style="color:#888;">沒有供應品項紀錄。</td></tr>';

        const events=[];
        const createdAt=po.createdAt||po.poDate||'';
        events.push({
            time:createdAt,
            type:'ORDER',
            title:'建立採購單',
            detail:`${po.poNo||po.id}｜${po.vendorName||''}｜${(purchaseItemsFromSavedPo(po)||[]).length} 個品項`
        });
        receipts.forEach(receipt=>{
            events.push({
                time:receipt.createdAt||receipt.receiptDate||'',
                type:'RECEIPT',
                title:`到貨 +${Number(receipt.qty||0)}`,
                detail:[receipt.itemCode||receipt.itemName||'',receipt.lotNo?('批號 '+receipt.lotNo):'',receipt.receiptDate||''].filter(Boolean).join('｜')
            });
        });
        communications.forEach(event=>{
            const channel=event.channel==='WEB_SHARE'?'開啟分享':'準備郵件';
            events.push({
                time:event.preparedAt||event.createdAt||'',
                type:'COMMUNICATION',
                title:channel,
                detail:[event.recipientEmail||'',event.createdBy||'','系統僅記錄已準備，不代表已寄達'].filter(Boolean).join('｜')
            });
        });
        if(String(po.status||'').toUpperCase()==='CANCELLED'){
            events.push({
                time:po.cancelledAt||po.updatedAt||'',
                type:'CANCELLED',
                title:'取消未到貨',
                detail:po.cancelReason||po.cancellationReason||'採購單已取消'
            });
        }
        events.sort((a,b)=>(Date.parse(b.time)||0)-(Date.parse(a.time)||0));
        eventsBody.innerHTML=events.map(event=>`
            <div class="purchase-timeline-event">
                <div style="display:flex;justify-content:space-between;gap:12px;">
                    <strong>${escapeHtml(event.title)}</strong>
                    <span class="record-reference">${escapeHtml(purchaseTimelineDateLabel(event.time))}</span>
                </div>
                <div class="record-reference">${escapeHtml(event.detail||'')}</div>
            </div>
        `).join('');
        if(status)status.textContent=`${supplies.length} 個供應品項｜${receipts.length} 筆到貨${canCreatePurchaseOrderCapability()?`｜${communications.length} 筆聯絡紀錄`:''}`;
    }catch(err){
        console.error('採購單追蹤載入失敗：',err);
        if(status)status.textContent='載入失敗：'+(err?.message||err);
        supplyBody.innerHTML='<tr><td colspan="6" style="color:#b42318;">載入失敗，請重試。</td></tr>';
    }
};

function purchaseOrderSearchTokens(po={}) {
    return globalThis.YushinSupplier.purchaseOrderSearchTokens(po);
}

function purchaseOrderHistoryMatches(po, keyword) {
    const needle=normalizeFullHistorySearchValue(keyword);
    if(!needle)return true;
    const values=[
        po.poNo,po.vendorName,po.buyerName,po.company,po.poDate,
        ...purchaseItemsFromSavedPo(po).flatMap(item=>[item.itemCode,item.itemName,item.brand,item.orderNo,item.orderId])
    ];
    return values.some(value=>normalizeFullHistorySearchValue(value).includes(needle));
}

window.schedulePurchaseOrderHistorySearch = function() {
    clearTimeout(poHistorySearchTimer);
    poHistorySearchTimer=scheduleListSearch(poHistorySearchTimer,()=>runPurchaseOrderHistorySearch());
};

async function runPurchaseOrderHistorySearch() {
    const generation = ++poHistorySearchGeneration;
    if(purchasingView!=='history')return renderPoList();
    const keyword=document.getElementById('poListSearch')?.value||'';
    const status=document.getElementById('poHistorySearchStatus');
    const normalized=normalizeFullHistorySearchValue(keyword);
    if(!normalized){
        poHistorySearchActive=false;poHistorySearchResults=[];poHistorySearchLoading=false;
        if(status)status.textContent='';
        renderPoList();return;
    }
    poHistorySearchLoading=true;poHistorySearchActive=true;poHistorySearchResults=[];
    const results=new Map();
    if(status)status.textContent='正在搜尋全部採購單…';
    renderPoList();
    try{
        // searchTokens 先把候選資料縮小，再逐頁讀完所有候選，避免只搜尋目前畫面的 50 筆。
        // 這不是掃描整個 collection；只有符合索引 token 的文件會被讀取。
        const token=fullHistoryServerToken(keyword);
        let checked=0;
        let cursor=null;
        if(token){
            while(true){
                let query=db.collection('purchaseOrders')
                    .where('searchTokens','array-contains',token)
                    .limit(DEFAULT_LIST_LIMIT);
                if(cursor)query=query.startAfter(cursor);
                const snapshot=await firestoreReadWithTimeout(query.get(),'採購單索引搜尋');
                if(generation!==poHistorySearchGeneration)return;
                checked+=snapshot.size;
                snapshot.docs.forEach(doc=>{
                    const po={id:doc.id,...doc.data()};
                    if(purchaseOrderHistoryMatches(po,keyword))results.set(po.id,po);
                });
                poHistorySearchResults=[...results.values()].sort((a,b)=>(b.poNo||'').localeCompare(a.poNo||''));
                renderPoList();
                if(status)status.textContent=`全歷史搜尋中：已檢查 ${checked} 筆候選資料，找到 ${results.size} 筆…`;
                if(snapshot.size<DEFAULT_LIST_LIMIT)break;
                cursor=snapshot.docs[snapshot.docs.length-1];
            }
        }
        if(generation!==poHistorySearchGeneration)return;
        await loadPurchaseHistorySupplyProjection([...results.values()], false);
        if(generation!==poHistorySearchGeneration)return;
        if(status)status.textContent=`全歷史搜尋完成：找到 ${results.size} 筆`;
    }catch(err){
        if(generation!==poHistorySearchGeneration)return;
        console.error('採購單全歷史搜尋失敗：',err);
        if(status)status.textContent='搜尋失敗，請重試';
    }finally{
        if(generation===poHistorySearchGeneration){
            poHistorySearchLoading=false;
            renderPoList();
        }
    }
}

function receivingSourceOrderForItem(item, orderById = null) {
    if (!item?.orderId) return null;
    return orderById?.get(item.orderId)
        || receivingSourceOrderCache.get(item.orderId)
        || ordersCache.find(order=>order.id===item.orderId)
        || null;
}

function receivingEvidenceEntry(supply) {
    const ordered = Math.max(0, Number(supply?.qty || 0));
    const received = Math.max(0, Number(supply?.receivedQty || 0));
    const remaining = Math.max(0, ordered - received);
    if (!supply?.id || remaining <= 0) return null;
    return {
        type:'supply', id:supply.id,
        label:supply.purchaseDocumentNo || supply.internalNo || supply.id,
        progress:{ordered,received,remaining,directShip:(supply.fulfillmentType||'WAREHOUSE')==='DIRECT_SHIP'}
    };
}

function receivingDueInfo(supplies = [], today = localDateString()) {
    const validDate = value => /^\d{4}-\d{2}-\d{2}$/.test(String(value || '').slice(0,10))
        ? String(value || '').slice(0,10)
        : '';
    const expectedDates = (supplies || [])
        .map(supply => validDate(supply?.expectedDate || supply?.scheduleDate || ''))
        .filter(Boolean)
        .sort();
    const expectedDate = expectedDates[0] || '';
    const todayDate = validDate(today) || localDateString();
    if (!expectedDate) return { expectedDate:'', status:'unscheduled', daysLate:0, sortRank:3 };
    if (expectedDate < todayDate) {
        const expectedTime = Date.parse(expectedDate + 'T00:00:00Z');
        const todayTime = Date.parse(todayDate + 'T00:00:00Z');
        const daysLate = Number.isFinite(expectedTime) && Number.isFinite(todayTime)
            ? Math.max(1, Math.floor((todayTime - expectedTime) / 86400000))
            : 1;
        return { expectedDate, status:'late', daysLate, sortRank:0 };
    }
    if (expectedDate === todayDate) return { expectedDate, status:'today', daysLate:0, sortRank:1 };
    return { expectedDate, status:'upcoming', daysLate:0, sortRank:2 };
}

function receivingDueHtml(info = {}) {
    const date = escapeHtml(info.expectedDate || '');
    if (info.status === 'late') return `<div class="receiving-due-note"><span class="status-badge status-overdue">逾期 ${Number(info.daysLate || 0)} 天</span><span class="record-reference">預計 ${date}</span></div>`;
    if (info.status === 'today') return `<div class="receiving-due-note is-warning">今天預計到貨 ${date}</div>`;
    if (info.status === 'upcoming') return `<div class="receiving-due-note">預計到貨 ${date}</div>`;
    return '<div class="receiving-due-note">預計到貨日未設定</div>';
}

function receivingWaitHtml(supplies = []) {
    const dates = supplies.map(supply => String(supply.poDate || supply.orderedAt || supply.orderDate || supply.createdAt || '').slice(0,10)).filter(Boolean).sort();
    const waiting = dates.length ? waitingDaysFromDate(dates[0]) : '';
    return waiting ? `<div style="margin-top:4px;font-size:12px;color:#667584;">已等待 ${escapeHtml(waiting)}</div>` : '';
}

function receivingPlanRiskInfo(order = {}, item = {}, supplies = []) {
    if (!globalThis.YushinProcurementDemand?.deliveryPlanRisk) {
        return { status:'unavailable', sortRank:4 };
    }
    const demand = procurementDemandForOrderItem(order, item);
    const risk = globalThis.YushinProcurementDemand.deliveryPlanRisk(demand, supplies);
    const sortRank = risk.status === 'at_risk'
        ? 0
        : risk.status === 'uncovered'
            ? 1
            : risk.status === 'unscheduled'
                ? 2
                : 3;
    return { ...risk, sortRank };
}

function receivingPlanRiskHtml(info = {}) {
    if (info.status === 'at_risk') {
        return `<div style="margin-top:4px;"><span class="status-badge status-soon">交期風險・預計晚需求 ${Number(info.delayDays || 0)} 天</span><span class="record-reference">需求 ${escapeHtml(info.requiredDate || '')}</span></div>`;
    }
    if (info.status === 'uncovered') {
        return `<div class="receiving-due-note is-warning">採購計畫尚缺 ${Number(info.missingQty || 0)}｜需求 ${escapeHtml(info.requiredDate || '')}</div>`;
    }
    if (info.status === 'unscheduled') {
        return `<div class="receiving-due-note is-warning">交期未完整排定｜需求 ${escapeHtml(info.requiredDate || '')}</div>`;
    }
    return '';
}


function buildReceivingEvidenceIndex() {
    const index = new Map();
    const add = (key, entry) => {
        if (!key || !entry) return;
        if (!index.has(key)) index.set(key, []);
        index.get(key).push(entry);
    };
    supplyReceivingCache.forEach(supply => {
        if (!supply?.orderId) return;
        const entry = receivingEvidenceEntry(supply);
        if (!entry) return;
        if (supply.itemId) add(`${supply.orderId}::id:${supply.itemId}`, entry);
        const sourceIndex = Number(supply.orderItemIndex);
        if (Number.isFinite(sourceIndex)) add(`${supply.orderId}::idx:${sourceIndex}`, entry);
    });
    return index;
}

function receivingEvidenceForWorkItem(order, item, itemIndex, evidenceIndex = null) {
    if (evidenceIndex) {
        const matches = [
            ...(item?.itemId ? (evidenceIndex.get(`${order.id}::id:${item.itemId}`) || []) : []),
            ...(evidenceIndex.get(`${order.id}::idx:${Number(itemIndex)}`) || [])
        ];
        return [...new Map(matches.map(entry => [entry.id, entry])).values()];
    }
    const evidence = [];
    supplyReceivingCache.forEach(supply => {
        if (!supply?.orderId || supply.orderId !== order.id) return;
        const sameItem = (supply.itemId && item.itemId && supply.itemId === item.itemId)
            || Number(supply.orderItemIndex) === Number(itemIndex);
        if (!sameItem) return;
        const entry = receivingEvidenceEntry(supply);
        if (entry) evidence.push(entry);
    });
    return evidence;
}

function supplyCancelActionHtml(supply) {
    if (!supply || !['PURCHASING_MANUAL', 'PURCHASING_PO'].includes(supply.type)) return '';
    if (!canCreatePurchaseOrderCapability()) return '';
    if (isPurchaseTerminalStatus(supply.status)) return '';
    const remaining = Math.max(0, Number(supply.qty || 0) - Number(supply.receivedQty || 0));
    if (remaining <= 0) return '';
    const key = `supply:${supply.id}`;
    const pending = purchaseCancellationInProgress.has(key);
    return `<button type="button" class="btn-small danger-menu-item" onclick="cancelSupplyOutstanding(${inlineJsValue(supply.id)})" ${pending ? 'disabled' : ''}>${pending ? '取消中…' : '取消未到貨'}</button>`;
}

function receivingWorkProgress(order, item) {
    const directShip = (item.fulfillmentType || order.fulfillmentType || 'WAREHOUSE') === 'DIRECT_SHIP';
    const orderedQty = Math.max(0, Number(item.orderedQty ?? item.qty ?? 0));
    const shortage = Math.max(0, Number(item.shortageQty || 0));
    const supplyOrdered = Math.max(0, Number(item.supplyOrderedQty || 0));
    const received = Math.max(0, Number(item.receivedQty || 0));
    const target = directShip ? orderedQty : Math.max(shortage, supplyOrdered);
    return { target, received:Math.min(target, received), remaining:Math.max(0, target - received), directShip };
}

function renderPurchasingReceivingWorkList(normalizedItemsByOrder = null, filterContext = null, dispatchStatesByOrder = null, lifecyclesByOrder = null, inventory = false) {
    if (inventory && window.renderInventoryPurchaseReceiving) return window.renderInventoryPurchaseReceiving();
    const tbody = document.getElementById(inventory ? 'inventoryReceivingBody' : 'poListBody');
    const head = document.getElementById(inventory ? 'inventoryReceivingHead' : 'poListHeadRow');
    const emptyHint = document.getElementById(inventory ? 'inventoryReceivingEmpty' : 'poListEmptyHint');
    const status = document.getElementById(inventory ? 'inventoryReceivingStatus' : 'poHistorySearchStatus');
    if (!tbody) return;
    if (head) head.innerHTML = '<th>訂單日期</th><th>客戶</th><th>負責業務</th><th>待到貨品項</th><th>到貨進度</th><th class="no-print">操作</th>';
    tbody.innerHTML = '';
    const fragment = document.createDocumentFragment();

    const filters = inventory ? { ...purchaseFilterContext(), selectedSales:'', selectedBrand:'', start:'', end:'' } : (filterContext || purchaseFilterContext());
    let workCount = 0;
    let missingEvidence = 0;
    let evidenceCount = 0;
    let standaloneSupplyCount = 0;
    let overdueCount = 0;
    let planRiskCount = 0;
    const representedSupplyIds = new Set();
    const evidenceIndex = buildReceivingEvidenceIndex();
    const supplyById = new Map(supplyReceivingCache.map(supply => [supply.id, supply]));
    const orderById = new Map(ordersCache.map(order => [order.id, order]));

    ordersCache.forEach(order => {
        const items = normalizedItemsByOrder?.get(order.id) || normalizedOrderItems(order);
        const lifecycle = lifecyclesByOrder?.get(order.id) || orderLifecycleInfo(order, items);
        if (lifecycle.status !== 'normal') return;
        const orderDispatchStates = dispatchStatesByOrder?.get(order.id) || null;
        items.forEach((item, itemIndex) => {
            const dispatch = orderDispatchStates?.get(item) || itemDispatchState(order, item);
            if (!orderItemDisplayCategories(order, item, lifecycle, dispatch).includes('arrival')) return;
            if (!purchaseLineMatchesFilters(order.orderDate, order.salesName, item.brand, filters)) return;
            workCount++;
            const progress = receivingWorkProgress(order, item);
            const evidence = receivingEvidenceForWorkItem(order, item, itemIndex, evidenceIndex);
            evidence.forEach(entry => representedSupplyIds.add(entry.id));
            evidenceCount += evidence.length;
            if (!evidence.length) missingEvidence++;
            const evidenceSupplies = evidence.map(entry => supplyById.get(entry.id)).filter(Boolean);
            const due = receivingDueInfo(evidenceSupplies);
            const planRisk = receivingPlanRiskInfo(order, item, evidenceSupplies);
            if (due.status === 'late') overdueCount++;
            if (planRisk.status === 'at_risk') planRiskCount++;

            const actionHtml = !canReceiveInventoryCapability()
                ? '<span class="order-progress-badge">唯讀</span>'
                : evidence.length
                    ? evidence.map((entry, index) => {
                        const suffix = evidence.length > 1 ? ` ${index + 1}/${evidence.length}` : '';
                        const supply = supplyById.get(entry.id);
                        const receiveButton = `<button type="button" class="btn-small btn-secondary" data-receipt-supply="${escapeAttr(entry.id)}" onclick="openSupplyReceipt(${inlineJsValue(entry.id)})">📥 到貨入庫${suffix}</button>`;
                        return [canConfirmSupplyReceipt(supply)?receiveButton:'<span class="order-progress-badge">待負責業務確認直送到貨</span>', supplyCancelActionHtml(supply)].filter(Boolean).join(' ');
                    }).join(' ')
                    : '<span class="order-progress-badge order-progress-warning">找不到採購紀錄</span>';

            const tr = document.createElement('tr');
            tr.innerHTML = `
                <td data-th="訂單日期">${escapeHtml(order.orderDate || '')}</td>
                <td data-th="客戶">${escapeHtml(order.customer || order.customerName || '')}</td>
                <td data-th="負責業務">${escapeHtml(order.salesName || '')}</td>
                <td data-th="待到貨品項">${escapeHtml(item.itemCode || item.itemName || item.itemId || '未命名品項')} × ${progress.target}</td>
                <td data-th="到貨進度">${progress.received > 0 ? `部分到貨 ${progress.received}/${progress.target}` : `待到貨 0/${progress.target}`}${receivingWaitHtml(evidenceSupplies)}${receivingDueHtml(due)}${receivingPlanRiskHtml(planRisk)}</td>
                <td data-th="操作" class="no-print">${actionHtml}</td>`;
            tr.dataset.receivingDueRank = String(due.sortRank);
            tr.dataset.receivingPlanRiskRank = String(planRisk.sortRank ?? 4);
            tr.dataset.receivingExpectedDate = due.expectedDate || '';
            tr.dataset.receivingOrderDate = order.orderDate || '';
            fragment.appendChild(tr);
        });
    });

    // 沒有對應到「正常訂單待到貨工作」的供應紀錄仍可能是真實在途：
    // 例如庫存補貨，或客戶訂單取消後供應商仍照常出貨。這些不可從採購頁消失。
    supplyReceivingCache.forEach(supply => {
        if (representedSupplyIds.has(supply.id)) return;
        const supplyProgress = globalThis.YushinSupply?.receiptProgress(supply);
        if (!supplyProgress) return;
        const ordered = supplyProgress.orderedQty;
        const remaining = supplyProgress.remainingQty;
        if (remaining <= 0) return;

        const sourceOrder = receivingSourceOrderForItem(supply, orderById);
        const sourceStatus = sourceOrder ? normalizedOrderStatus(sourceOrder) : '';
        const directShip = (supply.fulfillmentType || 'WAREHOUSE') === 'DIRECT_SHIP';
        const date = sourceOrder?.orderDate || supply.orderDate || '';
        const salesName = sourceOrder?.salesName || supply.salesName || supply.createdBy || '';
        const brand = supply.brand || '';
        if (supply.orderId) {
            if (!purchaseLineMatchesFilters(date, salesName, brand, filters)) return;
        } else {
            // 公司備庫沒有負責業務；負責業務篩選不應讓真實在途採購從待到貨消失。
            if (!purchaseLineMatchesFilters(date, '', brand, { ...filters, selectedSales:'' })) return;
        }

        // 已取消訂單的原廠直送沒有倉庫可承接，因此只能顯示警示、不可確認到貨。
        const blockedDirectShip = directShip && sourceOrder && sourceStatus !== 'normal';
        const cancelAction = supplyCancelActionHtml(supply);
        const actionHtml = !canConfirmSupplyReceipt(supply)
            ? [directShip?'<span class="order-progress-badge">待負責業務確認直送到貨</span>':'<span class="order-progress-badge">唯讀</span>',cancelAction].filter(Boolean).join(' ')
            : blockedDirectShip
                ? ['<span class="order-progress-badge order-progress-warning">來源訂單已取消，直送不可確認</span>', cancelAction].filter(Boolean).join(' ')
                : [
                    `<button type="button" class="btn-small btn-secondary" data-receipt-supply="${escapeAttr(supply.id)}" onclick="openSupplyReceipt(${inlineJsValue(supply.id)})">${directShip ? '確認直送到貨' : '📥 到貨入庫'}</button>`,
                    cancelAction
                ].filter(Boolean).join(' ');

        const customerLabel = sourceOrder?.customerName || sourceOrder?.customer || supply.customerName
            || (supply.orderId ? '來源訂單' : '庫存補貨');
        const sourceLabel = sourceOrder && sourceStatus !== 'normal'
            ? (supply.customerCancellationDisposition === 'KEEP_STOCK' ? '客戶已取消・供應商不同意取消・到貨轉庫存' : '客戶已取消・採購待確認供應商答覆')
            : !supply.orderId
                ? '庫存補貨'
                : sourceOrder
                    ? '待到貨'
                    : '供應紀錄';
        const due = receivingDueInfo([supply]);
        if (due.status === 'late') overdueCount++;
        const tr = document.createElement('tr');
        tr.innerHTML = `
            <td data-th="訂單日期">${escapeHtml(date)}</td>
            <td data-th="客戶">${escapeHtml(customerLabel)}</td>
            <td data-th="負責業務">${escapeHtml(salesName)}</td>
            <td data-th="待到貨品項">${escapeHtml(supply.itemCode || supply.itemName || supply.id)} × ${ordered}</td>
            <td data-th="到貨進度">${escapeHtml(sourceLabel)}｜${escapeHtml(supplyProgress.label)}${receivingWaitHtml([supply])}${receivingDueHtml(due)}</td>
            <td data-th="操作" class="no-print">${sourceOrder && sourceStatus !== 'normal' && canCreatePurchaseOrderCapability() ? customerCancellationActions(supply) : actionHtml}</td>`;
        tr.dataset.receivingDueRank = String(due.sortRank);
        tr.dataset.receivingPlanRiskRank = '4';
        tr.dataset.receivingExpectedDate = due.expectedDate || '';
        tr.dataset.receivingOrderDate = date || '';
        fragment.appendChild(tr);
        standaloneSupplyCount++;
    });

    const sortedRows = Array.from(fragment.childNodes).sort((a, b) => {
        const rankDiff = Number(a.dataset.receivingDueRank || 3) - Number(b.dataset.receivingDueRank || 3);
        if (rankDiff) return rankDiff;
        const planRiskDiff = Number(a.dataset.receivingPlanRiskRank || 4) - Number(b.dataset.receivingPlanRiskRank || 4);
        if (planRiskDiff) return planRiskDiff;
        const aExpected = a.dataset.receivingExpectedDate || '9999-12-31';
        const bExpected = b.dataset.receivingExpectedDate || '9999-12-31';
        const expectedDiff = aExpected.localeCompare(bExpected);
        if (expectedDiff) return expectedDiff;
        return String(b.dataset.receivingOrderDate || '').localeCompare(String(a.dataset.receivingOrderDate || ''));
    });
    sortedRows.forEach(row => fragment.appendChild(row));
    tbody.appendChild(fragment);
    renderReceiptTasks();

    if (!inventory) tbody.querySelectorAll('button[onclick^="openSupplyReceipt"]').forEach(button => {
        button.setAttribute('onclick', 'openInventoryReceiving()');
        button.textContent = '前往倉庫收貨';
    });
    const totalRows = workCount + standaloneSupplyCount;
    const supplyMetrics = receivingSupplyMetrics(filters);
    if (inventory) updateInventoryReceivingCount(supplyMetrics.count);
    if (emptyHint) {
        emptyHint.style.display = totalRows === 0 ? 'block' : 'none';
        emptyHint.textContent = !purchasingReceivingReady ? '正在載入待到貨工作…' : '目前沒有待到貨品項。';
    }
    if (status) {
        if (!purchasingReceivingReady) status.textContent = `待到貨工作 ${workCount} 個；採購資料載入中…`;
        else {
            const parts = [`待到貨 ${supplyMetrics.count} 筆採購供應（${supplyMetrics.quantity} 個）`, `${workCount} 個正常訂單品項`];
            if (overdueCount) parts.push(`逾期 ${overdueCount} 筆已置頂`);
            if (planRiskCount) parts.push(`另有 ${planRiskCount} 筆預計晚於需求日`);
            if (standaloneSupplyCount) parts.push(`另有 ${standaloneSupplyCount} 筆庫存補貨／非正常訂單供應`);
            if (evidenceCount > workCount) parts.push(`其中 ${evidenceCount - workCount} 筆為分批／多張採購來源，已合併在同一品項顯示`);
            if (missingEvidence) parts.push(`${missingEvidence} 個品項尚未找到可操作的採購紀錄`);
            status.textContent = parts.join('。');
        }
    }
}

window.renderPoList = function(normalizedItemsByOrder = null, filterContext = null, dispatchStatesByOrder = null, lifecyclesByOrder = null) {
    if (purchasingView === 'receiving') {
        renderPurchasingReceivingWorkList(normalizedItemsByOrder, filterContext, dispatchStatesByOrder, lifecyclesByOrder);
        updatePoLoadMoreButton();
        return;
    }
    const head = document.getElementById('poListHeadRow');
    if (head) head.innerHTML = '<th>單號</th><th>公司</th><th>供應商</th><th>採購人員</th><th>採購日期</th><th>預計到貨</th><th>等待天數</th><th>品項</th><th>總計金額</th><th>文件狀態</th><th>到貨進度</th><th class="no-print">操作</th>';
    const tbody = document.getElementById('poListBody');
    const searchInput = document.getElementById('poListSearch');
    if (!tbody || !searchInput) return;
    const keyword = (searchInput.value || '').toLowerCase();
    const filters = filterContext || purchaseFilterContext();
    tbody.innerHTML = '';
    const fragment = document.createDocumentFragment();
    let shown = 0;

    const poRows = poHistorySearchActive ? poHistorySearchResults : poListCache;
    poRows.forEach(po => {
        // 全歷史搜尋已在資料層比對單號、廠商、採購人員與品項；歷史搜尋模式不可再用較窄欄位二次過濾。
        if (!poHistorySearchActive) {
            const searchable = `${po.poNo || ''} ${po.vendorName || ''} ${po.supplierName || ''} ${po.supplierEmail || ''} ${po.buyerName || ''}`.toLowerCase();
            if (keyword && !searchable.includes(keyword)) return;
        }

        const items = purchaseItemsFromSavedPo(po);
        const companyInfo = companyData[po.company];
        const companyLabel = companyInfo ? `${companyInfo.title}（${companyInfo.prefix}）` : (po.company || '');
        const supplierContact = purchaseOrderSupplierContact(po);

        items.forEach((item,itemIndex)=>{
            const ordered=Math.max(0,Number(item.qty||0));
            if (!purchaseLineMatchesFilters(po.poDate, item.salesName, item.brand, filters)) return;
            shown++;
            const itemTotal=Math.round(ordered*Number(item.unitPrice||0)*1.05);
            const receiptProgress=purchaseHistoryItemReceiptProgress(po,itemIndex);
            const tr = document.createElement('tr');
            tr.innerHTML = `
                <td data-th="單號">${escapeHtml(po.poNo || '')}</td>
                <td data-th="公司">${escapeHtml(companyLabel)}</td>
                <td data-th="供應商">${escapeHtml(po.vendorName || '')}</td>
                <td data-th="採購人員">${escapeHtml(po.buyerName || '')}</td>
                <td data-th="採購日期">${escapeHtml(po.poDate || '')}</td>
                <td data-th="預計到貨">${escapeHtml(po.expectedDate || po.scheduleDate || '—')}${(po.expectedDate||po.scheduleDate)&&receiptProgress.remainingQty>0&&(po.expectedDate||po.scheduleDate)<localDateString()?'・逾期':''}</td>
                <td data-th="等待天數">${receiptProgress.remainingQty > 0 ? escapeHtml(poWaitingDays(po)||'—') : '已到貨'}</td>
                <td data-th="品項數">${escapeHtml(item.itemCode||item.itemName||'單一品項')} × ${ordered}</td>
                <td data-th="總計金額">${itemTotal.toLocaleString()}</td>
                <td data-th="文件狀態">${escapeHtml(purchaseOrderDocumentStatusLabel(po))}</td>
                <td data-th="到貨進度">${escapeHtml(receiptProgress.label)}</td>
                <td data-th="操作" class="no-print">${itemIndex===0?`
                    <div class="po-list-action-row">
                        <button type="button" class="btn-small" onclick="reprintPurchaseOrder(${inlineJsValue(po.id)})">載入</button>
                        ${po.status==='DRAFT' && po.documentOnly===true && canCreatePurchaseOrderCapability() && canEditPage('orders.po') ? `<button type="button" class="btn-small" onclick="confirmSavedPurchaseOrder(${inlineJsValue(po.id)})">確認已採購</button>` : ''}
                        ${canCreatePurchaseOrderCapability() && canEditPage('orders.po') ? `<button type="button" class="btn-small btn-secondary" onclick="copySavedPurchaseOrderAsNew(${inlineJsValue(po.id)})">複製新採購</button>` : ''}
                    </div>`:'—'}</td>
            `;
            fragment.appendChild(tr);
        });
    });


    tbody.appendChild(fragment);

    const emptyHint = document.getElementById('poListEmptyHint');
    if (emptyHint) {
        emptyHint.style.display = shown === 0 ? 'block' : 'none';
        emptyHint.textContent = poHistorySearchLoading ? '正在搜尋採購單…' : keyword || filters.start || filters.end || filters.selectedSales || filters.selectedBrand ? '查無符合條件的採購單。' : '目前還沒有產生過任何採購單。';
    }
};

// 把「採購訂單」裡一筆舊的採購單紀錄，重新載回採購單視窗，維持原本的單號，方便再列印一次
async function purchaseIncomingSyncPending(po) {
    if (po?.status==='DRAFT' || po?.documentOnly===true || isPurchaseTerminalStatus(po?.status)) return false;
    const supplyIds = Array.isArray(po?.supplyOrderIds) ? po.supplyOrderIds.filter(Boolean) : [];
    if (!supplyIds.length) return false;
    const supplies = await readDocumentsByIds('supplyOrders', supplyIds);
    if (supplies.length !== new Set(supplyIds).size) return true;
    return supplies.some(supply => {
        if (isPurchaseTerminalStatus(supply.status)) return false;
        if ((supply.fulfillmentType || 'WAREHOUSE') === 'DIRECT_SHIP') return false;
        const targetQty = Math.max(0, Number(supply.qty || 0) - Number(supply.receivedQty || 0));
        const registeredQty = Math.max(0, Number(supply.incomingRegisteredQty || 0));
        return registeredQty < targetQty;
    });
}

window.reprintPurchaseOrder = async function(poId) {
    poDirectStockOpenGeneration++;
    poDirectStockMode = false;
    poNoGeneration++;
    poNoLoading = false;
    poNoReady = true;
    const po = poListCache.find(p => p.id === poId) || poHistorySearchResults.find(p => p.id === poId);
    if (po && !poListCache.some(p => p.id === poId)) poListCache.push(po);
    if (!po) return;

    populatePoVendorSuggestions();
    poItems = purchaseItemsFromSavedPo(po);
    poAllItems = poItems;
    poEditingId = po.id;
    poIncomingSyncPending = false;
    switchPoCompany(po.company || 'yushin', null, true);

    document.getElementById('poVendorName').value = po.vendorName || '';
    document.getElementById('poBuyerName').innerText = po.buyerName || '';
    document.getElementById('poDate').value = po.poDate || '';
    const poExpectedDateInput=document.getElementById('poExpectedDate');
    if(poExpectedDateInput)poExpectedDateInput.value=po.expectedDate||po.scheduleDate||'';
    syncPoLeadDays();
    document.getElementById('poNo').innerText = po.poNo || '';

    renderPoItemsTable();
    updatePoModeUI();
    document.getElementById('poModalOverlay').classList.add('active');

    if(po.status==='DRAFT' && po.documentOnly===true){
        updatePoSaveStatus('文件已儲存，尚未採購。下載 PDF 不改採購進度；實際下單後請按「確認已採購」。');
        updatePoSaveButton();return;
    }
    if (isPurchaseTerminalStatus(po.status)) {
        poIncomingSyncPending = false;
        const terminalLabel=String(po.status||'').toUpperCase()==='CLOSED'?'已結案':'已取消';
        updatePoSaveStatus(`採購單 ${po.poNo || po.id} ${terminalLabel}；此文件僅供查閱或重新輸出 PDF，不會重新增加在途庫存。`);
        updatePoSaveButton();
        return;
    }

    poSaveInProgress = true;
    updatePoSaveStatus(`正在確認採購單 ${po.poNo || po.id} 的在途同步狀態…`);
    updatePoSaveButton();
    try {
        poIncomingSyncPending = await purchaseIncomingSyncPending(po);
        updatePoSaveStatus(poIncomingSyncPending
            ? `採購單 ${po.poNo || po.id} 已同步雲端，但供應紀錄仍需同步在途庫存。`
            : `採購單 ${po.poNo || po.id} 已同步雲端。按下方按鈕即可再次列印或輸出 PDF。`);
    } catch (err) {
        poIncomingSyncPending = true;
        updatePoSaveStatus(`無法確認供應紀錄的在途同步狀態：${err.message}`, true);
    } finally {
        poSaveInProgress = false;
        updatePoSaveButton();
    }
};

window.copySavedPurchaseOrderAsNew = async function(poId) {
    if (poSaveInProgress || !canCreatePurchaseOrderCapability() || !canEditPage('orders.po')) return;
    const po = poListCache.find(item => item.id === poId) || poHistorySearchResults.find(item => item.id === poId);
    if (!po) return alert('找不到這張採購單，請重新整理。');
    const sourceItems = purchaseItemsFromSavedPo(po);
    if (!sourceItems.length) return alert('這張採購單沒有可複製的品項。');

    poDirectStockOpenGeneration++;
    const copySourceId = `copy-${Date.now()}-${Math.random().toString(36).slice(2)}`;
    poDirectStockMode = true;
    poEditingId = null;
    poIncomingSyncPending = false;
    // 只複製商品與價格；新採購不沿用客戶需求、供應或到貨狀態。
    poAllItems = sourceItems.map((item, index) => ({
        ...emptyDirectPoItem(),
        sourceId: `${copySourceId}-${index}`,
        itemName: item.itemName,
        itemCode: item.itemCode,
        productId: item.productId,
        brand: item.brand,
        brandId: item.brandId,
        productLine: item.productLine || '',
        productType: item.productType || '',
        spec: item.spec || '',
        unit: item.unit || '',
        qty: item.qty,
        unitPrice: item.unitPrice,
        supplier: item.supplier || '',
        warehouseId: item.warehouseId || defaultWarehouse()?.id || ''
    }));
    poItems = poAllItems.map(item => ({ ...item }));

    populatePoVendorSuggestions();
    switchPoCompany(po.company || 'yushin', null, true);
    document.getElementById('poVendorName').value = po.vendorName || '';
    document.getElementById('poBuyerName').innerText = currentUserName || currentUser?.email || '';
    document.getElementById('poDate').value = localDateString();
    clearPoExpectedDate();
    renderPoItemsTable();
    // 先顯示表單，再讀取新單號，避免慢網路下按鈕沒有回饋。
    const numberPromise = generatePoNo();
    updatePoModeUI();
    updatePoSaveStatus('尚未建立新採購。請確認供應商、品項、數量、單價及預計到貨日，再按「建立採購單並下載 PDF」；文件不增加在途，實際下單後另按「確認已採購」。');
    document.getElementById('poModalOverlay').classList.add('active');
    await numberPromise;
};

window.exportPurchaseOrderFromHistory = async function(poId) {
    const button = actionButtonFromEventOrSelector();
    const buttonState = beginActionButton(button, '準備 PDF…');
    if (button && !buttonState) return;
    try {
        await reprintPurchaseOrder(poId);
        await printPurchaseOrder();
    } catch (err) {
        console.error('重新匯出採購單 PDF 失敗：', err);
        alert('重新匯出採購單 PDF 失敗：' + (err?.message || err));
    } finally {
        endActionButton(button, buttonState);
    }
};

// 從原始訂單上的採購單號直接開啟該張採購單，避免還要切分頁搜尋。
window.openPurchaseOrderFromOrder = async function(poNo) {
    const button = actionButtonFromEventOrSelector();
    const buttonState = beginActionButton(button, '開啟中…');
    if (button && !buttonState) return;
    const open = async po => {
        if (!po) { alert('找不到這張採購單紀錄。'); return; }
        if (!poListCache.some(item => item.id === po.id)) poListCache.push(po);
        await reprintPurchaseOrder(po.id);
    };
    try {
        const cached = poListCache.find(po => po.poNo === poNo || po.id === poNo);
        if (cached) {
            await open(cached);
            return;
        }
        const doc = await firestoreReadWithTimeout(
            db.collection('purchaseOrders').doc(poNo).get(),
            '採購單紀錄'
        );
        await open(doc.exists ? { id: doc.id, ...doc.data() } : null);
    } catch (err) {
        alert('讀取採購單失敗：' + (err?.message || err));
    } finally {
        endActionButton(button, buttonState);
    }
};

// Atomic quick-purchase commitment; UI refresh belongs to the caller.
async function commitQuickPurchase(orderId, itemId, purchaseDetails, actorUid=currentUser?.uid, actorRole=currentUserRole) {
        if (!purchaseDetails || typeof purchaseDetails.supplier !== 'string' || !purchaseDetails.supplier.trim()
            || !Number.isFinite(purchaseDetails.unitCost) || purchaseDetails.unitCost < 0
            || !Number.isFinite(purchaseDetails.expectedQty) || purchaseDetails.expectedQty < 0)
            throw new Error('請確認供應商、數量與有效的實際單位成本。');
        purchaseDetails={...purchaseDetails,supplier:purchaseDetails.supplier.trim()};
        const assertActor=()=>{
            if (!actorUid || currentUser?.uid!==actorUid || currentUserRole!==actorRole)
                throw new Error('登入身份已變更，請以原帳號重新確認採購。');
            if (!canCreatePurchaseOrderCapability() || !canAccessPage('orders.po')) throw new Error('目前無採購作業權限。');
        };
        assertActor();
        const actorName=currentUserName||currentUser?.email||'', now=new Date().toISOString(), orderDate=localDateString();
        let savedOrder, savedSupply, savedDemand, incomingProductKey='', incomingWarehouseId='';
        const supplyRef = supplyOrdersCollection().doc(quickPurchaseSupplyId(orderId, itemId));
        await runRoleTransaction(async tx => {
            assertActor();
            savedOrder=savedSupply=savedDemand=undefined;
            incomingProductKey=incomingWarehouseId='';
            const orderRef = db.collection('orders').doc(orderId);
            const [orderSnapshot, supplySnapshot] = await Promise.all([tx.get(orderRef), tx.get(supplyRef)]);
            assertActor();
            if (!orderSnapshot.exists) throw new Error('來源訂單已不存在。');
            const order = { id:orderId, ...orderSnapshot.data() };
            if (normalizedOrderStatus(order) !== 'normal') throw new Error('來源訂單已取消或作廢。');
            const items = normalizedOrderItems(order);
            const itemIndex = items.findIndex(item => item.itemId === itemId);
            if (itemIndex < 0) throw new Error('找不到來源訂單品項。');
            const item = items[itemIndex];
            const demand = procurementDemandForOrderItem(order, item);
            const qty = demand.remainingToOrderQty;
            if (qty > 0 && qty !== purchaseDetails.expectedQty) throw new Error('待採購數量已變更，請重新開啟確認。');
            if ((item.procurementType || order.procurementType || 'PURCHASING_PO') === 'SALES_SELF_ORDER') throw new Error('此品項為業務自行訂貨。');
            const demandId = demand.demandId || '';
            const existingSupply = supplySnapshot.exists ? { id:supplyRef.id, ...supplySnapshot.data() } : null;
            if (!(qty > 0) && !existingSupply) throw new Error('此品項已無待採購數量，請重新整理。');

            const currentProductKey = poIncomingKey(item);
            const currentFulfillmentType = item.fulfillmentType || order.fulfillmentType || 'WAREHOUSE';
            const currentWarehouseId = currentFulfillmentType === 'DIRECT_SHIP'
                ? '' : (item.warehouseId || defaultWarehouse()?.id || '');
            const productKey = existingSupply?.productKey || currentProductKey;
            const fulfillmentType = existingSupply?.fulfillmentType || currentFulfillmentType;
            const directShip = fulfillmentType === 'DIRECT_SHIP';
            const warehouseId = directShip ? '' : (existingSupply?.warehouseId || currentWarehouseId);

            if (existingSupply) {
                if (qty > 0 && (existingSupply.supplier !== purchaseDetails.supplier || Number(existingSupply.unitCost) !== purchaseDetails.unitCost)) {
                    throw new Error('追加採購的供應商或單價不同，請使用「產生採購單」另建紀錄，保留原採購金額。');
                }
                if (existingSupply.productKey && currentProductKey && existingSupply.productKey !== currentProductKey) {
                    throw new Error('此品項已建立供應紀錄，產品識別不可在追加採購前變更。');
                }
                if ((existingSupply.fulfillmentType || 'WAREHOUSE') !== currentFulfillmentType) {
                    throw new Error('此品項已建立供應紀錄，交付方式不可在追加採購前變更。');
                }
                if (!directShip && existingSupply.warehouseId && currentWarehouseId && existingSupply.warehouseId !== currentWarehouseId) {
                    throw new Error('此品項已建立供應紀錄，入庫倉庫不可在追加採購前變更。');
                }
            }
            if (!directShip && (!productKey || !warehouseId)) throw new Error('訂單快照缺少貨號或入庫倉庫，請先修正來源訂單。');

            const internalNo = existingSupply?.internalNo || `MO-${orderDate.replace(/-/g, '')}-${supplyRef.id.slice(-8).toUpperCase()}`;
            const alreadyOrdered = Math.max(0, Number(item.supplyOrderedQty || 0));
            const identity = brandIdentityForRecord(existingSupply || item);
            const canonicalBrand = identity.brand || resolveBrandName(existingSupply?.brand || item.brand || '');
            const canonicalBrandId = identity.brandId || existingSupply?.brandId || item.brandId || brandIdForName(canonicalBrand);
            const productId = String(existingSupply?.productId || item.productId || '').trim();
            const demandOrderPlan=globalThis.YushinProcurementDemand.applyOrder(demand,qty);
            if(qty>0&&demandOrderPlan.appliedQty!==qty)throw new Error('採購需求數量已變更，請重新整理後再試。');
            const demandRef=procurementDemandRef(demandId);
            const demandDoc=procurementDemandDocument(demandOrderPlan.demand,{
                productId,
                productKey,
                itemCode:item.itemCode||'',
                itemName:item.itemName||'',
                brand:canonicalBrand,
                brandId:canonicalBrandId,
                fulfillmentType,
                warehouseId,
                ownerUid:order.ownerUid||'',
                salesCode:order.salesCode||'',
                salesName:order.salesName||'',
                scheduleDate:item.scheduleDate||order.expectedDate||''
            },{
                createdAt:order.createdAt||now,
                updatedAt:now
            });
            const previousSupplyQty = Math.max(0, Number(existingSupply?.qty || 0));
            const nextSupplyQty = previousSupplyQty + Math.max(0, Number(qty || 0));
            const nextOrdered = alreadyOrdered + Math.max(0, Number(qty || 0));
            if (!globalThis.YushinReceiving?.normalizeSupply) {
                throw new Error('Receiving core 未載入，無法計算待到貨狀態。');
            }
            const supplyProjection = globalThis.YushinReceiving.normalizeSupply({
                ...(existingSupply || {}),
                qty: nextSupplyQty
            });
            const receivedQty = supplyProjection.receivedQty;
            const nextSupplyStatus = supplyProjection.status;
            const registeredIncomingQty = Math.max(0, Number(existingSupply?.incomingRegisteredQty || 0));
            const targetIncomingQty = directShip ? 0 : supplyProjection.remainingQty;
            const incomingDelta = targetIncomingQty - registeredIncomingQty;

            let invRef=null, whRef=null, invSnap=null, whSnap=null;
            if (!directShip && incomingDelta !== 0) {
                invRef = db.collection('inventory').doc(encodeURIComponent(productKey));
                whRef = db.collection('warehouseStocks').doc(warehouseStockDocId(warehouseId, productKey));
                [invSnap, whSnap] = await Promise.all([tx.get(invRef), tx.get(whRef)]);
            }
            assertActor();

            // 單純重試時不增加訂購量或事件，但仍會修復曾中斷的 incoming 同步。
            const orderEvents = Array.isArray(existingSupply?.orderEvents) ? existingSupply.orderEvents.slice() : [];
            if (qty > 0) {
                orderEvents.push({ qty, supplier:purchaseDetails.supplier, unitCost:purchaseDetails.unitCost, orderDate, createdAt:now, createdByUid:actorUid, createdBy:actorName });
            }

            savedSupply = {
                ...(existingSupply || {}),
                id:supplyRef.id,
                type:'PURCHASING_MANUAL',
                method:'PURCHASING_MANUAL',
                sourceType:'SALES_ORDER',
                sourceId:orderId,
                sourceItemId:itemId,
                demandId:existingSupply?.demandId||demandId||'',
                internalNo,
                status:nextSupplyStatus,
                orderId:existingSupply?.orderId||orderId,
                itemId:existingSupply?.itemId||itemId,
                orderItemIndex:existingSupply?.orderItemIndex??itemIndex,
                ownerUid:existingSupply?.ownerUid||order.ownerUid||'',
                salesCode:existingSupply?.salesCode||order.salesCode||'',
                salesName:existingSupply?.salesName||order.salesName||'',
                customerName:existingSupply?.customerName||order.customerName||'',
                company:existingSupply?.company||order.company||'yushin',
                productId,
                productKey,
                itemCode:existingSupply?.itemCode||item.itemCode||'',
                itemName:existingSupply?.itemName||item.itemName||'',
                brand:canonicalBrand,
                brandId:canonicalBrandId,
                productLine:existingSupply?.productLine||item.productLine||'',
                qty:nextSupplyQty,
                receivedQty,
                incomingRegisteredQty:targetIncomingQty,
                incomingRegisteredAt:incomingDelta !== 0 ? now : (existingSupply?.incomingRegisteredAt||''),
                supplier:existingSupply?.supplier || purchaseDetails.supplier,
                unitCost:existingSupply?.unitCost ?? purchaseDetails.unitCost,
                orderDate:existingSupply?.orderDate||orderDate,
                lastOrderedAt:qty > 0 ? orderDate : (existingSupply?.lastOrderedAt||existingSupply?.orderDate||orderDate),
                orderEvents,
                fulfillmentType,
                warehouseId,
                createdAt:existingSupply?.createdAt||now,
                updatedAt:now,
                createdByUid:existingSupply?.createdByUid||actorUid,
                createdBy:existingSupply?.createdBy||actorName,
                createdByRole:existingSupply?.createdByRole||actorRole
            };

            if (invRef && whRef) {
                const inv = inventoryNumbers(invSnap?.exists ? invSnap.data() : {});
                const wh = inventoryNumbers(whSnap?.exists ? whSnap.data() : {});
                if (invSnap?.exists) {
                    tx.set(invRef, {
                        productId,
                        itemCode:existingSupply?.itemCode||item.itemCode||'',
                        itemName:existingSupply?.itemName||item.itemName||'',
                        brand:canonicalBrand,
                        brandId:canonicalBrandId,
                        incoming:Math.max(0,inv.incoming+incomingDelta),
                        updatedAt:now
                    }, {merge:true});
                } else {
                    const nextInventory = {
                        productKey,
                        productId,
                        itemCode:existingSupply?.itemCode||item.itemCode||'',
                        itemName:existingSupply?.itemName||item.itemName||'',
                        brand:canonicalBrand,
                        brandId:canonicalBrandId,
                        onHand:0, reserved:0,
                        incoming:Math.max(0,incomingDelta), lots:[], updatedAt:now
                    };
                    nextInventory.searchTokens=buildInventorySearchTokens(nextInventory);
                    tx.set(invRef,nextInventory,{merge:true});
                }
                tx.set(whRef,{
                    warehouseId,productKey,
                    productId,
                    itemCode:existingSupply?.itemCode||item.itemCode||'',
                    itemName:existingSupply?.itemName||item.itemName||'',
                    brand:canonicalBrand,
                    brandId:canonicalBrandId,
                    onHand:wh.onHand,reserved:wh.reserved,
                    incoming:Math.max(0,wh.incoming+incomingDelta),updatedAt:now
                },{merge:true});
                tx.set(db.collection('inventoryMovements').doc(),{
                    type:'purchase_incoming',qty:incomingDelta,productKey,productId,warehouseId,
                    brand:canonicalBrand,brandId:canonicalBrandId,
                    fulfillmentType:'WAREHOUSE',sourceType:'SUPPLY_ORDER',sourceId:supplyRef.id,
                    purchaseDocumentId:internalNo,createdAt:now,
                    createdBy:actorName,
                    ownerUid:existingSupply?.ownerUid||order.ownerUid||'',
                    salesCode:existingSupply?.salesCode||order.salesCode||''
                });
                incomingProductKey=productKey;
                incomingWarehouseId=warehouseId;
            }

            tx.set(supplyRef, (({id, ...record}) => record)(savedSupply));
            if(demandRef)tx.set(demandRef,demandDoc,{merge:true});
            savedDemand = { ...demandDoc, id:demandId };
            if (qty > 0) {
                items[itemIndex] = {
                    ...item, supplyOrderedQty:nextOrdered,
                    manualOrderNos:[...new Set([...(item.manualOrderNos||[]),internalNo])],
                    orderedAt:item.orderedAt && item.orderedAt < orderDate ? item.orderedAt : orderDate,
                    orderEvents:[
                        ...(item.orderEvents||[]).filter(event=>event.id!==supplyRef.id),
                        {id:supplyRef.id,type:'PURCHASING_MANUAL',at:now,date:orderDate,qty,documentNo:internalNo,by:actorName}
                    ]
                };
                savedOrder = { ...order, items, itemCount:items.length, orderSchemaVersion:2, updatedAt:now };
                tx.update(orderRef, {items, itemCount:items.length, orderSchemaVersion:2,
                    ...orderWorkIndexFields(savedOrder), updatedAt:now});
            } else {
                savedOrder = order;
            }
        });
        return { savedOrder, savedSupply, savedDemand, incomingProductKey, incomingWarehouseId };
}
// Atomic quick-purchase service end.

// Purchasing transactions and checkpoints; no editor, DOM or UI-cache ownership.
function poIncomingKey(item) {
    return String(item.productId || (item.itemCode ? `code:${normalizeHistoryItemCode(item.itemCode)}` : '')).trim();
}
async function registerPurchaseIncoming(poId, poRecord, {actorUid=currentUser?.uid,actorRole=currentUserRole,onStockCommitted=null}={}) {
    if (poRecord?.status==='DRAFT' || poRecord?.documentOnly===true) throw Error('採購文件尚未確認已採購，不能登記在途。');
    if (isPurchaseTerminalStatus(poRecord?.status)) return;
    const assertActor=()=>{
        if (!actorUid || currentUser?.uid!==actorUid || currentUserRole!==actorRole) throw new Error('登入身份已變更，請以原帳號重試在途同步。');
        if (!canCreatePurchaseOrderCapability() || !canAccessPage('orders.po')) throw new Error('目前無採購作業權限。');
    };
    const quantity=(value,label,optional=false)=>{
        if (value===undefined&&optional) return 0;
        if ((typeof value!=='number'&&typeof value!=='string') || (typeof value==='string'&&!value.trim())
            || !Number.isFinite(Number(value)) || Number(value)<0) throw new Error(`${label}數量異常，請先核對紀錄。`);
        return Number(value);
    };
    assertActor();
    if (!globalThis.YushinReceiving?.normalizeSupply) throw new Error('Receiving core 未載入，無法同步在途庫存。');
    const supplyIds = [...new Set(Array.isArray(poRecord?.supplyOrderIds) ? poRecord.supplyOrderIds : [])];
    const now=new Date().toISOString(), actorName=currentUserName||currentUser?.email||'';
    for (const supplyId of supplyIds) {
        assertActor();
        const movementRef=db.collection('inventoryMovements').doc();
        let committedStock=null;
        await runRoleTransaction(async tx => {
            assertActor();
            committedStock=null;
            const supplyRef = supplyOrdersCollection().doc(supplyId);
            const [poSnap,supplySnap] = await Promise.all([tx.get(db.collection('purchaseOrders').doc(poId)),tx.get(supplyRef)]);
            assertActor();
            if (!poSnap.exists) throw new Error('找不到來源採購單，請先核對同步結果。');
            const livePo=poSnap.data();
            if(livePo.status==='DRAFT'||livePo.documentOnly===true)throw Error('原採購文件尚未確認已採購。');
            if (!Array.isArray(livePo.supplyOrderIds)||!livePo.supplyOrderIds.includes(supplyId)) throw new Error('採購單供應連結已變更，請重新開啟原單。');
            if (isPurchaseTerminalStatus(livePo.status)) return;
            if (!supplySnap.exists) throw new Error(`找不到供應紀錄 ${supplyId}`);
            const supply = supplySnap.data();
            if (supply.type!=='PURCHASING_PO'||supply.purchaseDocumentId!==poId) throw new Error('供應紀錄不屬於這張採購單，請先核對原單。');
            if (isPurchaseTerminalStatus(supply.status)) return;
            if ((supply.fulfillmentType || 'WAREHOUSE') === 'DIRECT_SHIP') return;

            const key = String(supply.productKey || supply.productId || '').trim();
            const warehouseId = String(supply.warehouseId || '').trim();
            if (!key || !warehouseId) throw new Error(`供應紀錄 ${supplyId} 缺少產品或倉庫資料`);

            const orderedQty=quantity(supply.qty,'採購');
            const receivedQty=quantity(supply.receivedQty,'到貨',true);
            if (receivedQty>orderedQty) throw new Error('到貨量超過採購量，請先核對供應紀錄。');
            quantity(supply.incomingRegisteredQty,'已登記在途',true);
            const projection=globalThis.YushinReceiving.normalizeSupply(supply);
            const targetQty = projection.remainingQty;
            const registeredQty = projection.incomingRegisteredQty;
            const delta = targetQty - registeredQty;
            if (!delta) return;

            const invRef = db.collection('inventory').doc(encodeURIComponent(key));
            const whRef = db.collection('warehouseStocks').doc(warehouseStockDocId(warehouseId,key));
            const invSnap = await tx.get(invRef);
            const whSnap = await tx.get(whRef);
            assertActor();
            if ((invSnap.exists&&invSnap.data().productKey&&invSnap.data().productKey!==key)
                || (whSnap.exists&&((whSnap.data().productKey&&whSnap.data().productKey!==key)
                    ||(whSnap.data().warehouseId&&whSnap.data().warehouseId!==warehouseId))))
                throw new Error('公司或分倉庫存識別不符，請先核對紀錄。');
            const companyIncoming=quantity(invSnap.exists?invSnap.data().incoming:undefined,'公司在途',true);
            const warehouseIncoming=quantity(whSnap.exists?whSnap.data().incoming:undefined,'分倉在途',true);
            if (companyIncoming+delta < -1e-9 || warehouseIncoming+delta < -1e-9) throw new Error('在途保留量不足，無法完整修正，請先核對公司與分倉庫存。');
            const inv = inventoryNumbers(invSnap.exists ? invSnap.data() : {});
            const wh = inventoryNumbers(whSnap.exists ? whSnap.data() : {});

            if (invSnap.exists) {
                tx.set(invRef,{
                    incoming:Math.max(0,inv.incoming+delta),
                    brand:resolveBrandName(supply.brand||''),
                    brandId:supply.brandId||brandIdForName(supply.brand||''),
                    updatedAt:now
                },{merge:true});
            } else {
                const nextInventory={
                    productKey:key,productId:supply.productId||'',itemCode:supply.itemCode||'',itemName:supply.itemName||'',
                    brand:resolveBrandName(supply.brand||''),brandId:supply.brandId||brandIdForName(supply.brand||''),onHand:0,reserved:0,incoming:Math.max(0,delta),lots:[],updatedAt:now
                };
                nextInventory.searchTokens=buildInventorySearchTokens(nextInventory);
                tx.set(invRef,nextInventory,{merge:true});
            }
            tx.set(whRef,{
                warehouseId,productKey:key,productId:supply.productId||'',itemCode:supply.itemCode||'',
                itemName:supply.itemName||'',brand:resolveBrandName(supply.brand||''),brandId:supply.brandId||brandIdForName(supply.brand||''),
                onHand:wh.onHand,reserved:wh.reserved,incoming:Math.max(0,wh.incoming+delta),updatedAt:now
            },{merge:true});
            tx.update(supplyRef,{incomingRegisteredQty:targetQty,incomingRegisteredAt:now,updatedAt:now});
            tx.set(movementRef,{
                type:'purchase_incoming',qty:delta,productKey:key,productId:supply.productId||'',warehouseId,
                brand:resolveBrandName(supply.brand||''),brandId:supply.brandId||brandIdForName(supply.brand||''),
                fulfillmentType:'WAREHOUSE',sourceType:'SUPPLY_ORDER',sourceId:supplyId,
                purchaseDocumentId:poId,createdAt:now,createdBy:actorName
            });
            committedStock={key,warehouseId};
        });
        try{
            assertActor();
            if (committedStock) onStockCommitted?.(committedStock.key,committedStock.warehouseId);
        }catch(err){
            if(committedStock)err.incomingCommitted=true;
            throw err;
        }
    }
}

async function cancelOutstandingSupplyRecord(poId, supplyId, reason, {actorUid=currentUser?.uid,actorRole=currentUserRole,onStockCommitted=null,onDemandChanged=null}={}) {
    const assertActor=()=>{
        if (!actorUid||currentUser?.uid!==actorUid||currentUserRole!==actorRole) throw new Error('登入身份已變更，請以原帳號重試取消。');
        if (!canCreatePurchaseOrderCapability()) throw new Error('目前無採購取消權限。');
    };
    const quantity=(value,label,optional=false)=>{
        if(value===undefined&&optional)return 0;
        if((typeof value!=='number'&&typeof value!=='string')||(typeof value==='string'&&!value.trim())||!Number.isFinite(Number(value))||Number(value)<0)
            throw new Error(`${label}數量異常，請先核對紀錄。`);
        return Number(value);
    };
    if(typeof reason!=='string'||!reason.trim())throw new Error('請填寫取消原因。');
    reason=reason.trim();assertActor();
    const now=new Date().toISOString(),actorName=currentUserName||currentUser?.email||'';
    const movementRef=db.collection('inventoryMovements').doc();
    let result={cancelledQty:0,receivedQty:0,terminalStatus:'',orderId:'',productKey:'',warehouseId:'',demandId:''};
    await runRoleTransaction(async tx => {
        assertActor();
        const supplyRef=supplyOrdersCollection().doc(supplyId);
        const supplySnap=await tx.get(supplyRef);
        assertActor();
        if(!supplySnap.exists)throw new Error(`找不到供應紀錄 ${supplyId}`);
        const supply=supplySnap.data()||{};
        if(!['PURCHASING_MANUAL','PURCHASING_PO'].includes(supply.type)
            ||(supply.purchaseDocumentId||supply.internalNo||supplyId)!==poId)throw new Error('供應紀錄與本次採購取消來源不符。');
        if(supply.type==='PURCHASING_PO'){
            const poSnap=await tx.get(db.collection('purchaseOrders').doc(poId));assertActor();
            if(!poSnap.exists||!Array.isArray(poSnap.data().supplyOrderIds)||!poSnap.data().supplyOrderIds.includes(supplyId))
                throw new Error('採購單供應連結不完整，請先核對原單。');
        }
        const rawQty=quantity(supply.qty,'採購'),rawReceived=quantity(supply.receivedQty,'到貨',true);
        if(rawReceived>rawQty)throw new Error('到貨量超過採購量，無法安全取消。');
        quantity(supply.incomingRegisteredQty,'已登記在途',true);
        if (!globalThis.YushinReceiving?.normalizeSupply) {
            throw new Error('Receiving core 未載入，無法計算取消數量。');
        }
        const supplyProjection=globalThis.YushinReceiving.normalizeSupply(supply);
        const ordered=supplyProjection.qty;
        const received=supplyProjection.receivedQty;
        const existingTerminal=isPurchaseTerminalStatus(supplyProjection.status);
        const remaining=existingTerminal
            ? Math.max(0,ordered-received)
            : supplyProjection.remainingQty;
        const stoppedQty=existingTerminal?quantity(supply.closedQty??supply.cancelledQty??remaining,'已停止'):0;
        if(existingTerminal&&Math.abs(stoppedQty-remaining)>1e-9)throw new Error('已停止數量與供應餘量不符，請先核對紀錄。');
        if(existingTerminal&&Number(supply.incomingRegisteredQty||0)!==0)throw new Error('終止供應仍保留在途量，請先核對紀錄。');
        const productKey=String(supply.productKey||supply.productId||'').trim();
        const warehouseId=String(supply.warehouseId||'').trim();
        result={
            cancelledQty:stoppedQty,
            receivedQty:received,
            terminalStatus:existingTerminal?supplyProjection.status:'',
            orderId:String(supply.orderId||''),
            productKey,
            warehouseId,
            demandId:String(supply.demandId||'')
        };
        if(existingTerminal||remaining<=0)return;

        const directShip=(supply.fulfillmentType||'WAREHOUSE')==='DIRECT_SHIP';
        const registeredIncoming=Math.max(0,Number(supply.incomingRegisteredQty||0));
        if(directShip&&registeredIncoming>0)throw new Error('直送供應不應有公司倉庫在途量，請先核對紀錄。');
        const orderRef=supply.orderId?db.collection('orders').doc(supply.orderId):null;
        const invRef=!directShip&&registeredIncoming>0&&productKey
            ? db.collection('inventory').doc(encodeURIComponent(productKey)):null;
        const whRef=!directShip&&registeredIncoming>0&&productKey&&warehouseId
            ? db.collection('warehouseStocks').doc(warehouseStockDocId(warehouseId,productKey)):null;
        const demandId=String(supply.demandId||'').trim();
        const demandRef=demandId?procurementDemandRef(demandId):null;

        // Read every linked document before the first write. This mirrors ERPNext's
        // status-updater model: the demand document is updated from the PO line change.
        const orderSnap=orderRef?await tx.get(orderRef):null;
        const invSnap=invRef?await tx.get(invRef):null;
        const whSnap=whRef?await tx.get(whRef):null;
        const demandSnap=demandRef?await tx.get(demandRef):null;
        assertActor();
        if(orderRef&&!orderSnap?.exists)throw new Error('來源訂單不存在，無法完整取消供應承諾。');
        if(demandRef&&!demandSnap?.exists)throw new Error('來源採購需求不存在，無法完整取消供應承諾。');
        if(!directShip&&registeredIncoming>0&&(!productKey||!warehouseId||!invSnap?.exists||!whSnap?.exists)){
            throw new Error(`供應紀錄 ${supplyId} 的在途庫存資料不完整，無法安全取消。`);
        }

        const terminalStatus=received>0?'CLOSED':'CANCELLED';
        if(orderSnap?.exists){
            const order=orderSnap.data();
            const items=normalizedOrderItems(order);
            const itemIndex=items.findIndex(item=>String(item.itemId||'')===String(supply.itemId||''));
            if(itemIndex<0)throw new Error(`來源訂單找不到供應紀錄 ${supplyId} 對應品項。`);
            const item=items[itemIndex];
            const currentSupplyOrdered=quantity(item.supplyOrderedQty,'訂單供應承諾',true);
            const receivedForItem=quantity(item.receivedQty,'訂單已到貨',true);
            if(currentSupplyOrdered-remaining<receivedForItem-1e-9)throw new Error('訂單供應承諾不足以完整取消，請先核對來源數量。');
            items[itemIndex]={
                ...item,
                supplyOrderedQty:Math.max(receivedForItem,currentSupplyOrdered-remaining)
            };
            const nextOrder={...order,items,itemCount:items.length,orderSchemaVersion:2,updatedAt:now};
            tx.update(orderRef,{
                items,itemCount:items.length,orderSchemaVersion:2,
                ...orderWorkIndexFields(nextOrder),updatedAt:now
            });
        }

        if(demandRef&&demandSnap?.exists){
            if(!globalThis.YushinProcurementDemand?.applySupplyCancellation){
                throw new Error('Procurement Demand core 未載入，無法重新開啟採購需求。');
            }
            const demandPlan=globalThis.YushinProcurementDemand.applySupplyCancellation(demandSnap.data()||{},supply);
            const demandBefore=demandSnap.data();
            const demandOrdered=quantity(demandBefore.orderedQty,'需求供應承諾',true);
            const demandReceived=quantity(demandBefore.receivedQty,'需求已到貨',true);
            if(demandPlan.releasedQty!==remaining||demandOrdered-remaining<demandReceived-1e-9)
                throw new Error('需求供應承諾不足以完整取消，請先核對來源數量。');
            const demandDoc=procurementDemandDocument(demandPlan.demand,{},{
                createdAt:demandSnap.data()?.createdAt||now,
                updatedAt:now
            });
            tx.set(demandRef,demandDoc,{merge:true});
        }

        if(invRef&&whRef){
            const inv=inventoryNumbers(invSnap.data());
            const wh=inventoryNumbers(whSnap.data());
            const companyIncoming=quantity(invSnap.data().incoming,'公司在途',true);
            const warehouseIncoming=quantity(whSnap.data().incoming,'分倉在途',true);
            if(companyIncoming<registeredIncoming-1e-9||warehouseIncoming<registeredIncoming-1e-9)throw new Error('在途保留量不足以完整扣回，取消未提交。');
            if((invSnap.data().productKey&&invSnap.data().productKey!==productKey)
                ||(whSnap.data().productKey&&whSnap.data().productKey!==productKey)
                ||(whSnap.data().warehouseId&&whSnap.data().warehouseId!==warehouseId))throw new Error('公司或分倉庫存識別不符。');
            tx.update(invRef,{incoming:Math.max(0,inv.incoming-registeredIncoming),updatedAt:now});
            tx.update(whRef,{incoming:Math.max(0,wh.incoming-registeredIncoming),updatedAt:now});
            tx.set(movementRef,{
                type:terminalStatus==='CLOSED'?'purchase_incoming_close':'purchase_incoming_cancel',
                qty:-registeredIncoming,
                productKey,warehouseId,
                fulfillmentType:'WAREHOUSE',
                sourceType:'SUPPLY_ORDER',
                sourceId:supplyId,
                purchaseDocumentId:poId,
                reason,
                ownerUid:supply.ownerUid||'',
                salesCode:supply.salesCode||'',
                createdAt:now,
                createdBy:actorName
            });
        }

        tx.update(supplyRef,{
            status:terminalStatus,
            ...(terminalStatus==='CLOSED'?{
                closedQty:remaining,closeReason:reason,closedAt:now,
                closedByUid:actorUid,closedBy:actorName
            }:{
                cancelledQty:remaining,cancelReason:reason,cancelledAt:now,
                cancelledByUid:actorUid,cancelledBy:actorName
            }),
            incomingRegisteredQty:0,
            updatedAt:now
        });
        result={cancelledQty:remaining,receivedQty:received,terminalStatus,orderId:String(supply.orderId||''),productKey,warehouseId,demandId};
    });
    try{
        assertActor();
        if(result.productKey&&result.warehouseId)onStockCommitted?.(result.productKey,result.warehouseId);
        if(result.demandId)onDemandChanged?.(result.demandId);
    }catch(err){
        err.supplyCommitted=true;
        err.supplyResult=result;
        throw err;
    }
    return result;
}

async function stopPurchaseOrderOutstanding(poId,reason,{actorUid=currentUser?.uid,actorRole=currentUserRole,onStockCommitted=null,onDemandChanged=null}={}) {
    const assertActor=()=>{
        if(!actorUid||currentUser?.uid!==actorUid||currentUserRole!==actorRole)throw new Error('登入身份已變更，請以原帳號重試取消。');
        if(!canCreatePurchaseOrderCapability())throw new Error('目前無採購取消權限。');
    };
    if(typeof reason!=='string'||!reason.trim())throw new Error('請填寫取消原因。');
    reason=reason.trim();assertActor();
    const actor={actorUid,actorRole,onStockCommitted,onDemandChanged},actorName=currentUserName||currentUser?.email||'',now=new Date().toISOString();
    const ref=db.collection('purchaseOrders').doc(poId);
    const supplyIds=await runRoleTransaction(async tx=>{
        const snapshot=await tx.get(ref);assertActor();
        if(!snapshot.exists)throw new Error('找不到這張採購單。');
        const ids=snapshot.data().supplyOrderIds;
        if(!Array.isArray(ids)||!ids.length||ids.some(id=>typeof id!=='string'||!id))throw new Error('採購單沒有完整供應連結。');
        return [...new Set(ids)];
    });
    const affectedOrderIds=new Set();
    for(const supplyId of supplyIds){
        assertActor();
        const result=await cancelOutstandingSupplyRecord(poId,supplyId,reason,actor);
        if(result.orderId)affectedOrderIds.add(result.orderId);
    }
    let patch=null,cancelledQty=0,receivedQty=0;
    await runRoleTransaction(async tx=>{
        assertActor();patch=null;cancelledQty=receivedQty=0;
        const snapshot=await tx.get(ref);
        const supplies=await Promise.all(supplyIds.map(id=>tx.get(supplyOrdersCollection().doc(id))));
        assertActor();
        if(!snapshot.exists)throw new Error('來源採購單已不存在。');
        const live=snapshot.data(),ids=Array.isArray(live.supplyOrderIds)?[...new Set(live.supplyOrderIds)]:[];
        if(JSON.stringify(ids.slice().sort())!==JSON.stringify(supplyIds.slice().sort()))throw new Error('採購單供應連結已變更，請重新執行取消。');
        supplies.forEach(snap=>{
            if(!snap.exists)throw new Error('採購單供應紀錄不完整。');
            const supply=snap.data();
            if(supply.type!=='PURCHASING_PO'||supply.purchaseDocumentId!==poId)throw new Error('供應紀錄不屬於這張採購單。');
            for(const field of ['qty','receivedQty','incomingRegisteredQty']){
                const value=supply[field]===undefined&&field!=='qty'?0:supply[field];
                if((typeof value!=='number'&&typeof value!=='string')||(typeof value==='string'&&!value.trim())||!Number.isFinite(Number(value))||Number(value)<0)
                    throw new Error('供應數量異常，無法結清採購單。');
            }
            const projection=globalThis.YushinReceiving.normalizeSupply(supply);
            const stopped=Number(supply.closedQty??supply.cancelledQty??(projection.qty-projection.receivedQty));
            if(!Number.isFinite(stopped)||stopped<0||projection.qty!==Number(supply.qty)||projection.receivedQty!==Number(supply.receivedQty||0)
                ||projection.incomingRegisteredQty!==Number(supply.incomingRegisteredQty||0))throw new Error('供應數量已變更或異常，無法結清採購單。');
            if(!isPurchaseTerminalStatus(projection.status)&&projection.remainingQty>0)throw new Error('尚有供應品項未停止，採購單不能結清。');
            receivedQty+=projection.receivedQty;
            if(isPurchaseTerminalStatus(projection.status)){
                if(projection.incomingRegisteredQty!==0)throw new Error('供應在途尚未釋放，採購單不能結清。');
                if(Math.abs(stopped-(projection.qty-projection.receivedQty))>1e-9)throw new Error('供應停止量與餘量不符，採購單不能結清。');
                cancelledQty+=stopped;
            }
        });
        if(isPurchaseTerminalStatus(live.status)){patch=live;return;}
        if(cancelledQty<=0)return;
        const documentStatus=receivedQty>0?'CLOSED':'CANCELLED';
        patch={status:documentStatus,stoppedQty:cancelledQty,
            ...(documentStatus==='CLOSED'?{closedQty:cancelledQty,closeReason:reason,closedAt:now,closedByUid:actorUid,closedBy:actorName}
                :{cancelledQty,cancelReason:reason,cancelledAt:now,cancelledByUid:actorUid,cancelledBy:actorName}),updatedAt:now};
        tx.update(ref,patch);
    });
    assertActor();
    return {patch,cancelledQty,receivedQty,supplyIds,affectedOrderIds:[...affectedOrderIds]};
}

// Purchase cancellation UI and cache refresh; authoritative writes stay in supply-order Service.
const purchaseCancellationInProgress = new Set();

window.cancelSupplyOutstanding = async function(supplyId) {
    if (!canCreatePurchaseOrderCapability()) {
        alert('只有管理員或採購可以取消採購的未到貨數量。');
        return;
    }
    const actionKey = `supply:${supplyId}`;
    const actorUid=currentUser?.uid,actorRole=currentUserRole;
    if (purchaseCancellationInProgress.has(actionKey)) return;

    let supply;
    try {
        const snapshot = await firestoreReadWithTimeout(
            supplyOrdersCollection().doc(supplyId).get(),
            '讀取採購品項狀態'
        );
        if (!snapshot.exists) throw new Error('找不到這筆供應紀錄。');
        supply = { id:snapshot.id, ...snapshot.data() };
    } catch (err) {
        alert('無法讀取採購品項：' + (err?.message || err));
        return;
    }

    if (!['PURCHASING_MANUAL', 'PURCHASING_PO'].includes(supply.type)) {
        alert('此採購方式不支援在這裡取消。');
        return;
    }
    if (isPurchaseTerminalStatus(supply.status)) {
        const label=String(supply.status||'').toUpperCase()==='CLOSED'?'已結案':'已取消';
        showActionFeedback(`這筆採購${label}，沒有待處理的未到貨數量。`, 'success');
        return;
    }
    const remaining = Math.max(0, Number(supply.qty || 0) - Number(supply.receivedQty || 0));
    if (remaining <= 0) {
        alert('這筆採購已全部到貨，沒有可取消的未到貨數量。');
        return;
    }

    const reasonRaw = prompt(
        `取消品項 ${supply.itemCode || supply.itemName || supply.id} 尚未到貨的 ${remaining} 個。\n採購單：${supply.purchaseDocumentNo || supply.internalNo || supply.id}\n只取消此品項，其他品項不受影響；已到貨的數量不回沖。\n來源訂單仍有效時，未滿足的數量會重新列入待採購。\n\n請輸入原因：`
    );
    if (reasonRaw === null) return;
    const reason = String(reasonRaw || '').trim();
    if (!reason) {
        alert('請填寫取消原因，方便後續追蹤。');
        return;
    }

    purchaseCancellationInProgress.add(actionKey);
    if (document.getElementById('purchasing-system')?.classList.contains('active')) renderPurchasingView();
    let supplyStopped=false;
    try {
        const result = await cancelOutstandingSupplyRecord(
            supply.purchaseDocumentId || supply.internalNo || supply.id,
            supply.id,
            reason,{actorUid,actorRole,onStockCommitted:invalidateWarehouseStockCache,onDemandChanged:invalidateProcurementDemandQueue}
        );
        supplyStopped=true;
        purchaseHistorySupplyCache.set(supply.id, {...supply, status:result.terminalStatus,
            incomingRegisteredQty:0, ...(result.terminalStatus === 'CLOSED' ? {closedQty:result.cancelledQty} : {cancelledQty:result.cancelledQty})});
        supplyReceivingCache = supplyReceivingCache.filter(row => row.id !== supply.id);
        try {
            await loadActiveReceivingSupplyCache(true);
            if (result.orderId) await refreshAffectedOrderCaches([result.orderId]);
        } catch (refreshError) {
            markMainPageDirty('orders.po');
            showActionFeedback('取消已完成，但清單更新失敗；請重新開啟採購頁確認。', 'warning');
            console.warn('取消後更新清單失敗', refreshError);
        }
        if (document.getElementById('purchasing-system')?.classList.contains('active')) renderPurchasingView();
        showActionFeedback(
            `${result.terminalStatus==='CLOSED'?'已結案':'已取消'}採購品項 ${supply.itemCode || supply.itemName || supply.id}；取消未到貨數量 ${result.cancelledQty || remaining}，在途庫存已同步。`,
            'success'
        );
    } catch (err) {
        console.error('取消採購品項未到貨失敗：', err);
        alert(supplyStopped||err?.supplyCommitted?'取消已完成，但畫面更新失敗；請重新開啟採購頁確認：'+(err?.message||err)
            :'取消採購品項失敗：' + (err?.message || err) + '。可以重新執行；已成功的異動不會重複扣除。');
    } finally {
        purchaseCancellationInProgress.delete(actionKey);
        if (document.getElementById('purchasing-system')?.classList.contains('active')) renderPurchasingView();
        if (document.getElementById('inventory-system')?.classList.contains('active') && inventoryReceivingVisible) renderPurchasingReceivingWorkList(null, null, null, null, true);
    }
};

window.cancelPurchaseOrderOutstanding = async function(poId) {
    if(!canCreatePurchaseOrderCapability()){alert('只有管理員或採購可以停止採購單未到貨數量。');return;}
    if(purchaseCancellationInProgress.has(poId))return;
    const actorUid=currentUser?.uid,actorRole=currentUserRole;
    const cached=poListCache.find(po=>po.id===poId)||poHistorySearchResults.find(po=>po.id===poId);
    let po=cached;
    try{
        const fresh=await firestoreReadWithTimeout(db.collection('purchaseOrders').doc(poId).get(),'讀取採購單取消狀態');
        if(!fresh.exists)throw new Error('找不到這張採購單。');
        po={id:fresh.id,...fresh.data()};
    }catch(err){
        alert('無法讀取採購單：'+(err?.message||err));
        return;
    }
    if(isPurchaseTerminalStatus(po.status)){
        const label=String(po.status||'').toUpperCase()==='CLOSED'?'已結案':'已取消';
        showActionFeedback(`這張採購單${label}，沒有待處理的未到貨數量。`,'success');
        return;
    }
    const reasonRaw=prompt(`停止採購單 ${po.poNo||po.id} 尚未到貨的數量。\n已實際到貨的數量不會回沖；若已有到貨紀錄，採購單會標示為「已結案」，完全未到貨才標示為「已取消」。\n原訂單會重新出現尚需採購的數量。\n\n請輸入原因：`);
    if(reasonRaw===null)return;
    const reason=String(reasonRaw||'').trim();
    if(!reason){alert('請填寫取消原因，方便後續追蹤。');return;}
    const supplyIds=Array.isArray(po.supplyOrderIds)?po.supplyOrderIds.filter(Boolean):[];
    if(!supplyIds.length){alert('這張採購單沒有可追蹤的供應紀錄，無法安全取消。');return;}

    purchaseCancellationInProgress.add(poId);
    let stopCommitted=false;
    try{
        const {patch,cancelledQty,supplyIds:committedSupplyIds,affectedOrderIds}=await stopPurchaseOrderOutstanding(poId,reason,{actorUid,actorRole,onStockCommitted:invalidateWarehouseStockCache,onDemandChanged:invalidateProcurementDemandQueue});
        if(!patch){alert('這張採購單目前沒有尚未到貨的數量可取消。');return;}
        stopCommitted=true;
        const documentStatus=patch.status;
        const applyPatch=row=>row?.id===poId?Object.assign(row,patch):row;
        poListCache.forEach(applyPatch);
        poHistorySearchResults.forEach(applyPatch);
        supplyReceivingCache=supplyReceivingCache.filter(row=>!committedSupplyIds.includes(row.id));
        try{
            if(affectedOrderIds.length)await refreshAffectedOrderCaches(affectedOrderIds);
        }catch(refreshError){
            markMainPageDirty('orders.po');
            console.warn('停止採購後更新清單失敗',refreshError);
            showActionFeedback('停止採購已完成，但清單更新失敗；請重新開啟採購頁確認。','warning');
        }
        writeAppDataCache('purchase-history',poListCache);
        if(document.getElementById('purchasing-system')?.classList.contains('active'))renderPurchasingView();
        else renderPoList();
        showActionFeedback(`${documentStatus==='CLOSED'?'已結案':'已取消'} ${po.poNo||poId}；停止未到貨數量 ${cancelledQty}，在途庫存與來源訂單待採購量已同步。`,'success');
    }catch(err){
        console.error('停止採購單未到貨失敗：',err);
        alert(stopCommitted?'停止採購已完成，但畫面更新失敗；請重新開啟採購頁確認：'+(err?.message||err)
            :'停止未完全完成：'+(err?.message||err)+'。可以再次執行同一動作；已完成的供應紀錄不會重複扣除。');
    }finally{
        purchaseCancellationInProgress.delete(poId);
    }
};

// Document preparation writes only the versioned PO snapshot, never supply/demand/stock.
function formalPurchaseDocumentIntent(record) {
    const ignored = new Set(['id','createdAt','updatedAt','lastOutputAt','lastOutputType','supplyOrderIds',
        'status','documentOnly','documentRevision','confirmedAt','confirmedByUid']);
    const canonical = value => Array.isArray(value) ? value.map(canonical) : value && typeof value === 'object'
        ? Object.fromEntries(Object.keys(value).sort().map(key => [key, canonical(value[key])])) : value;
    return JSON.stringify(canonical(Object.fromEntries(Object.entries(record).filter(([key]) => !ignored.has(key)))));
}
async function saveFormalPurchaseDocument(record, {actorUid=currentUser?.uid,actorRole=currentUserRole,expectedRevision=0}={}) {
    const check = () => {
        if (!actorUid || actorUid!==currentUser?.uid || actorRole!==currentUserRole
            || !canCreatePurchaseOrderCapability() || !canAccessPage('orders.po'))
            throw Error('登入身分或採購權限已變更。');
    };
    check();
    record=JSON.parse(JSON.stringify(record));
    if (!record?.poNo || record.poNo.includes('/') || !record.vendorName?.trim()
        || !Array.isArray(record.items) || !record.items.length
        || record.items.some(item=>!Number.isFinite(Number(item.qty)) || Number(item.qty)<=0
            || item.unitPrice===null || item.unitPrice==='' || !Number.isFinite(Number(item.unitPrice)) || Number(item.unitPrice)<0))
        throw Error('採購文件的單號、供應商、數量或價格不完整。');
    delete record.id; delete record.supplyOrderIds;
    record={...record,status:'DRAFT',documentOnly:true,documentRevision:1,createdByUid:actorUid,createdByRole:actorRole};
    let saved;
    await runRoleTransaction(async tx=>{
        check();
        const ref=db.collection('purchaseOrders').doc(record.poNo),snapshot=await tx.get(ref);
        check();
        if (snapshot.exists) {
            saved=snapshot.data();
            if(saved.status!=='DRAFT' || saved.documentOnly!==true)
                throw Error('這個單號已確認採購，請開啟原單核對。');
            record.createdByUid=saved.createdByUid;record.createdByRole=saved.createdByRole;
            if(formalPurchaseDocumentIntent(saved)===formalPurchaseDocumentIntent(record))return;
            if(!Number.isSafeInteger(expectedRevision) || expectedRevision<1
                || expectedRevision!==(saved.documentRevision||1))
                throw Error('這個單號已有不同內容，請重新載入原文件後再編輯。');
            saved={...record,createdAt:saved.createdAt,documentRevision:expectedRevision+1,updatedAt:new Date().toISOString()};
            tx.set(ref,saved);return;
        }
        saved=record;tx.set(ref,record);
    });
    check();return {id:saved.poNo,...saved};
}
// Authoritative PO, supply commitments and source-order linkage. Incoming remains a separate checkpoint.
async function commitFormalPurchaseEmulator(poRecord,actorUid,assertActor) {
    const local=host=>['localhost','127.0.0.1'].includes(host);
    if(typeof APP_ENVIRONMENT==='undefined'||APP_ENVIRONMENT!=='emulator'
        ||!local(globalThis.location?.hostname)||typeof firebase==='undefined'||!firebase.functions)
        throw new Error('採購後端試點僅限明確啟用的本機 Emulator。');
    const auth=firebase.auth(),functions=firebase.app().functions('asia-east1');
    if(auth.app?.options?.projectId!=='demo-yushin'||functions.app?.options?.projectId!=='demo-yushin'
        ||!local(auth.emulatorConfig?.host)||auth.emulatorConfig?.port!==9099)
        throw new Error('採購必須使用 demo-yushin 本機登入與 Functions Emulator。');
    const check=()=>{assertActor();if(auth.currentUser?.uid!==actorUid)throw new Error('實際登入身分已變更，請以原帳號核對採購結果。');};
    check();
    if(poRecord.items.length>5||poRecord.items.some(item=>!item.orderId||!item.itemId
        ||(item.sourceType&&item.sourceType!=='SALES_ORDER')
        ||!['WAREHOUSE','DIRECT_SHIP'].includes(item.fulfillmentType||'WAREHOUSE')))
        throw new Error('採購後端試點目前只支援 1–5 個客戶訂單實體入庫或直送品項。');
    const request={poNo:poRecord.poNo,poDate:poRecord.poDate,
        supplier:poRecord.supplierName||poRecord.vendorName,
        items:poRecord.items.map(item=>({orderId:item.orderId,itemId:item.itemId,
            qty:Number(item.qty),unitCost:Number(item.unitPrice)})),
        document:{company:poRecord.company,supplierSnapshot:poRecord.supplierSnapshot,
            expectedDate:poRecord.expectedDate||'',expectedDateSource:poRecord.expectedDateSource||'',
            lineScheduleDates:poRecord.items.map(item=>item.scheduleDate||'')}};
    if(poRecord.documentRevision)request.documentRevision=poRecord.documentRevision;
    functions.useEmulator('127.0.0.1',5001);
    // A failed/unknown Callable never falls through to the old client writer.
    const reply=await functions.httpsCallable('commitV2FormalPurchase')(request);check();
    const result=reply?.data,ids=request.items.map((_,index)=>formalSupplyOrderId(request.poNo,index));
    if(!['committed','already-applied'].includes(result?.status)||result.poNo!==request.poNo
        ||JSON.stringify(result.supplyOrderIds)!==JSON.stringify(ids))
        throw new Error('採購回覆不明確，請保留原單號核對，勿另建新單。');
    const read=async(name,id)=>{
        const snapshot=await db.collection(name).doc(id).get({source:'server'});check();
        if(!snapshot.exists)throw new Error('採購可能已提交，但回讀資料不完整，請保留原單號核對。');
        return {id,...snapshot.data()};
    };
    const saved=await read('purchaseOrders',request.poNo);
    const committedSourceOrders=[];for(const id of [...new Set(request.items.map(item=>item.orderId))])committedSourceOrders.push(await read('orders',id));
    const committedSupplyOrders=[];for(const id of ids)committedSupplyOrders.push(await read('supplyOrders',id));
    check();return {poRecord:saved,committedSourceOrders,committedSupplyOrders};
}
async function commitFormalPurchaseOrder(poRecord, {actorUid=currentUser?.uid,actorRole=currentUserRole}={}) {
        // Validate numbers before JSON snapshotting: JSON turns NaN/Infinity into null.
        if(poRecord && Array.isArray(poRecord.items) && poRecord.items.some(item=>
            ['demandRequestedQty','demandOrderedQty','demandReceivedQty'].some(key=>
                item[key]!==undefined && item[key]!==null
                && (!Number.isFinite(Number(item[key])) || Number(item[key])<0))))
            throw new Error('採購需求數量不正確。');
        poRecord=JSON.parse(JSON.stringify(poRecord));
        if (!poRecord || typeof poRecord.poNo!=='string' || !poRecord.poNo.trim() || poRecord.poNo.includes('/')
            || !String(poRecord.vendorName||'').trim() || !Array.isArray(poRecord.items) || !poRecord.items.length)
            throw new Error('採購單號、供應商或品項不完整。');
        for (const item of poRecord.items) {
            if (!Number.isFinite(Number(item.qty)) || Number(item.qty)<=0
                || item.unitPrice===null || item.unitPrice===undefined || item.unitPrice===''
                || !Number.isFinite(Number(item.unitPrice)) || Number(item.unitPrice)<0)
                throw new Error('請填寫有效採購數量與單價（可填 0）。');
        }
        const assertActor=()=>{
            if (!actorUid || currentUser?.uid!==actorUid || currentUserRole!==actorRole)
                throw new Error('登入身份已變更，請以原帳號重新確認採購單。');
            if (!canCreatePurchaseOrderCapability() || !canAccessPage('orders.po')) throw new Error('目前無採購作業權限。');
        };
        assertActor();
        if(globalThis.YUSHIN_FORMAL_PURCHASE_EMULATOR===true)
            return commitFormalPurchaseEmulator(poRecord,actorUid,assertActor);
        const actorName=currentUserName||currentUser?.email||'', now=poRecord.createdAt||new Date().toISOString();
        const poNo=poRecord.poNo, vendorName=poRecord.vendorName, poDocumentId=poNo;
        const orderIds=[...new Set(poRecord.items.map(item=>item.orderId).filter(Boolean))];
        let committedSourceOrders = [];
        let committedSupplyOrders = [];
        await runRoleTransaction(async transaction => {
            assertActor();
            committedSourceOrders = [];
            committedSupplyOrders = [];
            const plannedDemands=new Map();
            const demandWrites=new Map();
            const poRef = db.collection('purchaseOrders').doc(poDocumentId);
            const orderRefs = orderIds.map(orderId => db.collection('orders').doc(orderId));
            const poSnapshot = await transaction.get(poRef);
            const orderSnapshots = await Promise.all(orderRefs.map(ref => transaction.get(ref)));
            assertActor();
            if (poSnapshot.exists && poSnapshot.data().status==='DRAFT' && poSnapshot.data().documentOnly===true) {
                const draft=poSnapshot.data();
                if (formalPurchaseDocumentIntent(draft)!==formalPurchaseDocumentIntent(poRecord))
                    throw Error('採購文件與確認內容不同，請重新開啟原單。');
                poRecord={...poRecord,status:'ORDERED',documentOnly:false,
                    confirmedAt:now,confirmedByUid:actorUid};
            } else if (poSnapshot.exists) {
                const saved=poSnapshot.data();
                const ignored=new Set(['id','createdAt','updatedAt','lastOutputAt','lastOutputType','supplyOrderIds','status','documentOnly','confirmedAt','confirmedByUid']);
                const intent=record=>Object.fromEntries(Object.keys(poRecord).filter(key=>!ignored.has(key)).map(key=>[key,record[key]]));
                const canonical=value=>Array.isArray(value)?value.map(canonical):value&&typeof value==='object'
                    ?Object.fromEntries(Object.keys(value).sort().map(key=>[key,canonical(value[key])])):value;
                if (JSON.stringify(canonical(intent(saved)))!==JSON.stringify(canonical(intent(poRecord))))
                    throw new Error(`採購單號 ${poNo} 已存在且內容不同，請先核對原單。`);
                const ids=poRecord.items.map((_,index)=>formalSupplyOrderId(poDocumentId,index));
                if (JSON.stringify(saved.supplyOrderIds)!==JSON.stringify(ids)) throw new Error('既有採購單供應連結不完整，請先核對原單。');
                const supplies=await Promise.all(ids.map(id=>transaction.get(supplyOrdersCollection().doc(id))));
                assertActor();
                supplies.forEach((snapshot,index)=>{
                    const data=snapshot.exists?snapshot.data():null;
                    const item=poRecord.items[index];
                    if (!data || data.purchaseDocumentId!==poDocumentId || data.createdByUid!==actorUid || data.type!=='PURCHASING_PO'
                        || Number(data.qty)!==Number(item.qty) || Number(data.unitCost)!==Number(item.unitPrice)
                        || data.productKey!==poIncomingKey(item) || data.supplier!==(poRecord.supplierName||vendorName)
                        || data.sourceId!==(item.orderId||item.sourceId||('MANUAL_PO:'+poDocumentId+':'+index)) || data.sourceItemId!==(item.itemId||item.sourceItemId||''))
                        throw new Error('既有採購供應紀錄與本次作業不符，請先核對原單。');
                    committedSupplyOrders.push({id:ids[index],...data});
                });
                committedSourceOrders=orderSnapshots.filter(snapshot=>snapshot.exists).map(snapshot=>({id:snapshot.id,...snapshot.data()}));
                poRecord=saved;
                return;
            }
            orderSnapshots.forEach((snapshot, index) => {
                if (!snapshot.exists) throw new Error('來源訂單已不存在。');
                assertPurchaseLinesAvailable(snapshot.data(), poRecord.items.filter(item => item.orderId === orderIds[index]));
            });
            // Stock POs do not necessarily update a source sales order. Lock each
            // deterministic demand document inside this transaction before writing
            // any supply or PO records; competing POs will then conflict/retry.
            // Independent direct-stock purchases get their own per-PO demand ID.
            const stockDemands=new Map();
            const stockDemandInputs=new Map();
            poRecord.items.forEach((item,index)=>{
                const sourceType=item.sourceType||(item.orderId?'SALES_ORDER':'STOCK_REPLENISHMENT');
                if(!['SALES_ORDER','STOCK_REPLENISHMENT'].includes(sourceType))
                    throw new Error('採購需求來源類型不正確。');
                if(sourceType!=='STOCK_REPLENISHMENT')return;
                const sourceId=String(item.sourceId||'').trim()||('MANUAL_PO:'+poDocumentId+':'+index);
                const demandId=globalThis.YushinProcurementDemand.demandIdForSource({sourceType,sourceId});
                if(item.demandId&&item.demandId!==demandId)throw new Error('採購需求識別與品項來源不符，請重新開啟採購單。');
                if(!poIncomingKey(item))throw new Error('庫存採購缺少有效產品識別。');
                if([...stockDemandInputs.values()].some(row=>row.demandId===demandId))
                    throw new Error('同一補貨需求請合併為單一採購列，避免重複承諾。');
                stockDemandInputs.set(index,{sourceId,demandId});
            });
            await Promise.all([...stockDemandInputs.values()].map(async ({demandId})=>{
                const ref=procurementDemandRef(demandId);
                if(!ref)throw new Error('採購需求文件識別不正確。');
                const snap=await transaction.get(ref);
                stockDemands.set(demandId,{ref,data:snap.exists?snap.data():null});
            }));
            assertActor();
            const supplyOrderIds = [];
            poRecord.items.forEach((item,itemIndex)=>{
                const sourceType=item.sourceType||(item.orderId?'SALES_ORDER':'STOCK_REPLENISHMENT');
                let demandProjection;
                let sourceOrderForDemand=null;
                let sourceItemForDemand=null;
                if(sourceType==='SALES_ORDER'){
                    const sourceSnapshot=orderSnapshots.find(snapshot=>snapshot.id===item.orderId);
                    if(!sourceSnapshot?.exists)throw new Error('採購需求找不到來源訂單。');
                    sourceOrderForDemand={id:sourceSnapshot.id,...sourceSnapshot.data()};
                    const sourceItems=normalizedOrderItems(sourceOrderForDemand);
                    sourceItemForDemand=sourceItems.find(row=>row.itemId===item.itemId)
                        || sourceItems[Number(item.orderItemIndex||0)];
                    if(!sourceItemForDemand)throw new Error('採購需求找不到來源訂單品項。');
                    demandProjection=procurementDemandForOrderItem(sourceOrderForDemand,sourceItemForDemand);
                }else{
                    const input=stockDemandInputs.get(itemIndex);
                    const snapshot=stockDemands.get(input.demandId)?.data;
                    const requestedQty=Number(item.demandRequestedQty??item.qty??0);
                    const orderedQty=Number(item.demandOrderedQty||0);
                    const receivedQty=Number(item.demandReceivedQty||0);
                    if(![requestedQty,orderedQty,receivedQty].every(value=>Number.isFinite(value)&&value>=0))
                        throw new Error('庫存補貨需求數量不正確。');
                    if(snapshot){
                        if(snapshot.demandId!==input.demandId||snapshot.sourceType!==sourceType
                            ||snapshot.sourceId!==input.sourceId||snapshot.sourceItemId!==''
                            ||snapshot.productKey!==poIncomingKey(item))
                            throw new Error('既有庫存補貨需求識別與品項不一致，請先核對紀錄。');
                        if(snapshot.status==='CANCELLED')throw new Error('此補貨需求已取消，請先恢復後再建立採購單。');
                        if(![snapshot.requestedQty,snapshot.orderedQty,snapshot.receivedQty].every(value=>typeof value==='number'&&Number.isFinite(value)&&value>=0)
                            ||snapshot.orderedQty>snapshot.requestedQty||snapshot.receivedQty>snapshot.orderedQty)
                            throw new Error('既有補貨需求數量不一致，請先核對供應紀錄。');
                    }
                    // Persisted commitments win over stale modal values. A previously
                    // stored demand cannot silently grow from an old browser snapshot.
                    // Independent/manual POs use unique IDs and start from zero.
                    demandProjection=globalThis.YushinProcurementDemand.normalizeDemand({
                        demandId:input.demandId,sourceType,sourceId:input.sourceId,sourceItemId:'',
                        requestedQty:snapshot?Math.max(snapshot.orderedQty,Math.min(snapshot.requestedQty,requestedQty)):requestedQty,
                        orderedQty:snapshot?snapshot.orderedQty:orderedQty,
                        receivedQty:snapshot?snapshot.receivedQty:receivedQty,
                        scheduleDate:snapshot?.scheduleDate||String(item.demandScheduleDate||item.requiredByDate||'').trim()
                    });
                }
                if (plannedDemands.has(demandProjection.demandId)) {
                    if (sourceType!=='SALES_ORDER') throw new Error('同一補貨需求請合併為單一採購列，避免重複承諾。');
                    demandProjection=plannedDemands.get(demandProjection.demandId);
                }
                const demandOrderPlan=globalThis.YushinProcurementDemand.applyOrder(demandProjection,Number(item.qty||0));
                if(demandOrderPlan.appliedQty!==Number(item.qty||0)){
                    throw new Error('採購需求數量已變更，請重新整理後再建立採購單。');
                }
                plannedDemands.set(demandProjection.demandId,demandOrderPlan.demand);
                const demandRef=sourceType==='STOCK_REPLENISHMENT'
                    ?stockDemands.get(demandProjection.demandId)?.ref
                    :procurementDemandRef(demandProjection.demandId);
                const demandDoc=procurementDemandDocument(demandOrderPlan.demand,{
                    productId:item.productId||sourceItemForDemand?.productId||'',
                    productKey:poIncomingKey(item)||inventoryProductKey(sourceItemForDemand||{}),
                    itemCode:item.itemCode||sourceItemForDemand?.itemCode||'',
                    itemName:item.itemName||sourceItemForDemand?.itemName||'',
                    brand:resolveBrandName(item.brand||sourceItemForDemand?.brand||''),
                    fulfillmentType:item.fulfillmentType||sourceItemForDemand?.fulfillmentType||'WAREHOUSE',
                    warehouseId:(item.fulfillmentType||sourceItemForDemand?.fulfillmentType||'WAREHOUSE')==='DIRECT_SHIP'
                        ? '' : (item.warehouseId||sourceItemForDemand?.warehouseId||defaultWarehouse()?.id||''),
                    ownerUid:item.ownerUid||sourceOrderForDemand?.ownerUid||'',
                    salesCode:item.salesCode||sourceOrderForDemand?.salesCode||'',
                    salesName:item.salesName||sourceOrderForDemand?.salesName||'',
                    // Preserve Material Request required-by timing. Do not overwrite it
                    // with this PO line's vendor delivery estimate.
                    scheduleDate:demandProjection.scheduleDate
                        ||sourceItemForDemand?.requiredByDate
                        ||sourceItemForDemand?.scheduleDate
                        ||sourceOrderForDemand?.requiredByDate
                        ||sourceOrderForDemand?.expectedDate
                        ||''
                },{
                    createdAt:sourceOrderForDemand?.createdAt||poRecord.createdAt,
                    updatedAt:poRecord.createdAt
                });

                const supplyId=formalSupplyOrderId(poDocumentId,itemIndex);
                const supplyRef=supplyOrdersCollection().doc(supplyId);
                supplyOrderIds.push(supplyId);
                const supplyRecord={
                    // ERPNext-style：採購方式與需求來源分開。
                    // 正式採購單永遠是 PURCHASING_PO；是否為客戶需求或備庫由 sourceType 表示。
                    type:'PURCHASING_PO',
                    method:'PURCHASING_PO',
                    sourceType,
                    sourceId:sourceType==='STOCK_REPLENISHMENT'?demandProjection.sourceId:(item.orderId||item.sourceId||''),
                    sourceItemId:item.itemId||item.sourceItemId||'',
                    demandId:demandProjection.demandId||'',
                    internalNo:poNo,
                    purchaseDocumentId:poDocumentId,
                    purchaseDocumentNo:poNo,
                    status:'ORDERED',
                    orderId:item.orderId||'',
                    itemId:item.itemId||'',
                    orderItemIndex:Number(item.orderItemIndex||0),
                    ownerUid:item.ownerUid||'',
                    salesCode:item.salesCode||'',
                    salesName:item.salesName||'',
                    productId:item.productId||'',
                    productKey:poIncomingKey(item),
                    itemCode:item.itemCode||'',
                    itemName:item.itemName||'',
                    brand:resolveBrandName(item.brand||''),
                    brandId:item.brandId||brandIdForName(item.brand||''),
                    qty:Number(item.qty||0),
                    receivedQty:0,
                    incomingRegisteredQty:0,
                    supplier:poRecord.supplierName||vendorName,
                    supplierId:poRecord.supplierId||'',
                    supplierEmail:poRecord.supplierEmail||'',
                    unitCost:Number(item.unitPrice||0),
                    orderDate:poRecord.poDate,
                    expectedDate:item.scheduleDate||poRecord.expectedDate||'',
                    scheduleDate:item.scheduleDate||poRecord.scheduleDate||poRecord.expectedDate||'',
                    fulfillmentType:item.fulfillmentType||'WAREHOUSE',
                    warehouseId:(item.fulfillmentType||'WAREHOUSE')==='DIRECT_SHIP'?'':(item.warehouseId||defaultWarehouse()?.id||''),
                    createdAt:poRecord.createdAt,
                    updatedAt:poRecord.createdAt,
                    createdByUid:actorUid,
                    createdBy:actorName,
                    createdByRole:actorRole
                };
                transaction.set(supplyRef,supplyRecord);
                if(demandRef)demandWrites.set(demandProjection.demandId,{ref:demandRef,doc:demandDoc});
                committedSupplyOrders.push({id:supplyId,...supplyRecord});
            });
            poRecord.supplyOrderIds=supplyOrderIds;
            demandWrites.forEach(({ref,doc})=>transaction.set(ref,doc,{merge:true}));
            transaction.set(poRef, poRecord);
            orderSnapshots.forEach((snapshot, index) => {
                if (snapshot.exists) {
                    const orderData = snapshot.data();
                    const orderedLines=poRecord.items.filter(item=>item.orderId===snapshot.id);
                    const nextItems=normalizedOrderItems(orderData).map((item,itemIndex)=>{
                        const matches=orderedLines.filter(line=>Number(line.orderItemIndex)===itemIndex);
                        const orderedQty=matches.reduce((sum,line)=>sum+Number(line.qty||0),0);
                        const currentSupplyOrdered=Math.max(0,Number(item.supplyOrderedQty||0));
                        const cumulative=currentSupplyOrdered+orderedQty;
                        const identityLine=matches.find(line=>line.itemId&&item.itemId&&line.itemId===item.itemId)||matches[0];
                        return orderedQty>0?{
                            ...item,
                            // 採購單可補齊來源訂單原本缺少的產品識別資料；已有值不覆蓋，
                            // 避免「來源貨號空白 → 採購頁可填 → 儲存又被擋住」的死路流程。
                            productId:item.productId||identityLine?.productId||'',
                            itemCode:item.itemCode||identityLine?.itemCode||'',
                            itemName:item.itemName||identityLine?.itemName||'',
                            brand:item.brand||resolveBrandName(identityLine?.brand||''),
                            brandId:item.brandId||identityLine?.brandId||brandIdForName(item.brand||identityLine?.brand||''),
                            productLine:item.productLine||identityLine?.productLine||'',
                            supplyOrderedQty:cumulative,
                            purchaseDocumentNos:[...new Set([...(item.purchaseDocumentNos||[]),poNo])],
                            orderedAt:item.orderedAt && item.orderedAt < poRecord.poDate ? item.orderedAt : poRecord.poDate,
                            orderEvents:[
                                ...(item.orderEvents||[]).filter(event=>event.id!==poDocumentId),
                                {id:poDocumentId,type:'PURCHASING_PO',at:now,date:poRecord.poDate||'',qty:orderedQty,documentNo:poNo,by:poRecord.buyerName||actorName}
                            ]
                        }:item;
                    });
                    const nextOrderData={...orderData,items:nextItems,itemCount:nextItems.length,orderSchemaVersion:2};
                    const orderUpdates = {
                        items:nextItems,itemCount:nextItems.length,orderSchemaVersion:2,
                        ...orderWorkIndexFields(nextOrderData),
                        linkedDocuments: normalizeDocumentLinks([...(orderData.linkedDocuments || []), documentLink(DOCUMENT_TYPES.PURCHASE_ORDER, poDocumentId, 'document')])
                    };
                    transaction.update(orderRefs[index], orderUpdates);
                    committedSourceOrders.push({id:snapshot.id,...orderData,...orderUpdates});
                }
            });
        });

        return {poRecord,committedSourceOrders,committedSupplyOrders};
}
// Formal purchase service end.
// Transport only. All receipt quantities and writes remain in the same receiving Service.
async function receiveV2SupplyEmulator(supplyId,qty,lotNo,expiryDate,operationId,options) {
    const local=host=>['localhost','127.0.0.1'].includes(host);
    if(typeof APP_ENVIRONMENT==='undefined'||APP_ENVIRONMENT!=='emulator'
        ||!local(globalThis.location?.hostname)||typeof firebase==='undefined'||!firebase.functions)
        throw Error('多倉收貨後端僅限本機 Emulator。');
    const auth=firebase.auth(),functions=firebase.app().functions('asia-east1');
    if(auth.app?.options?.projectId!=='demo-yushin'||functions.app?.options?.projectId!=='demo-yushin'
        ||!local(auth.emulatorConfig?.host)||auth.emulatorConfig?.port!==9099)
        throw Error('多倉收貨必須使用 demo-yushin 本機登入與 Functions。');
    const uid=options.actorUid??currentUser?.uid,role=options.actorRole??currentUserRole;
    const check=()=>{
        if(!uid||auth.currentUser?.uid!==uid||currentUser?.uid!==uid||currentUserRole!==role
            ||!(['admin','purchaser','warehouse'].includes(role)&&canReceiveInventoryCapability()
                 ||['sales','engineer'].includes(role)))
            throw Error('收貨身分已變更，請以原帳號核對。');
    };
    check();
    const jobs=JSON.parse(sessionStorage.getItem('yushin-receipt-tasks:'+uid)||'[]');
    const job=Array.isArray(jobs)&&jobs.find(job=>job.ownerUid===uid&&job.actorRole===role&&job.supplyId===supplyId
        &&job.entries?.some(entry=>`${job.operationBase}-${entry.itemIndex}`===operationId&&entry.qty===qty&&entry.lotNo===lotNo&&entry.expiryDate===expiryDate));
    if(!job)throw Error('收貨原始作業尚未安全保存，請保留原資料並重新確認。');
    functions.useEmulator('127.0.0.1',5001);
    const response=await functions.httpsCallable('receiveV2Supply')({supplyId,qty,lotNo,expiryDate,operationId});check();
    const result=response?.data;
    if(result?.status!=='confirmed'||result.supplyId!==supplyId||result.operationId!==operationId
        ||!Array.isArray(result.affectedOrderIds)||result.affectedOrderIds.some(id=>typeof id!=='string'||!id))
        throw Error('收貨回覆不明確，請使用原資料重試。');
    const receipt=await db.collection('receipts').doc(operationId).get({source:'server'});check();
    const proof=receipt.exists?receipt.data():null;
    // Direct receipts deliberately omit warehouse lot/expiry fields. Match that
    // schema without weakening exact batch checks for physical warehouse receipts.
    const direct=proof?.fulfillmentType==='DIRECT_SHIP';
    const empty=value=>value===undefined||value==='';
    const batchMatches=direct
        ? lotNo===''&&expiryDate===''&&empty(proof.lotNo)&&empty(proof.expiryDate)&&proof.warehouseId===''
        : proof?.lotNo===lotNo&&proof?.expiryDate===expiryDate;
    if(!proof||proof.supplyOrderId!==supplyId||proof.qty!==qty||!batchMatches
        ||proof.createdByUid!==uid||proof.createdByRole!==role
        ||(!direct&&proof.reservationLocationSchemaVersion!==2))
        throw Error('收貨已可能提交，但憑證尚未確認，請使用原資料重試。');
    if(proof.fulfillmentType!=='DIRECT_SHIP')
        options.onStockCommitted?.(proof.productKey,proof.warehouseId);
    check();return result.affectedOrderIds;
}
// Transaction layer only. Optional synchronous observers report committed locations;
// callers own cache invalidation and presentation. Never notify from a transaction callback.
async function allocateFreeReceiptStockToShortages(productKey,warehouseId,maxQty,actor,excludeOrderId='',receiptId='',checkpointCollection='receipts',allocationGuard=null,onStockCommitted=null) {
    allocationGuard?.();
    if(!['receipts','stockTransfers'].includes(checkpointCollection))throw new Error('庫存分配進度來源不正確。');
    let remaining=Math.max(0,Number(maxQty||0)),allocatedQty=0;
    const affectedOrderIds = new Set();
    const skippedCandidateIds = new Set();
    let completionReason='exhausted';
    if(!remaining||!productKey||!warehouseId)return {allocatedQty:0,unallocatedQty:remaining,affectedOrderIds:[]};
    const compare=globalThis.YushinReservation?.compareReservationPriority;
    if(!compare)throw new Error('庫存分配核心未載入，請重新載入後重試分配。');
    // Allocate one live shortage at a time. Re-reading candidates after every successful
    // transaction preserves oldest-first ordering even when multiple receipts run concurrently.
    // 已失效／取消的最舊候選只跳過，不可阻塞後面的正常缺貨訂單。
    while(remaining>0){
        allocationGuard?.();
        const oldestCandidate=async status=>{
            let candidate=null,cursor=null;
            while(true){
                let q=db.collection('inventoryReservations').where('productKey','==',productKey).where('status','==',status).limit(50);
                if(cursor)q=q.startAfter(cursor);
                const page=await firestoreReadWithTimeout(q.get(),'庫存預留候選');
                allocationGuard?.();
                for(const doc of page.docs){
                    const row={...doc.data(),id:doc.id};
                    if(row.orderId===excludeOrderId||row.warehouseId!==warehouseId||!(Number(row.shortageQty||0)>0)||skippedCandidateIds.has(row.id))continue;
                    if(!candidate||compare(row,candidate)<0)candidate=row;
                }
                if(page.size<50)break;
                const last=page.docs[page.docs.length-1];
                if(!last||last.id===cursor?.id)throw new Error('庫存預留分頁未前進，請重新載入後重試分配。');
                cursor=last;
            }
            return candidate;
        };
        const candidates=await Promise.all([oldestCandidate('shortage'),oldestCandidate('active')]);
        allocationGuard?.();
        const candidate=candidates.filter(Boolean).sort(compare)[0];
        if(!candidate){completionReason='no-demand';break;}
        let took=0,skipCandidate=false,stopAllocation=false;
        const allocationTime=new Date().toISOString();
        const movementRef=db.collection('inventoryMovements').doc();
        await runRoleTransaction(async tx=>{
            took=0;skipCandidate=false;stopAllocation=false;
            allocationGuard?.();
            const orderRef=db.collection('orders').doc(candidate.orderId);
            const reservationRef=db.collection('inventoryReservations').doc(candidate.id);
            const invRef=db.collection('inventory').doc(encodeURIComponent(productKey));
            const whRef=db.collection('warehouseStocks').doc(warehouseStockDocId(warehouseId,productKey));
            const receiptRef=receiptId?db.collection(checkpointCollection).doc(receiptId):null;
            const demandId=globalThis.YushinProcurementDemand.demandIdForSource({sourceType:'SALES_ORDER',sourceId:candidate.orderId,sourceItemId:candidate.itemId});
            const demandRef=procurementDemandRef(demandId);
            const [orderSnap,resSnap,invSnap,whSnap,receiptSnap]=await Promise.all([
                tx.get(orderRef),tx.get(reservationRef),tx.get(invRef),tx.get(whRef),
                receiptRef?tx.get(receiptRef):Promise.resolve(null)
            ]);
            const demandSnap=await tx.get(demandRef);
            allocationGuard?.();
            if(!orderSnap.exists||!resSnap.exists||!whSnap.exists||!invSnap.exists){skipCandidate=true;return;}
            if(receiptRef&&!receiptSnap?.exists){completionReason='deferred';stopAllocation=true;return;}
            const reservation=resSnap.data();
            if(reservation.productKey!==productKey||reservation.warehouseId!==warehouseId){skipCandidate=true;return;}
            const liveShortage=Math.max(0,Number(reservation.shortageQty||0));
            const order={id:orderSnap.id,...orderSnap.data()};
            if(normalizedOrderStatus(order)!=='normal'||orderInventorySyncIncomplete(order)||liveShortage<=0){skipCandidate=true;return;}
            const receipt=receiptSnap?.exists?(receiptSnap.data()||{}):null;
            const receiptTarget=receiptRef?Math.max(0,Number(receipt?.autoAllocationQty||0)):remaining;
            const receiptAllocated=receiptRef?Math.max(0,Number(receipt?.autoAllocatedQty||0)):0;
            const receiptRemaining=receiptRef?Math.max(0,receiptTarget-receiptAllocated):remaining;
            const items=normalizedOrderItems(order);
            const index=items.findIndex(item=>item.itemId===reservation.itemId);
            if(index<0){skipCandidate=true;return;}
            const item=items[index],oldReserved=Number(item.reservedQty||0);
            if(inventoryProductKey(item)!==productKey||item.warehouseId!==warehouseId||item.transferPendingId||(item.fulfillmentType||'WAREHOUSE')!=='WAREHOUSE'){skipCandidate=true;return;}
            const oldShortage=Math.max(0,Number(item.shortageQty??liveShortage));
            // 已向供應商下訂的缺口不能再占用補貨，否則現貨與待到貨重複涵蓋同一需求。
            if(Math.abs(oldReserved-Number(reservation.quantity||0))>1e-9||Math.abs(oldShortage-liveShortage)>1e-9)throw new Error('訂單與庫存預留數量不一致，請由管理員檢查後重試。');
            const uncovered=remainingProcurementQty(order,item);
            if(uncovered<=0){skipCandidate=true;return;}
            const stockPlan=globalThis.YushinReservation.planReservationReceipt({productKey,warehouseId,
                qty:Math.min(remaining,receiptRemaining),requestedReserveQty:uncovered,addsStock:false,
                reservation,aggregateStock:invSnap.data(),warehouseStock:whSnap.data(),itemReservedQty:order.items[index].reservedQty});
            const take=stockPlan.allocatedQty;
            if(take<=0){completionReason='exhausted';stopAllocation=true;return;}
            items[index]={...item,reservedQty:stockPlan.reservation.quantity,shortageQty:stockPlan.reservation.shortageQty};
            const now=allocationTime;
            const nextOrder={...order,items,updatedAt:now};
            tx.update(orderRef,{items,...orderWorkIndexFields(nextOrder),updatedAt:now});
            const demand=procurementDemandForOrderItem(nextOrder,items[index]);
            tx.set(demandRef,procurementDemandDocument({...(demandSnap.exists?demandSnap.data():{}),...demand},{
                sourceItemIndex:index,productId:item.productId||'',productKey,
                itemCode:item.itemCode||'',itemName:item.itemName||'',brand:item.brand||'',
                fulfillmentType:'WAREHOUSE',warehouseId,ownerUid:order.ownerUid||'',
                salesCode:order.salesCode||'',salesName:order.salesName||''
            },{createdAt:demandSnap.exists?demandSnap.data().createdAt:order.createdAt||now,updatedAt:now}),{merge:true});
            tx.update(reservationRef,{...stockPlan.reservation,updatedAt:now});
            if(invSnap.exists)tx.update(invRef,{reserved:stockPlan.aggregateStock.reserved,updatedAt:now});
            tx.update(whRef,{reserved:stockPlan.warehouseStock.reserved,updatedAt:now});
            if(receiptRef){
                const nextAllocated=receiptAllocated+take;
                tx.update(receiptRef,{
                    autoAllocatedQty:nextAllocated,
                    allocationCompleted:nextAllocated>=receiptTarget,
                    allocationUpdatedAt:now
                });
            }
            tx.set(movementRef,inventoryMovementRecord(allocationGuard&&!receiptId?'reserve_from_free_stock':'reserve_from_receipt',take,candidate.orderId,productKey,actor,{
                warehouseId,itemId:reservation.itemId||'',fulfillmentType:'WAREHOUSE',createdAt:now,
                ownerUid:order.ownerUid||'',salesCode:order.salesCode||'',
                ...(checkpointCollection==='receipts'?{receiptId:receiptId||''}:{transferId:receiptId||''})
            }));
            took=take;
        });
        allocationGuard?.();
        if(took>0){onStockCommitted?.(productKey,warehouseId);allocatedQty+=took;remaining-=took;affectedOrderIds.add(candidate.orderId);continue;}
        if(skipCandidate){
            // 避免同一輪一直選到已取消／失效的舊 reservation；改看下一個候選。
            skippedCandidateIds.add(candidate.id);
            continue;
        }
        if(stopAllocation)break;
        break;
    }
    return {allocatedQty,unallocatedQty:remaining,affectedOrderIds:[...affectedOrderIds],completionReason};
}

// Reuse this receiving Service for the v2 trial; never create another receipt
// writer. The browser path stays closed until its backend/Rules adapters exist.
async function assertV2ReceiptActor(transaction, actorUid, actorRole) {
    if(typeof process==='undefined'||!process.env?.FIRESTORE_EMULATOR_HOST||db.projectId!=='demo-yushin')
        throw new Error('多倉收貨目前僅允許 demo-yushin Emulator，尚未開放正式入口。');
    const actor=await transaction.get(db.collection('users').doc(actorUid));
    if(!actor.exists||actor.data().active===false||actor.data().disabled===true
        ||actor.data().role!==actorRole||!['admin','purchaser','warehouse'].includes(actorRole))
        throw new Error('真實登入角色無此多倉收貨權限。');
}
async function validateV2ReceiptSource(transaction, {order,supply,reservation,item,inventory,warehouseStock,demand,actorUid,actorRole,qty}) {
    await assertV2ReceiptActor(transaction,actorUid,actorRole);
    const integer=(value,label)=>{
        if(!Number.isSafeInteger(value)||value<0)throw new Error(label+'必須是非負整數。');
        return value;
    };
    const id=value=>{
        if(typeof value!=='string'||!value||value!==value.trim()||value.includes('/')||value.length>160)
            throw new Error('多倉收貨來源識別不正確。');
        return value;
    };
    const orderId=id(supply.orderId),itemId=id(supply.itemId),productKey=id(supply.productKey),warehouseId=id(supply.warehouseId);
    const status=normalizedOrderStatus(order),cancelled=status==='cancelled';
    if(!Array.isArray(order.items)||!order.items.length||order.items.length>5
        ||order.items.filter(row=>row?.itemId===itemId).length!==1
        ||!order.ownerUid||!order.salesCode||!['normal','cancelled'].includes(status)
        ||(cancelled?order.status!=='cancelled':!['active','normal'].includes(order.status))
        ||!['normal','active','cancelled','',undefined].includes(order.orderStatus)
        ||order.returnPending===true||item.transferPendingId||item.custodyTransferId
        ||integer(order.logisticsTransfersPending??0,'調撥途中')!==0)
        throw new Error('多倉收貨只支援來源完整且無調撥的 1–5 品項訂單。');
    for(const field of ['warehouseShipmentRecords','deliveryRecords','returnRecords','returnHistory']){
        if(!Array.isArray(order[field]??[]))throw new Error('多倉收貨履約紀錄格式不正確。');
    }
    let jointHolds=null,wholeShipment=null;
    if(order.items.length>1){
        // Validate the whole event set before selecting the receiving line.
        // A sibling acknowledgement is never this line's outstanding demand.
        if(order.inventoryReservationStatus!=='completed'||!order.inventoryReservationAttemptId)
            throw new Error('多品項收貨僅支援已完成初始化的訂單。');
        wholeShipment=globalThis.YushinFulfillment.projectOrderShipmentReturns({orderId,items:order.items,
            shipments:order.warehouseShipmentRecords??[],deliveries:order.deliveryRecords??[],returns:order.returnRecords??[]});
        if((order.warehouseShipmentRecords??[]).length>40)
            throw new Error('多品項歷史出貨憑證超過本試點安全上限。');
        const seen=new Set(),products=new Map();
        jointHolds={company:0,warehouses:new Map()};
        const candidates=reservation.lifecycleWarehouseIds;
        if(!Array.isArray(candidates)||candidates.length!==2||new Set(candidates).size!==2)
            throw new Error('整單原候選倉資料不正確。');
        candidates.forEach(id);
        for(const row of order.items){
            const rowId=id(row?.itemId),productId=id(row.productId),key=id(row.inventoryProductKey||productId);
            const ordered=integer(row.qty??row.orderedQty,'品項訂購量');
            if(seen.has(rowId)||!ordered||(row.orderedQty!==undefined&&row.orderedQty!==ordered)
                ||(row.fulfillmentType||'WAREHOUSE')!=='WAREHOUSE'
                ||String(row.productType||row.type||'').toUpperCase()==='SERVICE'
                ||row.transferPendingId||row.custodyTransferId||!candidates.includes(id(row.warehouseId||order.warehouseId)))
                throw new Error('多品項收貨來源必須是唯一實體商品且無調撥途中。');
            seen.add(rowId);
            if(!products.has(productId))products.set(productId,await transaction.get(db.collection('products').doc(productId)));
            const product=products.get(productId);
            if(!product.exists||product.data().active===false||String(product.data().productType||product.data().type||'').toUpperCase()==='SERVICE')
                throw new Error('服務或停用商品不可進行多品項實貨收貨。');
            const snap=rowId===itemId?null:await transaction.get(db.collection('inventoryReservations').doc(`${orderId}__${rowId}`));
            const ledger=rowId===itemId?reservation:(snap.exists?snap.data():{});
            if(ledger.locationSchemaVersion!==2||ledger.warehouseId!==undefined||ledger.orderId!==orderId||ledger.itemId!==rowId
                ||ledger.productKey!==key||ledger.ownerUid!==order.ownerUid||ledger.salesCode!==order.salesCode
                ||!Array.isArray(ledger.lifecycleWarehouseIds)||ledger.lifecycleWarehouseIds.length!==2
                ||new Set(ledger.lifecycleWarehouseIds).size!==2||ledger.lifecycleWarehouseIds.some(wh=>!candidates.includes(wh))
                ||integer(ledger.quantity,'品項預留')!==row.reservedQty||integer(ledger.shortageQty,'品項缺口')!==row.shortageQty
                ||ledger.status!==(cancelled?'released':ledger.quantity>0?'active':ledger.shortageQty>0?'shortage':'fulfilled')
                ||integer(row.supplyOrderedQty??0,'品項供應量')<integer(row.receivedQty??0,'品項收貨量'))
                throw new Error('多品項收貨的完整預留來源或供應投影不一致。');
            const projection=wholeShipment.items.find(part=>part.itemId===rowId);
            if(integer(row.warehouseShippedQty??0,'品項出貨')!==projection.shippedQty
                ||integer(row.deliveredQty??0,'品項交付')!==projection.confirmedQty
                ||integer(row.returnedQty??0,'品項退貨')!==projection.returnedQty
                ||integer(row.dispatchPreparedQty??0,'品項打單')<projection.shippedQty
                ||integer(row.dispatchPreparedQty??0,'品項打單')>ordered
                ||(cancelled
                    ?ledger.quantity!==0||ledger.shortageQty!==0
                        ||globalThis.YushinReservation.reservationLocations(ledger).length!==0
                        ||projection.pendingDeliveryQty!==0||(row.dispatchPreparedQty??0)!==projection.shippedQty
                    :ledger.quantity+ledger.shortageQty!==projection.outstandingQty))
                throw new Error('多品項收貨預留與來源剩餘需求不一致。');
            const held=globalThis.YushinReservation.reservationStockDeltas({},ledger);
            if(held.warehouseDeltas.some(change=>!candidates.includes(change.warehouseId)))
                throw new Error('多品項預留不在原候選倉。');
            if(key===productKey){
                jointHolds.company+=held.companyReservedDelta;
                for(const change of held.warehouseDeltas)jointHolds.warehouses.set(change.warehouseId,
                    (jointHolds.warehouses.get(change.warehouseId)||0)+change.reservedDelta);
            }
        }
    }
    const returns=order.returnRecords??[];
    if((order.returnHistory??[]).some(event=>event?.action!=='add'||!returns.some(record=>record.id===event.recordId)))
        throw new Error('退貨歷史含尚未整合的更正或缺少原入庫來源。');
    const warehouseShipmentContext={orderId,itemId,productKey,
        shipments:wholeShipment?(order.warehouseShipmentRecords??[]).filter(row=>row.itemId===itemId):order.warehouseShipmentRecords??[],
        deliveries:wholeShipment?(order.deliveryRecords??[]).filter(row=>row.itemId===itemId):order.deliveryRecords??[],
        returns:wholeShipment?returns.filter(row=>row.itemId===itemId):returns};
    const shipment=wholeShipment?wholeShipment.items.find(part=>part.itemId===itemId):
        globalThis.YushinFulfillment.projectShipmentReturns({...warehouseShipmentContext,orderedQty:item.qty??item.orderedQty});
    // Empty caches must also match the actual bounded return query. Otherwise
    // removing a cached event could hide a physical receipt from this transaction.
    const proofs=await transaction.get(db.collection('inventoryMovements').where('sourceId','==',orderId)
        .where('action','==','location_customer_return').limit(201));
    await globalThis.YushinFulfillment.validateOrderLocationReturnProofs({...order,returnRecords:returns},
        {orderId,itemId,syncAttemptId:order.inventoryReservationAttemptId},productKey,
        proofs.docs.map(s=>({id:s.id,data:s.data()})),{closedOnly:true,hashIntent:async intent=>{
            const digest=await globalThis.crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(intent)));
            return Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');
        }});
    if(integer(item.warehouseShippedQty??0,'出貨量')!==shipment.shippedQty
        ||integer(item.deliveredQty??0,'交付量')!==shipment.confirmedQty
        ||integer(order.deliveredQty??0,'訂單交付量')!==(wholeShipment??shipment).confirmedQty
        ||integer(item.returnedQty??0,'退貨量')!==shipment.returnedQty
        ||integer(order.returnedQty??0,'訂單退貨量')!==(wholeShipment??shipment).returnedQty
        ||(order.isDelivered??false)!==(wholeShipment??shipment).isDelivered)
        throw new Error('多倉收貨的出貨、送達或退貨投影不一致。');
    for(const record of wholeShipment?(order.warehouseShipmentRecords??[]):warehouseShipmentContext.shipments){
        // Read every immutable debit in this transaction so a stale or forged
        // source cannot reduce the quantity awaiting reservation.
        if(record.movementId!=='location-ship-'+record.id)throw new Error('來源倉庫出貨憑證不一致。');
        const proof=await transaction.get(db.collection('inventoryMovements').doc(record.movementId));
        globalThis.YushinFulfillment.validateShipmentMovement(record,proof.exists?proof.data():null,
            wholeShipment?{orderId,itemId:record.itemId,productKey:record.productKey}:{orderId,itemId,productKey});
    }
    const demandId=globalThis.YushinProcurementDemand.demandIdForSource({sourceType:'SALES_ORDER',sourceId:orderId,sourceItemId:itemId});
    if(supply.sourceType!=='SALES_ORDER'||supply.sourceId!==orderId||supply.sourceItemId!==itemId
        ||supply.demandId!==demandId||supply.ownerUid!==order.ownerUid||supply.salesCode!==order.salesCode
        ||supply.productId!==item.productId||supply.fulfillmentType!=='WAREHOUSE'
        ||(supply.method!==undefined&&supply.method!==supply.type)
        ||!demand||demand.demandId!==demandId||demand.sourceType!=='SALES_ORDER'
        ||demand.sourceId!==orderId||demand.sourceItemId!==itemId||demand.productKey!==productKey
        ||demand.productId!==item.productId||demand.ownerUid!==order.ownerUid||demand.salesCode!==order.salesCode
        ||demand.fulfillmentType!=='WAREHOUSE'
        ||reservation.orderId!==orderId||reservation.itemId!==itemId||reservation.productKey!==productKey
        ||reservation.ownerUid!==order.ownerUid||reservation.salesCode!==order.salesCode
        ||reservation.warehouseId!==undefined)
        throw new Error('多倉收貨的訂單、需求或預留來源不一致。');
    integer(qty,'本次收貨');
    const held=integer(reservation.quantity,'預留'),shortage=integer(reservation.shortageQty,'缺口');
    const ordered=integer(item.qty??item.orderedQty,'訂購量');
    const supplied=integer(item.supplyOrderedQty??0,'供應量'),received=integer(item.receivedQty??0,'收貨量');
    const supplyQty=integer(supply.qty,'來源採購量'),supplyReceived=integer(supply.receivedQty??0,'來源收貨量');
    const registered=integer(supply.incomingRegisteredQty??0,'來源在途');
    if(supplyQty>supplied||supplyReceived>received||supplyReceived>supplyQty||registered>supplyQty-supplyReceived
        ||supply.originalFulfillmentType==='DIRECT_SHIP')throw new Error('供應承諾或原供貨方式與多倉來源不一致。');
    if(cancelled&&(supply.customerCancellationDisposition!=='KEEP_STOCK'
        ||!supply.customerCancellationResolvedAt||!supply.customerCancellationResolvedBy))
        throw new Error('取消訂單尚無採購保留入庫的完整決策。');
    const demandQty=integer(demand.requestedQty,'採購需求');
    integer(demand.orderedQty,'需求供應量');integer(demand.receivedQty,'需求收貨量');
    const normalizedDemand=globalThis.YushinProcurementDemand.normalizeDemand({...demand,
        status:cancelled?'CANCELLED':'',cancelled});
    if((item.orderedQty!==undefined&&item.orderedQty!==ordered)||item.reservedQty!==held||item.shortageQty!==shortage
        ||demand.orderedQty!==supplied||demand.receivedQty!==received||demandQty<supplied
        ||demand.status!==normalizedDemand.status||demand.remainingToOrderQty!==normalizedDemand.remainingToOrderQty
        ||demand.remainingToReceiveQty!==normalizedDemand.remainingToReceiveQty
        ||(!cancelled&&demand.cancelled===true)
        ||(cancelled?(held!==0||shortage!==0||reservation.status!=='released'):held+shortage!==shipment.outstandingQty))
        throw new Error('多倉收貨數量與來源投影不一致。');
    const rows=globalThis.YushinReservation.reservationLocations(reservation);
    const candidates=new Set([warehouseId,id(item.warehouseId||order.warehouseId),...rows.map(row=>row.warehouseId)]);
    if(reservation.lifecycleWarehouseIds!==undefined){
        if(!Array.isArray(reservation.lifecycleWarehouseIds)||reservation.lifecycleWarehouseIds.length!==2
            ||new Set(reservation.lifecycleWarehouseIds).size!==2)throw new Error('原候選倉資料不正確。');
        reservation.lifecycleWarehouseIds.forEach(id);
        if([...candidates].some(w=>!reservation.lifecycleWarehouseIds.includes(w)))throw new Error('收貨倉不在原候選倉。');
        reservation.lifecycleWarehouseIds.forEach(w=>candidates.add(w));
    }
    if(candidates.size>2)throw new Error('此收貨試點最多支援兩個實體倉。');
    for(const wh of candidates){
        const master=await transaction.get(db.collection('warehouses').doc(wh));
        if(!master.exists||master.data().systemCustody||master.data().warehouseType==='CUSTODY'
            ||wh.startsWith('custody-')||(wh===warehouseId&&master.data().active===false))
            throw new Error('收貨倉或原預留倉不是可用的實體倉。');
        const stock=wh===warehouseId?warehouseStock:(await transaction.get(db.collection('warehouseStocks').doc(warehouseStockDocId(wh,productKey)))).data();
        const own=rows.find(row=>row.warehouseId===wh)?.qty||0;
        if(!stock||stock.productKey!==productKey||stock.warehouseId!==wh
            ||integer(stock.reserved,'分倉預留')<(jointHolds?.warehouses.get(wh)??own)
            ||stock.reserved+integer(stock.transferFreeInTransit??0,'分倉途中')>integer(stock.onHand,'分倉實貨'))
            throw new Error('原分倉預留或實貨帳異常，不能部分收貨。');
    }
    if(!inventory||inventory.productKey!==productKey||integer(inventory.reserved,'公司預留')<(jointHolds?.company??held)
        ||inventory.reserved+integer(inventory.transferFreeInTransit??0,'公司途中')>integer(inventory.onHand,'公司實貨'))
        throw new Error('公司多倉庫存帳異常。');
    if(supply.type==='PURCHASING_PO'){
        const po=await transaction.get(db.collection('purchaseOrders').doc(id(supply.purchaseDocumentId)));
        const record=po.exists?po.data():{},links=record.supplyOrderIds;
        // Match the actual immutable PO-line link, not a supplied array index.
        const index=Array.isArray(links)?links.indexOf(supply.id):-1;
        const line=Array.isArray(record.items)?record.items[index]:null;
        if(index<0||links.filter(key=>key===supply.id).length!==1||!line
            ||line.orderId!==orderId||line.itemId!==itemId||line.productId!==item.productId
            ||Number(line.qty)!==supply.qty||line.warehouseId!==warehouseId
            ||isPurchaseTerminalStatus(record.status))throw new Error('多倉收貨缺少有效供應商採購單憑證。');
    }else if(!['PURCHASING_MANUAL','SALES_SELF_ORDER'].includes(supply.type))throw new Error('不支援的多倉供應來源。');
    return warehouseShipmentContext;
}

async function receiveSupplyOrderRecord(supplyId,qty,lotNo='',expiryDate='',operationId='',options={}) {
    if(globalThis.YUSHIN_V2_RECEIVING_EMULATOR===true)
        return receiveV2SupplyEmulator(supplyId,qty,lotNo,expiryDate,operationId,options);
    const actorUid=options.actorUid??currentUser?.uid,actorRole=options.actorRole??currentUserRole;
    const assertActor=(supply=null)=>{
        if(!actorUid||actorUid!==currentUser?.uid||actorRole!==currentUserRole)throw new Error('登入帳號或角色已變更，請以原身分重試到貨作業。');
        if(!['admin','purchaser','warehouse','sales','engineer'].includes(actorRole)||(supply&&!canConfirmSupplyReceipt(supply)))throw new Error('目前沒有這筆到貨確認權限。');
    };
    assertActor();
    const quantity=(value,label,optional=false)=>{
        if(value===undefined&&optional)return 0;
        if((typeof value!=='number'&&typeof value!=='string')||(typeof value==='string'&&!value.trim())
            ||!Number.isFinite(Number(value))||Number(value)<0)throw new Error(`${label}數量異常，請先核對紀錄。`);
        return Number(value);
    };
    if(!Number.isFinite(qty)||qty<=0)throw new Error('到貨數量必須是大於 0 的有效數字。');
    if(typeof lotNo!=='string'||typeof expiryDate!=='string')throw new Error('到貨批號或效期格式不正確。');
    const now=new Date().toISOString(),actor=deliveryActor(),receiptDate=localDateString();
    const operationKey=String(operationId||'').trim();
    if(!operationKey)throw new Error('缺少到貨操作識別碼，請重新開啟待到貨視窗後再試。');
    let receivedProductKey='',receivedWarehouseId='',sourceOrderId='',sourceOrderStatus='',reservedForSource=0,alreadyProcessed=false,processedReceipt=null;
    const affectedOrderIds = new Set();
    const lotRef=db.collection('inventoryLots').doc(),movementRef=db.collection('inventoryMovements').doc();
    let confirmedSupply=null;
    await runRoleTransaction(async tx=>{
        assertActor();
        receivedProductKey='';receivedWarehouseId='';sourceOrderId='';sourceOrderStatus='';reservedForSource=0;alreadyProcessed=false;processedReceipt=null;confirmedSupply=null;
        affectedOrderIds.clear();
        const supplyRef=supplyOrdersCollection().doc(supplyId);
        const receiptRef=db.collection('receipts').doc(operationKey);
        const supplySnap=await tx.get(supplyRef);
        const receiptSnap=await tx.get(receiptRef);
        if(!supplySnap.exists)throw new Error('找不到供應紀錄。');
        const supply={...supplySnap.data(),id:supplyId};
        assertActor(supply);confirmedSupply=supply;
        if(!canConfirmSupplyReceipt(supply))throw new Error('原廠直送由該訂單負責業務確認；倉庫收貨僅限採購、倉管或管理員。');
        if (!globalThis.YushinSupply?.normalize || !globalThis.YushinReceiving?.buildReceiptSnapshot
            || !globalThis.YushinProcurementDemand?.applyReceipt) {
            throw new Error('Supply／Receiving／Procurement Demand core 未載入，無法建立可追溯的到貨紀錄。');
        }
        const demandRef=procurementDemandRef(supply.demandId||'');
        const demandSnap=demandRef?await tx.get(demandRef):null;
        assertActor(supply);
        const procurement=globalThis.YushinSupply.normalize({...supply,id:supplyId});
        const updateDemandReceipt=(receiptQty)=>{
            if(!demandRef)return;
            if(demandSnap?.exists){
                const demand=demandSnap.data();
                const sourceId=supply.sourceId||supply.orderId||(procurement.sourceType==='STOCK_REPLENISHMENT'?(supply.productId||supply.itemCode||''):'');
                for(const [field,expected] of [['sourceId',sourceId],['sourceItemId',supply.sourceItemId||supply.itemId||''],
                    ['productKey',supply.productKey||inventoryProductKey(supply)],['fulfillmentType',supply.fulfillmentType||'WAREHOUSE']]){
                    if(demand[field]&&demand[field]!==expected)throw new Error('採購需求與供應來源、產品或供貨方式不符。');
                }
                const ordered=quantity(demand.orderedQty,'需求已訂貨',true),received=quantity(demand.receivedQty,'需求已到貨',true);
                if(ordered-received<receiptQty)throw new Error('採購需求的未到貨承諾量不足，無法安全收貨。');
            }
            const fallbackRequested=Math.max(
                Number(supply.qty||0),
                Number(supply.receivedQty||0)+Number(receiptQty||0)
            );
            const baseDemand=demandSnap?.exists
                ? demandSnap.data()
                : globalThis.YushinProcurementDemand.normalizeDemand({
                    demandId:supply.demandId||'',
                    sourceType:supply.sourceType||(supply.orderId?'SALES_ORDER':'STOCK_REPLENISHMENT'),
                    sourceId:supply.sourceId||supply.orderId||'',
                    sourceItemId:supply.sourceItemId||supply.itemId||'',
                    requestedQty:fallbackRequested,
                    orderedQty:Math.max(fallbackRequested,Number(supply.qty||0)),
                    receivedQty:Number(supply.receivedQty||0),
                    scheduleDate:''
                });
            const receiptDemandPlan=globalThis.YushinProcurementDemand.applyReceipt(baseDemand,receiptQty);
            if(receiptDemandPlan.appliedQty!==Number(receiptQty||0)){
                throw new Error('採購需求收貨數量已變更，請重新整理後再試。');
            }
            if(demandSnap?.exists){
                const next=receiptDemandPlan.demand;
                tx.update(demandRef,{receivedQty:next.receivedQty,remainingToReceiveQty:next.remainingToReceiveQty,perReceived:next.perReceived,status:next.status,updatedAt:now});
                return;
            }
            if(['sales','engineer'].includes(currentUserRole))throw new Error('直送供應缺少採購需求紀錄，請由採購確認後再重試。');
            const demandDoc=procurementDemandDocument(receiptDemandPlan.demand,{
                sourceItemIndex:Number.isInteger(supply.orderItemIndex)?supply.orderItemIndex:baseDemand.sourceItemIndex,
                productId:supply.productId||'',
                productKey:supply.productKey||'',
                itemCode:supply.itemCode||'',
                itemName:supply.itemName||'',
                brand:supply.brand||'',
                fulfillmentType:supply.fulfillmentType||'WAREHOUSE',
                warehouseId:(supply.fulfillmentType||'WAREHOUSE')==='DIRECT_SHIP'?'':(supply.warehouseId||''),
                ownerUid:supply.ownerUid||'',
                salesCode:supply.salesCode||'',
                salesName:supply.salesName||'',
                scheduleDate:baseDemand.scheduleDate||''
            },{
                createdAt:baseDemand.createdAt||supply.createdAt||now,
                updatedAt:now
            });
            tx.set(demandRef,demandDoc,{merge:true});
        };
        const buildReceipt=(event={})=>globalThis.YushinReceiving.buildReceiptSnapshot(procurement,{
            supplyOrderId:supplyId,
            receiptDate,
            createdAt:now,
            createdBy:actor,
            ...event,
            extra:{...event.extra,createdByUid:actorUid,createdByRole:actorRole}
        });
        if (supply.orderId) affectedOrderIds.add(supply.orderId);
        // 已成功提交過的同一 receiptId 必須先走冪等重試；即使之後取消了剩餘未到貨，
        // 也不能把已完成的到貨重試誤判成新的「取消後收貨」。
        if(receiptSnap.exists){
            const receipt=receiptSnap.data()||{};
            if(receipt.reservationLocationSchemaVersion===2)await assertV2ReceiptActor(tx,actorUid,actorRole);
            if(String(receipt.supplyOrderId||'')!==String(supplyId)||Number(receipt.qty)!==qty
                ||String(receipt.lotNo||'')!==lotNo||String(receipt.expiryDate||'')!==expiryDate
                ||(receipt.createdByUid&&receipt.createdByUid!==actorUid)||(receipt.createdByRole&&receipt.createdByRole!==actorRole))throw new Error('到貨操作識別碼衝突，請重新開啟待到貨視窗。');
            alreadyProcessed=true;
            processedReceipt=receipt;
            if((receipt.fulfillmentType||supply.fulfillmentType||'WAREHOUSE')!=='DIRECT_SHIP'){
                receivedProductKey=String(receipt.productKey||supply.productKey||supply.productId||'').trim();
                receivedWarehouseId=String(receipt.warehouseId||supply.warehouseId||'').trim();
                sourceOrderId=receipt.orderId||supply.orderId||'';
            }
            return;
        }
        if (isPurchaseTerminalStatus(supply.status)) {
            throw new Error(String(supply.status||'').toUpperCase()==='CLOSED'
                ? '此供應紀錄已結案，不能再確認到貨。'
                : '此供應紀錄已取消，不能再確認到貨。');
        }
        const remaining=Math.max(0,Number(supply.qty||0)-Number(supply.receivedQty||0));
        const ordered=quantity(supply.qty,'供應'),received=quantity(supply.receivedQty,'已到貨',true);
        const registeredIncoming=quantity(supply.incomingRegisteredQty,'已登記在途',true);
        if(received>ordered||registeredIncoming>ordered-received)throw new Error('供應數量或在途數量異常，請由採購核對後重試。');
        if(qty<=0||qty>remaining)throw new Error(`本次到貨數量不可超過 ${remaining}。`);
        const directShip=(supply.fulfillmentType||'WAREHOUSE')==='DIRECT_SHIP';
        if((supply.sourceType==='SALES_ORDER'||supply.itemId)&&!supply.orderId)throw new Error('供應紀錄缺少來源訂單關聯。');
        if(supply.orderId&&((supply.sourceId&&supply.sourceId!==supply.orderId)
            ||(supply.sourceItemId&&supply.sourceItemId!==supply.itemId)))throw new Error('供應紀錄的來源識別互相矛盾。');
        const validateSourceItem=(order,items)=>{
            if(orderInventorySyncIncomplete(order))throw new Error('來源訂單的庫存同步尚未完成，無法安全收貨。');
            if(!supply.itemId)throw new Error('供應紀錄缺少來源品項。');
            const matches=items.map((item,index)=>item.itemId===supply.itemId?index:-1).filter(index=>index>=0);
            if(matches.length!==1)throw new Error('來源訂單品項不存在或識別碼重複，無法安全收貨。');
            const index=matches[0],item=items[index],raw=order.items[index];
            const key=String(supply.productKey||inventoryProductKey(supply)||'').trim();
            if(!key||inventoryProductKey(item)!==key||(item.fulfillmentType||'WAREHOUSE')!==(supply.fulfillmentType||'WAREHOUSE'))
                throw new Error('供應與來源品項的產品或供貨方式不符。');
            const committed=quantity(raw.supplyOrderedQty,'來源已訂貨',true),arrived=quantity(raw.receivedQty,'來源已到貨',true);
            quantity(raw.reservedQty,'來源預留',true);
            if(committed-arrived<qty)throw new Error('來源訂單的未到貨承諾量不足，無法安全收貨。');
            return index;
        };
        if(directShip){
            if(registeredIncoming!==0)throw new Error('直送供應不可具有公司在途庫存，請由採購核對。');
            if(lotNo||expiryDate)throw new Error('原廠直送不登記公司庫存批號或效期。');
            if(!supply.orderId||!supply.itemId)throw new Error('原廠直送紀錄缺少來源訂單／品項。');
            const orderRef=db.collection('orders').doc(supply.orderId);
            const orderSnap=await tx.get(orderRef);
            if(!orderSnap.exists)throw new Error('找不到來源訂單。');
            assertActor(supply);
            const order=orderSnap.data();
            if(currentUserRole!=='admin'&&order.ownerUid!==currentUser?.uid)throw new Error('只有此訂單負責業務可確認直送到貨。');
            if(normalizedOrderStatus(order)!=='normal')throw new Error('來源訂單已取消，不能繼續確認到貨；請先處理／恢復來源訂單。');
            const items=normalizedOrderItems(order);
            const itemIndex=validateSourceItem(order,items);
            const item=items[itemIndex];
            // Purchase Receipt / Delivery are cumulative ERP events. A replacement after a return
            // can legitimately make gross delivered quantity exceed the original ordered quantity.
            // Completion is decided from net delivered (gross - returns), not by truncating history.
            const delivered=Number(item.deliveredQty||0)+qty;
            items[itemIndex]={
                ...item,
                receivedQty:Number(item.receivedQty||0)+qty,
                deliveredQty:delivered,
                directShipDeliveredQty:Number(item.directShipDeliveredQty||0)+qty,
                receiptEvents:[
                    ...(item.receiptEvents||[]),
                    {id:operationKey,at:now,date:receiptDate,qty,sourceId:supplyId,by:actor,fulfillmentType:'DIRECT_SHIP'}
                ]
            };
            const deliveryRecord={
                id:`direct-${operationKey}`,receiptId:operationKey,itemId:supply.itemId,itemIndex,date:receiptDate,qty,
                notes:'原廠直送到貨確認',createdBy:actor,createdAt:now,sourceType:'DIRECT_SHIP_RECEIPT',sourceId:supplyId
            };
            const deliveryRecords=[...savedDeliveryRecords(order),deliveryRecord];
            const grossDelivered=deliveryRecords.reduce((sum,row)=>sum+Number(row.qty||0),0);
            const returned=returnedQuantity(order);
            const total=orderQuantity({...order,items});
            const nextOrder={
                ...order,items,itemCount:items.length,orderSchemaVersion:2,
                deliveryRecords,deliveredQty:grossDelivered,
                isDelivered:Math.max(0,grossDelivered-returned)>=total&&total>0,
                updatedAt:now
            };
            tx.update(orderRef,{
                items,itemCount:items.length,orderSchemaVersion:2,
                deliveryRecords,deliveredQty:grossDelivered,isDelivered:nextOrder.isDelivered,
                ...orderWorkIndexFields(nextOrder),updatedAt:now
            });
            const receiptPlan=globalThis.YushinSupply.applyReceipt(procurement,qty);
            const receivedQty=receiptPlan.record.receivedQty;
            tx.update(supplyRef,{receivedQty,status:receiptPlan.record.status,updatedAt:now});
            updateDemandReceipt(qty);
            tx.set(receiptRef,buildReceipt({
                receiptId:operationKey,
                operationId:operationKey,
                qty,
                cumulativeReceivedQty:receivedQty,
                fulfillmentType:'DIRECT_SHIP',
                warehouseId:''
            }));
            return;
        }
        const productKey=supply.productKey||supply.productId||(supply.itemCode?`code:${normalizeHistoryItemCode(supply.itemCode)}`:'');
        if(!productKey)throw new Error('此品項缺少 產品識別碼／貨號。');
        const warehouseId=String(supply.warehouseId||'').trim();
        if(!warehouseId)throw new Error('此供應紀錄尚未指定入庫倉庫，無法安全入庫。');
        receivedProductKey=productKey;receivedWarehouseId=warehouseId;sourceOrderId=supply.orderId||'';
        const invRef=db.collection('inventory').doc(encodeURIComponent(productKey));
        const whRef=warehouseId?db.collection('warehouseStocks').doc(warehouseStockDocId(warehouseId,productKey)):null;
        const invSnap=await tx.get(invRef);
        const whSnap=whRef?await tx.get(whRef):null;
        for(const [snap,label] of [[invSnap,'公司'],[whSnap,'分倉']]){
            if(!snap?.exists)continue;
            const stock=snap.data();
            if((stock.productKey&&stock.productKey!==productKey)||(stock.productId&&supply.productId&&stock.productId!==supply.productId)
                ||(label==='分倉'&&stock.warehouseId&&stock.warehouseId!==warehouseId))throw new Error('公司或分倉庫存識別不符，無法安全收貨。');
            for(const field of ['onHand','reserved','incoming'])quantity(stock[field],label+field,true);
            if(Number(stock.reserved||0)>Number(stock.onHand||0))throw new Error('公司或分倉預留超過實貨，請先核對紀錄。');
        }
        const inv=inventoryNumbers(invSnap.exists?invSnap.data():{});
        const wh=inventoryNumbers(whSnap?.exists?whSnap.data():{});
        const receiptPlan=globalThis.YushinSupply.applyReceipt(procurement,qty);
        const incomingRelease=receiptPlan.incomingReleaseQty;
        if(inv.incoming<incomingRelease||wh.incoming<incomingRelease)throw new Error('公司或分倉在途保留量不足，無法完整收貨扣回。');
        let order=null,items=[],itemIndex=-1,reserveQty=0,sourceStockPlan=null,sourceReservationV2=false;
        if(supply.orderId){
            const orderRef=db.collection('orders').doc(supply.orderId);
            const reservationRef=db.collection('inventoryReservations').doc(`${supply.orderId}__${supply.itemId}`);
            const orderSnap=await tx.get(orderRef);
            const reservationSnap=await tx.get(reservationRef);
            assertActor(supply);
            if(!orderSnap.exists)throw new Error('找不到來源訂單，無法安全收貨。');
            if(orderSnap.exists){
                order=orderSnap.data();
                sourceOrderStatus=normalizedOrderStatus(order);
                if(sourceOrderStatus!=='normal'&&supply.customerCancellationDisposition!=='KEEP_STOCK')throw new Error('請先由採購確認供應商答覆，保留採購轉庫存後再收貨。');
                // 倉庫型採購即使來源訂單已取消，供應商仍可能照常出貨。
                // 此時貨照常入庫，但不可再占回已取消訂單；整批視為自由庫存。
                items=normalizedOrderItems(order);itemIndex=validateSourceItem(order,items);
                if(itemIndex>=0){
                    let item=items[itemIndex];
                    if(!reservationSnap.exists)throw new Error('來源訂單缺少庫存預留紀錄，無法安全入庫。');
                    const savedReservation=reservationSnap.data();
                    if(savedReservation.locationSchemaVersion!==undefined||savedReservation.locations!==undefined)
                        globalThis.YushinReservation.reservationLocations(savedReservation);
                    sourceReservationV2=savedReservation.locationSchemaVersion===2;
                    if(sourceReservationV2){
                        // Preserve every untouched v2 line verbatim, not a legacy
                        // normalized projection of its quantities or metadata.
                        items=order.items.map(row=>({...row}));item=items[itemIndex];
                    }
                    const warehouseShipmentContext=sourceReservationV2?await validateV2ReceiptSource(tx,{order,supply,reservation:reservationSnap.data(),item,
                        inventory:invSnap.exists?invSnap.data():null,warehouseStock:whSnap?.exists?whSnap.data():null,
                        demand:demandSnap?.exists?demandSnap.data():null,actorUid,actorRole,qty}):undefined;
                    if(sourceOrderStatus==='normal'){
                        if(!reservationSnap.exists)throw new Error('來源訂單缺少庫存預留紀錄，無法安全入庫。');
                        const reservation=reservationSnap.data();
                        if(reservation.orderId!==supply.orderId||reservation.itemId!==supply.itemId||reservation.productKey!==productKey
                            ||(!sourceReservationV2&&(reservation.warehouseId!==warehouseId||item.warehouseId!==warehouseId))||item.transferPendingId)
                            throw new Error('來源預留的產品、倉庫或訂單關聯不符，無法安全入庫。');
                        const rawReserved=quantity(order.items[itemIndex].reservedQty,'來源預留',true);
                        const ledgerReserved=quantity(reservation.quantity,'預留帳'),ledgerShortage=quantity(reservation.shortageQty,'缺貨帳',true);
                        const localReserved=sourceReservationV2?(globalThis.YushinReservation.reservationLocations(reservation).find(row=>row.warehouseId===warehouseId)?.qty||0):ledgerReserved;
                        if(rawReserved!==ledgerReserved||Math.abs(Number(item.reservedQty||0)-ledgerReserved)>1e-9
                            ||Math.abs(Number(item.shortageQty||0)-ledgerShortage)>1e-9||inv.reserved<ledgerReserved||wh.reserved<localReserved)
                            throw new Error('來源訂單與公司／分倉預留數量不一致，請先核對紀錄。');
                        const currentReserved=Math.max(0,Number(reservation.quantity||0));
                        const receiptPlan=globalThis.YushinReceiving.applyReceiptToOrderItem({...item,reservedQty:currentReserved},qty,warehouseShipmentContext);
                        const next=receiptPlan.item;
                        sourceStockPlan=globalThis.YushinReservation.planReservationReceipt({productKey,warehouseId,qty,
                            requestedReserveQty:receiptPlan.reservedDelta,reservation,
                            aggregateStock:invSnap.exists?invSnap.data():{},warehouseStock:whSnap?.exists?whSnap.data():{},
                            itemReservedQty:order.items[itemIndex].reservedQty});
                        if(Math.abs(sourceStockPlan.allocatedQty-receiptPlan.reservedDelta)>1e-9)throw new Error('收貨預留與來源需求不一致，請先核對公司與分倉庫存。');
                        reserveQty=sourceStockPlan.allocatedQty;
                        reservedForSource=reserveQty;
                        items[itemIndex]={
                            ...next,
                            reservedQty:next.reservedQty,
                            receiptEvents:[
                                ...(item.receiptEvents||[]),
                                {id:operationKey,at:now,date:receiptDate,qty,sourceId:supplyId,by:actor,fulfillmentType:'WAREHOUSE'}
                            ]
                        };
                        const nextOrder={...order,items,itemCount:items.length,orderSchemaVersion:2,updatedAt:now};
                        tx.update(orderRef,{items,itemCount:items.length,orderSchemaVersion:2,...orderWorkIndexFields(nextOrder),updatedAt:now});
                        tx.set(reservationRef,{
                            ...sourceStockPlan.reservation,orderId:supply.orderId,itemId:supply.itemId,orderNo:order.orderNo||order.quoteNo||supply.orderId,
                            productKey,itemCode:supply.itemCode||'',itemName:supply.itemName||'',customerName:order.customerName||'',
                            ownerUid:order.ownerUid||'',salesCode:order.salesCode||'',salesName:order.salesName||'',orderDate:order.orderDate||'',
                            quantity:Number(next.reservedQty||0),shortageQty:Number(next.shortageQty||0),
                            status:Number(next.reservedQty||0)>0?'active':'shortage',...(!sourceReservationV2?{warehouseId}:{}),updatedAt:now
                        },{merge:true});
                    }else{
                        if(sourceReservationV2)sourceStockPlan=globalThis.YushinReservation.planReservationReceipt({productKey,warehouseId,qty,requestedReserveQty:0,
                            reservation:reservationSnap.data(),aggregateStock:invSnap.data(),warehouseStock:whSnap.data(),itemReservedQty:0});
                        // 取消中的來源訂單不重新占庫存，但仍同步實際到貨摘要。
                        // 這樣日後恢復訂單時，不會把已經到倉的數量再次誤判成在途採購。
                        const receiptPlan=globalThis.YushinReceiving.applyReceiptToOrderItem({...item,reservedQty:0},qty);
                        items[itemIndex]={
                            ...item,
                            receivedQty:receiptPlan.item.receivedQty,
                            receiptEvents:[
                                ...(item.receiptEvents||[]),
                                {id:operationKey,at:now,date:receiptDate,qty,sourceId:supplyId,by:actor,fulfillmentType:'WAREHOUSE',sourceOrderStatus:'cancelled'}
                            ]
                        };
                        const nextOrder={...order,items,itemCount:items.length,orderSchemaVersion:2,updatedAt:now};
                        tx.update(orderRef,{items,itemCount:items.length,orderSchemaVersion:2,...orderWorkIndexFields(nextOrder),updatedAt:now});
                    }
                }
            }
        }
        assertActor(supply);
        const embeddedLots=[...(invSnap.exists?(invSnap.data().lots||[]):[])];
        const embeddedIndex=embeddedLots.findIndex(l=>(l.lotNo||'')===lotNo&&(l.expiryDate||'')===expiryDate);
        if(embeddedIndex>=0)embeddedLots[embeddedIndex]={...embeddedLots[embeddedIndex],qty:Number(embeddedLots[embeddedIndex].qty||0)+qty};
        else embeddedLots.push({lotNo,expiryDate,qty,receivedAt:now,sourceSupplyId:supplyId});
        {
          const nextInventory={...(invSnap.exists?invSnap.data():{}),productKey,productId:supply.productId||'',itemCode:supply.itemCode||'',itemName:supply.itemName||'',brand:supply.brand||'',onHand:sourceStockPlan?sourceStockPlan.aggregateStock.onHand:inv.onHand+qty,reserved:sourceStockPlan?sourceStockPlan.aggregateStock.reserved:inv.reserved+reserveQty,incoming:inv.incoming-incomingRelease,lots:embeddedLots,updatedAt:now};
          nextInventory.searchTokens=buildInventorySearchTokens(nextInventory);
          tx.set(invRef,nextInventory,{merge:true});
        }
        if(whRef)tx.set(whRef,{warehouseId,productKey,productId:supply.productId||'',itemCode:supply.itemCode||'',itemName:supply.itemName||'',brand:supply.brand||'',onHand:sourceStockPlan?sourceStockPlan.warehouseStock.onHand:wh.onHand+qty,reserved:sourceStockPlan?sourceStockPlan.warehouseStock.reserved:wh.reserved+reserveQty,incoming:wh.incoming-incomingRelease,updatedAt:now},{merge:true});
        tx.set(lotRef,{productKey,productId:supply.productId||'',warehouseId,lotNo,expiryDate,receivedQty:qty,remainingQty:qty,supplier:supply.supplier||'',sourceType:'SUPPLY_ORDER',sourceId:supplyId,receivedAt:now});
        tx.set(db.collection('inventoryLotCosts').doc(lotRef.id),{lotId:lotRef.id,productKey,productId:supply.productId||'',warehouseId,...(currentUserRole==='warehouse'&&permissionRulesReady?{costSourceSupplyId:supplyId}:{unitCost:Number(supply.unitCost||0)}),sourceType:'SUPPLY_ORDER',sourceId:supplyId,createdAt:now,createdBy:actor});
        const autoAllocationQty=Math.max(0,Number(qty||0)-reserveQty);
        tx.set(receiptRef,buildReceipt({
            receiptId:operationKey,
            operationId:operationKey,
            qty,
            cumulativeReceivedQty:receiptPlan.record.receivedQty,
            productKey,
            warehouseId,
            fulfillmentType:'WAREHOUSE',
            extra:{
                sourceOrderStatus,
                ...(sourceReservationV2?{reservationLocationSchemaVersion:2}:{}),
                autoAllocationQty,
                autoAllocatedQty:0,
                allocationCompleted:autoAllocationQty===0,
                lotId:lotRef.id,
                lotNo,
                expiryDate
            }
        }));
        tx.set(movementRef,{type:'receipt',qty,productKey,warehouseId,lotNo,expiryDate,sourceType:'SUPPLY_ORDER',sourceId:supplyId,receiptId:operationKey,createdAt:now,createdBy:actor,ownerUid:supply.ownerUid||'',salesCode:supply.salesCode||''});
        updateDemandReceipt(qty);
        tx.update(supplyRef,{
            receivedQty:receiptPlan.record.receivedQty,
            incomingRegisteredQty:receiptPlan.record.incomingRegisteredQty,
            status:receiptPlan.record.status,
            updatedAt:now
        });
    });
    try {
        assertActor(confirmedSupply);
        if (receivedProductKey && receivedWarehouseId) options.onStockCommitted?.(receivedProductKey, receivedWarehouseId);

        // Replenishment / excess receipt stock automatically serves oldest outstanding shortages.
        // The physical receipt is already committed before this phase. If this follow-up is interrupted,
        // the same immutable receiptId is reused to count prior allocations and only the remainder is retried.
        let freeQty=receivedProductKey&&receivedWarehouseId?Math.max(0,Number(qty||0)-reservedForSource):0;
        if(alreadyProcessed){
            const allocationTarget=Math.max(0,Number(processedReceipt?.autoAllocationQty||0));
            if(allocationTarget>0){
                const priorMovements=await readQueryInBatches(
                    db.collection('inventoryMovements').where('receiptId','==',operationKey)
                );
                assertActor(confirmedSupply);
                const alreadyAllocated=priorMovements
                    .filter(row=>row.type==='reserve_from_receipt')
                    .reduce((sum,row)=>sum+Math.max(0,Number(row.qty||0)),0);
                let reconciledAllocated=alreadyAllocated;
                await runRoleTransaction(async tx=>{
                    assertActor(confirmedSupply);
                    const receiptRef=db.collection('receipts').doc(operationKey);
                    const receiptSnap=await tx.get(receiptRef);
                    assertActor(confirmedSupply);
                    if(!receiptSnap.exists)throw new Error('找不到已提交的到貨分配進度。');
                    const receipt=receiptSnap.data()||{};
                    const currentAllocated=Math.max(0,Number(receipt.autoAllocatedQty||0));
                    reconciledAllocated=Math.max(currentAllocated,alreadyAllocated);
                    if(reconciledAllocated!==currentAllocated){
                        tx.update(receiptRef,{
                            autoAllocatedQty:reconciledAllocated,
                            allocationCompleted:reconciledAllocated>=allocationTarget,
                            allocationUpdatedAt:new Date().toISOString()
                        });
                    }
                });
                assertActor(confirmedSupply);
                freeQty=Math.max(0,allocationTarget-reconciledAllocated);
            }else{
                freeQty=0;
            }
        }
        if(freeQty>0){
            const allocation=await allocateFreeReceiptStockToShortages(
                receivedProductKey,receivedWarehouseId,freeQty,actor,sourceOrderId,operationKey,'receipts',()=>assertActor(confirmedSupply),options.onStockCommitted
            );
            allocation.affectedOrderIds.forEach(id=>affectedOrderIds.add(id));
        }
        assertActor(confirmedSupply);
        return [...affectedOrderIds];
    }catch(allocationErr){
        const error=new Error(
            '到貨已提交，但後續確認或庫存分配尚未完成：'
            +(allocationErr?.message||allocationErr)
            +'。請再按一次「確認到貨」重試；系統不會重複入庫。'
        );
        error.code='receipt-allocation-pending';
        error.receiptCommitted=true;
        error.affectedOrderIds=[...affectedOrderIds];
        throw error;
    }
}

// Receipt dialogs, frozen retry jobs and view refresh. Authoritative writes stay in Services.
let poReceiptTargetId = '';
let poReceiptOperationId = '';

function receiptOperationStorageKey(supplyId, ownerUid = currentUser?.uid || '') {
    return `yushin-receipt-operation:${ownerUid}:${String(supplyId || '')}`;
}
function ensureReceiptOperationId(supplyId) {
    const key=receiptOperationStorageKey(supplyId);
    let operationId='';
    try { operationId=sessionStorage.getItem(key)||''; } catch (_) {}
    if(!operationId){
        operationId=`receipt-${Date.now()}-${Math.random().toString(36).slice(2,10)}`;
        try { sessionStorage.setItem(key,operationId); } catch (_) {}
    }
    poReceiptOperationId=operationId;
    return operationId;
}
function clearReceiptOperationId(supplyId, completedOperationId = '', ownerUid = currentUser?.uid || '') {
    try {
        const key=receiptOperationStorageKey(supplyId,ownerUid);
        if(!completedOperationId||sessionStorage.getItem(key)===completedOperationId)sessionStorage.removeItem(key);
    } catch (_) {}
    if(currentUser?.uid===ownerUid&&(!completedOperationId||poReceiptOperationId===completedOperationId))poReceiptOperationId='';
}
window.closePoReceiptBatch = function() {
    document.getElementById('poReceiptBatchOverlay')?.classList.remove('active');
    const body=document.getElementById('poReceiptBatchBody');
    if(body)body.innerHTML='';
    poReceiptTargetId='';
};


window.receiveSupplyOrder = function(supplyId) {
    if (!canReceiveInventoryCapability()) { alert('您沒有到貨入庫權限。'); return; }
    if (receiptTaskBlocksSupply(supplyId)) return;
    const supply=pendingSupplyCache.find(row=>row.id===supplyId);
    if(!supply)return;
    const remaining=Math.max(0,Number(supply.qty||0)-Number(supply.receivedQty||0));
    if(remaining<=0){alert('這筆訂貨已全部入庫。');return;}
    poReceiptTargetId='supply:'+supplyId;
    ensureReceiptOperationId(supplyId);
    const directShip=(supply.fulfillmentType||'WAREHOUSE')==='DIRECT_SHIP';
    const title=document.getElementById('poReceiptBatchTitle');
    if(title)title.textContent=directShip ? `原廠直送到貨｜${supply.internalNo||supplyId}` : `到貨入庫｜${supply.internalNo||supplyId}`;
    const body=document.getElementById('poReceiptBatchBody');
    body.innerHTML=`<tr data-index="0">
      <td><input type="checkbox" class="po-receive-select" checked></td>
      <td>${escapeHtml(supply.itemCode||'')}</td>
      <td>${escapeHtml(supply.itemName||'')}</td>
      <td>${Number(supply.qty||0)}</td><td>${Number(supply.receivedQty||0)}</td><td>${remaining}</td>
      <td><input type="number" class="po-receive-qty" min="0" max="${remaining}" step="any" value="${remaining}" style="width:85px;"></td>
      <td><input type="text" class="po-receive-lot" placeholder="批號" ${directShip ? 'disabled' : ''}></td>
      <td><input type="date" class="po-receive-expiry" ${directShip ? 'disabled' : ''}></td>
    </tr>`;
    document.getElementById('poReceiptBatchOverlay')?.classList.add('active');
};


window.openSupplyReceipt = function(supplyId) {
    if (receiptTaskBlocksSupply(supplyId)) return;
    const supply = supplyReceivingCache.find(row => row.id === supplyId);
    if (!supply) { alert('找不到這筆待到貨紀錄，請重新整理。'); return; }
    if (!canConfirmSupplyReceipt(supply)) { showActionFeedback('原廠直送請由該訂單負責業務確認到貨。','warning');return; }

    const ordered = Math.max(0, Number(supply.qty || 0));
    const received = Math.max(0, Number(supply.receivedQty || 0));
    const remaining = Math.max(0, ordered - received);
    if (remaining <= 0) { alert('此品項已全部到貨。'); return; }

    const directShip = (supply.fulfillmentType || 'WAREHOUSE') === 'DIRECT_SHIP';
    poReceiptTargetId = `supply:${supply.id}`;
    ensureReceiptOperationId(supply.id);
    const body = document.getElementById('poReceiptBatchBody');
    const title = document.getElementById('poReceiptBatchTitle');
    if (title) title.textContent = directShip
        ? `原廠直送到貨｜${supply.internalNo || supply.id}｜${supply.itemCode || supply.itemName || ''}`
        : `到貨入庫｜${supply.internalNo || supply.id}｜${supply.itemCode || supply.itemName || ''}`;
    body.innerHTML = `
        <tr data-index="0">
            <td><input type="checkbox" class="po-receive-select" checked></td>
            <td>${escapeHtml(supply.itemCode || '')}</td>
            <td>${escapeHtml(supply.itemName || '')}</td>
            <td>${ordered}</td><td>${received}</td><td>${remaining}</td>
            <td><input type="number" class="po-receive-qty" min="0" max="${remaining}" step="any" value="${remaining}" style="width:85px;"></td>
            <td><input type="text" class="po-receive-lot" placeholder="批號" ${directShip ? 'disabled' : ''}></td>
            <td><input type="date" class="po-receive-expiry" ${directShip ? 'disabled' : ''}></td>
        </tr>`;
    document.getElementById('poReceiptBatchOverlay')?.classList.add('active');
};

const receiptTaskJobs = new Map();
const restoredReceiptTaskUsers = new Set();

function receiptTaskKey(supplyId, ownerUid = currentUser?.uid || '') {
    return `${ownerUid}:${supplyId}`;
}
function persistReceiptTasks(ownerUid) {
    try {
        const jobs=[...receiptTaskJobs.values()].filter(job=>job.ownerUid===ownerUid&&job.state!=='done');
        sessionStorage.setItem(`yushin-receipt-tasks:${ownerUid}`,JSON.stringify(jobs));
    } catch(err) { console.warn('無法暫存背景到貨工作，請保持頁面開啟：',err); }
}
function restoreReceiptTasks() {
    const uid=currentUser?.uid;
    if(!uid||restoredReceiptTaskUsers.has(uid))return;
    restoredReceiptTaskUsers.add(uid);
    try {
        const jobs=JSON.parse(sessionStorage.getItem(`yushin-receipt-tasks:${uid}`)||'[]');
        if(Array.isArray(jobs))jobs.forEach(job=>{
            if(job.ownerUid!==uid||typeof job.supplyId!=='string'||!job.supplyId||typeof job.operationBase!=='string'||!job.operationBase||!Array.isArray(job.entries)||!job.entries.length
                ||job.entries.some(entry=>!Number.isFinite(entry.qty)||entry.qty<=0||!Number.isInteger(entry.itemIndex)||entry.itemIndex<0))return;
            const key=receiptTaskKey(job.supplyId,uid);
            if(!receiptTaskJobs.has(key))receiptTaskJobs.set(key,{...job,state:'error',error:'上次處理結果尚未確認；可用原資料重試，系統不會重複入庫。'});
        });
    } catch(err) { console.warn('背景到貨暫存讀取失敗：',err); }
}
function renderReceiptTasks() {
    const panel=document.getElementById('receiptTaskStatus');
    if(!panel)return;
    const jobs=[...receiptTaskJobs.values()].filter(job=>job.ownerUid===currentUser?.uid);
    panel.hidden=!jobs.length;
    panel.innerHTML=jobs.map(job=>`<div class="receipt-task ${job.state==='error'?'receipt-task-error':''}">
        <span>${escapeHtml(job.label)}：${job.state==='error'?escapeHtml(job.error):'到貨處理中，可繼續其他操作；請保持頁面開啟。'}</span>
        ${job.state==='error'&&(canReceiveInventoryCapability()||['sales','engineer'].includes(currentUserRole))?`<button type="button" class="btn-small" onclick="retryReceiptTask(${inlineJsValue(job.supplyId)})">用原資料重試</button>`:''}
    </div>`).join('');
    document.querySelectorAll('button[data-receipt-supply]').forEach(button=>{
        const job=receiptTaskJobs.get(receiptTaskKey(button.dataset.receiptSupply));
        button.disabled=!!job||button.dataset.receiptConfirmed==='true';
        if(job)button.textContent=job.state==='error'?'到貨待確認':'到貨處理中…';
    });
}
function receiptTaskBlocksSupply(supplyId) {
    restoreReceiptTasks();
    const job=receiptTaskJobs.get(receiptTaskKey(supplyId));
    if(!job)return false;
    renderReceiptTasks();
    showActionFeedback(job.state==='error'?'這筆到貨結果待確認，請使用上方「用原資料重試」。':'這筆到貨正在背景處理，其他品項可繼續操作。','warning');
    return true;
}
window.retryReceiptTask = function(supplyId) {
    if(!canReceiveInventoryCapability()&&!['sales','engineer'].includes(currentUserRole))return;
    const job=receiptTaskJobs.get(receiptTaskKey(supplyId));
    if(!job||job.state!=='error')return;
    // 舊暫存未含角色，只在本人明確重試時補上；新工作跨重試保留原角色。
    if(!job.actorRole)job.actorRole=currentUserRole;
    return runReceiptTask(job);
};
window.addEventListener('beforeunload',event=>{
    if([...receiptTaskJobs.values()].some(job=>job.state==='running')){
        event.preventDefault();event.returnValue='';
    }
});

async function refreshReceiptTaskViews(affectedOrderIds,contextGuard=null) {
    contextGuard?.();
    markMainPageDirty('inventory','orders.list','orders.po','admin');
    const refreshes=[];
    // 已開始的查詢可能早於這次到貨；等它結束後再讀最新資料，避免合併成過期的刷新。
    const pendingReads=[purchasingReceivingLoadPromise,activeReceivingSupplyLoadPromise].filter(Boolean);
    if(pendingReads.length)await Promise.allSettled(pendingReads);
    contextGuard?.();
    if(inventoryReceivingVisible&&document.getElementById('inventory-system')?.classList.contains('active'))refreshes.push(loadPurchasingReceivingQueue(true));
    else if(canAccessPage('inventory')&&document.getElementById('inventory-system')?.classList.contains('active'))refreshes.push(loadInventory(true));
    if(getDataScope('orders')!=='none')refreshes.push(refreshAffectedOrderCaches([...affectedOrderIds]));
    const results=await Promise.allSettled(refreshes);
    if(results.some(result=>result.status==='rejected'))showActionFeedback('到貨已完成；部分畫面同步失敗，重新進入該頁會再載入。','warning');
}

async function runReceiptTask(job) {
    if(job.state==='running'||job.ownerUid!==currentUser?.uid||(!canReceiveInventoryCapability()&&!['sales','engineer'].includes(currentUserRole)))return;
    const assertJobActor=()=>{if(job.ownerUid!==currentUser?.uid||job.actorRole!==currentUserRole)throw new Error('登入帳號或角色已變更，請以原身分確認到貨結果。');};
    job.state='running';job.error='';
    persistReceiptTasks(job.ownerUid);
    renderReceiptTasks();
    const affectedOrderIds=new Set();
    const supplyId=job.supplyId;
    try {
        assertJobActor();
        for(const entry of job.entries){
            assertJobActor();
            if(currentUser?.uid!==job.ownerUid||(!canReceiveInventoryCapability()&&!['sales','engineer'].includes(currentUserRole)))throw new Error('登入身份已變更，請以原帳號確認到貨結果。');
            const operationId=`${job.operationBase}-${entry.itemIndex}`;
            const ids=await receiveSupplyOrderRecord(supplyId,entry.qty,entry.lotNo,entry.expiryDate,operationId,{actorUid:job.ownerUid,actorRole:job.actorRole,onStockCommitted:invalidateWarehouseStockCache});
            assertJobActor();
            ids.forEach(id=>affectedOrderIds.add(id));
        }
        // 核心資料已確認完成後才移除暫存。保留同一個 operationId 供網路中斷重試。
        assertJobActor();
        clearReceiptOperationId(supplyId,job.operationBase,job.ownerUid);
        job.state='done';
        receiptTaskJobs.delete(receiptTaskKey(supplyId,job.ownerUid));
        persistReceiptTasks(job.ownerUid);
        if(currentUser?.uid!==job.ownerUid||currentUserRole!==job.actorRole)return;
        // 暫時移除這筆舊到貨列；部分到貨餘額由後續查詢帶回，不用舊快取推算數量。
        supplyReceivingCache=supplyReceivingCache.filter(row=>row.id!==supplyId);
        pendingSupplyCache=pendingSupplyCache.filter(row=>row.id!==supplyId);
        document.querySelectorAll('button[data-receipt-supply]').forEach(button=>{
            if(button.dataset.receiptSupply===supplyId){button.dataset.receiptConfirmed='true';button.disabled=true;button.textContent='到貨已確認';}
        });
        renderReceiptTasks();
        showActionFeedback(`${job.label}：到貨已確認。`,'success');
        await refreshReceiptTaskViews(affectedOrderIds,assertJobActor);
    } catch(err) {
        if(job.state==='done'){
            if(currentUser?.uid===job.ownerUid&&currentUserRole===job.actorRole)showActionFeedback('到貨已確認；畫面同步失敗，重新進入該頁會再載入。','warning');
            return;
        }
        // 後續分配可能尚未完成；原收貨資料與識別碼必須保留，不能換成新的一筆。
        job.state='error';
        job.error=err?.code==='receipt-allocation-pending'&&err?.receiptCommitted
            ? '已確認到貨，後續處理尚未完成。請用原資料重試。'
            : `結果待確認：${err.message||err}。請用原資料重試。`;
        persistReceiptTasks(job.ownerUid);
        if(currentUser?.uid===job.ownerUid&&currentUserRole===job.actorRole)renderReceiptTasks();
    }
}

window.savePoReceiptBatch = async function() {
    const poId=poReceiptTargetId;
    if(!poId?.startsWith('supply:')){alert('到貨必須從供應紀錄進入，請重新開啟待到貨品項。');return;}
    const supplyId=poId.slice(7);
    if(receiptTaskBlocksSupply(supplyId))return;
    const rows=[...document.querySelectorAll('#poReceiptBatchBody tr')].filter(row=>row.querySelector('.po-receive-select')?.checked);
    const entries=rows.map(row=>({itemIndex:Number(row.dataset.index),qty:Number(row.querySelector('.po-receive-qty')?.value||0),
        lotNo:(row.querySelector('.po-receive-lot')?.value||'').trim(),expiryDate:row.querySelector('.po-receive-expiry')?.value||''}));
    if(!entries.length||entries.some((entry,index)=>!Number.isFinite(entry.qty)||entry.qty<=0||entry.qty>Number(rows[index].querySelector('.po-receive-qty')?.max)||!Number.isInteger(entry.itemIndex))){
        alert('請勾選到貨品項，數量須大於 0 且不可超過未收數量。');return;
    }
    const operationBase=poReceiptOperationId||ensureReceiptOperationId(supplyId);
    const supply=supplyReceivingCache.find(row=>row.id===supplyId)||pendingSupplyCache.find(row=>row.id===supplyId);
    if(!supply||!canConfirmSupplyReceipt(supply)){showActionFeedback('目前沒有這筆到貨確認權限，請重新開啟訂單。','warning');return;}
    const job={supplyId,operationBase,entries,ownerUid:currentUser.uid,actorRole:currentUserRole,label:supply?.itemCode||supply?.itemName||supplyId,state:'queued',error:''};
    receiptTaskJobs.set(receiptTaskKey(supplyId),job);
    persistReceiptTasks(job.ownerUid);
    // 關閉視窗前先保存獨立快照；後續開啟另一筆不會覆寫這筆的數量、批號或識別碼。
    closePoReceiptBatch();
    showActionFeedback('已開始背景確認到貨，可繼續其他操作；請保持頁面開啟。');
    return runReceiptTask(job);
};
/* =========================================================
   產生採購單：採購把選好的訂單品項，整理成一張要發給供應商的「採購單」，
   格式跟估價單相同，但抬頭是供應商、單價預設帶「含稅成本」而不是賣客戶的售價，
   而且單價在這裡還可以再調整；也可以切換又鑫／辰星／鼎新，套用各公司的抬頭資訊跟單號代碼
   ========================================================= */
let poItems = [];
let poAllItems = [];
let poCurrentCompany = 'yushin';
let poEditingId = null;
let poSaveInProgress = false;
let poDirectStockMode = false;
let poIncomingSyncPending = false;
let poNoGeneration = 0;
let poDirectStockOpenGeneration = 0;
let poNoReady = false;
let poNoLoading = false;
let poDraftLoading = false;

function editingUnconfirmedPurchaseDocument() {
    if(!poEditingId || typeof poListCache==='undefined')return false;
    const po=poListCache.find(row=>row.id===poEditingId);
    return po?.status==='DRAFT' && po.documentOnly===true;
}
function purchaseDocumentHasUnsavedChanges(record) {
    if(document.getElementById('poVendorName')?.value.trim()!==record.vendorName
        || document.getElementById('poDate')?.value!==record.poDate
        || (document.getElementById('poExpectedDate')?.value||'')!==(record.expectedDate||''))return true;
    const fields=['orderId','itemId','productId','warehouseId','fulfillmentType','itemCode','itemName','brand','qty','unitPrice'];
    const intent=items=>items.map(item=>Object.fromEntries(fields.map(key=>[key,
        ['qty','unitPrice'].includes(key)?Number(item[key]):String(item[key]||'')])));
    return JSON.stringify(intent(poItems))!==JSON.stringify(intent(purchaseItemsFromSavedPo(record)));
}
function setPoDraftLoading(loading) {
    poDraftLoading = loading;
    document.querySelectorAll('#poVendorName, #poDate, #poExpectedDate, #poLeadDays, #poItemsBody input, #poItemsBody button, #poModalOverlay .sub-tab').forEach(control => {
        control.disabled = loading || (!!poEditingId && (!editingUnconfirmedPurchaseDocument() || control.matches?.('.sub-tab')));
    });
    updatePoSaveButton();
}

function updatePoSaveStatus(message = '', isError = false) {
    const status = document.getElementById('poSaveStatus');
    if (!status) return;
    status.textContent = message;
    status.style.color = isError ? '#b42318' : '#12502b';
}

function updatePoSaveButton() {
    const button = document.getElementById('printPurchaseOrderBtn');
    if (!button) return;
    const waitingForNumber = !poEditingId && !poNoReady;
    const confirmButton = document.getElementById('confirmPoOrderedBtn');
    if (confirmButton) confirmButton.disabled=poSaveInProgress||poDraftLoading||(typeof formalPurchaseRecoveryRunning!=='undefined'&&formalPurchaseRecoveryRunning);
    const copyButton = document.getElementById('poCopyAsNewBtn');
    if (copyButton) copyButton.disabled = poSaveInProgress;
    button.disabled = poSaveInProgress || waitingForNumber || poDraftLoading;
    button.textContent = poDraftLoading ? '載入採購資料中…' : waitingForNumber
        ? (poNoLoading ? '產生單號中…' : '單號未就緒')
        : poEditingId && !editingUnconfirmedPurchaseDocument() ? '📄 下載 PDF' : '📄 儲存文件並下載 PDF';
}

function purchaseItemsFromSavedPo(po) {
    const sourceItems = [po?.items, po?.orderItems, po?.purchaseItems, po?.lineItems, po?.products]
        .find(items => Array.isArray(items) && items.length)
        || ((po?.itemName || po?.productName || po?.itemCode || po?.productCode) ? [po] : []);
    return sourceItems.map((item, index) => ({
        ...item,
        orderId: item.orderId || item.sourceOrderId || '',
        orderItemIndex: item.orderItemIndex ?? index,
        itemName: item.itemName || item.productName || item.name || item.nameCn || '',
        itemCode: item.itemCode || item.productCode || item.code || item.model || '',
        productId: item.productId || '',
        brand: item.brand || item.manufacturer || '',
        brandId: item.brandId || '',
        qty: parseFloat(item.qty ?? item.quantity ?? item.count) || 1,
        unitPrice: parseFloat(item.unitPrice ?? item.costPrice ?? item.cost ?? item.purchasePrice) || 0
    })).filter(item => item.itemName || item.itemCode);
}

// 將不同時期的訂單品項格式統一成採購單使用的格式。舊資料是一張訂單一個
// itemName/itemCode/qty；新版或匯入資料可能使用 items、orderItems 或 products。
// 只在讀取時轉換，不回寫原訂單，避免 Phase 1 變成資料模型遷移。
function purchaseItemsFromOrder(order) {
    const collections = [order?.items, order?.orderItems, order?.lineItems, order?.products];
    const sourceItems = collections.find(items => Array.isArray(items) && items.length) || [order || {}];
    return sourceItems.map((item, index) => {
        const itemCode = item.itemCode || item.productCode || item.code || item.model || order.itemCode || order.productCode || '';
        const itemName = item.itemName || item.productName || item.name || item.nameCn || order.itemName || order.productName || '';
        const brand = item.brand || item.manufacturer || order.brand || '';
        const qtyValue = item.qty ?? item.quantity ?? item.count ?? (sourceItems.length === 1 ? order.qty ?? order.quantity : 1);
        let cost = parseFloat(item.costPrice ?? item.cost ?? item.purchasePrice ?? (sourceItems.length === 1 ? order.costPrice : NaN));
        {
            const savedProductId = item.productId || order.productId || '';
            const normalizedCode = normalizeItemCode(itemCode);
            const normalizedBrand = String(brand || '').trim().toLocaleLowerCase();
            const priceMatch = (savedProductId && priceList.find(product => product.productId === savedProductId))
                || (normalizedBrand && priceItemLookup.get(`brand:${normalizedBrand}:${normalizedCode}`))
                || priceItemLookup.get(`code:${normalizedCode}`);
            const productId = savedProductId || priceMatch?.productId || (priceMatch ? stableProductId(priceMatch) : '');
            const secureCost = productId ? purchaseCostCache.get(productId) : null;
            if (secureCost !== undefined && secureCost !== null) cost = Number(secureCost);
            else if ((!Number.isFinite(cost) || cost < 0) && priceMatch) {
                cost = parseFloat(priceMatch.cost ?? priceMatch.costPrice ?? priceMatch.purchasePrice);
            }
        }
        const parsedQty=parseFloat(qtyValue);
        const fullQty=Number.isFinite(parsedQty)&&parsedQty>0?parsedQty:1;
        const procurementType=item.procurementType||order.procurementType||'PURCHASING_PO';
        if(procurementType==='SALES_SELF_ORDER') return null;
        // 待採購數量必須與採購頁、訂單工作狀態共用同一公式。
        // shortageQty 會在到貨時下降，不能再直接減累計 supplyOrderedQty，
        // 否則「部分採購已全部到貨、但仍有剩餘缺口」會被誤算成 0。
        const remainingPurchase=remainingProcurementQty(order,item);
        return {
            orderId: order.id,
            orderItemIndex: index,
            itemId:item.itemId||`item-${index+1}`,
            itemName,
            itemCode,
            productId: item.productId || order.productId || '',
            brand,
            brandId: item.brandId || order.brandId || '',
            qty: remainingPurchase,
            productLine: item.productLine || order.productLine || '',
            ownerUid: order.ownerUid || '',
            salesCode: order.salesCode || '',
            salesName: order.salesName || '',
            fulfillmentType: item.fulfillmentType || order.fulfillmentType || 'WAREHOUSE',
            warehouseId: item.warehouseId || order.warehouseId || '',
            unitPrice: Number.isFinite(cost) && cost >= 0 ? cost : null,
            procurementType
        };
    }).filter(item => item && (item.itemName || item.itemCode) && Number(item.qty||0)>0);
}

function bestPurchaseOrderCompany(selectedOrders, items, preferredCompany) {
    const companies = ['yushin', 'morningstar', 'MULTI-LIFE'];
    const savedCompanies = [...new Set(selectedOrders.map(order => order.company).filter(company => companies.includes(company)))];
    if (savedCompanies.length === 1 && items.some(item => isCompanyBrandAllowed(savedCompanies[0], item.brand))) return savedCompanies[0];
    if (companies.includes(preferredCompany) && items.some(item => isCompanyBrandAllowed(preferredCompany, item.brand))) return preferredCompany;
    return companies
        .map(company => ({ company, count: items.filter(item => isCompanyBrandAllowed(company, item.brand)).length }))
        .sort((a, b) => b.count - a.count)[0]?.company || 'yushin';
}

async function openProductManagementProductsInPurchase(products) {
    if (!canEditPage('orders.po') || !products.length) return false;
    const button = actionButtonFromEventOrSelector();
    const state = beginActionButton(button, '載入採購品項…');
    if (button && !state) return false;
    try {
        // Refresh only selected products; never trust a stale selection or scan all costs.
        const refreshed = await Promise.all(products.map(async selected => {
            const id = selected.productId || selected.id;
            const [productSnap, costSnap] = await Promise.all([
                firestoreReadWithTimeout(db.collection('products').doc(id).get(), '讀取採購產品'),
                firestoreReadWithTimeout(db.collection('productCosts').doc(id).get(), '讀取標準成本')
            ]);
            if (!productSnap.exists || productSnap.data().active === false || productSnap.data().status === 'INACTIVE') {
                throw new Error('所選產品已停用或不存在，請重新選取。');
            }
            const costValue = costSnap.exists ? costSnap.data().standardCost ?? costSnap.data().costPrice : null;
            const cost = costValue === null || costValue === undefined ? NaN : Number(costValue);
            return { ...productSnap.data(), productId:id, purchaseCost:Number.isFinite(cost) && cost >= 0 ? cost : null };
        }));
        // The modal opens synchronously before warehouse suggestions finish loading.
        const opening = openDirectStockPurchase(refreshed[0]);
        poItems = refreshed.map(product => ({ ...emptyDirectPoItem(),
            ...productManagementSource(product), unitPrice:product.purchaseCost }));
        poAllItems = poItems;
        renderPoItemsTable();
        updatePoModeUI();
        await opening;
        return true;
    } catch (err) {
        showActionFeedback('加入採購單失敗：' + err.message, 'warning');
        return false;
    } finally { endActionButton(button, state); }
}

window.addProductManagementToPurchase = async function(productId) {
    await openProductManagementProductsInPurchase([{ productId }]);
};

window.addProductManagementSelectionToPurchase = async function() {
    const products = selectedProductManagementProducts();
    if (await openProductManagementProductsInPurchase(products)) clearProductManagementSelection();
};

window.openDirectStockPurchase = async function(product = null) {
    if (!canEditPage('orders.po')) return;
    const openingGeneration = ++poDirectStockOpenGeneration;
    poDirectStockMode = true;
    poEditingId = null;
    poIncomingSyncPending = false;
    poAllItems = [];
    poItems = [];
    document.getElementById('poVendorName').value = '';
    document.getElementById('poBuyerName').innerText = currentUserName || (currentUser ? currentUser.email : '');
    document.getElementById('poDate').value = localDateString();
    clearPoExpectedDate();
    switchPoCompany(currentCompany || 'yushin', null, true);
    generatePoNo();
    addDirectPoItem();
    if(product){
        poItems[0]={...poItems[0],productId:product.productId||product.id,
            itemCode:product.manufacturerPartNo||product.sku||product.model||'',
            itemName:product.productName||product.nameCn||product.nameEn||'',
            brand:resolveBrandName(product.brandName||product.brand||''),
            brandId:product.brandId||'',productLine:product.productLine||'',productType:product.productType||'',
            unitPrice:null};
        renderPoItemsTable();
    }
    updatePoModeUI();
    updatePoSaveStatus('這張採購單尚未建立。確認品項、供應商與單價後，按「儲存文件並下載 PDF」；實際下單後另按「確認已採購」。');
    document.getElementById('poModalOverlay').classList.add('active');

    // 備貨單的空白表單不依賴雲端主檔，先立即顯示；供應商與預設倉庫在背景補齊。
    // 不重畫使用者已經開始輸入的表格，避免慢網路回來時洗掉尚未觸發 change 的文字。
    await loadSupplierWarehouseMasters();
    if (openingGeneration !== poDirectStockOpenGeneration || !poDirectStockMode || poEditingId) return;
    const warehouseId = defaultWarehouse()?.id || '';
    poItems.forEach(item => {
        if (!item.warehouseId) item.warehouseId = warehouseId;
    });
    populatePoVendorSuggestions();
    updatePoModeUI();
};

function emptyDirectPoItem() {
    return {
        orderId:'', sourceType:'STOCK_REPLENISHMENT', sourceId:'',
        itemName:'', itemCode:'', productId:'', brand:'', brandId:'', qty:1, unitPrice:null, supplier:'',
        productLine:'', fulfillmentType:'WAREHOUSE', warehouseId:defaultWarehouse()?.id || ''
    };
}

window.addDirectPoItem = function() {
    poDirectStockMode = true;
    poItems.push(emptyDirectPoItem());
    poAllItems = poItems;
    window.autoFillPoExpectedDate(poItems);
    renderPoItemsTable();
    updatePoModeUI();
};

window.onDirectPoCodeChange = async function(idx, value) {
    if (!poItems[idx]) return;
    const requestedCode = String(value || '').trim();
    const preferredBrand = resolveBrandName(poItems[idx].brand || '');
    poItems[idx] = {
        ...poItems[idx],
        itemCode: requestedCode,
        itemName: '',
        productId: '',
        brand: preferredBrand,
        brandId: brandIdForName(preferredBrand),
        unitPrice: null,
        supplier: '',
        productLine: ''
    };
    poAllItems = poItems;
    const match = requestedCode ? await findProductByCode(requestedCode, preferredBrand) : null;
    if (!poItems[idx] || String(poItems[idx].itemCode || '').trim() !== requestedCode) return;
    if (match) {
        const secureCost = await loadVisibleProductCost(match);
        if (!poItems[idx] || String(poItems[idx].itemCode || '').trim() !== requestedCode) return;
        poItems[idx] = {
            ...poItems[idx],
            itemCode: match.model || requestedCode,
            itemName: match.nameCn || match.nameEn || '',
            productId: match.productId || stableProductId(match),
            brand: resolveBrandName(match.brand || ''),
            brandId: match.brandId || brandIdForName(match.brand || ''),
            unitPrice: secureCost !== null && Number.isFinite(secureCost)
                ? secureCost
                : match.cost !== null && match.cost !== undefined && match.cost !== '' && Number.isFinite(Number(match.cost)) ? Number(match.cost) : null,
            supplier: match.supplier || '',
            productLine: match.productLine || '',
            fulfillmentType: poItems[idx].fulfillmentType || 'WAREHOUSE',
            warehouseId: poItems[idx].warehouseId || defaultWarehouse()?.id || ''
        };
        const mappedSupplier = supplierForProduct(
            match.brand,
            match.productLine,
            match.productId || stableProductId(match),
            match.model || requestedCode
        );
        if (!document.getElementById('poVendorName').value && mappedSupplier) {
            document.getElementById('poVendorName').value = mappedSupplier.purchaseHeaderName || mappedSupplier.supplierName || '';
        } else if (!document.getElementById('poVendorName').value && match.supplier) {
            document.getElementById('poVendorName').value = match.supplier;
        }
    }
    poAllItems = poItems;
    window.autoFillPoExpectedDate(poItems);
    renderPoItemsTable();
};

window.updateDirectPoText = function(idx, field, value) {
    if (!poItems[idx]) return;
    poItems[idx][field] = field === 'brand' ? resolveBrandName(value) : String(value || '').trim();
    if (field === 'brand') {
        poItems[idx].brandId = brandIdForName(poItems[idx].brand);
        if (poItems[idx].itemCode) {
            onDirectPoCodeChange(idx, poItems[idx].itemCode);
            return;
        }
    }
    poAllItems = poItems;
    window.autoFillPoExpectedDate(poItems);
};

function updatePoModeUI() {
    const leadDays=document.getElementById('poLeadDays');
    if(leadDays)leadDays.disabled=!!poEditingId;
    const addBtn = document.getElementById('poAddStockItemBtn');
    const hint = document.getElementById('poModeHint');
    const brandList = document.getElementById('poBrandList');
    const overlay = document.getElementById('poModalOverlay');
    const title = document.getElementById('poModalTitle');
    const existingBanner = document.getElementById('poExistingBanner');
    const existingNumber = document.getElementById('poExistingNumber');
    const copyBtn = document.getElementById('poCopyAsNewBtn');
    if (brandList) brandList.innerHTML = getUnifiedBrandNames(false).map(name => `<option value="${escapeAttr(name)}"></option>`).join('');

    const viewingExisting = !!poEditingId;
    overlay?.classList.toggle('po-viewing-existing', viewingExisting && !editingUnconfirmedPurchaseDocument());
    if (title) title.textContent = viewingExisting ? '查看採購單' : '建立採購單';
    if (existingBanner) existingBanner.style.display = viewingExisting ? 'flex' : 'none';
    if (existingNumber) existingNumber.textContent = viewingExisting ? (document.getElementById('poNo')?.innerText || poEditingId) : '';

    const savedPo = viewingExisting ? poListCache.find(po => po.id === poEditingId) : null;
    const canCopySafely = !!savedPo && canCreatePurchaseOrderCapability() && canEditPage('orders.po');
    if (copyBtn) { copyBtn.style.display = canCopySafely ? '' : 'none'; copyBtn.disabled = poSaveInProgress; }
    const timelineBtn = document.getElementById('poViewHistoryBtn');
    if (timelineBtn) timelineBtn.style.display = viewingExisting ? '' : 'none';
    const cancelBtn = document.getElementById('poCancelOutstandingBtn');
    const hasOutstanding = !!savedPo && !isPurchaseTerminalStatus(savedPo.status) && purchaseItemsFromSavedPo(savedPo).some((_, index) => Number(purchaseHistoryItemReceiptProgress(savedPo, index).remainingQty) > 0);
    const confirmBtn = document.getElementById('confirmPoOrderedBtn');
    if (confirmBtn) { confirmBtn.hidden = !savedPo || savedPo.status!=='DRAFT'; confirmBtn.disabled=poSaveInProgress||poDraftLoading; }
    setPoDraftLoading(poDraftLoading);
    if (cancelBtn) cancelBtn.style.display = canCopySafely && hasOutstanding ? '' : 'none';
    const supplierContact = savedPo ? purchaseOrderSupplierContact(savedPo) : purchaseOrderSupplierContact({vendorName:document.getElementById('poVendorName')?.value||''});

    if (addBtn) addBtn.style.display = !viewingExisting && poDirectStockMode ? '' : 'none';
    if (hint) hint.textContent = viewingExisting
        ? savedPo?.status==='DRAFT' ? '這是尚未確認採購的文件；下載 PDF 不增加在途，實際下單後請按「確認已採購」。' : '這是已確認的採購單。內容鎖定；重新匯出 PDF 不重複登記採購。'
        : poDirectStockMode
            ? '製作庫存採購文件：可加入多個品項；確認已採購後才列入在途庫存。'
            : '訂單採購：品項來自業務訂單，可調整採購數量與進貨單價。';
    updatePoSaveButton();
}


function clearPoExpectedDate() {
    const days=document.getElementById('poLeadDays');
    if(days)days.value='';
    const input=document.getElementById('poExpectedDate');
    if(!input)return;
    input.value='';
    delete input.dataset.expectedDateSource;
    syncPoLeadDays();
}

window.markPoExpectedDateManual = function() {
    const input=document.getElementById('poExpectedDate');
    if(input)input.dataset.expectedDateSource='manual';
};

window.autoFillPoExpectedDate = function(items = poItems, preferredSupplierId = '') {
    const input=document.getElementById('poExpectedDate');
    if(!input || poEditingId)return input?.value||'';
    if(input.dataset.expectedDateSource==='manual') {
        if(document.getElementById('poLeadDays')?.value!=='')window.setPoLeadDays();
        return input.value||'';
    }
    if(!globalThis.YushinSupplier?.purchaseExpectedDate)return '';

    const vendorName=String(document.getElementById('poVendorName')?.value||'').trim();
    const liveSupplier=supplierForVendorName(vendorName);
    const supplierId=String(preferredSupplierId||liveSupplier?.id||liveSupplier?.supplierId||'').trim();
    const supplier=supplierMasterCache.find(item =>
        String(item.id||item.supplierId||'')===supplierId
    )||liveSupplier||null;
    const orderDate=String(document.getElementById('poDate')?.value||'').trim();
    const expected=globalThis.YushinSupplier.purchaseExpectedDate(
        items||[],
        supplier||0,
        orderDate
    );

    if(expected){
        input.value=expected;
        input.dataset.expectedDateSource='lead-time';
    }else if(input.dataset.expectedDateSource==='lead-time'){
        input.value='';
        delete input.dataset.expectedDateSource;
    }
    syncPoLeadDays();
    return expected;
};

function syncPoLeadDays() {
    const days=document.getElementById('poLeadDays');
    const date=document.getElementById('poExpectedDate')?.value;
    const ordered=document.getElementById('poDate')?.value;
    if(days)days.value=date&&ordered?Math.max(0,(Date.parse(date)-Date.parse(ordered))/86400000):'';
    const hint=document.getElementById('poExpectedDateHint');
    if(hint)hint.textContent=date?`預計 ${date} 到貨`:'未設定交期';
}

window.setPoLeadDays = function() {
    if(poEditingId)return;
    const days=document.getElementById('poLeadDays');
    const date=document.getElementById('poExpectedDate');
    const ordered=document.getElementById('poDate')?.value;
    if(!days||!date)return;
    const value=Number(days.value);
    if(days.value===''||!ordered){date.value='';delete date.dataset.expectedDateSource;}
    else if(Number.isInteger(value)&&value>=0){
        const expected=new Date(ordered+'T00:00:00Z');
        expected.setUTCDate(expected.getUTCDate()+value);
        date.value=expected.toISOString().slice(0,10);
        date.dataset.expectedDateSource='manual';
    }else{
        date.value='';delete date.dataset.expectedDateSource;
        const hint=document.getElementById('poExpectedDateHint');
        if(hint)hint.textContent='請輸入 0 或以上的整數天數';
        return;
    }
    const hint=document.getElementById('poExpectedDateHint');
    if(hint)hint.textContent=date.value?`預計 ${date.value} 到貨`:'未設定交期';
};

function poItemsWithScheduleDates(items = [], supplierId = '', orderDate = '', headerExpectedDate = '', expectedDateSource = '') {
    const manualHeader = expectedDateSource === 'manual'
        || (!!headerExpectedDate && expectedDateSource !== 'lead-time');
    const supplier=supplierMasterCache.find(item =>
        String(item.id||item.supplierId||'')===String(supplierId||'')
    )||null;
    return (items || []).map(item => {
        let scheduleDate = '';
        if (manualHeader) {
            scheduleDate = headerExpectedDate || '';
        } else if (supplier && globalThis.YushinSupplier?.itemExpectedArrivalDate) {
            scheduleDate = globalThis.YushinSupplier.itemExpectedArrivalDate(item,supplier,orderDate);
        }
        return { ...item, scheduleDate };
    });
}

async function autoFillPoSupplier(items, isCurrent = () => true) {
    await loadSupplierWarehouseMasters();
    if (!isCurrent()) return '';
    const rows=items||[];
    const resolved = rows.map(item => supplierForProduct(
        item.brand,
        item.productLine,
        item.productId,
        item.itemCode
    )).filter(Boolean);
    if (!resolved.length) {
        window.autoFillPoExpectedDate(rows,'__unresolved__');
        return '';
    }
    const ids = [...new Set(resolved.map(item => item.id || item.supplierId))];
    if (ids.length !== 1) {
        window.autoFillPoExpectedDate(rows,'__multiple__');
        return '';
    }
    const supplier = resolved[0];
    const header = supplier.purchaseHeaderName || supplier.supplierName || '';
    const input = document.getElementById('poVendorName');
    if (input && header) input.value = header;
    window.autoFillPoExpectedDate(rows,ids[0]);
    return header;
}

function populatePoVendorSuggestions() {
    const list = document.getElementById('poVendorSuggestions');
    if (!list) return;
    const vendorsByKey = new Map();
    const addVendor = name => {
        const value=String(name||'').trim();
        if(!value)return;
        const key=value.normalize('NFKC').replace(/\s+/g,' ').toLocaleLowerCase();
        if(!vendorsByKey.has(key))vendorsByKey.set(key,value);
    };
    supplierMasterCache.forEach(supplier=>addVendor(supplier.purchaseHeaderName||supplier.supplierName));
    poListCache.forEach(po=>addVendor(po.vendorName));
    list.innerHTML = '';
    [...vendorsByKey.values()]
        .sort((a, b) => a.localeCompare(b, 'zh-Hant'))
        .forEach(name => {
            const option = document.createElement('option');
            option.value = name;
            list.appendChild(option);
        });
}

window.closePurchaseOrderModal = function() {
    poDirectStockOpenGeneration++;
    poNoGeneration++;
    poNoLoading = false;
    poNoReady = false;
    setPoDraftLoading(false);
    document.getElementById('poModalOverlay').classList.remove('active');
};

// 切換採購單要用哪間公司的抬頭／單號代碼（又鑫 YS／辰星 MS／鼎新 DS），跟估價單的公司切換邏輯一致
window.switchPoCompany = function(compKey, el, skipNoGen) {
    if ((poDraftLoading || poEditingId) && !skipNoGen) return;
    poCurrentCompany = compKey;
    document.querySelectorAll('#poModalOverlay .sub-nav .sub-tab').forEach(t => t.classList.remove('active'));
    const targetTab = document.getElementById(`po-sub-${compKey}`);
    if (targetTab) targetTab.classList.add('active');
    else if (el) el.classList.add('active');

    const info = companyData[compKey];
    if (info) {
        document.getElementById('poCompTitle').innerText = info.title;
        document.getElementById('poCompSub').innerText = info.sub;
        document.getElementById('poCompAddr').innerText = info.addr;
        document.getElementById('poCompContact').innerHTML = info.contact;
    }

    // 依管理員設定，採購單只帶入該分公司代理的廠牌；切換分公司時立即重新篩選。
    if (!skipNoGen && poAllItems.length) {
        poItems = poAllItems.filter(item => isCompanyBrandAllowed(compKey, item.brand));
        renderPoItemsTable();
    }

    // 重新列印「採購訂單」裡舊有的採購單時，要沿用當初存的單號，不能在這裡重新產生一個新的
    if (!skipNoGen) generatePoNo();
};

// 採購單號格式：PO-{公司代碼}-{日期}-{採購代號}-{流水號}，跟估價單單號的組成方式一致，
// 例如又鑫、代號 03 的採購，會是 PO-YS-20260824-03-01。
// 流水號是真的依照雲端已經產生過幾張採購單去算「目前最大流水號 + 1」，不是隨機亂數，
// 邏輯跟估價單的 generateQuoteNo 一致，這樣才能保證同一天同一間公司不會撞號
window.generatePoNo = async function() {
    const info = companyData[poCurrentCompany];
    if (!info) return '';
    const generation = ++poNoGeneration;
    const dateStr = getFormattedDateCode();
    const purchaserCode = currentUserCode || '01';
    const prefix = `PO-${info.prefix}-${dateStr}-${purchaserCode}-`;
    const numberEl = document.getElementById('poNo');

    poNoReady = false;
    poNoLoading = true;
    if (numberEl) numberEl.innerText = '產生中…';
    updatePoSaveButton();

    try {
        const snapshot = await firestoreReadWithTimeout(
            db.collection('purchaseOrders')
                .where('poNo', '>=', prefix)
                .where('poNo', '<=', prefix + '\uf8ff')
                .orderBy('poNo', 'desc')
                .limit(1)
                .get(),
            '採購單號'
        );

        // 使用者可能在查詢尚未回來時切換公司、關閉視窗或開啟另一張單。
        // 舊查詢結果不得再覆蓋目前畫面。
        if (generation !== poNoGeneration) return '';

        let maxSeq = 0;
        snapshot.forEach(doc => {
            const seqStr = (doc.data().poNo || '').split('-').pop();
            const seq = parseInt(seqStr, 10);
            if (!isNaN(seq) && seq > maxSeq) maxSeq = seq;
        });
        const nextNo = `${prefix}${String(maxSeq + 1).padStart(2, '0')}`;
        if (numberEl) numberEl.innerText = nextNo;
        poNoReady = true;
        return nextNo;
    } catch (e) {
        if (generation !== poNoGeneration) return '';
        // 查不到目前最大流水號時不能直接假設 01；那可能撞到已存在的正式 PO。
        if (numberEl) numberEl.innerText = '—';
        poNoReady = false;
        updatePoSaveStatus('採購單號讀取失敗，請切換公司或重新開啟後再試。', true);
        return '';
    } finally {
        if (generation === poNoGeneration) {
            poNoLoading = false;
            updatePoSaveButton();
        }
    }
};

function renderPoItemsTable() {
    const tbody = document.getElementById('poItemsBody');
    tbody.innerHTML = '';
    poItems.forEach((item, idx) => {
        const missingPrice = item.unitPrice === null || item.unitPrice === undefined || item.unitPrice === '' || !Number.isFinite(Number(item.unitPrice)) || Number(item.unitPrice) < 0;
        const tr = document.createElement('tr');
        if (poDirectStockMode) {
            tr.innerHTML = `
                <td style="border:1px solid #999;padding:4px;"><input type="text" value="${escapeAttr(item.itemName||'')}" placeholder="品名" style="width:100%;box-sizing:border-box;" onchange="updateDirectPoText(${idx},'itemName',this.value)"></td>
                <td style="border:1px solid #999;padding:4px;"><input type="text" list="priceModelList" value="${escapeAttr(item.itemCode||'')}" placeholder="貨號" style="width:100%;box-sizing:border-box;" onchange="onDirectPoCodeChange(${idx},this.value)"></td>
                <td style="border:1px solid #999;padding:4px;"><input type="text" list="poBrandList" value="${escapeAttr(item.brand||'')}" placeholder="廠牌" style="width:100%;box-sizing:border-box;" onchange="updateDirectPoText(${idx},'brand',this.value)"></td>
                <td style="border:1px solid #999;padding:4px;"><input type="number" min="0.0001" step="any" value="${item.qty||1}" style="width:100%;box-sizing:border-box;" onchange="updatePoItem(${idx},'qty',this.value)"></td>
                <td style="border:1px solid #999;padding:4px;"><input type="number" min="0" step="0.01" value="${missingPrice?'':item.unitPrice}" placeholder="未稅進貨單價" class="${missingPrice?'po-missing-price':''}" style="width:100%;box-sizing:border-box;" onchange="updatePoItem(${idx},'unitPrice',this.value)"></td>
                <td style="border:1px solid #999;padding:4px;text-align:right;">${(Number(item.qty||0)*Number(item.unitPrice||0)).toFixed(0)}</td>
                <td class="no-print" style="border:1px solid #999;padding:4px;text-align:center;"><button type="button" class="btn-small btn-danger" onclick="removePoItem(${idx})">刪除</button></td>
            `;
        } else {
            tr.innerHTML = `
                <td style="border:1px solid #999;padding:4px;"><input type="text" value="${escapeAttr(item.itemName||'')}" placeholder="品名" style="width:100%;box-sizing:border-box;" onchange="updateDirectPoText(${idx},'itemName',this.value)"></td>
                <td style="border:1px solid #999;padding:4px;"><input type="text" list="priceModelList" value="${escapeAttr(item.itemCode||'')}" placeholder="貨號" style="width:100%;box-sizing:border-box;" onchange="onDirectPoCodeChange(${idx},this.value)"></td>
                <td style="border:1px solid #999;padding:4px;"><input type="text" list="poBrandList" value="${escapeAttr(item.brand||'')}" placeholder="廠牌" style="width:100%;box-sizing:border-box;" onchange="updateDirectPoText(${idx},'brand',this.value)"></td>
                <td style="border:1px solid #999;padding:4px;"><input type="number" step="1" value="${item.qty}" style="width:100%;box-sizing:border-box;" onchange="updatePoItem(${idx}, 'qty', this.value)"></td>
                <td style="border:1px solid #999;padding:4px;"><input type="number" min="0.01" step="0.01" value="${missingPrice ? '' : item.unitPrice}" placeholder="請填進貨單價" class="${missingPrice ? 'po-missing-price' : ''}" style="width:100%;box-sizing:border-box;" onchange="updatePoItem(${idx}, 'unitPrice', this.value)">${missingPrice ? '<small class="po-missing-price-hint">缺少成本</small>' : ''}</td>
                <td style="border:1px solid #999;padding:4px;text-align:right;">${(item.qty * item.unitPrice).toFixed(0)}</td>
                <td class="no-print" style="border:1px solid #999;padding:4px;text-align:center;"><button type="button" class="btn-small btn-danger" onclick="removePoItem(${idx})">刪除</button></td>
            `;
        }
        tbody.appendChild(tr);
    });
    recalcPoTotals();
    setPoDraftLoading(poDraftLoading);
}

window.updatePoItem = function(idx, field, value) {
    if (poDraftLoading || (poEditingId&&!editingUnconfirmedPurchaseDocument()) || !poItems[idx] || !['qty','unitPrice'].includes(field)) return;
    poItems[idx][field] = field === 'unitPrice' && String(value).trim() === '' ? null : parseFloat(value);
    // Keep focused inputs mounted: a change handler must not replace the next
    // input after the browser has already moved focus into it.
    const row = document.getElementById('poItemsBody')?.children[idx];
    if (row) {
        row.cells[5].textContent=(Number(poItems[idx].qty||0)*Number(poItems[idx].unitPrice||0)).toFixed(0);
        const price=row.querySelector('input[onchange*=unitPrice]');
        if(price)price.classList.toggle('po-missing-price',poItems[idx].unitPrice===null);
        if(poItems[idx].unitPrice!==null)row.querySelector('.po-missing-price-hint')?.remove();
    }
    recalcPoTotals();
};

window.removePoItem = function(idx) {
    const removed = poItems[idx];
    poItems.splice(idx, 1);
    poAllItems = poAllItems.filter(item => item !== removed);
    window.autoFillPoExpectedDate(poItems);
    renderPoItemsTable();
};

function recalcPoTotals() {
    const amounts=globalThis.YushinSupplier.purchaseAmountMetadata(poItems);
    document.getElementById('poSubtotal').innerText = amounts.subtotalExTax.toLocaleString();
    document.getElementById('poTax').innerText = amounts.taxAmount.toLocaleString();
    document.getElementById('poGrandTotal').innerText = amounts.totalIncTax.toLocaleString();
}

function formalSupplyOrderId(purchaseOrderId, itemIndex) {
    return `po-${encodeURIComponent(String(purchaseOrderId||''))}-${Number(itemIndex||0)}`;
}

function assertPurchaseLinesAvailable(order, lines) {
    if(orderInventorySyncIncomplete(order))throw new Error('來源訂單庫存尚未同步完成，請稍後再採購。');
    if (normalizedOrderStatus(order) !== 'normal') throw new Error('來源訂單已取消或作廢。');
    const sourceItems = normalizedOrderItems(order);
    const requestedByIndex = new Map();
    for (const line of lines) {
        const index = Number(line.orderItemIndex);
        const source = sourceItems[index];
        const sourceItemCode = String(source?.itemCode || '').trim();
        const lineItemCode = String(line?.itemCode || '').trim();
        const stableItemMismatch = !!(line?.itemId && source?.itemId && line.itemId !== source.itemId);
        if (!Number.isInteger(index) || !source || stableItemMismatch
            || (sourceItemCode && lineItemCode && sourceItemCode !== lineItemCode)) {
            throw new Error('來源訂單品項已變更，請重新建立採購單。');
        }
        requestedByIndex.set(index, (requestedByIndex.get(index) || 0) + Number(line.qty || 0));
    }
    for (const [index, qty] of requestedByIndex) {
        const source = sourceItems[index];
        const remaining = remainingProcurementQty(order, source);
        if (!(qty > 0) || qty > remaining + 1e-9) throw new Error('待採購數量已變更，請重新開啟來源訂單。');
    }
}

function poPdfFileName(poNo, vendorName) {
    const raw = [poNo, vendorName].filter(Boolean).join('-') || '採購單';
    return raw.replace(/[\\/:*?"<>|]+/g, '-').replace(/\s+/g, ' ').trim() + '.pdf';
}

function normalizePoPdfFields(root) {
    const expected=root.querySelector('#poExpectedDate');
    if(expected){const label=expected.parentElement.querySelector('label[style]');if(label)label.style.display='';}
    root.querySelectorAll('.no-print').forEach(node => node.remove());
    root.querySelectorAll('input').forEach(input => {
        const span = document.createElement('span');
        span.className = 'po-pdf-field-value';
        span.textContent = input.value || '';
        input.replaceWith(span);
    });
    root.querySelectorAll('[id]').forEach(node => node.removeAttribute('id'));
}

function createPoPdfStage() {
    const source = document.getElementById('printablePO');
    if (!source) throw new Error('找不到採購單內容');

    const stage = document.createElement('div');
    stage.className = 'quote-pdf-stage po-pdf-stage';
    const documentNode = document.createElement('div');
    documentNode.className = 'po-pdf-document po-pdf-page';
    const text = id => document.getElementById(id)?.textContent || '';
    const value = id => document.getElementById(id)?.value || '';
    documentNode.innerHTML = `
        <div class="header-container"><div class="header-info">
            <h1>${escapeHtml(text('poCompTitle'))}</h1><h2>${escapeHtml(text('poCompSub'))}</h2>
            <p>${escapeHtml(text('poCompAddr'))}</p><p>${escapeHtml(text('poCompContact'))}</p>
        </div></div>
        <h2 style="text-align:center;letter-spacing:10px;margin:10px 0;">採 購 單</h2>
        <div class="meta-row-three">
            <div>抬頭：${escapeHtml(value('poVendorName'))}</div>
            <div>採購人員：${escapeHtml(text('poBuyerName'))}</div>
            <div>採購日期：${escapeHtml(value('poDate'))}</div>
        </div>
        <div class="meta-row-three"><div>預計到貨日：${escapeHtml(value('poExpectedDate'))}</div><div>單號：${escapeHtml(text('poNo'))}</div></div>
        <table style="width:100%;margin-top:8px;border-collapse:collapse;">
            <thead><tr><th>品名 / 規格</th><th>貨號</th><th>廠牌</th><th>數量</th><th>單價</th><th>小計</th></tr></thead>
            <tbody>${poItems.map(item => `<tr><td>${escapeHtml(item.itemName||'')}${item.spec?`<br>${escapeHtml(item.spec)}`:''}</td><td>${escapeHtml(item.itemCode||'')}</td><td>${escapeHtml(item.brand||'')}</td><td>${Number(item.qty||0)}</td><td>${Number(item.unitPrice||0).toLocaleString('zh-TW')}</td><td>${(Number(item.qty||0)*Number(item.unitPrice||0)).toLocaleString('zh-TW')}</td></tr>`).join('')}</tbody>
        </table>
        <div class="po-total-section" style="text-align:right;margin-top:10px;">
            <p>未稅合計：NT$ ${escapeHtml(text('poSubtotal'))}</p><p>營業稅（5%）：NT$ ${escapeHtml(text('poTax'))}</p><p><b>總計金額：NT$ ${escapeHtml(text('poGrandTotal'))}</b></p>
        </div>`;
    stage.appendChild(documentNode);
    document.body.appendChild(stage);
    return { stage, documentNode };
}

function createPoPdfPage(stage, source, includeHeader = false) {
    const page = document.createElement('div');
    page.className = 'po-pdf-page';

    const sourceTable = source.querySelector('table');
    if (includeHeader) {
        for (const child of [...source.children]) {
            if (child === sourceTable) break;
            page.appendChild(child.cloneNode(true));
        }
    }

    const table = sourceTable.cloneNode(false);
    table.removeAttribute('id');
    const thead = sourceTable.querySelector('thead');
    if (thead) table.appendChild(thead.cloneNode(true));
    const tbody = document.createElement('tbody');
    table.appendChild(tbody);
    page.appendChild(table);
    stage.appendChild(page);
    return { page, tbody };
}

function paginatePoPdfDocument(stage, source) {
    const sourceTable = source.querySelector('table');
    if (!sourceTable) return [source];
    const rows = [...sourceTable.querySelectorAll('tbody tr')];
    const summary = source.querySelector('.po-total-section');
    const maxHeight = quotePdfPageHeightPx(stage);

    source.style.display = 'none';
    const pages = [];
    let current = createPoPdfPage(stage, source, true);
    pages.push(current);

    for (const row of rows) {
        const clone = row.cloneNode(true);
        current.tbody.appendChild(clone);
        if (current.page.scrollHeight > maxHeight && current.tbody.children.length > 1) {
            clone.remove();
            current = createPoPdfPage(stage, source, false);
            pages.push(current);
            current.tbody.appendChild(clone);
        }
    }

    if (summary) {
        const summaryClone = summary.cloneNode(true);
        current.page.appendChild(summaryClone);
        if (current.page.scrollHeight > maxHeight) {
            summaryClone.remove();
            const donor = current;
            const finalPage = createPoPdfPage(stage, source, false);
            pages.push(finalPage);
            finalPage.page.appendChild(summaryClone);

            // 與估價單相同：最後一頁優先保留合計區，再把前頁最後的品項往後搬，
            // 只要超出 A4 可用高度就立即放回，避免產生大片空白或切到合計內容。
            while (donor.tbody.lastElementChild) {
                const candidate = donor.tbody.lastElementChild;
                finalPage.tbody.prepend(candidate);
                if (finalPage.page.scrollHeight > maxHeight) {
                    donor.tbody.appendChild(candidate);
                    break;
                }
            }
        }
    }

    source.remove();
    return pages.map(entry => entry.page);
}

async function printSavedPoDocument(poNo, vendorName) {
    const options=arguments[2]||{};
    let stage = null;
    const button = document.getElementById('printPurchaseOrderBtn');
    const download = options.download !== false;
    const modalGeneration = poDirectStockOpenGeneration;
    const exportingPoId = poEditingId;
    try {
        if (typeof window.html2canvas !== 'function' || !window.jspdf?.jsPDF) {
            throw new Error('PDF 元件尚未載入');
        }

        if (button) {
            button.disabled = true;
            button.innerText = download ? '準備 PDF…' : '準備附件…';
        }
        updatePoSaveStatus(download ? '正在準備採購單 PDF…' : '正在準備郵件附件…');

        const exportDom = createPoPdfStage();
        stage = exportDom.stage;
        await waitForPdfImages(exportDom.documentNode);

        const isSinglePage = exportDom.documentNode.scrollHeight <= quotePdfPageHeightPx(stage) - 12;
        const pages = isSinglePage ? [exportDom.documentNode] : paginatePoPdfDocument(stage, exportDom.documentNode);
        if (!isSinglePage) await waitForPdfImages(stage);

        const isMobile = /Android|iPhone|iPad|iPod/i.test(navigator.userAgent);
        const scale = isMobile ? 1.15 : 1.65;
        const pdf = new window.jspdf.jsPDF({ orientation:'portrait', unit:'mm', format:'a4', compress:!isSinglePage });

        await addDocumentPagesToPdf(pdf, pages, {
            scale,
            isolateRoot:stage,
            onProgress: (pageNo, pageCount) => {
                if (button) button.innerText = `正在產生 PDF… ${pageNo}/${pageCount}`;
                updatePoSaveStatus(`正在產生採購單 PDF… ${pageNo}/${pageCount}`);
            }
        });

        const fileName=poPdfFileName(poNo, vendorName);
        const blob=pdf.output('blob');
        if(download){
            if (button) button.innerText = '正在下載 PDF…';
            if (await window.DocumentDownloads.savePdf('purchase', pdf, fileName) === false) {
                updatePoSaveStatus('採購單 PDF 已產生；已取消匯出');
                return {blob,fileName};
            }
            updatePoSaveStatus('✓ 採購單 PDF 已產生');
            if(poDirectStockOpenGeneration===modalGeneration&&poEditingId===exportingPoId)closePurchaseOrderModal();
            showActionFeedback(`採購單 ${poNo} PDF 已匯出。`,'success');
        }else{
            updatePoSaveStatus('✓ 採購單 PDF 附件已準備');
        }
        return {blob,fileName};
    } finally {
        stage?.remove();
    }
}

window.printPurchaseOrder = async function() {
    if (poSaveInProgress || poDraftLoading) return;
    if (!canCreatePurchaseOrderCapability() || !canAccessPage('orders.po')) return;
    const leadDaysInput=document.getElementById('poLeadDays');
    if((!poEditingId||editingUnconfirmedPurchaseDocument())&&leadDaysInput?.value&&(!Number.isInteger(Number(leadDaysInput.value))||Number(leadDaysInput.value)<0)){
        updatePoSaveStatus('預計交期請輸入 0 或以上的整數天數。',true);
        return;
    }
    if (!poEditingId && !poNoReady) {
        updatePoSaveStatus(poNoLoading ? '採購單號仍在產生中，完成後即可列印 / 存為 PDF。' : '採購單號尚未就緒，請切換公司或重新開啟後再試。', !poNoLoading);
        return;
    }
    const actorUid=currentUser?.uid, actorRole=currentUserRole;
    const originalDraft=editingUnconfirmedPurchaseDocument()?poListCache.find(po=>po.id===poEditingId):null;
    poSaveInProgress = true;
    try { await window.DocumentDownloads.prepare('purchase'); }
    catch (err) { updatePoSaveStatus(err.message, true); return; }
    finally { poSaveInProgress = false; }
    if (poEditingId && !originalDraft) {
        const savedPo=poListCache.find(po=>po.id===poEditingId);
        if(!savedPo){alert('找不到已儲存的採購文件，請重新整理。');return;}
        poSaveInProgress=true;updatePoSaveButton();
        try { await printSavedPoDocument(savedPo.poNo,savedPo.vendorName); }
        catch(err){ updatePoSaveStatus('採購文件已儲存，但 PDF 輸出失敗：'+err.message,true); }
        finally { poSaveInProgress=false;updatePoSaveButton(); }
        return;
    }
    if (poItems.length === 0) {
        alert('目前沒有任何品項，請先選取或不要刪光所有品項。');
        return;
    }
    if (poItems.some(item => !Number.isFinite(Number(item.qty)) || Number(item.qty) <= 0)) {
        alert('每個採購品項的數量都必須大於 0。');
        return;
    }
    if (poDirectStockMode && poItems.some(item => (item.fulfillmentType || 'WAREHOUSE') === 'DIRECT_SHIP')) {
        alert('新增庫存採購單是公司庫存採購，不能設定為原廠直送。');
        return;
    }
    if (poDirectStockMode && poItems.some(item => !String(item.warehouseId || defaultWarehouse()?.id || '').trim())) {
        alert('新增庫存採購單必須指定入庫倉庫，請先建立或選擇倉庫。');
        return;
    }
    if (poDirectStockMode) {
        const unmatchedStockItems = poItems.filter(item => {
            const productId = String(item.productId || '').trim();
            const match = findPriceItemForOrder({ itemCode:item.itemCode || '', brand:item.brand || '' });
            if (!productId || !match) return true;
            const matchedProductId = String(match.productId || stableProductId(match) || '').trim();
            return matchedProductId !== productId
                || normalizeBrandLookupKey(match.brand || '') !== normalizeBrandLookupKey(item.brand || '');
        });
        if (unmatchedStockItems.length) {
            alert('庫存採購的每個品項都必須對應產品主檔。請重新選擇有效貨號後再建立採購單。');
            return;
        }
    }
    if (poItems.some(item => (item.fulfillmentType || 'WAREHOUSE') !== 'DIRECT_SHIP' && !String(item.warehouseId || defaultWarehouse()?.id || '').trim())) {
        alert('入庫品項必須有倉庫，請先在倉庫管理建立預設倉庫。');
        return;
    }
    const invalidIdentityItems = poItems.filter(item => !String(item.itemCode||'').trim() || !String(item.itemName||'').trim() || !String(item.brand||'').trim());
    if (invalidIdentityItems.length) {
        alert('請完成每個採購品項的貨號、品名與廠牌。');
        return;
    }
    const missingPriceItems = poItems.filter(item => item.unitPrice === null || item.unitPrice === undefined || item.unitPrice === '' || !Number.isFinite(Number(item.unitPrice)) || Number(item.unitPrice) < 0);
    if (missingPriceItems.length) {
        alert(`以下品項尚未填入有效的進貨單價：${missingPriceItems.map(item => item.itemName || item.itemCode || '未命名品項').join('、')}`);
        return;
    }
    // 訂單裡存的廠牌，如果當初是透過估價單「其他（自行輸入）」填的自訂名稱，不會出現在正式廠牌清單裡；
    // 只要目前公司有開放「其他廠牌」，這種自訂名稱就不能當作違規
    if (poItems.some(item => !isCompanyBrandAllowed(poCurrentCompany, item.brand) && !isCompanyOtherOptionAllowed(poCurrentCompany))) {
        alert('採購單含有不屬於目前分公司代理的廠牌，請切換分公司或移除該品項。');
        return;
    }
    const vendorName = document.getElementById('poVendorName').value.trim();
    if (!vendorName) {
        alert('請填寫供應商名稱。');
        return;
    }
    const poNo = document.getElementById('poNo').innerText.trim();
    if (!poNo || poNo === '產生中…' || poNo === '—') {
        updatePoSaveStatus('採購單號尚未就緒，請切換公司或重新開啟後再試。', true);
        return;
    }
    const orderIds = [...new Set(poItems.map(item => item.orderId).filter(Boolean))];
    const supplierContact = supplierForVendorName(vendorName);
    if (!globalThis.YushinSupplier?.snapshotForPurchaseOrder) {
        throw new Error('Supplier core 未載入，無法建立供應商快照。');
    }
    const supplierSnapshot=globalThis.YushinSupplier.snapshotForPurchaseOrder(
        supplierContact||{},
        {supplierName:vendorName,purchaseHeaderName:vendorName}
    );
    const poDate=document.getElementById('poDate').value;
    const expectedDateInput=document.getElementById('poExpectedDate');
    const expectedDate=expectedDateInput?.value||'';
    const expectedDateSource=expectedDateInput?.dataset.expectedDateSource
        || (expectedDate ? 'manual' : '');
    const scheduledPoItems=poItemsWithScheduleDates(
        poItems,
        supplierSnapshot.supplierId||'',
        poDate,
        expectedDate,
        expectedDateSource
    );
    const poRecord = {
        poNo,
        company: poCurrentCompany,
        vendorName:supplierSnapshot.purchaseHeaderName||vendorName,
        supplierId:supplierSnapshot.supplierId||'',
        supplierName:supplierSnapshot.supplierName||vendorName,
        supplierEmail:supplierSnapshot.email||'',
        supplierSnapshot,
        buyerName: document.getElementById('poBuyerName').innerText || currentUserName || '',
        poDate,
        expectedDate,
        expectedDateSource,
        scheduleDate:expectedDate,
        purchaseType: poItems.every(item => !item.orderId) ? 'stock' : 'order',
        items: scheduledPoItems.map(item => {
            const brand = resolveBrandName(item.brand || '');
            return { ...item, brand, brandId:item.brandId || brandIdForName(brand) };
        }),
        ...globalThis.YushinSupplier.purchaseAmountMetadata(scheduledPoItems),
        createdAt: new Date().toISOString(),
        lastOutputAt: new Date().toISOString(),
        lastOutputType: 'PDF',
        ...linkedDocumentFields(orderIds.length === 1 ? DOCUMENT_TYPES.ORDER : '', orderIds.length === 1 ? orderIds[0] : '', orderIds.map(orderId => documentLink(DOCUMENT_TYPES.ORDER, orderId, 'source')))
    };
    poRecord.searchTokens=purchaseOrderSearchTokens(poRecord);
    const button = document.getElementById('printPurchaseOrderBtn');
    poSaveInProgress = true;
    if (button) {
        button.disabled = true;
        button.innerText = '同步雲端中…';
    }
    updatePoSaveStatus('正在同步採購單到雲端…');
    const generation=poDirectStockOpenGeneration;
    let saved=false;
    try {
        const documentRecord=await saveFormalPurchaseDocument(poRecord,{actorUid,actorRole,expectedRevision:originalDraft?.documentRevision|| (originalDraft?1:0)});
        saved=true;
        if(currentUser?.uid!==actorUid || currentUserRole!==actorRole || generation!==poDirectStockOpenGeneration)return;
        const index=poListCache.findIndex(po=>po.id===documentRecord.id);
        if(index>=0)poListCache[index]=documentRecord;else poListCache.unshift(documentRecord);
        poEditingId=documentRecord.id;poIncomingSyncPending=false;
        document.getElementById('poVendorName').value=documentRecord.vendorName;
        poItems=purchaseItemsFromSavedPo(documentRecord);poAllItems=poItems;renderPoItemsTable();
        updatePoModeUI();
        updatePoSaveStatus(`採購文件 ${poNo} 已儲存，尚未確認採購；下載 PDF 不會增加在途。`);
        await printSavedPoDocument(poNo,vendorName);
    } catch(err) {
        if(currentUser?.uid===actorUid && currentUserRole===actorRole && generation===poDirectStockOpenGeneration){
            const message=saved ? '採購文件已儲存，但 PDF 輸出失敗；可由原單重印：' : '文件儲存結果未確認，請保留原單號重試或查詢；尚未執行採購登記：';
            updatePoSaveStatus(message+err.message,true);
        }
    } finally {
        poSaveInProgress=false;updatePoSaveButton();
    }
};

// 「製作下一張估價單」：手動觸發，不會因為誤按列印視窗的取消鈕就被清空。
// 按下後會先確認，避免不小心點到把還沒印的內容洗掉；確認後清空表單、單號跳下一號，
// 並且立刻把這個「全新、還是空的」狀態存成本機草稿，這樣萬一使用者按完馬上關網頁，
// 重開時看到的會是這張全新的空白單，而不是被清掉的上一張。
// Browser checkpoint only. The existing PO and incoming Services own all writes.
let formalPurchaseRecoveryRunning = false;
function formalPurchasePendingKey() {
    return 'formal-po-pending:' + encodeURIComponent(currentUser?.uid || '');
}
function pendingFormalPurchase() {
    const raw = sessionStorage.getItem(formalPurchasePendingKey());
    if (!raw) return null;
    try {
        const pending = JSON.parse(raw), po = pending?.poRecord;
        if (pending.version !== 1 || pending.actorUid !== currentUser?.uid
            || pending.actorRole !== currentUserRole || !['admin','purchaser'].includes(pending.actorRole)
            || !po || typeof po.poNo !== 'string' || !po.poNo || po.poNo.includes('/')
            || !Array.isArray(po.items) || !po.items.length)
            throw Error('invalid checkpoint');
        return pending;
    } catch (_) {
        throw Error('前次採購紀錄無法核對，請以原帳號及角色查核；請勿另建採購單。');
    }
}
function rememberFormalPurchase(poRecord, actorUid, actorRole) {
    if (actorUid !== currentUser?.uid || actorRole !== currentUserRole)
        throw Error('登入身分已變更，無法儲存採購作業。');
    if (!Array.isArray(poRecord?.items) || !poRecord.items.length
        || (globalThis.YUSHIN_FORMAL_PURCHASE_EMULATOR === true && (poRecord.items.length > 5 || poRecord.items.some(item => !item.orderId || !item.itemId
            || (item.sourceType && item.sourceType !== 'SALES_ORDER')
            || !['WAREHOUSE','DIRECT_SHIP'].includes(item.fulfillmentType || 'WAREHOUSE')))))
        throw Error('採購後端試點目前只支援 1–5 個客戶訂單實體入庫或直送品項。');
    if (pendingFormalPurchase()) throw Error('請先確認前次採購結果，勿另建採購單。');
    const pending = {version:1, actorUid, actorRole, poRecord};
    // A failed storage write stops the operation BEFORE the server is called.
    sessionStorage.setItem(formalPurchasePendingKey(), JSON.stringify(pending));
    renderFormalPurchaseRecovery();
}
function clearFormalPurchasePending(poNo, actorUid, actorRole) {
    if (currentUser?.uid !== actorUid || currentUserRole !== actorRole) return;
    const pending = pendingFormalPurchase();
    if (pending?.poRecord.poNo === poNo) sessionStorage.removeItem(formalPurchasePendingKey());
    renderFormalPurchaseRecovery();
}
function cacheCommittedFormalPurchase({poRecord, committedSourceOrders, committedSupplyOrders}) {
    invalidateProcurementDemandQueue();
    syncCommittedPurchaseOrderSources(committedSourceOrders);
    if (committedSupplyOrders.length) {
        const supplyMap = new Map(supplyReceivingCache.map(row => [row.id, row]));
        committedSupplyOrders.forEach(row => supplyMap.set(row.id, row));
        supplyReceivingCache = [...supplyMap.values()]
            .sort((a,b) => String(b.orderDate || b.createdAt || '').localeCompare(String(a.orderDate || a.createdAt || '')));
    }
    const savedPo = {id:poRecord.poNo, ...poRecord};
    const index = poListCache.findIndex(po => po.id === savedPo.id);
    if (index >= 0) poListCache[index] = savedPo;
    else poListCache.unshift(savedPo);
    return savedPo;
}
function renderFormalPurchaseRecovery() {
    const panel = document.getElementById('formalPurchaseRecoveryPanel');
    if (!panel) return;
    panel.hidden = true;
    if (!currentUser?.uid
        || !canCreatePurchaseOrderCapability() || !canAccessPage('orders.po')) return;
    try {
        const pending = pendingFormalPurchase();
        if (!pending) return;
        panel.textContent = `採購單 ${pending.poRecord.poNo} 的結果尚待確認。`;
        const button = document.createElement('button');
        button.type = 'button'; button.id = 'confirmFormalPurchasePendingBtn';
        button.textContent = formalPurchaseRecoveryRunning ? '核對中…' : '確認前次採購結果';
        button.disabled = formalPurchaseRecoveryRunning || poSaveInProgress;
        button.onclick = recoverFormalPurchase;
        panel.appendChild(button);
    } catch (error) { panel.textContent = error.message; }
    panel.hidden = false;
}
async function recoverFormalPurchase() {
    if (formalPurchaseRecoveryRunning || poSaveInProgress) return;
    const uid = currentUser?.uid, role = currentUserRole;
    let confirmedPoNo = '';
    const check = () => {
        if (!uid || currentUser?.uid !== uid || currentUserRole !== role
            || !canCreatePurchaseOrderCapability() || !canAccessPage('orders.po'))
            throw Error('登入身分已變更，請以原帳號確認採購結果。');
    };
    try {
        check();
        const pending = pendingFormalPurchase();
        if (!pending) return;
        formalPurchaseRecoveryRunning = true;
        renderFormalPurchaseRecovery();
        const result = await commitFormalPurchaseOrder(pending.poRecord, {actorUid:uid, actorRole:role});
        check();
        const savedPo = cacheCommittedFormalPurchase(result);
        await registerPurchaseIncoming(savedPo.id, savedPo,
            {actorUid:uid, actorRole:role, onStockCommitted:invalidateWarehouseStockCache});
        check();
        confirmedPoNo = savedPo.poNo;
        clearFormalPurchasePending(savedPo.poNo, uid, role);
        // Clearing the demand cache does not automatically reload the current
        // ordering view. Refresh once after a confirmed PO so an unpurchased
        // sibling line (including one at another warehouse) remains actionable.
        if (document.getElementById('purchasing-system')?.classList.contains('active')
            && purchasingView === 'ordering') {
            await loadPendingPurchaseOrders(true);
            if (procurementDemandLoaded && !pendingPurchaseError)
                purchasingViewLoaded.add('ordering');
        }
        if (poEditingId === savedPo.id) poIncomingSyncPending = false;
        if (document.getElementById('poModalOverlay')?.classList.contains('active')
            && document.getElementById('poNo')?.textContent?.trim() === savedPo.poNo)
            closePurchaseOrderModal();
        showActionFeedback(`採購單 ${savedPo.poNo} 已確認，在途同步完成；可由原採購單下載 PDF。`, 'success');
        renderPurchasingView();
    } catch (error) {
        if (currentUser?.uid === uid && currentUserRole === role)
            showActionFeedback(confirmedPoNo
                ? `採購單 ${confirmedPoNo} 與在途已確認，但畫面更新未完成：${error.message}`
                : '採購結果尚未確認：' + error.message, 'warning');
    } finally {
        formalPurchaseRecoveryRunning = false;
        renderFormalPurchaseRecovery();
    }
}
window.recoverFormalPurchase = recoverFormalPurchase;

// Explicit business confirmation. PDF and document reads never enter this path.
window.confirmSavedPurchaseOrder = async function(poId) {
    if(formalPurchaseRecoveryRunning || poSaveInProgress || poDraftLoading
        || !canCreatePurchaseOrderCapability() || !canAccessPage('orders.po'))return;
    const uid=currentUser?.uid,role=currentUserRole,generation=sessionDataGeneration;
    try {
        if(pendingFormalPurchase())throw Error('請先使用「確認前次採購結果」核對未完成作業，再確認其他文件。');
        const snap=await db.collection('purchaseOrders').doc(poId).get({source:'server'});
        if(currentUser?.uid!==uid || currentUserRole!==role || sessionDataGeneration!==generation)return;
        if(!snap.exists)throw Error('找不到原採購文件。');
        const record=snap.data();
        if(poEditingId===poId && document.getElementById('poModalOverlay')?.classList.contains('active')
            && purchaseDocumentHasUnsavedChanges(record))throw Error('文件有尚未儲存的修改，請先儲存文件，再確認已採購。');
        if(record.status!=='DRAFT' || record.documentOnly!==true)throw Error('此文件已確認或已停止，請更新清單並核對原採購紀錄。');
        if(!confirm(`確認採購單 ${record.poNo} 已向供應商下單？本次將登記文件上的品項與數量，並列入待到貨。`))return;
        rememberFormalPurchase(record,uid,role);
        await recoverFormalPurchase();
    } catch(error) {
        if(currentUser?.uid===uid && currentUserRole===role)showActionFeedback(error.message,'warning');
    }
};
window.startNextQuote = function() {
    if (!confirm('確定要開始製作下一張估價單嗎？目前畫面上的內容將會被清空（如果還沒匯出 PDF，請先確認已經處理好）。')) return;
    setQuoteEditingContext('');
    setQuoteOutputStatus('');
    resetQuoteFormForNextOne();
    saveQuoteDraft();
};

function resetQuoteFormForNextOne() {
    document.getElementById('clientName').value = '';
    document.getElementById('ordererName').value = '';
    document.getElementById('discountRateInput').value = 0;
    document.getElementById('validDays').value = 90;
    document.getElementById('quoteRemarks').value = '';

    document.getElementById('quoteItems').innerHTML = '';
    addQuoteRow();
    calculateTotals();

    // 單號直接把目前這組號碼的流水號 +1，不重新查一次雲端——
    // 因為上一張單的雲端存檔是背景進行、不保證這時候已經真的寫進 Firestore，
    // 這時如果重新查詢「目前最大流水號」，很可能還查到上一張存檔前的舊資料，算出來的下一號反而會撞號
    const quoteNoInput = document.getElementById('quoteNo');
    const parts = (quoteNoInput.value || '').split('-');
    const lastPart = parts[parts.length - 1];
    const lastSeq = parseInt(lastPart, 10);
    if (parts.length >= 2 && !isNaN(lastSeq)) {
        parts[parts.length - 1] = String(lastSeq + 1).padStart(lastPart.length, '0');
        quoteNoInput.value = parts.join('-');
    }
}

// 新增：處理狀態切換的函數
// 先在畫面上立即反應（樂觀更新），不用等雲端回應才變色，感覺上會快很多；
// 如果雲端寫入失敗，才把狀態復原並提示錯誤
// Shared order billing service. UI is responsible for feedback, not Firestore writes.
async function setOrderBillingStatus(orderId,newValue,billingDate,logEntry,timestamp) {
    if(typeof newValue!=='boolean')throw new Error('核銷狀態必須明確指定。');
    if(newValue&&!isValidOrderBillingDate(billingDate))throw new Error('請選擇正確的核銷日期。');
    return runRoleTransaction(async transaction=>{
        const ref=db.collection('orders').doc(orderId);
        const snapshot=await transaction.get(ref);
        if(!snapshot.exists)throw new Error('找不到這筆訂單。');
        const order=snapshot.data();
        if(normalizedOrderStatus(order)!=='normal')throw new Error('這筆訂單已取消。');
        if(!!order.isBilled===newValue)return {
            isBilled:newValue,billingDate:order.billingDate||'',
            status:order.status||BUSINESS_STATUS.ACTIVE,
            statusHistory:[...(order.statusHistory||[])]
        };
        const updates={
            isBilled:newValue,
            billingDate:newValue?billingDate:'',
            status:BUSINESS_STATUS.ACTIVE,updatedAt:timestamp,
            statusHistory:firebase.firestore.FieldValue.arrayUnion(logEntry)
        };
        Object.assign(updates,orderWorkIndexFields({...order,...updates}));
        transaction.update(ref,updates);
        return {isBilled:newValue,billingDate:updates.billingDate,
            status:BUSINESS_STATUS.ACTIVE,
            statusHistory:[...(order.statusHistory||[]),logEntry]};
    });
}

function isValidOrderBillingDate(value) {
    if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;
    const [year,month,day]=value.split('-').map(Number);
    const date=new Date(Date.UTC(year,month-1,day));
    return date.getUTCFullYear()===year&&date.getUTCMonth()===month-1&&date.getUTCDate()===day;
}

async function changeOrderBillingDate(orderId,value,history) {
    if(!isValidOrderBillingDate(value))throw new Error('請選擇正確的核銷日期。');
    return runRoleTransaction(async transaction=>{
        const ref=db.collection('orders').doc(orderId);
        const snapshot=await transaction.get(ref);
        if(!snapshot.exists)throw new Error('找不到這筆訂單。');
        const order=snapshot.data();
        if(normalizedOrderStatus(order)!=='normal'||order.isBilled!==true)
            throw new Error('這筆訂單已取消或尚未核銷，不能更改核銷日期。');
        if(String(order.billingDate||'')===value)return {
            billingDate:value,fieldEditHistory:[...(order.fieldEditHistory||[])]};
        const entry={...history,before:String(order.billingDate||history.before||'')};
        transaction.update(ref,{
            billingDate:value,updatedAt:entry.at,
            fieldEditHistory:firebase.firestore.FieldValue.arrayUnion(entry)
        });
        return {billingDate:value,fieldEditHistory:[...(order.fieldEditHistory||[]),entry]};
    });
}

window.toggleOrderStatus = function(orderId, field, newValue) {
    if (!canManageOrderLifecycleCapability() || !canEditPage('orders.list')) return;
    if (field !== 'isBilled') {
        alert('訂貨、到貨與送貨狀態已由 V2 採購／入庫／打單流程自動管理。');
        return;
    }
    const o = ordersCache.find(x => x.id === orderId);
    if (!o || !canEditPage('orders.list')) return;
    const pendingKey = `${orderId}:isBilled`;
    if (pendingOrderStatusKeys.has(pendingKey)) return;
    if (normalizedOrderStatus(o) !== 'normal') { alert('已取消的訂單不能更改進度。'); return; }

    const billingDate = newValue ? (orderBillingDate(o) || localDateString()) : '';
    const previousWorkFilter = activeOrderWorkFilter;
    const previous = {
        isBilled: o.isBilled,
        billingDate: o.billingDate || '',
        status: o.status,
        statusHistory: [...(o.statusHistory || [])]
    };
    const actor = currentUserName || currentUser?.email || '未知使用者';
    const timestamp = new Date().toISOString();
    const logEntry = { field:'isBilled', value:newValue, label:newValue ? '已核銷' : '取消已核銷', by:actor, at:timestamp };

    o.isBilled = newValue;
    o.billingDate = billingDate;
    if (!newValue && activeOrderWorkFilter === 'complete') activeOrderWorkFilter = 'billing';
    if (newValue && activeOrderWorkFilter === 'billing' && deliveryProgressInfo(o).state === 'complete') activeOrderWorkFilter = 'complete';
    o.statusHistory = [...previous.statusHistory, logEntry];
    pendingOrderStatusKeys.add(pendingKey);
    writeAppDataCache('orders', ordersCache);
    renderOrdersList();

    setOrderBillingStatus(orderId,newValue,billingDate,logEntry,timestamp).then(committed => {
        Object.assign(o, committed);
        pendingOrderStatusKeys.delete(pendingKey);
        writeAppDataCache('orders', ordersCache);
        renderOrdersList();
        if (currentDeliveryOrderId === orderId) { renderDeliveryModal(); renderOrderLifecycleModal(); }
    }).catch(err => {
        Object.assign(o, previous);
        pendingOrderStatusKeys.delete(pendingKey);
        activeOrderWorkFilter = previousWorkFilter;
        writeAppDataCache('orders', ordersCache);
        renderOrdersList();
        if (currentDeliveryOrderId === orderId) {
            renderDeliveryModal();
            renderOrderLifecycleModal();
        }
        alert('更新狀態失敗，已還原：' + err.message);
    });
};

window.updateOrderBillingDate = function(orderId, value) {
    const order = ordersCache.find(item => item.id === orderId);
    if (!order || !order.isBilled || !canEditPage('orders.list')) return;
    if (!isValidOrderBillingDate(value)) { alert('請選擇正確的核銷日期。'); renderOrdersList(); return; }
    const pendingKey=`${orderId}:billingDate`;
    if(pendingOrderStatusKeys.has(pendingKey))return;
    const previous = order.billingDate || '';
    if (previous === value) return;
    const previousHistory=[...(order.fieldEditHistory||[])];
    const history = {
        field: 'billingDate', label: '修改核銷日期', before: previous || orderBillingDate(order), after: value,
        by: currentUserName || currentUser?.email || '未知使用者', at: new Date().toISOString()
    };
    pendingOrderStatusKeys.add(pendingKey);
    order.billingDate = value;
    order.fieldEditHistory = [...previousHistory,history];
    writeAppDataCache('orders', ordersCache);
    renderOrdersList();
    changeOrderBillingDate(orderId,value,history).then(committed=>{
        Object.assign(order,committed);
        pendingOrderStatusKeys.delete(pendingKey);
        writeAppDataCache('orders',ordersCache);
        renderOrdersList();
    }).catch(err=>{
        if(order.billingDate===value){
            order.billingDate=previous;
            order.fieldEditHistory=previousHistory;
        }
        pendingOrderStatusKeys.delete(pendingKey);
        writeAppDataCache('orders',ordersCache);
        renderOrdersList();
        alert('更新核銷日期失敗，已還原：'+err.message);
    });
};

function formatOrderStatusTime(value) {
    if (!value) return '';
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return String(value);
    return date.toLocaleString('zh-TW', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false });
}

window.showCustomerOrderHistory = async function(customerName) {
    const customerKey = normalizeFullHistorySearchValue(customerName);
    if (!customerKey) return;
    const overlay = document.getElementById('customerOrderHistoryOverlay');
    const title = document.getElementById('customerOrderHistoryTitle');
    const summary = document.getElementById('customerTransactionSummary');
    const tbody = document.getElementById('customerOrderHistoryBody');
    const quoteTbody = document.getElementById('customerQuoteHistoryBody');
    if (title) title.innerText = `客戶近期交易摘要：${customerName}`;
    if (summary) summary.innerHTML = '<div class="customer-summary-card"><span>資料狀態</span><strong>讀取完整歷史中…</strong></div>';
    if (tbody) tbody.innerHTML = '<tr><td colspan="7" style="color:#888;">讀取訂單歷史中…</td></tr>';
    if (quoteTbody) quoteTbody.innerHTML = '<tr><td colspan="6" style="color:#888;">讀取估價歷史中…</td></tr>';
    if (overlay) overlay.classList.add('active');

    try {
        const orderToken = fullHistoryQueryToken('order', customerName);
        const quoteToken = fullHistoryQueryToken('quote', customerName);
        const [orderSnap, quoteSnap] = await Promise.all([
            orderToken
                ? firestoreReadWithTimeout(scopedHistorySearchQuery('orders', orderToken).limit(DEFAULT_LIST_LIMIT).get(), '客戶訂單歷史')
                : Promise.resolve({ docs: [] }),
            quoteToken
                ? firestoreReadWithTimeout(scopedHistorySearchQuery('quotes', quoteToken).limit(DEFAULT_LIST_LIMIT).get(), '客戶估價歷史')
                : Promise.resolve({ docs: [] })
        ]);
        const exactCustomerKey = normalizeCustomerKey(customerName);
        const orders = (orderSnap.docs || [])
            .map(doc => ({ id: doc.id, ...doc.data() }))
            .filter(order => normalizeCustomerKey(order.customerName || order.customer || '') === exactCustomerKey)
            .sort((a, b) => String(b.orderDate || '').localeCompare(String(a.orderDate || '')));
        const quotes = (quoteSnap.docs || [])
            .map(doc => ({ id: doc.id, ...doc.data() }))
            .filter(quote => [quote.ordererName, quote.clientName].some(value => normalizeCustomerKey(value) === exactCustomerKey))
            .sort((a, b) => String(b.quoteDate || b.quoteNo || '').localeCompare(String(a.quoteDate || a.quoteNo || '')));
        const quoteItems = quotes.flatMap(quote => (quote.items || []).map(item => ({ quote, item })))
            .sort((a, b) => String(b.quote.quoteDate || b.quote.quoteNo || '').localeCompare(String(a.quote.quoteDate || a.quote.quoteNo || '')));
        const recentDates = [...orders.map(order => order.orderDate), ...quotes.map(quote => quote.quoteDate)].filter(Boolean).sort().reverse();
        const latestOrder = orders[0];
        const latestQuoteItem = quoteItems[0];
        const latestPrice = latestOrder
            ? `NT$ ${Number(parseFloat(String(latestOrder.unitPrice ?? '').replace(/,/g, '')) || 0).toLocaleString()}`
            : latestQuoteItem ? `NT$ ${Number(parseFloat(String(latestQuoteItem.item.price ?? '').replace(/,/g, '')) || 0).toLocaleString()}` : '－';
        const latestProduct = latestOrder?.itemName || latestQuoteItem?.item?.nameCn || latestQuoteItem?.item?.nameEn || '－';
        if (summary) summary.innerHTML = `
            <div class="customer-summary-card"><span>最近交易日</span><strong>${escapeHtml(recentDates[0] || '－')}</strong></div>
            <div class="customer-summary-card"><span>最近購買／估價品項</span><strong>${escapeHtml(latestProduct)}</strong></div>
            <div class="customer-summary-card"><span>上次單價</span><strong>${escapeHtml(latestPrice)}</strong></div>
            <div class="customer-summary-card"><span>最近估價</span><strong>${escapeHtml(quotes[0] ? `${quotes[0].quoteNo || '－'}／${quotes[0].quoteDate || '－'}` : '－')}</strong></div>`;
        if (tbody) tbody.innerHTML = orders.length ? orders.slice(0, 20).map(order => `
            <tr><td>${escapeHtml(order.orderDate || '')}</td><td>${escapeHtml(order.brand || '')}</td><td>${escapeHtml(order.itemCode || '')}</td><td>${escapeHtml(order.itemName || '')}</td><td>${escapeHtml(String(order.qty || ''))}</td><td>${escapeHtml(String(order.totalPrice || ''))}</td><td>${deliveryProgressInfo(order).delivered>0 ? (deliveryProgressInfo(order).state==='complete'?'已送貨':'部分送貨') : fulfillmentProgressInfo(order).shippable>0 ? '可出貨' : fulfillmentProgressInfo(order).pendingDispatch>0 ? '待打單' : purchaseProgressInfo(order).label}</td></tr>
        `).join('') : '<tr><td colspan="7" style="color:#888;">目前沒有訂單紀錄。</td></tr>';
        if (quoteTbody) quoteTbody.innerHTML = quoteItems.length ? quoteItems.slice(0, 20).map(({ quote, item }) => `
            <tr><td>${escapeHtml(quote.quoteDate || '')}</td><td>${escapeHtml(quote.quoteNo || '')}</td><td>${escapeHtml(item.nameCn || item.nameEn || item.model || '')}</td><td>${escapeHtml(String(item.qty || ''))}</td><td>${escapeHtml(String(item.price || ''))}</td><td>${quote.dealClosed ? '已成交' : '估價中'}</td></tr>
        `).join('') : '<tr><td colspan="6" style="color:#888;">目前沒有估價紀錄。</td></tr>';
    } catch (err) {
        console.error('讀取客戶完整交易歷史失敗：', err);
        if (summary) summary.innerHTML = '<div class="customer-summary-card"><span>資料狀態</span><strong>讀取失敗</strong></div>';
        if (tbody) tbody.innerHTML = '<tr><td colspan="7" style="color:#888;">無法讀取完整訂單歷史。</td></tr>';
        if (quoteTbody) quoteTbody.innerHTML = '<tr><td colspan="6" style="color:#888;">無法讀取完整估價歷史。</td></tr>';
    }
};

window.closeCustomerOrderHistory = function() {
    document.getElementById('customerOrderHistoryOverlay').classList.remove('active');
};

function deliveryRecordId() {
    if (window.crypto && typeof window.crypto.randomUUID === 'function') return window.crypto.randomUUID();
    return `delivery-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
}

function deliveryActor() {
    return currentUserName || currentUser?.email || '未知使用者';
}

function localDateString() {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
}

function normalizeBusinessDate(value) {
    if (!value) return '';
    const raw = String(value).trim().replace(/\//g, '-');
    if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
    return dateOnlyFromTimestamp(value);
}

function unifiedPeriodRange(key = 'this-year') {
    const now = new Date();
    const y = now.getFullYear();
    const m = now.getMonth();
    const fmt = d => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    if (key === 'all') return { start: '', end: '' };
    if (key === 'this-month') return { start: fmt(new Date(y, m, 1)), end: fmt(new Date(y, m + 1, 0)) };
    if (key === 'last-month') return { start: fmt(new Date(y, m - 1, 1)), end: fmt(new Date(y, m, 0)) };
    if (key === 'this-quarter') {
        const qStart = Math.floor(m / 3) * 3;
        return { start: fmt(new Date(y, qStart, 1)), end: fmt(new Date(y, qStart + 3, 0)) };
    }
    if (key === 'last-year') return { start: `${y - 1}-01-01`, end: `${y - 1}-12-31` };
    return { start: `${y}-01-01`, end: `${y}-12-31` };
}

function dateInUnifiedPeriod(value, key = 'this-year') {
    const date = normalizeBusinessDate(value);
    const { start, end } = unifiedPeriodRange(key);
    if (!start && !end) return true;
    return !!date && (!start || date >= start) && (!end || date <= end);
}

let orderProgressHistoryExpanded = false;
let currentOrderHistoryId = null;
let orderLifecycleFormOpen = false;
let orderReturnFormOpen = false;
window.selectOrderProgressTab = function(tab) {
    if (!['delivery', 'returns'].includes(tab)) return;
    ['delivery', 'returns'].forEach(name => {
        document.getElementById(`orderProgressPanel-${name}`).hidden = name !== tab;
        const button = document.getElementById(`orderProgressTab-${name}`);
        button.setAttribute('aria-selected', String(name === tab));
    });
};
window.showAllOrderProgressHistory = function() {
    orderProgressHistoryExpanded = true;
    const order = ordersCache.find(o => o.id === currentOrderHistoryId);
    if (order) renderOrderStatusHistory(order);
};
function labelOrderProgressRecords(bodyId, labels) {
    const body = document.getElementById(bodyId);
    if (!body) return;
    Array.from(body.rows).forEach(row => Array.from(row.cells).forEach((cell, i) => {
        if (cell.colSpan === 1) cell.dataset.label = labels[i];
    }));
}
window.closeOrderLifecycleForm = function() {
    orderLifecycleFormOpen = false;
    document.getElementById('orderStatusEditPanel').style.display = 'none';
};
window.openOrderLifecycleForm = function() {
    const order = ordersCache.find(o => o.id === currentLifecycleOrderId);
    if (!order || !canManageOrderLifecycleCapability() || !canEditPage('orders.list')) return;
    if (globalThis.YUSHIN_V2_LIFECYCLE_EMULATOR===true){
        try{if(!pendingV2OrderLifecycle(order.id)&&normalizedOrderStatus(order)==='normal'&&deliveryProgressInfo(order).remaining<=0)return;}
        catch(err){alert(err.message);return;}
    }else if (normalizedOrderStatus(order) === 'normal' && deliveryProgressInfo(order).remaining <= 0) return;
    selectOrderProgressTab('returns');
    orderLifecycleFormOpen = true;
    document.getElementById('orderLifecycleStatus').value = normalizedOrderStatus(order) === 'normal' ? 'cancelled' : 'normal';
    renderOrderLifecycleModal();
};
window.openReturnForm = function() {
    const order = ordersCache.find(o => o.id === currentLifecycleOrderId);
    if (!order || !canManageOrderLifecycleCapability() || !canEditPage('orders.list')) return;
    if (!normalizedOrderItems(order).some(item => returnItemDeliveredQty(order, item.itemId) - returnItemReturnedQty(order, item.itemId) - customerReturnPendingQty(order, item.itemId) > 0)) return;
    selectOrderProgressTab('returns');
    orderReturnFormOpen = true;
    document.getElementById('returnCancelEditBtn').style.display = '';
    renderOrderLifecycleModal();
    document.getElementById('returnDate').focus();
};

window.openDeliveryModal = function(orderId) {
    const order = ordersCache.find(item => item.id === orderId);
    if (!order) return;
    if(orderInventorySyncIncomplete(order)){showActionFeedback('這筆訂單庫存尚未同步完成，請先完成或重試同步。','warning');return;}
    currentDeliveryOrderId = orderId;
    currentLifecycleOrderId = orderId;
    orderProgressHistoryExpanded = false;
    orderLifecycleFormOpen = false;
    orderReturnFormOpen = false;
    selectOrderProgressTab('delivery');
    deliveryPartialFormOpen = false;
    document.getElementById('deliveryModalTitle').innerText = `訂單進度：${order.customerName || order.itemName || '訂單'}`;
    document.getElementById('orderLifecycleStatus').value = normalizedOrderStatus(order);
    document.getElementById('orderLifecycleDate').value = order.orderStatusDate || localDateString();
    document.getElementById('orderLifecycleReason').value = order.orderStatusReason || '';
    resetDeliveryForm();
    resetReturnForm();
    renderDeliveryModal();
    renderOrderLifecycleModal();
    window.renderOrderDeliverySettingsButton?.(order);
    document.getElementById('deliveryModalOverlay').classList.add('active');
};

window.closeDeliveryModal = function() {
    currentDeliveryOrderId = null;
    currentLifecycleOrderId = null;
    deliveryPartialFormOpen = false;
    document.getElementById('deliveryModalOverlay').classList.remove('active');
};

window.prepareOrderLifecycle = function(orderId, status) {
    openDeliveryModal(orderId);
    openOrderLifecycleForm();
    if (!orderLifecycleFormOpen) return;
    document.getElementById('orderLifecycleStatus').value = status;
    document.getElementById('orderLifecycleDate').value = localDateString();
    document.getElementById('orderLifecycleReason').value = '';
    onOrderLifecycleStatusChange();
    document.getElementById('orderStatusEditPanel').scrollIntoView({ behavior: 'smooth', block: 'center' });
    document.getElementById('orderLifecycleReason').focus();
};

async function adjustInventoryReservationForLifecycle(transaction, orderId, order, nextStatus, actor, options={}) {
    if(!['normal','cancelled'].includes(nextStatus))throw new Error('不支援的訂單狀態。');
    if(!Array.isArray(order?.items)||!order.items.length
        ||order.items.some(item=>!item||typeof item!=='object'||Array.isArray(item)))
        throw new Error('訂單缺少有效品項明細，無法安全取消或恢復。請由管理員核對原始訂單、庫存預留及採購需求。');
    const items = normalizedOrderItems(order);
    // Multiple lines must never address the same reservation or demand document,
    // including collisions between generated legacy IDs and explicit IDs.
    const itemIds=items.map((item,index)=>String(item.itemId||`item-${index+1}`));
    if(new Set(itemIds).size!==itemIds.length)
        throw new Error('訂單品項識別碼重複，無法安全取消或恢復。請由管理員核對品項與庫存預留。');
    const now = new Date().toISOString();

    // Firestore transactions require every read before the first write.
    const contexts = [];
    // A restored order may only reserve against a live physical warehouse.
    // Reuse master snapshots when several items target the same location.
    const restoredWarehouseSnapshots = new Map();
    // All linked purchase demands must be read before the first transaction write.
    // Deletion/testing flows may opt out explicitly; regular lifecycle never does.
    const syncLinkedDemands=!options.skipDemandSync;
    for (let index = 0; index < items.length; index++) {
        const item = items[index];
        const savedItem=order.items?.[index]||{};
        const itemReservedQty=Object.hasOwn(savedItem,'reservedQty')?savedItem.reservedQty:item.reservedQty;
        const itemId = String(item.itemId || `item-${index + 1}`);
        const productKey = inventoryProductKey(item);
        const directShip = (item.fulfillmentType || 'WAREHOUSE') === 'DIRECT_SHIP';
        // Reuse the canonical projection: closed returns do not need replacement,
        // and legacy item-only delivery totals remain authoritative when no ledger exists.
        const delivered = Math.max(0, Number(item.deliveredQty||0)-Number(item.returnedQty||0));
        const ordered = Math.max(0, Number(item.qty || item.orderedQty || 0));
        const warehouseId = directShip ? '' : (item.warehouseId || order.warehouseId || defaultWarehouse()?.id || '');
        const invRef = !directShip && productKey ? inventoryRefFor(item) : null;
        const whRef = !directShip && warehouseId && productKey ? db.collection('warehouseStocks').doc(warehouseStockDocId(warehouseId, productKey)) : null;
        const reservationRef = db.collection('inventoryReservations').doc(`${orderId}__${itemId}`);
        const invSnap = invRef ? await transaction.get(invRef) : null;
        const whSnap = whRef ? await transaction.get(whRef) : null;
        const reservationSnap = await transaction.get(reservationRef);
        const demandRef=syncLinkedDemands?procurementDemandRef(globalThis.YushinProcurementDemand.demandIdForSource({sourceType:'SALES_ORDER',sourceId:orderId,sourceItemId:itemId})):null;
        const demandSnap=demandRef?await transaction.get(demandRef):null;
        const reservationData=reservationSnap.exists?reservationSnap.data():{};
        if(nextStatus==='normal'&&!directShip&&productKey){
            if(!warehouseId||String(warehouseId).startsWith('custody-'))
                throw new Error('原訂單倉庫不是可用的實體倉庫；請由管理員先核對倉庫與貨品位置，再恢復訂單。');
            let warehouseSnap=restoredWarehouseSnapshots.get(warehouseId);
            if(!warehouseSnap){
                warehouseSnap=await transaction.get(db.collection('warehouses').doc(warehouseId));
                restoredWarehouseSnapshots.set(warehouseId,warehouseSnap);
            }
            if(!warehouseSnap.exists||warehouseSnap.data().active===false
                ||warehouseSnap.data().systemCustody||warehouseSnap.data().warehouseType==='CUSTODY')
                throw new Error('原訂單倉庫已停用、已刪除或屬業務保管位置，不能恢復預留。請由管理員核對倉庫及調撥紀錄。');
        }
        if(!directShip&&item.transferPendingId)throw new Error('此品項尚在倉庫調撥途中，請目的倉確認收貨後再取消或恢復。');
        for(const [key,value] of Object.entries({orderId,itemId,productKey,warehouseId})){
            if(reservationData[key]!==undefined&&reservationData[key]!==value)
                throw new Error('預留來源、產品或倉庫與訂單不一致，請先核對資料。');
        }
        for(const snap of [invSnap,whSnap]){
            if(snap?.exists&&snap.data().productKey!==undefined&&snap.data().productKey!==productKey)
                throw new Error('庫存產品與訂單不一致，請先核對資料。');
        }
        if(whSnap?.exists&&whSnap.data().warehouseId!==undefined&&whSnap.data().warehouseId!==warehouseId)
            throw new Error('分倉庫存位置與訂單不一致，請先核對資料。');
        contexts.push({item,itemReservedQty,itemId,index,productKey,directShip,delivered,ordered,warehouseId,invRef,whRef,invSnap,whSnap,reservationRef,reservationSnap,reservationData,demandRef,demandSnap});
    }

    const nextItems = [];
    let totalReserved = 0;
    let totalShortage = 0;
    const stockStates = new Map();
    contexts.forEach(ctx => {
        if (ctx.invRef && ctx.invSnap?.exists && !stockStates.has(ctx.invRef.path)) stockStates.set(ctx.invRef.path,{...ctx.invSnap.data(),ref:ctx.invRef,beforeReserved:ctx.invSnap.data().reserved});
        if (ctx.whRef && ctx.whSnap?.exists && !stockStates.has(ctx.whRef.path)) stockStates.set(ctx.whRef.path,{...ctx.whSnap.data(),ref:ctx.whRef,beforeReserved:ctx.whSnap.data().reserved});
    });

    for (const ctx of contexts) {
        const {item,itemReservedQty,itemId,productKey,directShip,delivered,ordered,warehouseId,invRef,whRef,invSnap,whSnap,reservationRef,reservationSnap,reservationData} = ctx;

        if (directShip || !productKey) {
            // A direct or unlinked line cannot silently erase an existing hold.
            globalThis.YushinReservation.planReservationLifecycle({nextStatus:'cancelled',
                existingQty:reservationData.quantity,itemReservedQty});
            const shortage = directShip ? 0 : Math.max(0, ordered - delivered);
            transaction.set(reservationRef, {
                orderId,itemId,orderNo:order.orderNo||order.quoteNo||orderId,productKey,
                itemCode:item.itemCode||'',itemName:item.itemName||'',customerName:order.customerName||'',
                salesCode:order.salesCode||salesCodeForName(order.salesName),salesName:order.salesName||'',
                orderDate:order.orderDate||'',quantity:0,shortageQty:nextStatus==='cancelled'?0:shortage,
                status:nextStatus==='cancelled'?'released':(directShip?'direct_ship':'shortage'),warehouseId:'',updatedAt:now
            }, { merge:true });
            const nextReserved = nextStatus==='cancelled' ? 0 : 0;
            nextItems.push({...item,itemId,reservedQty:nextReserved,shortageQty:nextStatus==='cancelled'?0:shortage});
            totalReserved += nextReserved;
            totalShortage += nextStatus==='cancelled'?0:shortage;
            continue;
        }

        const invState = invRef ? stockStates.get(invRef.path) : null;
        const whState = whRef ? stockStates.get(whRef.path) : null;
        const existingQty=reservationData.quantity;
        if(Number(existingQty)>0&&(!reservationSnap.exists||reservationData.warehouseId!==warehouseId))
            throw new Error('既有預留缺少正確位置，請先核對資料。');
        if (nextStatus === 'cancelled') {
            const plan=globalThis.YushinReservation.planReservationLifecycle({nextStatus,existingQty,
                itemReservedQty,aggregateStock:invState,warehouseStock:whState});
            const release=-plan.reservedDelta;
            if (release > 0) {
                invState.reserved = Number(invState.reserved||0) - release;
                whState.reserved = Number(whState.reserved||0) - release;
                transaction.set(db.collection('inventoryMovements').doc(), inventoryMovementRecord('release',-release,orderId,productKey,actor,{reason:'order_cancelled',warehouseId,itemId}));
            }
            transaction.set(reservationRef,{
                orderId,itemId,orderNo:order.orderNo||order.quoteNo||orderId,productKey,
                itemCode:item.itemCode||'',itemName:item.itemName||'',customerName:order.customerName||'',
                salesCode:order.salesCode||salesCodeForName(order.salesName),salesName:order.salesName||'',
                orderDate:order.orderDate||'',quantity:0,shortageQty:0,status:'released',warehouseId,updatedAt:now
            },{merge:true});
            nextItems.push({...item,itemId,reservedQty:0,shortageQty:0});
            continue;
        }

        const outstanding = Math.max(0, ordered - delivered);
        // 已下 PO／自行訂購的數量屬於既有在途供應，恢復訂單時不能再拿同一數量預留現貨，
        // 否則會同時出現「待到貨」與庫存 reservation，造成供應量重複計算。
        const orderedSupply = Math.max(0, Number(item.supplyOrderedQty||0));
        const receivedSupply = Math.max(0, Number(item.receivedQty||0));
        const incomingSupply = Math.min(outstanding, Math.max(0, orderedSupply - receivedSupply));
        const plan=globalThis.YushinReservation.planReservationLifecycle({nextStatus,existingQty,
            itemReservedQty,requestedQty:outstanding,inTransitQty:incomingSupply,
            aggregateStock:invState,warehouseStock:whState});
        const reserve=plan.reservedQty;
        // shortageQty 一律代表尚無實貨預留的量；已下訂待到貨另由 supplyOrderedQty - receivedQty 涵蓋。
        const shortage = plan.shortageQty;
        if(plan.reservedDelta){
            invState.reserved=Number(invState.reserved||0)+plan.reservedDelta;
            whState.reserved=Number(whState.reserved||0)+plan.reservedDelta;
            transaction.set(db.collection('inventoryMovements').doc(),inventoryMovementRecord(plan.reservedDelta>0?'reserve':'release',plan.reservedDelta,orderId,productKey,actor,{reason:'order_restored',warehouseId,itemId}));
        }
        transaction.set(reservationRef,{
            orderId,itemId,orderNo:order.orderNo||order.quoteNo||orderId,productKey,
            itemCode:item.itemCode||'',itemName:item.itemName||'',customerName:order.customerName||'',
            salesCode:order.salesCode||salesCodeForName(order.salesName),salesName:order.salesName||'',
            orderDate:order.orderDate||'',quantity:reserve,shortageQty:shortage,
            status:reserve>0?'active':(shortage>0?'shortage':'fulfilled'),warehouseId,updatedAt:now
        },{merge:true});
        nextItems.push({...item,itemId,reservedQty:reserve,shortageQty:shortage});
        totalReserved += reserve;
        totalShortage += shortage;
    }

    // Restore/cancel the linked demand in the same transaction as reservations
    // and stock; never publish an order status before its procurement projection.
    if(syncLinkedDemands){
        const restoredOrder=nextStatus==='normal'
            ? {...order,id:orderId,status:'active',orderStatus:'normal',items:nextItems}
            : null;
        for(const ctx of contexts){
            const previous=ctx.demandSnap?.exists?ctx.demandSnap.data():null;
            if(previous&&(
                previous.demandId!=='SALES_ORDER:'+orderId+':'+ctx.itemId
                ||previous.sourceType!=='SALES_ORDER'||previous.sourceId!==orderId
                ||previous.sourceItemId!==ctx.itemId||previous.productKey!==ctx.productKey
                ||previous.ownerUid!==order.ownerUid||previous.salesCode!==order.salesCode
                ||(previous.sourceItemIndex!==undefined&&previous.sourceItemIndex!==-1&&previous.sourceItemIndex!==ctx.index)
            ))throw new Error('採購需求與訂單歸屬或品項不一致，請先核對資料。');
            if(nextStatus==='cancelled'){
                if(previous&&previous.status!=='CANCELLED')
                    transaction.update(ctx.demandRef,{status:'CANCELLED',remainingToOrderQty:0,
                        sourceItemIndex:ctx.index,updatedAt:now});
                continue;
            }
            const nextItem=nextItems[ctx.index];
            const doc=orderItemProcurementDemandDocument(restoredOrder,nextItem,previous,now);
            if(previous){
                // Historical supplier orders and receipts cannot be erased,
                // inferred upwards, or reassigned by restoring a commercial order.
                if(previous.orderedQty!==doc.orderedQty||previous.receivedQty!==doc.receivedQty
                    ||previous.fulfillmentType!==doc.fulfillmentType
                    ||previous.warehouseId!==doc.warehouseId)
                    throw new Error('採購需求與供應商履約紀錄不一致，請先稽核再恢復訂單。');
                transaction.update(ctx.demandRef,{
                    requestedQty:doc.requestedQty,remainingToOrderQty:doc.remainingToOrderQty,
                    remainingToReceiveQty:doc.remainingToReceiveQty,perOrdered:doc.perOrdered,
                    perReceived:doc.perReceived,status:doc.status,sourceItemIndex:ctx.index,
                    updatedAt:now
                });
            }else if(doc.requestedQty>0||doc.orderedQty>0||doc.receivedQty>0){
                transaction.set(ctx.demandRef,doc);
            }
        }
    }
    stockStates.forEach(state => {
        if(Number(state.reserved||0)!==Number(state.beforeReserved||0))
            transaction.update(state.ref,{reserved:Number(state.reserved||0),updatedAt:now});
    });
    transaction.update(db.collection('orders').doc(orderId),{
        items:nextItems,updatedAt:now
    });
    return {items:nextItems,totalReserved,totalShortage};
}

// Central authority for cancellation/restoration of an order and its stock holds.
async function setOrderLifecycleStatus(orderId,nextStatus,details=null) {
    if(globalThis.YUSHIN_V2_LIFECYCLE_EMULATOR===true)return setV2OrderLifecycleEmulator(orderId,nextStatus,details);
    if(!['normal','cancelled'].includes(nextStatus))throw new Error('不支援的訂單狀態。');
    // Quick actions change status only; the form may also amend date/reason.
    const date=details===null?localDateString():details.date;
    const reason=details===null?'':String(details.reason||'').trim();
    if(typeof date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(date)
        ||!Number.isFinite(Date.parse(date+'T00:00:00Z'))
        ||new Date(date+'T00:00:00Z').toISOString().slice(0,10)!==date)
        throw new Error('請填寫正確的狀態日期。');
    const actor=deliveryActor(),at=new Date().toISOString();
    let savedOrder;
    await runRoleTransaction(async transaction => {
        const ref = db.collection('orders').doc(orderId);
        const snapshot = await transaction.get(ref);
        if (!snapshot.exists) throw new Error('找不到這筆訂單。');
        const order = snapshot.data();
        const previous = { status: normalizedOrderStatus(order), date: order.orderStatusDate || '', reason: order.orderStatusReason || '' };
        const statusChanged=previous.status!==nextStatus;
        if (!statusChanged&&(details===null||(previous.date===date&&previous.reason===reason))) {
            savedOrder=order;
            return;
        }
        if(statusChanged&&nextStatus==='cancelled'&&deliveryProgressInfo(order).remaining<=0)throw new Error('訂單已無剩餘未送貨數量，請重新確認。');
         const history = {
            action: statusChanged&&nextStatus === 'normal' ? 'restore' : 'status_change',
            before: previous,
            after: { status: nextStatus, date, reason },
            by: actor,
            at
        };
        const reservationLifecycle=statusChanged
            ?await adjustInventoryReservationForLifecycle(transaction, orderId, order, nextStatus, actor):null;
        const updates = {
            items:reservationLifecycle?.items||order.items||[],
            itemCount:(reservationLifecycle?.items||normalizedOrderItems(order)).length,
            orderSchemaVersion:2,
            status: nextStatus === 'cancelled' ? BUSINESS_STATUS.CANCELLED : BUSINESS_STATUS.ACTIVE,
            orderStatus: nextStatus,
            orderStatusDate: date,
            orderStatusReason: reason,
            updatedAt: history.at,
            orderLifecycleHistory: firebase.firestore.FieldValue.arrayUnion(history)
        };
        Object.assign(updates,orderWorkIndexFields({...order,...updates}));
        transaction.update(ref, updates);
        savedOrder = { ...order, ...updates, orderLifecycleHistory: [...(order.orderLifecycleHistory || []), history] };
    });
    return savedOrder;
}

// Transport only: the existing backend lifecycle Service owns every stock change.
function pendingV2OrderLifecycle(orderId){
 if(globalThis.YUSHIN_V2_LIFECYCLE_EMULATOR!==true)return null;
 const raw=sessionStorage.getItem('v2-lifecycle:'+encodeURIComponent(currentUser?.uid||'')+':'+encodeURIComponent(orderId));
 if(!raw)return null;
 try{
  const intent=JSON.parse(raw);
  if(!intent||intent.orderId!==orderId||intent.actorUid!==currentUser?.uid||intent.actorRole!==currentUserRole
   ||!['normal','cancelled'].includes(intent.nextStatus)||!/^\w[\w-]{11,95}$/.test(intent.operationId||'')
   ||!Array.isArray(intent.itemIds)||!intent.itemIds.length||intent.itemIds.length>5
   ||!Array.isArray(intent.warehouseIds)||intent.warehouseIds.length!==2)throw Error('invalid pending lifecycle');
  return intent;
 }catch(_){throw Error('前次取消／恢復結果尚未確認，請使用原帳號與角色核對。');}
}
async function setV2OrderLifecycleEmulator(orderId,nextStatus,details=null){
 const local=host=>host==='localhost'||host==='127.0.0.1';
 if(globalThis.YUSHIN_V2_LIFECYCLE_EMULATOR!==true||!local(globalThis.location?.hostname)
  ||typeof firebase==='undefined'||!firebase.auth||!firebase.functions)throw Error('v2 取消／恢復僅限本機 Emulator。');
 const auth=firebase.auth(),functions=firebase.app().functions('asia-east1'),uid=currentUser?.uid,role=currentUserRole;
 if(auth.app?.options?.projectId!=='demo-yushin'||functions.app?.options?.projectId!=='demo-yushin'
  ||!local(auth.emulatorConfig?.host)||auth.emulatorConfig?.port!==9099)
  throw Error('v2 取消／恢復只允許本機 demo-yushin Auth／Functions Emulator。');
 const check=()=>{
  if(!uid||auth.currentUser?.uid!==uid||currentUser?.uid!==uid||currentUserRole!==role
   ||!['admin','sales','engineer'].includes(role)||!canManageOrderLifecycleCapability()||!canEditPage('orders.list'))
   throw Error('登入身分或取消／恢復權限已變更。');
 };
 check();
 const key='v2-lifecycle:'+encodeURIComponent(uid)+':'+encodeURIComponent(orderId);
 let frozen=pendingV2OrderLifecycle(orderId);
 if(frozen){
  if(frozen.nextStatus!==nextStatus||(details!==null&&(frozen.date!==details.date||frozen.reason!==String(details.reason||'').trim())))
   throw Error('尚有未確認的取消／恢復，請先以原狀態、日期與原因核對結果。');
 }else{
  const date=details===null?localDateString():details.date,reason=String(details?.reason||'').trim();
  if(!['normal','cancelled'].includes(nextStatus)||typeof date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(date)
   ||!Number.isFinite(Date.parse(date+'T00:00:00Z'))||new Date(date+'T00:00:00Z').toISOString().slice(0,10)!==date||reason.length>1000)
   throw Error('請填寫正確的目標狀態、日期與原因。');
  const snapshot=await db.collection('orders').doc(orderId).get({source:'server'});check();
  if(!snapshot.exists)throw Error('找不到原始訂單。');
  const order=snapshot.data(),items=order.items;
  if(order.inventoryReservationStatus!=='completed'||!order.inventoryReservationAttemptId||!Array.isArray(items)
   ||!items.length||items.length>5||items.some(row=>typeof row?.itemId!=='string'||!row.itemId||row.itemId.includes('/'))
   ||new Set(items.map(row=>row.itemId)).size!==items.length)throw Error('訂單尚未具備完整的 v2 取消／恢復來源。');
  if(normalizedOrderStatus(order)===nextStatus)throw Error('訂單已是此狀態；v2 試點不提供單獨更正日期／原因。');
  let warehouseIds;
  for(const item of items){
   const snap=await db.collection('inventoryReservations').doc(orderId+'__'+item.itemId).get({source:'server'});check();
   const ledger=snap.exists?snap.data():null,candidates=ledger?.lifecycleWarehouseIds;
   if(!ledger||ledger.locationSchemaVersion!==2||ledger.orderId!==orderId||ledger.itemId!==item.itemId
    ||!Array.isArray(candidates)||candidates.length!==2||new Set(candidates).size!==2
    ||candidates.some(id=>typeof id!=='string'||!id||id.includes('/')))
    throw Error('缺少原始 v2 雙倉來源，不能以指定倉或目前位置猜測。');
   const sorted=[...candidates].sort();
   if(warehouseIds&&JSON.stringify(warehouseIds)!==JSON.stringify(sorted))throw Error('整單品項的原候選倉不一致。');
   warehouseIds=sorted;
  }
  frozen={orderId,itemIds:items.map(row=>row.itemId).sort(),warehouseIds,nextStatus,date,reason,
   operationId:'lifecycle_'+globalThis.crypto.randomUUID().replaceAll('-','_'),
   syncAttemptId:order.inventoryReservationAttemptId,actorUid:uid,actorRole:role};
  sessionStorage.setItem(key,JSON.stringify(frozen));
 }
 check();functions.useEmulator('127.0.0.1',5001);
 const {actorUid,actorRole,...payload}=frozen;
 const response=await functions.httpsCallable('setV2OrderLifecycle')(payload);check();
 const result=response?.data;
 if(!['applied','already-applied'].includes(result?.status)||result.orderId!==orderId||result.nextStatus!==frozen.nextStatus
  ||result.receiptId!=='single-v2-lifecycle-'+frozen.operationId||!Array.isArray(result.items)
  ||JSON.stringify(result.items.map(row=>row.itemId).sort())!==JSON.stringify(frozen.itemIds)
  ||!['completed','recovery-pending','not-applicable'].includes(result.postCommitAllocation?.status))
  throw Error('取消／恢復回覆無法核對，請保留原識別碼確認結果。');
 const refreshed=await db.collection('orders').doc(orderId).get({source:'server'});check();
 if(!refreshed.exists)throw Error('取消／恢復已回覆成功但訂單回讀失敗，請核對原操作。');
 const savedOrder=refreshed.data();
 // An old receipt may be replayed after a later restore; display the current
 // authoritative order, never replace it with the old target status.
 if(!(savedOrder.orderLifecycleHistory||[]).some(row=>row.operationId===frozen.operationId
  &&row.by===uid&&row.actorRole===role&&row.after?.status===frozen.nextStatus
  &&row.after?.date===frozen.date&&row.after?.reason===frozen.reason))
  throw Error('訂單尚未讀回原取消／恢復憑證，請保留識別碼確認結果。');
 Object.defineProperty(savedOrder,'v2LifecycleOutcome',{value:{warehouseIds:frozen.warehouseIds,postCommitAllocation:result.postCommitAllocation}});
 sessionStorage.removeItem(key);
 return savedOrder;
}

function confirmOrderCancellation(order) {
        const progress=deliveryProgressInfo(order);
        if(progress.remaining<=0){alert('這筆訂單已無剩餘未送貨數量。已送貨品項請使用退貨流程。');return false;}
        const items=normalizedOrderItems(order);
        const reserved=items.reduce((sum,item)=>sum+Math.max(0,Number(item.reservedQty||0)),0);
        const incoming=items.reduce((sum,item)=>sum+Math.max(0,Number(item.supplyOrderedQty||0)-Number(item.receivedQty||0)),0);
        const documents=[...new Set(items.flatMap(item=>item.purchaseDocumentNos||[]))];
        const action=progress.delivered>0?'取消剩餘未送貨數量':'取消訂單';
        const message=[`${action}：${progress.remaining} 個。`, `釋放庫存預留：${reserved} 個；已到貨的貨仍留在庫存。`,
            incoming>0?`尚有 ${incoming} 個採購未到貨；已建立採購單不會自動取消，請到採購待到貨確認：供應商同意取消，或保留採購轉庫存。`:'',
            documents.length?`關聯採購單：${documents.join('、')}`:'',
            progress.delivered>0?'已送貨與退貨紀錄保留，已送出的貨不會自動退回庫存。':''].filter(Boolean).join('\n\n');
        return confirm(message);
}

function applySavedOrderLifecycle(orderId,savedOrder){
    normalizedOrderItems(savedOrder).forEach(item=>{
        const productKey=inventoryProductKey(item);
        const warehouseIds=savedOrder.v2LifecycleOutcome?.warehouseIds
            ||[(item.fulfillmentType||'WAREHOUSE')==='DIRECT_SHIP'?'':(item.warehouseId||savedOrder.warehouseId||'')];
        warehouseIds.forEach(warehouseId=>{if(productKey&&warehouseId)invalidateWarehouseStockCache(productKey,warehouseId);});
    });
    const index=ordersCache.findIndex(item=>item.id===orderId),syncedOrder={id:orderId,...savedOrder};
    if(index>=0)ordersCache[index]=syncedOrder;
    syncOrderIntoPurchasingCaches(syncedOrder);
    writeAppDataCache('orders',ordersCache);
    if(savedOrder.v2LifecycleOutcome?.postCommitAllocation.status==='recovery-pending')
        showActionFeedback('訂單取消已完成；釋放庫存的後續配貨仍待合格物流角色續處理，不代表取消失敗。','warning');
}

window.quickSetOrderLifecycle = async function(orderId, nextStatus) {
    if (!canManageOrderLifecycleCapability() || !canEditPage('orders.list')) { alert('此操作僅限訂單負責業務或管理員。'); return; }
    if (!['normal', 'cancelled'].includes(nextStatus)) return;
    const cachedOrder = ordersCache.find(item => item.id === orderId);
    if (!cachedOrder) return;
    let retry;
    try{retry=globalThis.YUSHIN_V2_LIFECYCLE_EMULATOR===true?pendingV2OrderLifecycle(orderId):null;}catch(err){alert(err.message);return;}
    if(!retry&&cachedOrder.inventoryReservationStatus==='pending'){showActionFeedback('這筆訂單庫存仍在同步，請完成或重試同步後再變更狀態。','warning');return;}
    if(retry&&retry.nextStatus!==nextStatus){alert('請先確認前次取消／恢復結果。');return;}
    if (pendingLifecycleOrderIds.has(orderId) || (!retry&&normalizedOrderStatus(cachedOrder) === nextStatus)) return;
    if(!retry&&nextStatus==='cancelled'&&!confirmOrderCancellation(cachedOrder))return;
    pendingLifecycleOrderIds.add(orderId);
    renderOrdersList();
    if (currentDeliveryOrderId === orderId) { renderDeliveryModal(); renderOrderLifecycleModal(); }
    let committed=false;
    try {
        const savedOrder=await setOrderLifecycleStatus(orderId,nextStatus);
        committed=true;
        // The lifecycle transaction already synchronizes stock and purchase demand.
        applySavedOrderLifecycle(orderId,savedOrder);
        pendingLifecycleOrderIds.delete(orderId);
        renderOrdersList();
        if (currentDeliveryOrderId === orderId) { renderDeliveryModal(); renderOrderLifecycleModal(); }
    } catch (err) {
        pendingLifecycleOrderIds.delete(orderId);
        renderOrdersList();
        if (currentDeliveryOrderId === orderId) { renderDeliveryModal(); renderOrderLifecycleModal(); }
        alert((committed?'訂單狀態已確認，但畫面更新失敗；請重新讀取，勿重建作業：':`${nextStatus === 'normal' ? '恢復' : '取消'}訂單結果未確認：`) + err.message);
    }
};

window.toggleOrderProgressStatus = function(field, newValue) {
    const orderId = currentDeliveryOrderId;
    if (!orderId || !canManageOrderLifecycleCapability() || !canEditPage('orders.list')) return;
    toggleOrderStatus(orderId, field, newValue);
    renderDeliveryModal();
};

window.resetDeliveryForm = function() {
    deliveryCreateAttempt = null;
    deliveryPartialFormOpen = false;
    document.getElementById('deliveryFormPanel').style.display = 'none';
    document.getElementById('deliveryEditId').value = '';
    document.getElementById('deliveryDate').value = localDateString();
    document.getElementById('deliveryQty').value = '';
    document.getElementById('deliveryNotes').value = '';
    document.getElementById('deliveryFormTitle').innerText = '新增送貨紀錄';
    document.getElementById('deliveryCancelEditBtn').style.display = 'none';
    const itemSelect=document.getElementById('deliveryItemId');
    if(itemSelect)itemSelect.disabled=false;
    const order = ordersCache.find(item => item.id === currentDeliveryOrderId);
    const progress = deliveryProgressInfo(order || {});
    document.getElementById('deliveryFormHint').innerText = `目前最多還可登錄 ${progress.remaining} 個。`;
};

window.openPartialDeliveryForm = function() {
    const order = ordersCache.find(item => item.id === currentDeliveryOrderId);
    if (!order || !canManageOrderLifecycleCapability() || !canEditPage('orders.list')) return;
    if (normalizedOrderStatus(order) !== 'normal') { alert('已取消的訂單不能新增送貨紀錄。'); return; }
    const progress = deliveryProgressInfo(order);
    let awaitingConfirmation=false;
    if(globalThis.YUSHIN_V2_DELIVERY_EMULATOR===true){
        try{awaitingConfirmation=!!pendingV2DeliveryConfirmation(order.id);}
        catch(error){alert(error.message);return;}
    }
    if (progress.remaining <= 0&&!awaitingConfirmation) { alert('這筆訂單已全數送貨。'); return; }
    selectOrderProgressTab('delivery');
    deliveryPartialFormOpen = true;
    document.getElementById('deliveryFormPanel').style.display = '';
    document.getElementById('deliveryQty').value = '';
    // The original renderer restores the frozen acknowledgement after reload;
    // opening the form must not erase its quantity or shipment selection.
    if(globalThis.YUSHIN_V2_DELIVERY_EMULATOR===true)renderDeliveryModal();
    document.getElementById('deliveryDate').focus();
};

window.openPartialDeliveryForOrder = function(orderId) {
    if (!canManageOrderLifecycleCapability()) return;
    openDeliveryModal(orderId);
    openPartialDeliveryForm();
};

window.openReturnManagement = function(orderId) {
    if (!canManageOrderLifecycleCapability()) return;
    openDeliveryModal(orderId);
    openReturnForm();
    if (!orderReturnFormOpen) return;
    const form = document.getElementById('returnFormPanel');
    form.scrollIntoView({ behavior: 'smooth', block: 'center' });
    document.getElementById('returnDate').focus();
};

window.openOrderStatusHistory = function(orderId) {
    const order = ordersCache.find(item => item.id === orderId);
    if (!order) return;
    currentOrderHistoryId = orderId;
    orderProgressHistoryExpanded = false;
    document.getElementById('orderHistoryModalTitle').innerText = `操作紀錄：${order.orderNo || order.customerName || '訂單'}`;
    renderOrderStatusHistory(order);
    document.getElementById('orderHistoryModalOverlay').classList.add('active');
};
window.closeOrderStatusHistory = function() {
    currentOrderHistoryId = null;
    document.getElementById('orderHistoryModalOverlay').classList.remove('active');
};

function renderOrderStatusHistory(order) {
    const tbody = document.getElementById('orderStatusHistoryBody');
    if (!tbody) return;
    const entries = [];
    const createdAt=order.createdAt||order.orderDate||'';
    if(createdAt){
        entries.push({
            at:createdAt,
            action:'建立訂單',
            by:order.createdByName||order.createdBy||order.creatorName||order.salesName||'',
            detail:[order.orderNo||order.id||'',order.customerName||''].filter(Boolean).join('｜')
        });
    }
    normalizedOrderItems(order).forEach(item=>{
        const itemLabel=[item.itemCode||'',item.itemName||''].filter(Boolean).join(' ');
        const orderEvents=Array.isArray(item.orderEvents)?item.orderEvents:[];
        orderEvents.forEach(event=>{
            const action=event.type==='SALES_SELF_ORDER'?'業務自行訂貨':'已採購';
            const detail=[itemLabel,event.documentNo||'',event.qty!=null?(`數量 ${event.qty}`):''].filter(Boolean).join('｜');
            entries.push({at:event.at||event.date||item.orderedAt||'',action,by:event.by||'',detail});
        });
        // 已有 orderedAt 的既有資料仍可顯示一筆採購時間，不要求回補歷史事件。
        if(!orderEvents.length&&item.orderedAt&&Number(item.supplyOrderedQty||0)>0){
            const documentNos=[...(item.purchaseDocumentNos||[]),...(item.manualOrderNos||[]),...(item.selfOrderNos||[])].filter(Boolean);
            entries.push({at:item.orderedAt,action:(item.procurementType||'')==='SALES_SELF_ORDER'?'業務自行訂貨':'已採購',by:'',detail:[itemLabel,documentNos.join('、'),`累計 ${Number(item.supplyOrderedQty||0)}`].filter(Boolean).join('｜')});
        }
        (item.receiptEvents||[]).forEach(event=>{
            const action=event.fulfillmentType==='DIRECT_SHIP'?'原廠直送到貨':'採購入庫';
            const detail=[itemLabel,event.qty!=null?(`到貨 ${event.qty}`):'',event.sourceOrderStatus==='cancelled'?'來源訂單已取消，轉自由庫存':''].filter(Boolean).join('｜');
            entries.push({at:event.at||event.date||'',action,by:event.by||'',detail});
        });
    });
    (order.statusHistory || []).forEach(item => entries.push({ at: item.at, action: item.label || '進度變更', by: item.by, detail: '' }));
    (order.deliveryHistory || []).forEach(item => {
        const action = { create: '新增送貨', edit: '修改送貨', delete: '刪除送貨', cancel_all: '取消全部送貨', clear_legacy_estimate: '取消歷史推估' }[item.action] || '送貨異動';
        const record = item.after || item.before || {};
        const detail = record.qty != null ? `${record.date || ''}／${record.qty} 個${record.notes ? `／${record.notes}` : ''}` : '';
        entries.push({ at: item.at, action, by: item.by, detail });
    });
    (order.returnHistory || []).forEach(item => {
        const action = { create: '新增退貨', edit: '修改退貨', delete: '刪除退貨' }[item.action] || '退貨異動';
        const record = item.after || item.before || {};
        entries.push({ at: item.at, action, by: item.by, detail: `${record.date || ''}${record.qty != null ? `／${record.qty} 個` : ''}${record.reason ? `／${record.reason}` : ''}` });
    });
    const deliveryHistoryRecordIds=new Set((order.deliveryHistory||[]).flatMap(item=>[item.after?.id,item.before?.id]).filter(Boolean));
    savedDeliveryRecords(order).forEach(record=>{
        if(record.id&&deliveryHistoryRecordIds.has(record.id))return;
        entries.push({at:record.createdAt||record.date||'',action:'送貨紀錄',by:record.createdBy||'',detail:`${record.date||''}${record.qty!=null?`／${record.qty} 個`:''}${record.notes?`／${record.notes}`:''}`});
    });
    const returnHistoryRecordIds=new Set((order.returnHistory||[]).flatMap(item=>[item.after?.id,item.before?.id]).filter(Boolean));
    savedReturnRecords(order).forEach(record=>{
        if(record.id&&returnHistoryRecordIds.has(record.id))return;
        entries.push({at:record.createdAt||record.date||'',action:'退貨紀錄',by:record.createdBy||'',detail:`${record.date||''}${record.qty!=null?`／${record.qty} 個`:''}${record.reason?`／${record.reason}`:''}`});
    });
    (order.orderLifecycleHistory || []).forEach(item => {
        const statusLabels = { normal: '恢復正常', cancelled: '取消訂單', voided: '取消訂單' };
        const after = item.after || {};
        entries.push({ at: item.at, action: statusLabels[after.status] || '訂單狀態變更', by: item.by, detail: `${after.date || ''}${after.reason ? `／${after.reason}` : ''}` });
    });
    (order.fieldEditHistory || []).forEach(item => entries.push({ at: item.at, action: item.label || '修改資料', by: item.by, detail: `${item.before ?? '－'} → ${item.after ?? '－'}` }));
    // 採購／到貨狀態由 supplyOrders、receipts、reservation 與 dispatch qty 推導。
    if (order.isBilled && !(order.statusHistory || []).some(item => item.field === 'isBilled')) {
        entries.push({ at: orderBillingDate(order) || order.orderDate || '', action: '核銷（歷史推估）', by: '舊資料未記錄', detail: '依目前核銷狀態推估' });
    }
    if (order.isDelivered && !savedDeliveryRecords(order).length && !(order.deliveryHistory || []).length) {
        entries.push({ at: order.orderDate || '', action: '送貨（歷史推估）', by: '舊資料未記錄', detail: '依目前訂單狀態推估，日期暫用訂單日期' });
    }
    for(const h of order.logisticsHistory||[])entries.push({at:h.at,action:h.action,by:h.by,detail:h.detail||''});
    entries.sort((a, b) => String(b.at || '').localeCompare(String(a.at || '')));
    tbody.innerHTML = entries.length ? (orderProgressHistoryExpanded ? entries : entries.slice(0, 5)).map(item => `<tr><td>${escapeHtml(formatOrderStatusTime(item.at))}</td><td>${escapeHtml(item.action || '')}</td><td>${escapeHtml(item.by || '')}</td><td>${escapeHtml(item.detail || '')}</td></tr>`).join('') : '<tr><td colspan="4" style="color:#888;">尚無操作紀錄。</td></tr>';
    document.getElementById('orderHistoryMoreBtn').hidden = orderProgressHistoryExpanded || entries.length <= 5;
    labelOrderProgressRecords('orderStatusHistoryBody', ['時間', '動作', '操作人', '說明']);
}

async function applyInventoryDeliveryDeltaInTransaction(transaction, order, deltaQty, actor, sourceId, reversalRecords) {
    // Customer service is not company-owned stock, including parts bought for the job.
    if(String(order.productType||order.type||'').trim().toUpperCase()==='SERVICE')throw new Error('服務型品項不得走一般商品出貨或庫存還原；請先完成服務作業流程。');
    if(order.transferPendingId)throw new Error('此品項尚在倉庫調撥途中，請目的倉先確認收貨。');
    const deliveryPlan=globalThis.YushinWarehouseLogistics?.plan(order.deliveryPlan||order.shippingInstructions||{});
    if(deltaQty>0&&(order.fulfillmentType||'WAREHOUSE')!=='DIRECT_SHIP'&&deliveryPlan?.mode==='PICKUP'&&order.warehouseId&&order.warehouseId!==defaultWarehouse()?.id&&!String(order.warehouseId).startsWith('custody-'))throw new Error('主倉自領品項仍在分倉，請先完成調回主倉與收貨。');
    if(deltaQty>0&&globalThis.YushinWarehouseLogistics?.businessDeliveryState&&typeof canReceiveInventoryCapability==='function'&&!canReceiveInventoryCapability()){
        const state=globalThis.YushinWarehouseLogistics.businessDeliveryState(order,order,{shippable:deltaQty},defaultWarehouse()?.id||'');
        if(!state.shippable)throw new Error(state.deliveryWait+'，目前不能登錄已送貨。');
    }
    if (!deltaQty || (order.fulfillmentType || 'WAREHOUSE') === 'DIRECT_SHIP') return { reservedDelta:0,newReservedQty:Math.max(0,Number(order.reservedQty||0)),lotAllocations:[],cogs:0 };
    const productKey = inventoryProductKey(order);
    const warehouseId = order.warehouseId || defaultWarehouse()?.id || '';
    const invRef = inventoryRefFor(order);
    const whRef = warehouseId ? db.collection('warehouseStocks').doc(warehouseStockDocId(warehouseId,productKey)) : null;
    if (!invRef || !whRef) throw new Error('此訂單尚未指定有效倉庫，無法進行庫存出貨。');

    const deliveryItemId=String(order.itemId||'').trim();
    if(!deliveryItemId) throw new Error('出貨品項缺少 itemId，無法安全對應庫存預留紀錄。');
    const deliveryReservationRef=db.collection('inventoryReservations').doc(`${sourceId}__${deliveryItemId}`);
    const invSnap = await transaction.get(invRef);
    const whSnap = await transaction.get(whRef);
    const reservationSnap = await transaction.get(deliveryReservationRef);
    if (!whSnap.exists) throw new Error('指定倉庫沒有這個產品的分倉庫存，請先入庫或以庫存調整建立分倉數量。');

    const inv = inventoryNumbers(invSnap.exists ? invSnap.data() : {}), wh = inventoryNumbers(whSnap.data());
    const stockPlan=deltaQty>0?globalThis.YushinReservation.planReservationIssue({
        productKey,warehouseId,qty:deltaQty,reservation:reservationSnap.exists?reservationSnap.data():{},
        aggregateStock:invSnap.exists?invSnap.data():undefined,warehouseStock:whSnap.data(),
        requireReservation:order.requireStockReservation===true,itemReservedQty:order.reservedQty
    }):globalThis.YushinReservation.planReservationReturn({operation:'SHIP_REVERSAL',deltaQty:-deltaQty,
        orderStatus:normalizedOrderStatus(order),productKey,warehouseId,reservation:reservationSnap.exists?reservationSnap.data():{},
        aggregateStock:invSnap.exists?invSnap.data():undefined,warehouseStock:whSnap.data(),itemReservedQty:order.reservedQty
    });
    const newReservedRemaining=stockPlan.reservation.quantity;
    const reservedDelta=stockPlan.reservedDelta;
    const now = new Date().toISOString();
    let lotAllocations=[],cogs=0;

    if (deltaQty > 0) {
        // Web Firestore transactions accept document references, not queries.
        // Discover IDs, then re-read every candidate in the transaction so concurrent
        // delivery/receipt changes force a retry before any stock is written.
        const lotQuery=await db.collection('inventoryLots').where('productKey','==',productKey).where('warehouseId','==',warehouseId).where('remainingQty','>',0).get();
        const lotSnapshots=await Promise.all(lotQuery.docs.map(doc=>transaction.get(doc.ref)));
        const lotDocs=lotSnapshots.filter(doc=>doc.exists).map(doc=>({id:doc.id,...doc.data()}))
            .filter(l=>l.productKey===productKey&&l.warehouseId===warehouseId&&Number(l.remainingQty||0)>0);
        if(!lotDocs.length)throw new Error('此庫存尚未建立批次成本資料，請先完成入庫／期初庫存批次建檔後再送貨。');
        const allocation=globalThis.YushinInventory.allocateLots(lotDocs.map(lot=>({...lot,unitCost:0})),deltaQty);
        lotAllocations=allocation.allocations;cogs=allocation.totalCost;
        lotAllocations.forEach(row=>{
            const lot=lotDocs.find(x=>x.id===row.lotId);
            transaction.update(db.collection('inventoryLots').doc(row.lotId),{remainingQty:Number(lot.remainingQty||0)-row.qty,updatedAt:now});
        });
    } else {
        const restoreQty=Math.abs(deltaQty);
        const sourceRecords=Array.isArray(reversalRecords)&&reversalRecords.length?reversalRecords:savedDeliveryRecords(order);
        const reversal=globalThis.YushinInventory.reverseLotAllocations(sourceRecords,restoreQty);
        lotAllocations=reversal.allocations.map(row=>({...row,qty:-row.qty,cost:-row.cost}));
        const lotIds=[...new Set(reversal.allocations.map(row=>row.lotId))];
        const lotContexts=await Promise.all(lotIds.map(async lotId=>{
            const lotRef=db.collection('inventoryLots').doc(lotId);
            return {lotId,lotRef,lotSnap:await transaction.get(lotRef)};
        }));
        const restored=globalThis.YushinInventory.planLotRestoration({productKey,warehouseId,
            allocations:reversal.allocations,lots:lotContexts.filter(row=>row.lotSnap.exists)
                .map(row=>({...row.lotSnap.data(),id:row.lotId}))});
        for(const row of restored)transaction.update(db.collection('inventoryLots').doc(row.lotId),{remainingQty:row.remainingQty,updatedAt:now});
        cogs=-reversal.totalCost;
    }

    if (invSnap.exists) transaction.set(invRef,{onHand:stockPlan.aggregateStock.onHand,reserved:stockPlan.aggregateStock.reserved,incoming:inv.incoming,updatedAt:now},{merge:true});
    transaction.set(whRef,{warehouseId,productKey,onHand:stockPlan.warehouseStock.onHand,reserved:stockPlan.warehouseStock.reserved,incoming:wh.incoming,updatedAt:now},{merge:true});
    const movementRef=db.collection('inventoryMovements').doc();
    transaction.set(movementRef,inventoryMovementRecord(deltaQty>0?'ship':'ship_reversal',-deltaQty,sourceId,productKey,actor,{
        warehouseId,itemId:deliveryItemId,fulfillmentType:'WAREHOUSE',reservedDelta,lotAllocations,costPending:true,
        warehouseStockId:whRef.id,inventoryDocId:invRef.id,
        ownerUid:order.ownerUid||'',salesCode:order.salesCode||''
    }));

    transaction.set(deliveryReservationRef,{...stockPlan.reservation,...inventoryReservationPayload(sourceId,order,newReservedRemaining,stockPlan.reservation.status),itemId:deliveryItemId,warehouseId},{merge:true});
    return { reservedDelta,newReservedQty:newReservedRemaining,lotAllocations,cogs,movementId:movementRef.id };
}
function applyInventoryDeliveryInTransaction(transaction, orderRef, order, deliveryQty, actor, sourceId) {
    return applyInventoryDeliveryDeltaInTransaction(transaction, order, deliveryQty, actor, sourceId);
}

async function applyInventoryReturnDeltaInTransaction(transaction, order, deltaQty, actor, sourceId, previousReturnRecord) {
    if(String(order.productType||order.type||'').trim().toUpperCase()==='SERVICE')throw new Error('服務型品項不得走一般商品退貨入庫；客戶器材與檢體不是公司庫存。');
    if (!deltaQty || (order.fulfillmentType || 'WAREHOUSE') === 'DIRECT_SHIP') return {lotAllocations:[],cogs:0};
    const productKey = inventoryProductKey(order);
    const warehouseId = order.warehouseId || defaultWarehouse()?.id || '';
    const invRef = inventoryRefFor(order);
    const whRef = warehouseId ? db.collection('warehouseStocks').doc(warehouseStockDocId(warehouseId,productKey)) : null;
    if (!invRef || !whRef) throw new Error('此訂單沒有可追蹤的出貨倉庫。');
    const deliveryItemId=String(order.itemId||'').trim();
    if(!deliveryItemId) throw new Error('退貨品項缺少 itemId，無法安全對應庫存預留紀錄。');
    const reservationRef=db.collection('inventoryReservations').doc(`${sourceId}__${deliveryItemId}`);
    const invSnap = await transaction.get(invRef);
    const whSnap = await transaction.get(whRef);
    const reservationSnap = await transaction.get(reservationRef);
    if (!whSnap.exists) throw new Error('找不到原出貨倉庫庫存。');
    const inv=inventoryNumbers(invSnap.exists?invSnap.data():{}), wh=inventoryNumbers(whSnap.data());
    const stockPlan=globalThis.YushinReservation.planReservationReturn({operation:'CUSTOMER_RETURN',deltaQty,
        orderStatus:normalizedOrderStatus(order),settlement:order.customerReturnSettlement||'REPLACE',
        productKey,warehouseId,reservation:reservationSnap.exists?reservationSnap.data():{},
        aggregateStock:invSnap.exists?invSnap.data():undefined,warehouseStock:whSnap.data(),itemReservedQty:order.reservedQty
    });
    const now=new Date().toISOString();
    let lotAllocations=[],cogs=0;
    let selectedAllocations;
    if(deltaQty>0){
        // Editing a return increases only the new delta; its original lots are already returned.
        const priorReturns = savedReturnRecords(order).filter(record => !previousReturnRecord || record.id !== previousReturnRecord.id);
        if (previousReturnRecord) priorReturns.push(previousReturnRecord);
        const available=globalThis.YushinInventory.availableReturnAllocations(savedDeliveryRecords(order),priorReturns);
        const plan=globalThis.YushinInventory.reverseLotAllocations([{qty:available.reduce((sum,row)=>sum+Number(row.qty||0),0),lotAllocations:available}],deltaQty);
        selectedAllocations=plan.allocations;lotAllocations=plan.allocations;cogs=plan.totalCost;
    }else{
        const plan=globalThis.YushinInventory.reverseLotAllocations(previousReturnRecord?[previousReturnRecord]:[],Math.abs(deltaQty));
        selectedAllocations=plan.allocations;
        lotAllocations=plan.allocations.map(row=>({...row,qty:-row.qty,cost:-row.cost}));cogs=-plan.totalCost;
    }
    const lotIds=[...new Set(selectedAllocations.map(row=>row.lotId))];
    const lotContexts=await Promise.all(lotIds.map(async lotId=>{
        const lotRef=db.collection('inventoryLots').doc(lotId);
        return {lotId,lotRef,lotSnap:await transaction.get(lotRef)};
    }));
    const restored=globalThis.YushinInventory.planLotRestoration({productKey,warehouseId,
        allocations:selectedAllocations,direction:deltaQty>0?1:-1,
        lots:lotContexts.filter(row=>row.lotSnap.exists).map(row=>({...row.lotSnap.data(),id:row.lotId}))});
    for(const row of restored)transaction.update(db.collection('inventoryLots').doc(row.lotId),{remainingQty:row.remainingQty,updatedAt:now});
    const nextReservation=stockPlan.reservation.quantity,reservationDelta=stockPlan.reservedDelta;
    transaction.set(invRef,{onHand:stockPlan.aggregateStock.onHand,reserved:stockPlan.aggregateStock.reserved,incoming:inv.incoming,updatedAt:now},{merge:true});
    transaction.set(whRef,{warehouseId,productKey,onHand:stockPlan.warehouseStock.onHand,reserved:stockPlan.warehouseStock.reserved,incoming:wh.incoming,updatedAt:now},{merge:true});
    transaction.set(reservationRef,{...stockPlan.reservation,...inventoryReservationPayload(sourceId,order,nextReservation,stockPlan.reservation.status),itemId:deliveryItemId,warehouseId},{merge:true});
    transaction.set(db.collection('inventoryMovements').doc(),{
        type:deltaQty>0?'return_in':'return_reversal',qty:deltaQty,productKey,warehouseId,
        fulfillmentType:'WAREHOUSE',sourceType:DOCUMENT_TYPES.ORDER,sourceId,
        createdAt:now,createdBy:actor,lotAllocations,costPending:true,reservationDelta,
        ownerUid:order.ownerUid||'',salesCode:order.salesCode||''
    });
    return {lotAllocations,cogs,reservationDelta,newReservedQty:nextReservation};
}

// A legacy estimate is metadata, not a physical shipment or stock movement.
// Re-read in the protected transaction so a stale modal cannot erase real records.
async function clearOrderLegacyDeliveryEstimate(orderId) {
    const actor=deliveryActor(),at=new Date().toISOString();
    let savedOrder;
    await runRoleTransaction(async transaction=>{
        const ref=db.collection('orders').doc(orderId);
        const snapshot=await transaction.get(ref);
        if(!snapshot.exists)throw new Error('找不到這筆訂單。');
        const order=snapshot.data();
        if(savedDeliveryRecords(order).length)
            throw new Error('這筆訂單已有實際送貨紀錄，請重新整理後逐筆更正。');
        if(returnedQuantity(order)>0)
            throw new Error('這筆訂單已有退貨紀錄，請先更正退貨紀錄。');
        if(!deliveryProgressInfo(order).isLegacyEstimated){savedOrder=order;return;}
        const history={action:'clear_legacy_estimate',
            before:{isDelivered:true,estimatedDate:order.orderDate||''},
            after:null,by:actor,at};
        const updates={isDelivered:false,deliveredQty:0,deliveryRecords:[],
            deliveryHistory:firebase.firestore.FieldValue.arrayUnion(history),updatedAt:at};
        Object.assign(updates,orderWorkIndexFields({...order,...updates}));
        transaction.update(ref,updates);
        savedOrder={...order,...updates,deliveryHistory:[...(order.deliveryHistory||[]),history]};
    });
    return savedOrder;
}
// Emulator-only bridge. A customer acknowledgement never writes physical stock.
function pendingV2DeliveryConfirmation(orderId){
 if(globalThis.YUSHIN_V2_DELIVERY_EMULATOR!==true)return null;
 const key='v2-delivery:'+encodeURIComponent(currentUser?.uid||'')+':'+encodeURIComponent(orderId);
 const raw=sessionStorage.getItem(key);
 if(!raw)return null;
 try{
  const intent=JSON.parse(raw);
  if(!intent||intent.orderId!==orderId||intent.actorUid!==currentUser?.uid
    ||intent.actorRole!==currentUserRole||!intent.operationId)
    throw Error('invalid pending delivery actor');
  return intent;
 }catch(_){throw Error('前次客戶送達結果尚未確認，請使用原帳號核對，不能重新登錄。');}
}
function v2DeliveryEmulatorTransport(){
 const local=host=>host==='localhost'||host==='127.0.0.1';
 if(globalThis.YUSHIN_V2_DELIVERY_EMULATOR!==true||!local(globalThis.location?.hostname)||typeof firebase==='undefined'||!firebase.auth||!firebase.functions)
  throw Error('v2 送達目前僅限本機 Emulator。');
 const auth=firebase.auth(),functions=firebase.app().functions('asia-east1'),uid=currentUser?.uid,role=currentUserRole;
 if(auth.app?.options?.projectId!=='demo-yushin'||functions.app?.options?.projectId!=='demo-yushin'
   ||!local(auth.emulatorConfig?.host)||auth.emulatorConfig?.port!==9099)
  throw Error('v2 送達只允許本機 demo-yushin Auth／Functions Emulator。');
 const check=()=>{
  if(!uid||auth.currentUser?.uid!==uid||currentUser?.uid!==uid||currentUserRole!==role
   ||!['admin','sales','engineer'].includes(role)
   ||!canManageOrderLifecycleCapability()||!canEditPage('orders.list'))
   throw Error('登入身分或送達作業權限已變更。');
 };
 check();return {uid,role,functions,check};
}
async function confirmV2ShipmentDeliveryEmulator(orderId,{date,qty,notes='',itemId='',shipmentId='',recordId}){
 const {uid,role,functions,check}=v2DeliveryEmulatorTransport();
 if(pendingV2DeliveryReversal(orderId))throw Error('尚有未確認的送達撤銷，請先核對原操作。');
 if(!Number.isSafeInteger(qty)||qty<=0||typeof date!=='string'
  ||!/^([0-9]{4})-([0-9]{2})-([0-9]{2})$/.test(date)
  ||!Number.isFinite(Date.parse(date+'T00:00:00Z'))
  ||new Date(date+'T00:00:00Z').toISOString().slice(0,10)!==date
  ||typeof notes!=='string'||notes.length>1000)
  throw Error('v2 送達數量、日期或備註不正確。');
 const key='v2-delivery:'+encodeURIComponent(uid)+':'+encodeURIComponent(orderId);
 let frozen=pendingV2DeliveryConfirmation(orderId);
 if(frozen){
  if(frozen.quantity!==qty||frozen.date!==date||frozen.notes!==notes
   ||(itemId&&frozen.itemId!==itemId)||(shipmentId&&frozen.shipmentId!==shipmentId))
   throw Error('尚有未確認的送達結果，請以原品項、來源出貨、數量與日期重試。');
 }else{
  if(!/^[a-zA-Z0-9_-]{12,96}$/.test(recordId||''))throw Error('送達操作識別碼不正確。');
  const snapshot=await db.collection('orders').doc(orderId).get({source:'server'});check();
  if(!snapshot.exists)throw Error('找不到原始訂單。');
  const order=snapshot.data(),rows=order.items||[];
  const resolvedItemId=itemId||(rows.length===1?rows[0].itemId:'');
  if(order.inventoryReservationStatus!=='completed'||!order.inventoryReservationAttemptId
    ||rows.length<1||rows.length>5||!resolvedItemId)
    throw Error('訂單尚未具備完整的 v2 送達來源。');
  const source=(order.warehouseShipmentRecords||[]).find(s=>s.id===shipmentId&&s.itemId===resolvedItemId);
  if(!source)throw Error('請先選擇這個品項的實際出貨紀錄。');
  const projected=globalThis.YushinFulfillment.projectOrderShipmentReturns({orderId,items:rows,
   shipments:order.warehouseShipmentRecords||[],deliveries:order.deliveryRecords||[],returns:order.returnRecords||[]});
  const part=projected.items.find(row=>row.itemId===resolvedItemId);
  const remaining=part?.shipments.find(row=>row.shipmentId===shipmentId)?.pendingQty;
  if(!Number.isSafeInteger(remaining)||qty>remaining)throw Error('本筆出貨尚待確認送達數量不足，請重新讀取。');
  frozen={orderId,itemId:resolvedItemId,shipmentId,quantity:qty,date,notes,
   operationId:recordId,syncAttemptId:order.inventoryReservationAttemptId,actorUid:uid,actorRole:role};
  sessionStorage.setItem(key,JSON.stringify(frozen));
 }
 check();functions.useEmulator('127.0.0.1',5001);
 const {actorUid,actorRole,...payload}=frozen;
 const response=await functions.httpsCallable('confirmV2ShipmentDelivery')(payload);check();
 const data=response?.data;
 if(!['applied','already-applied'].includes(data?.status)||data.recordId!==frozen.operationId
    ||data.orderId!==orderId||data.itemId!==frozen.itemId||data.shipmentId!==frozen.shipmentId)
  throw Error('送達回覆無法核對，必須保留原識別碼重試。');
 const refreshed=await db.collection('orders').doc(orderId).get({source:'server'});check();
 if(!refreshed.exists)throw Error('送達回覆成功但訂單回讀失敗，請核對原操作。');
 sessionStorage.removeItem(key);
 return refreshed.data();
}

function pendingV2DeliveryReversal(orderId){
 if(globalThis.YUSHIN_V2_DELIVERY_EMULATOR!==true)return null;
 const raw=sessionStorage.getItem('v2-delivery-reversal:'+encodeURIComponent(currentUser?.uid||'')+':'+encodeURIComponent(orderId));
 if(!raw)return null;
 try{
  const intent=JSON.parse(raw);
  if(!intent||intent.orderId!==orderId||intent.actorUid!==currentUser?.uid
   ||intent.actorRole!==currentUserRole||!intent.operationId||!intent.deliveryRecordId)
   throw Error('invalid pending reversal actor');
  return intent;
 }catch(_){throw Error('前次送達撤銷尚未確認，請使用原帳號與角色核對。');}
}
async function reverseV2ShipmentDeliveryEmulator(orderId,deliveryRecordId,{date,reason,operationId}){
 const {uid,role,functions,check}=v2DeliveryEmulatorTransport();
 if(pendingV2DeliveryConfirmation(orderId))throw Error('尚有未確認的送達登錄，請先核對原操作。');
 if(typeof reason!=='string'||!reason.trim()||reason.length>1000||typeof date!=='string'
  ||!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date+'T00:00:00Z'))
  ||new Date(date+'T00:00:00Z').toISOString().slice(0,10)!==date)
  throw Error('請填寫正確的撤銷日期與原因。');
 reason=reason.trim();
 const key='v2-delivery-reversal:'+encodeURIComponent(uid)+':'+encodeURIComponent(orderId);
 let frozen=pendingV2DeliveryReversal(orderId);
 if(frozen){
  if(frozen.deliveryRecordId!==deliveryRecordId||frozen.date!==date||frozen.reason!==reason)
   throw Error('尚有未確認的送達撤銷，請使用原紀錄、日期與原因重試。');
 }else{
  if(!/^[a-zA-Z0-9_-]{12,96}$/.test(operationId||''))throw Error('撤銷操作識別碼不正確。');
  const snapshot=await db.collection('orders').doc(orderId).get({source:'server'});check();
  if(!snapshot.exists)throw Error('找不到原始訂單。');
  const order=snapshot.data(),record=(order.deliveryRecords||[]).find(row=>row.id===deliveryRecordId);
  if(order.inventoryReservationStatus!=='completed'||!order.inventoryReservationAttemptId
   ||!record||record.sourceType!=='WAREHOUSE_SHIPMENT_CONFIRMATION'||record.orderId!==orderId
   ||!order.items?.some(row=>row.itemId===record.itemId))throw Error('找不到可撤銷的原始送達確認。');
  if((order.returnRecords||[]).length)throw Error('已有實物退貨的送達撤銷尚未開放。');
  frozen={orderId,itemId:record.itemId,deliveryRecordId,operationId,
   syncAttemptId:order.inventoryReservationAttemptId,date,reason,actorUid:uid,actorRole:role};
  sessionStorage.setItem(key,JSON.stringify(frozen));
 }
 check();functions.useEmulator('127.0.0.1',5001);
 const {actorUid,actorRole,...payload}=frozen;
 const response=await functions.httpsCallable('reverseV2ShipmentDelivery')(payload);check();
 const result=response?.data;
 if(!['applied','already-applied'].includes(result?.status)||result.operationId!==frozen.operationId
  ||result.orderId!==orderId||result.itemId!==frozen.itemId||result.deliveryRecordId!==deliveryRecordId)
  throw Error('撤銷回覆無法核對，請保留原識別碼重試。');
 const refreshed=await db.collection('orders').doc(orderId).get({source:'server'});check();
 if(!refreshed.exists)throw Error('撤銷已回覆成功但訂單回讀失敗，請核對原操作。');
 sessionStorage.removeItem(key);
 return refreshed.data();
}

// Order delivery mutations. UI owns input/feedback; this service owns protected writes.
function assertOrderDeliveryIncrease(order,item,qty) {
    if(String(item?.productType||item?.type||'').trim().toUpperCase()==='SERVICE')
        throw new Error('服務型品項不能使用商品送貨紀錄；須另有服務完成及客戶交付憑證。');
    if(qty<=0)return;
    if(orderInventorySyncIncomplete(order))throw new Error('訂單庫存尚未同步完成');
    if((item.fulfillmentType||'WAREHOUSE')==='DIRECT_SHIP')return;
    const single=normalizedOrderItems(order).length===1;
    const gross=savedDeliveryRecords(order).filter(row=>row.itemId===item.itemId||(!row.itemId&&single))
        .reduce((sum,row)=>sum+Number(row.qty||0),0);
    const state=globalThis.YushinFulfillment.dispatchState({deliveredQty:gross,
        reservedQty:item.reservedQty,dispatchPreparedQty:item.dispatchPreparedQty});
    if(qty>state.shippable+1e-9)throw new Error(`${item.itemName||'品項'} 目前已打單可出貨數量只有 ${state.shippable}。`);
    return state;
}

function deliveryRecordWasReversed(order,recordId) {
    return (order.deliveryHistory||[]).some(row=>
        (row.action==='delete'&&row.recordId===recordId)
        ||(row.action==='cancel_all'&&(row.before?.records||[]).some(record=>record.id===recordId)));
}

async function completeOrderDelivery(orderId,today) {
    if(globalThis.YUSHIN_V2_DELIVERY_EMULATOR===true)throw Error('v2 送達必須逐筆對應原出貨；不可使用一般送貨或更正扣帳。');
    const actor=deliveryActor(),now=new Date().toISOString(),recordId=deliveryRecordId();
    let savedOrder;
    await runRoleTransaction(async transaction => {
        const ref = db.collection('orders').doc(orderId);
        const snapshot = await transaction.get(ref);
        if (!snapshot.exists) throw new Error('找不到這筆訂單。');
        const order = snapshot.data();
        if (normalizedOrderStatus(order) !== 'normal') throw new Error('這筆訂單已取消。');
        if(orderInventorySyncIncomplete(order))throw new Error('訂單庫存尚未同步完成');
        const transactionItems=normalizedOrderItems(order);
        // UI 已阻擋多品項一鍵送貨；transaction 仍要以最新資料再次驗證，
        // 避免 stale cache 或另一端剛修改品項後寫入無法歸屬品項的送貨紀錄。
        if (transactionItems.length !== 1) throw new Error('多品項訂單不能一鍵完成送貨，請逐品項登錄。');
        if (order.isDelivered && savedDeliveryRecords(order).length === 0) throw new Error('這筆舊資料已視為全數送貨。');
        const total = orderQuantity(order);
        const records = savedDeliveryRecords(order).slice();
        const {effectiveDelivered}=orderDeliveryProjection(order);
        const remaining = Math.max(0, total - effectiveDelivered);
        if (!total) throw new Error('訂單數量必須大於 0，才能登錄送貨。');
        if (remaining <= 0) {savedOrder=order;return;}
        assertOrderDeliveryIncrease(order,transactionItems[0],remaining);
        const record = { id: recordId, itemId:transactionItems[0].itemId, date: today, qty: remaining, notes: '一鍵完成剩餘送貨', createdBy: actor, createdAt: now };
        records.push(record);
        const history = { action: 'create', source: 'quick_complete', recordId: record.id, before: null, after: record, by: actor, at: now };
        const statusEntries = [];
        const deliveryItem=transactionItems[0];
        const itemOrder={...order,...deliveryItem,deliveryRecords:records.filter(row=>row.itemId===deliveryItem.itemId),isDelivered:false};
        const inventoryResult=await applyInventoryDeliveryInTransaction(transaction, ref, itemOrder, remaining, actor, orderId);
        record.lotAllocations=inventoryResult?.lotAllocations||[];
        record.cogs=Number(inventoryResult?.cogs||0);
        records[records.length-1]=record;
        const nextItems=transactionItems.map((item,index)=>index===0?{...item,reservedQty:Number(inventoryResult?.newReservedQty??item.reservedQty??0)}:item);
        const grossAfterDelivery = records.reduce((sum, item) => sum + (parseFloat(item.qty) || 0), 0);
        const effectiveAfterDelivery = orderDeliveryProjection({...order,deliveryRecords:records,isDelivered:false}).effectiveDelivered;
        const updates = {
            items:nextItems, deliveryRecords: records, deliveredQty: grossAfterDelivery, isDelivered: effectiveAfterDelivery >= total,
            deliveryHistory: firebase.firestore.FieldValue.arrayUnion(history)
        };
        if (statusEntries.length) updates.statusHistory = firebase.firestore.FieldValue.arrayUnion(...statusEntries);
        Object.assign(updates,orderWorkIndexFields({...order,...updates}));
        transaction.update(ref, updates);
        savedOrder = {
            ...order, ...updates,
            deliveryHistory: [...(order.deliveryHistory || []), history],
            statusHistory: [...(order.statusHistory || []), ...statusEntries]
        };
    });
    return savedOrder;
}

async function cancelOrderDeliveries(orderId) {
    if(globalThis.YUSHIN_V2_DELIVERY_EMULATOR===true)throw Error('v2 送達必須逐筆對應原出貨；不可使用一般送貨或更正扣帳。');
    const actor=deliveryActor(),now=new Date().toISOString();
    let savedOrder;
    await runRoleTransaction(async transaction => {
        const ref = db.collection('orders').doc(orderId);
        const snapshot = await transaction.get(ref);
        if (!snapshot.exists) throw new Error('找不到這筆訂單。');
        const order = snapshot.data();
        // 前端雖已擋多品項，但 transaction 必須再次依最新 Firestore 資料驗證，
        // 避免 stale cache／重複操作把整張訂單的庫存還原到錯誤品項。
        if (normalizedOrderItems(order).length !== 1) throw new Error('只有單品項訂單可以一鍵取消全部送貨，請逐品項更正送貨紀錄。');
        if (returnedQuantity(order) > 0) throw new Error('這筆訂單已有退貨紀錄，請先更正退貨紀錄。');
        if (!savedDeliveryRecords(order).length&&!order.isDelivered) {savedOrder=order;return;}
        const progress = deliveryProgressInfo(order);
        if (progress.state !== 'complete') throw new Error('這筆訂單目前不是全數已送貨狀態。');
        const before = savedDeliveryRecords(order).length
            ? { records: savedDeliveryRecords(order), deliveredQty: progress.delivered }
            : { legacyEstimated: true, estimatedDate: order.orderDate || '', deliveredQty: progress.delivered };
        const history = { action: 'cancel_all', source: 'quick_toggle', before, after: { records: [], deliveredQty: 0 }, by: actor, at: now };
        const currentItems=normalizedOrderItems(order);
        const deliveryItem=currentItems[0];
        assertOrderDeliveryIncrease(order,deliveryItem,0);
        const itemOrder={...order,...deliveryItem,deliveryRecords:savedDeliveryRecords(order),isDelivered:false};
        const inventoryResult=await applyInventoryDeliveryDeltaInTransaction(transaction, itemOrder, -progress.delivered, actor, orderId, savedDeliveryRecords(order));
        const nextItems=currentItems.map((item,index)=>index===0?{...item,reservedQty:Number(inventoryResult?.newReservedQty??item.reservedQty??0)}:item);
        const updates = { items:nextItems, deliveryRecords: [], deliveredQty: 0, isDelivered: false, deliveryHistory: firebase.firestore.FieldValue.arrayUnion(history), updatedAt: now };
        Object.assign(updates,orderWorkIndexFields({...order,...updates}));
        transaction.update(ref, updates);
        savedOrder = { ...order, ...updates, deliveryHistory: [...(order.deliveryHistory || []), history] };
    });
    return savedOrder;
}

async function saveOrderDeliveryRecord(orderId,{date,qty,notes='',editId='',itemId='',recordId,shipmentId=''}) {
    if(globalThis.YUSHIN_V2_DELIVERY_EMULATOR===true){
        if(editId)throw Error('v2 已確認的送達紀錄不可直接編輯，請改用送達撤銷流程。');
        return confirmV2ShipmentDeliveryEmulator(orderId,{date,qty,notes,itemId,shipmentId,recordId});
    }
    if(!date||typeof qty!=='number'||!Number.isFinite(qty)||qty<=0)
        throw new Error('請填寫送貨日期與大於 0 的送貨數量。');
    if(!editId&&(typeof recordId!=='string'||!recordId.trim()))throw new Error('缺少送貨作業識別碼，請重新開啟表單。');
    const actor=deliveryActor(),now=new Date().toISOString();
    let savedOrder;
    await runRoleTransaction(async transaction => {
        const ref = db.collection('orders').doc(orderId);
        const snapshot = await transaction.get(ref);
        if (!snapshot.exists) throw new Error('找不到這筆訂單。');
        const order = snapshot.data();
        if (order.isDelivered && savedDeliveryRecords(order).length === 0) throw new Error('請先取消舊資料的歷史推估送貨紀錄。');
        const records = savedDeliveryRecords(order).slice();
        if(!editId&&deliveryRecordWasReversed(order,recordId))
            throw new Error('這筆送貨作業已更正撤銷，不能重試為新的送貨。');
        // A lost response may be retried with the same form attempt ID.
        // Never reinterpret an existing ID as a second physical shipment.
        const submitted=!editId&&records.find(row=>row.id===recordId);
        if(submitted){
            if(submitted.date!==date||Number(submitted.qty)!==qty||String(submitted.notes||'')!==notes
                ||(itemId&&normalizedOrderItems(order).length>1&&submitted.itemId!==itemId))
                throw new Error('這個送貨識別碼已有不同內容，請重新查詢送貨紀錄。');
            savedOrder=order;return;
        }
        const existingIndex = records.findIndex(item => item.id === editId);
        if (editId && existingIndex < 0) throw new Error('這筆送貨紀錄已被其他人修改或刪除，請重新開啟後再試。');
        if (normalizedOrderStatus(order) !== 'normal' && existingIndex < 0) throw new Error('已取消的訂單不能新增送貨紀錄。');
        const previous = existingIndex >= 0 ? records[existingIndex] : null;
        const orderItems=normalizedOrderItems(order);
        // Select only the recorded item: never silently substitute the first item.
        const requestedItemId=previous?.itemId||(orderItems.length===1?orderItems[0]?.itemId:itemId)||'';
        const targetItem=orderItems.find(item=>item.itemId===requestedItemId);
        if(!targetItem)throw new Error('找不到指定送貨品項，請重新開啟訂單確認。');
        if(previous&&previous.itemId===targetItem.itemId&&previous.date===date
            &&Number(previous.qty)===qty&&String(previous.notes||'')===notes){savedOrder=order;return;}
        const itemOtherDelivered=records.filter(r=>r.id!==editId&&((!r.itemId&&orderItems.length===1)||r.itemId===targetItem.itemId)).reduce((s,r)=>s+Number(r.qty||0),0);
        const itemReturns=savedReturnRecords(order).filter(r=>(!r.itemId&&orderItems.length===1)||r.itemId===targetItem.itemId);
        const itemReturned=itemReturns.reduce((s,r)=>s+Number(r.qty||0),0);
        // 退貨後補送必須以「有效送貨量」驗證，而不是歷史累計送貨量。
        // 例如訂購10、曾送10、退2，可再補送2；歷史送貨會成為12，但有效送貨仍是10。
        const itemGrossAfter=itemOtherDelivered+qty;
        if(itemGrossAfter+1e-9<itemReturned)throw new Error(`${targetItem.itemName||'品項'} 累計送貨數量不能低於已登錄的退貨數量 ${itemReturned}。`);
        const itemEffectiveAfter=globalThis.YushinFulfillment.projectOrderDelivery({grossDeliveredQty:itemGrossAfter,returnedQty:itemReturned,returnRecords:itemReturns}).effectiveDelivered;
        if(itemEffectiveAfter>Number(targetItem.qty||0)+1e-9)throw new Error(`${targetItem.itemName||'品項'} 有效送貨數量將超過訂單數量。`);
        assertOrderDeliveryIncrease(order,targetItem,qty-Number(previous?.qty||0));
        const record = previous
            ? { ...previous, itemId:targetItem.itemId, date, qty, notes, updatedBy: actor, updatedAt: now }
            : { id: recordId, itemId:targetItem.itemId, date, qty, notes, createdBy: actor, createdAt: now };
        if (existingIndex >= 0) records[existingIndex] = record; else records.push(record);
        const totalDelivered = records.reduce((sum, item) => sum + (parseFloat(item.qty) || 0), 0);
        const total = orderQuantity(order);
        if (!total) throw new Error('訂單數量必須大於 0，才能登錄送貨。');
        const effectiveTotalDelivered=orderDeliveryProjection({...order,deliveryRecords:records,isDelivered:false}).effectiveDelivered;
        if (effectiveTotalDelivered > total + 1e-9) throw new Error(`有效送貨數量 ${effectiveTotalDelivered} 超過訂單數量 ${total}。`);
        const alreadyReturned = returnedQuantity(order);
        if (totalDelivered + 1e-9 < alreadyReturned) throw new Error(`累計送貨數量不能低於已登錄的退貨數量 ${alreadyReturned}。`);
        const action = previous ? 'edit' : 'create';
        const history = { action, recordId: record.id, before: previous, after: record, by: actor, at: now };
        const updates = { deliveryRecords: records, deliveredQty: totalDelivered, isDelivered: effectiveTotalDelivered >= total, deliveryHistory: firebase.firestore.FieldValue.arrayUnion(history), updatedAt: now };
        const deliveryDelta = qty - Number(previous?.qty || 0);
        if(deliveryDelta){
            const itemRecords=records.filter(r=>r.itemId===targetItem.itemId);
            const itemOrder={...order,...targetItem,qty:Number(targetItem.qty||0),reservedQty:Number(targetItem.reservedQty||0),deliveryRecords:itemRecords,isDelivered:false};
            const inventoryResult=await applyInventoryDeliveryDeltaInTransaction(transaction,itemOrder,deliveryDelta,actor,orderId,deliveryDelta<0&&previous?[previous]:null);
            const syncedItems=orderItems.map(item=>item.itemId===targetItem.itemId?{...item,reservedQty:Number(inventoryResult?.newReservedQty??item.reservedQty??0)}:item);
            updates.items=syncedItems;
            if(deliveryDelta>0){
                record.lotAllocations=[...(previous?.lotAllocations||[]),...(inventoryResult.lotAllocations||[])];
                record.cogs=Number(previous?.cogs||0)+Number(inventoryResult.cogs||0);
                const recordIndex=records.findIndex(r=>r.id===record.id);
                if(recordIndex>=0)records[recordIndex]=record;
                updates.deliveryRecords=records;
            } else if(previous){
                const reversed=(inventoryResult.lotAllocations||[]).map(row=>({...row,qty:Math.abs(Number(row.qty||0))}));
                record.lotAllocations=globalThis.YushinInventory.allocationsAfterReversal(previous.lotAllocations||[],reversed);
                record.cogs=record.lotAllocations.reduce((sum,row)=>sum+Number(row.cost??(Number(row.qty||0)*Number(row.unitCost||0))),0);
                const recordIndex=records.findIndex(r=>r.id===record.id);
                if(recordIndex>=0)records[recordIndex]=record;
                updates.deliveryRecords=records;
            }
        }
        // Build the sentinel only after stock accounting populated the final record.
        updates.deliveryHistory=firebase.firestore.FieldValue.arrayUnion(history);
        Object.assign(updates,orderWorkIndexFields({...order,...updates}));
        transaction.update(ref, updates);
        savedOrder = { ...order, ...updates, deliveryHistory: [...(order.deliveryHistory || []), history] };
    });
    return savedOrder;
}

async function correctOrderDeliveryRecord(orderId,recordId,correctionReason) {
    if(globalThis.YUSHIN_V2_DELIVERY_EMULATOR===true)throw Error('v2 送達必須逐筆對應原出貨；不可使用一般送貨或更正扣帳。');
    if(typeof correctionReason!=='string'||!correctionReason.trim())throw new Error('請填寫誤登更正原因。');
    const actor=deliveryActor(),now=new Date().toISOString();
    let savedOrder;
    await runRoleTransaction(async transaction => {
        const ref = db.collection('orders').doc(orderId);
        const snapshot = await transaction.get(ref);
        if (!snapshot.exists) throw new Error('找不到這筆訂單。');
        const order = snapshot.data();
        const records = savedDeliveryRecords(order);
        const removed = records.find(item => item.id === recordId);
        if (!removed) {
            if((order.deliveryHistory||[]).some(row=>row.action==='delete'&&row.recordId===recordId)) {savedOrder=order;return;}
            throw new Error('找不到這筆送貨紀錄。');
        }
        const next = records.filter(item => item.id !== recordId);
        const totalDelivered = next.reduce((sum, item) => sum + (parseFloat(item.qty) || 0), 0);
        const alreadyReturned = returnedQuantity(order);
        if (totalDelivered + 1e-9 < alreadyReturned) throw new Error(`刪除後的送貨數量會低於已登錄的退貨數量 ${alreadyReturned}，請先更正退貨紀錄。`);
        const history = { action: 'delete', recordId, before: removed, after: null, reason: correctionReason.trim(), by: actor, at: now };
        const orderItems=normalizedOrderItems(order);
        const targetItem=orderItems.find(item=>item.itemId===removed.itemId) || (orderItems.length===1?orderItems[0]:null);
        if(!targetItem)throw new Error('找不到原送貨品項，無法安全還原庫存。');
        assertOrderDeliveryIncrease(order,targetItem,0);
        const itemRecords=records.filter(r=>((!r.itemId&&orderItems.length===1)||r.itemId===targetItem.itemId));
        const itemGrossAfter=itemRecords.filter(r=>r.id!==recordId).reduce((sum,row)=>sum+Number(row.qty||0),0);
        const itemReturned=savedReturnRecords(order)
            .filter(row=>((!row.itemId&&orderItems.length===1)||row.itemId===targetItem.itemId))
            .reduce((sum,row)=>sum+Number(row.qty||0),0);
        if(itemGrossAfter+1e-9<itemReturned)throw new Error(`${targetItem.itemName||'品項'} 刪除後的送貨數量會低於已登錄的退貨數量 ${itemReturned}，請先更正退貨紀錄。`);
        const itemOrder={...order,...targetItem,itemId:targetItem.itemId,qty:Number(targetItem.qty||targetItem.orderedQty||0),reservedQty:Number(targetItem.reservedQty||0),deliveryRecords:itemRecords,isDelivered:false};
        const inventoryResult=await applyInventoryDeliveryDeltaInTransaction(transaction, itemOrder, -Number(removed.qty || 0), actor, orderId, [removed]);
        const syncedItems=orderItems.map(item=>item.itemId===targetItem.itemId?{...item,reservedQty:Number(inventoryResult?.newReservedQty??item.reservedQty??0)}:item);
        const effectiveDelivered=orderDeliveryProjection({...order,deliveryRecords:next,isDelivered:false}).effectiveDelivered;
        const updates = { items:syncedItems, deliveryRecords: next, deliveredQty: totalDelivered, isDelivered: effectiveDelivered >= orderQuantity(order) && orderQuantity(order) > 0, deliveryHistory: firebase.firestore.FieldValue.arrayUnion(history), updatedAt: now };
        Object.assign(updates,orderWorkIndexFields({...order,...updates}));
        transaction.update(ref, updates);
        savedOrder = { ...order, ...updates, deliveryHistory: [...(order.deliveryHistory || []), history] };
    });
    return savedOrder;
}

// Customer cancellation/return writers shared by the existing UI actions.
// No prompts, DOM, query rendering or second inventory implementation.
function customerReturnNeedsLocationReceipt(order) {
    return Array.isArray(order?.warehouseShipmentRecords) && order.warehouseShipmentRecords.length > 0;
}
function assertLegacyCustomerReturnSource(order) {
    if(customerReturnNeedsLocationReceipt(order))
        throw new Error('此出貨來源的退貨收貨尚未開放，請保留待收申請；不能使用一般退貨入庫。');
}
function customerReturnPendingQty(order, itemId, excludeId='') {
    return (order.returnRequests||[]).filter(r=>r.itemId===itemId && r.id!==excludeId && r.status==='PENDING')
        .reduce((sum,r)=>sum+Math.max(0,Number(r.qty)-Number(r.receivedQty||0)),0);
}
function customerReturnActorContext(capability) {
    const actorUid=currentUser?.uid,actorRole=typeof currentUserRole==='undefined'?null:currentUserRole;
    const assertCurrent=()=>{
        if(!actorUid||currentUser?.uid!==actorUid
            ||(typeof currentUserRole==='undefined'?null:currentUserRole)!==actorRole||!capability())
            throw new Error('登入帳號或權限已變更，請重新開啟作業。');
    };
    assertCurrent();return {actorUid,actorRole,assertCurrent};
}
function customerReturnRequestMatches(record,{operationId,itemId,qty,date,reason,actorUid}) {
    return !!record && record.id===operationId && record.itemId===itemId
        && record.qty===qty && record.date===date && record.reason===reason
        && record.settlement==='CLOSE' && record.createdByUid===actorUid;
}
async function readCommittedCustomerReturnRequest(intent,actorRole,assertCurrent) {
    // A concurrent stale proposal can be denied before the SDK retries it.
    // Re-read the profile and immutable request in one fresh, read-only transaction.
    let confirmed=null;
    await runRoleTransaction(async tx=>{
        confirmed=null;assertCurrent();
        const user=await tx.get(db.collection('users').doc(intent.actorUid));assertCurrent();
        if(!user.exists)return;
        const profile=user.data();
        if((profile.active!==undefined&&profile.active!==true)||profile.disabled===true
            ||profile.role!==actorRole||!['admin','sales','engineer'].includes(profile.role))return;
        // Client Rules recheck ownership; transaction retries also re-read this profile.
        const snapshot=await tx.get(db.collection('orders').doc(intent.orderId));assertCurrent();
        if(!snapshot.exists)return;
        const order={...snapshot.data(),id:intent.orderId};
        if(customerReturnRequestMatches((order.returnRequests||[]).find(r=>r.id===intent.operationId),intent))confirmed=order;
    });
    assertCurrent();return confirmed;
}
async function commitCustomerReturnRequest({orderId,itemId,operationId,qty,date,reason=''}) {
    const {actorUid,actorRole,assertCurrent}=customerReturnActorContext(()=>canManageOrderLifecycleCapability());
    if([orderId,itemId,operationId].some(id=>typeof id!=='string'||!id||id!==id.trim()||id.includes('/')||id.length>160)
        ||!Number.isFinite(qty)||qty<=0||typeof reason!=='string'
        ||typeof date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(date)
        ||!Number.isFinite(Date.parse(date+'T00:00:00Z'))
        ||new Date(date+'T00:00:00Z').toISOString().slice(0,10)!==date)
        throw new Error('退貨品項、日期或數量不正確。');
    reason=reason.trim();const actor=deliveryActor();let saved;
    const intent={orderId,itemId,operationId,qty,date,reason,actorUid};
    try{await runRoleTransaction(async tx=>{
        assertCurrent();const ref=db.collection('orders').doc(orderId),snap=await tx.get(ref);assertCurrent();
        if(!snap.exists)throw new Error('找不到訂單。');const order={...snap.data(),id:orderId};
        const requests=[...(order.returnRequests||[])],prior=requests.find(r=>r.id===operationId);
        if(prior){
            if(!customerReturnRequestMatches(prior,intent))
                throw new Error('退貨申請識別碼已對應其他內容，請先查詢原申請結果。');
            saved=order;return;
        }
        const item=normalizedOrderItems(order).find(i=>i.itemId===itemId);if(!item)throw new Error('找不到原送貨品項。');
        const allowed=returnItemDeliveredQty(order,itemId)-returnItemReturnedQty(order,itemId)-customerReturnPendingQty(order,itemId);
        if(requests.length>=30)throw new Error('每張訂單最多 30 次退貨申請，請先處理既有申請。');
        if(qty>allowed+1e-9)throw new Error(`最多可申請 ${Math.max(0,allowed)} 個；已扣除其他待收退貨。`);
        const now=new Date().toISOString(),record={id:operationId,itemId,qty,receivedQty:0,date,reason,status:'PENDING',settlement:'CLOSE',createdAt:now,createdBy:actor,createdByUid:actorUid};
        requests.push(record);const patch={returnRequests:requests,returnPending:true,returnRequestMutationIndex:requests.length-1,updatedAt:now};
        assertCurrent();tx.update(ref,patch);saved={...order,...patch};
    });}catch(error){
        if(error.code!=='permission-denied')throw error;
        assertCurrent();
        try{saved=await readCommittedCustomerReturnRequest(intent,actorRole,assertCurrent);}
        catch(_){assertCurrent();throw error;}
        if(!saved)throw error;
    }
    assertCurrent();return saved;
}
async function commitCustomerReturnWithdrawal({orderId,requestId}) {
    const {actorUid,assertCurrent}=customerReturnActorContext(()=>canManageOrderLifecycleCapability());let saved;
    await runRoleTransaction(async tx=>{
        assertCurrent();const ref=db.collection('orders').doc(orderId),snap=await tx.get(ref);assertCurrent();
        if(!snap.exists)throw new Error('找不到訂單。');const order={...snap.data(),id:orderId},requests=[...(order.returnRequests||[])];
        const index=requests.findIndex(r=>r.id===requestId);if(index<0)throw new Error('找不到退貨申請。');
        if(requests[index].status!=='PENDING'){saved=order;return;}
        const now=new Date().toISOString();requests[index]={...requests[index],status:'CANCELLED',cancelledAt:now,cancelledBy:actorUid};
        const patch={returnRequests:requests,returnPending:requests.some(r=>r.status==='PENDING'),returnRequestMutationIndex:index,updatedAt:now};
        assertCurrent();tx.update(ref,patch);saved={...order,...patch};
    });
    assertCurrent();return saved;
}
async function commitCancelledPurchaseKeepStock({supplyId,warehouseId,expectedDirect}) {
    const {actorUid,assertCurrent}=customerReturnActorContext(()=>canCreatePurchaseOrderCapability());let saved;
    const actor=deliveryActor();
    if(typeof expectedDirect!=='boolean')throw new Error('缺少原採購收貨方式。');
    await runRoleTransaction(async tx=>{
        assertCurrent();const ref=supplyOrdersCollection().doc(supplyId),snap=await tx.get(ref);assertCurrent();
        if(!snap.exists)throw new Error('找不到採購品項。');const supply={...snap.data(),id:supplyId};
        const orderSnap=await tx.get(db.collection('orders').doc(supply.orderId));assertCurrent();
        if(!orderSnap.exists||normalizedOrderStatus(orderSnap.data())==='normal')throw new Error('客戶訂單未取消，請重新確認。');
        if(isPurchaseTerminalStatus(supply.status))throw new Error('採購已取消／結案。');
        if(supply.customerCancellationDisposition==='KEEP_STOCK'){saved=supply;return;}
        const remaining=Math.max(0,Number(supply.qty||0)-Number(supply.receivedQty||0));
        if(!remaining)throw new Error('此品項已全部到貨。');
        const key=String(supply.productKey||supply.productId||''),redirect=supply.fulfillmentType==='DIRECT_SHIP';
        if(redirect!==expectedDirect)throw new Error('採購收貨方式已變更，請更新清單後重新確認。');
        if(redirect)await assertActiveReturnWarehouse(tx,warehouseId);
        const invRef=redirect?db.collection('inventory').doc(encodeURIComponent(key)):null;
        const whRef=redirect?db.collection('warehouseStocks').doc(warehouseStockDocId(warehouseId,key)):null;
        const invSnap=invRef?await tx.get(invRef):null,whSnap=whRef?await tx.get(whRef):null;
        if(redirect&&!key)throw new Error('缺少產品識別碼。');
        const now=new Date().toISOString(),patch={customerCancellationDisposition:'KEEP_STOCK',customerCancellationResolvedAt:now,customerCancellationResolvedBy:actorUid,updatedAt:now};
        assertCurrent();
        if(redirect){
            Object.assign(patch,{originalFulfillmentType:'DIRECT_SHIP',fulfillmentType:'WAREHOUSE',warehouseId,redirectInventoryId:encodeURIComponent(key),redirectWarehouseStockId:warehouseStockDocId(warehouseId,key),incomingRegisteredQty:remaining});
            const info={productKey:key,productId:supply.productId||key,itemCode:supply.itemCode||'',itemName:supply.itemName||'',brand:supply.brand||'',updatedAt:now};
            tx.set(invRef,{...info,incoming:Number(invSnap?.data()?.incoming||0)+remaining},{merge:true});
            tx.set(whRef,{...info,warehouseId,incoming:Number(whSnap?.data()?.incoming||0)+remaining},{merge:true});
            tx.set(db.collection('inventoryMovements').doc('redirect-'+supplyId),{type:'cancelled_direct_ship_redirect',qty:remaining,productKey:key,warehouseId,sourceType:'SUPPLY_ORDER',sourceId:supplyId,createdAt:now,createdBy:actor});
        }
        tx.update(ref,patch);saved={...supply,...patch};
        // runRoleTransaction mirrors supply changes to the receiving view atomically.
    });
    assertCurrent();return saved;
}
async function postCustomerReturnStock(tx,order,item,qty,receiptId,warehouseId){
    assertLegacyCustomerReturnSource(order);
    const itemDeliveries=savedDeliveryRecords(order).filter(r=>r.itemId===item.itemId||(!r.itemId&&order.items.length===1));
    const itemReturns=savedReturnRecords(order).filter(r=>r.itemId===item.itemId||(!r.itemId&&order.items.length===1));
    if((item.fulfillmentType||order.fulfillmentType||'WAREHOUSE')!=='DIRECT_SHIP'){
        // Settlement returns are free stock; never reserve them for the original customer.
        return applyInventoryReturnDeltaInTransaction(tx,{...order,...item,customerReturnSettlement:'CLOSE',warehouseId,itemId:item.itemId,deliveryRecords:itemDeliveries,returnRecords:itemReturns},qty,deliveryActor(),order.id,null);
    }
    const supplyId=(item.receiptEvents||[]).find(e=>e.fulfillmentType==='DIRECT_SHIP'&&e.sourceId)?.sourceId;
    if(!supplyId)throw new Error('直送退貨缺少原採購來源，請先以「待檢」收貨，補齊原採購來源後再转庫存。');
    const supplySnap=await tx.get(db.collection('receivingSupplyOrders').doc(supplyId));
    if(!supplySnap.exists)throw new Error('找不到原直送採購資料，請先以待檢收貨。');
    const key=inventoryProductKey(item),invRef=db.collection('inventory').doc(encodeURIComponent(key)),whRef=db.collection('warehouseStocks').doc(warehouseStockDocId(warehouseId,key));
    const invSnap=await tx.get(invRef),whSnap=await tx.get(whRef),lotRef=db.collection('inventoryLots').doc('return-'+receiptId);
    const now=new Date().toISOString(),info={productKey:key,productId:item.productId||key,itemCode:item.itemCode||'',itemName:item.itemName||'',brand:item.brand||'',updatedAt:now};
    tx.set(invRef,{...info,onHand:Number(invSnap.data()?.onHand||0)+qty},{merge:true});
    tx.set(whRef,{...info,warehouseId,onHand:Number(whSnap.data()?.onHand||0)+qty},{merge:true});
    tx.set(lotRef,{...info,warehouseId,qty,remainingQty:qty,sourceType:'SUPPLY_ORDER',sourceId:supplyId,returnReceiptId:receiptId,receivedAt:now,createdAt:now,lotNo:'退貨-'+receiptId});
    tx.set(db.collection('inventoryLotCosts').doc(lotRef.id),{lotId:lotRef.id,productKey:key,warehouseId,costSourceSupplyId:supplyId,sourceType:'SUPPLY_ORDER',sourceId:supplyId,createdAt:now});
    tx.set(db.collection('inventoryMovements').doc('return-'+receiptId),{type:'customer_return_received',qty,productKey:key,warehouseId,sourceType:'ORDER',sourceId:order.id,returnReceiptId:receiptId,createdAt:now,createdBy:deliveryActor()});
    return {lotAllocations:[{lotId:lotRef.id,qty}],newReservedQty:Number(item.reservedQty||0)};
}

async function assertActiveReturnWarehouse(tx,warehouseId){
    if(typeof warehouseId!=='string'||!warehouseId||warehouseId.startsWith('custody-'))throw new Error('退貨收貨只能使用有效的實體倉庫。');
    const warehouseSnap=await tx.get(db.collection('warehouses').doc(warehouseId));
    const warehouse=warehouseSnap.exists?warehouseSnap.data():null;
    if(!warehouse||warehouse.active===false||warehouse.systemCustody===true||warehouse.warehouseType==='CUSTODY')
        throw new Error('收貨倉庫不存在、已停用或屬於業務保管位置，請重新選擇。');
}
async function commitCustomerReturnReceipt({orderId,requestId,receiptId,qty,quality,warehouseId}){
    if(!canReceiveInventoryCapability())throw new Error('無收貨權限。');
    const actorUid=currentUser?.uid;
    await runRoleTransaction(async tx=>{
        if(!actorUid||currentUser?.uid!==actorUid||!canReceiveInventoryCapability())throw new Error('登入帳號或權限已變更，請重新開啟退貨收貨。');
        const receiptRef=db.collection('customerReturnReceipts').doc(receiptId),orderRef=db.collection('orders').doc(orderId);
        const receiptSnap=await tx.get(receiptRef),orderSnap=await tx.get(orderRef);
        if(currentUser?.uid!==actorUid||!canReceiveInventoryCapability())throw new Error('登入帳號或權限已變更，請重新開啟退貨收貨。');
        if(receiptSnap.exists){
            const receipt=receiptSnap.data();
            if(receipt.orderId!==orderId||receipt.requestId!==requestId||receipt.qty!==qty||receipt.quality!==quality||receipt.warehouseId!==warehouseId||receipt.receivedBy!==actorUid)throw new Error('退貨重試識別碼已對應其他收貨內容，請先查詢原收貨結果。');
            return;
        }
        if(!orderSnap.exists)throw new Error('來源訂單已不存在。');
        const order={id:orderId,...orderSnap.data()};
        assertLegacyCustomerReturnSource(order);
        const requests=[...(order.returnRequests||[])],index=requests.findIndex(r=>r.id===requestId);
        if(index<0||requests[index].status!=='PENDING')throw new Error('退貨申請已撤回或完成。');
        const request=requests[index],remaining=Number(request.qty)-Number(request.receivedQty||0);
        if(!Number.isFinite(qty)||qty<=0||qty>remaining+1e-9)throw new Error(`實收數量不可超過 ${remaining}。`);
        const item=normalizedOrderItems(order).find(i=>i.itemId===request.itemId);if(!item)throw new Error('找不到退貨品項。');
        await assertActiveReturnWarehouse(tx,warehouseId);
        if((item.fulfillmentType||order.fulfillmentType||'WAREHOUSE')!=='DIRECT_SHIP'&&item.warehouseId&&item.warehouseId!==warehouseId)
            throw new Error('一般退貨必須收到原出貨倉庫，再使用正式調撥流程。');
        if(returnItemReturnedQty(order,item.itemId)+qty>returnItemDeliveredQty(order,item.itemId)+1e-9)throw new Error('累計實收退貨超過已送貨數量。');
        if(!['SALEABLE','INSPECTION','DAMAGED'].includes(quality)||!warehouseId)throw new Error('收貨狀況或倉庫無效。');
        let result={lotAllocations:[]};
        if(quality==='SALEABLE')result=await postCustomerReturnStock(tx,order,item,qty,receiptId,warehouseId);
        else if(item.fulfillmentType!=='DIRECT_SHIP'){
            const deliveries=savedDeliveryRecords(order).filter(r=>r.itemId===item.itemId||(!r.itemId&&order.items.length===1));
            const returns=savedReturnRecords(order).filter(r=>r.itemId===item.itemId||(!r.itemId&&order.items.length===1));
            const available=YushinInventory.availableReturnAllocations(deliveries,returns);
            result.lotAllocations=YushinInventory.reverseLotAllocations([{qty:available.reduce((s,r)=>s+Number(r.qty||0),0),lotAllocations:available}],qty).allocations;
        }
        if(currentUser?.uid!==actorUid||!canReceiveInventoryCapability())throw new Error('登入帳號或權限已變更，請重新開啟退貨收貨。');
        const now=new Date().toISOString(),record={id:receiptId,requestId,itemId:item.itemId,date:localDateString(),qty,reason:request.reason||'',settlement:'CLOSE',quality,warehouseId,createdAt:now,createdBy:deliveryActor(),lotAllocations:result.lotAllocations||[]};
        requests[index]={...request,receivedQty:Number(request.receivedQty||0)+qty,status:qty>=remaining?'RECEIVED':'PENDING'};
        const records=[...savedReturnRecords(order),record],patch={returnRequests:requests,returnPending:requests.some(r=>r.status==='PENDING'),returnRecords:records,returnedQty:records.reduce((s,r)=>s+Number(r.qty||0),0),returnReceiptId:receiptId,updatedAt:now};
        if(result.newReservedQty!==undefined)patch.items=order.items.map(i=>i.itemId===item.itemId?{...i,reservedQty:result.newReservedQty}:i);
        Object.assign(patch,orderWorkIndexFields({...order,...patch}));
        tx.set(receiptRef,{orderId,requestId,requestIndex:index,qty,quality,warehouseId,itemId:item.itemId,itemName:item.itemName||'',ownerUid:order.ownerUid||'',salesCode:order.salesCode||'',disposition:quality==='SALEABLE'?'STOCK':'HOLD',record,createdAt:now,receivedBy:actorUid});
        tx.update(orderRef,patch);
    });
}

async function commitCustomerReturnHoldRelease(id){
    if(!canReceiveInventoryCapability())throw new Error('無收貨權限。');
    await runRoleTransaction(async tx=>{
        const receiptRef=db.collection('customerReturnReceipts').doc(id),snap=await tx.get(receiptRef);
        if(!snap.exists)throw new Error('找不到退貨收貨紀錄。');const receipt=snap.data();if(receipt.disposition!=='HOLD')return;
        const orderRef=db.collection('orders').doc(receipt.orderId),orderSnap=await tx.get(orderRef);if(!orderSnap.exists)throw new Error('原訂單已不存在。');
        const order={id:receipt.orderId,...orderSnap.data()};
        assertLegacyCustomerReturnSource(order);
        const item=normalizedOrderItems(order).find(i=>i.itemId===receipt.itemId);
        const record=savedReturnRecords(order).find(r=>r.id===id);if(!item||!record)throw new Error('找不到原退貨品項或紀錄。');
        await assertActiveReturnWarehouse(tx,receipt.warehouseId);
        if((item.fulfillmentType||order.fulfillmentType||'WAREHOUSE')!=='DIRECT_SHIP'&&item.warehouseId&&item.warehouseId!==receipt.warehouseId)
            throw new Error('原收貨倉庫與來源訂單不一致，請先查核再轉庫存。');
        await postCustomerReturnStock(tx,{...order,returnRecords:savedReturnRecords(order).filter(r=>r.id!==id)},item,Number(receipt.qty),id,receipt.warehouseId);
        tx.update(receiptRef,{disposition:'STOCK',releasedAt:new Date().toISOString(),releasedBy:currentUser.uid});
    });
}
// Explicit-source return receipt transport. UI enablement is a separate acceptance gate.
function v2CustomerReturnTransport(){
    const local=host=>host==='localhost'||host==='127.0.0.1';
    if(globalThis.YUSHIN_V2_RETURN_RECEIPT_EMULATOR!==true||!local(globalThis.location?.hostname)
        ||typeof firebase==='undefined'||!firebase.auth||!firebase.functions)
        throw Error('退貨實收傳輸目前僅限本機 Emulator。');
    const auth=firebase.auth(),functions=firebase.app().functions('asia-east1');
    const uid=currentUser?.uid,role=currentUserRole;
    if(auth.app?.options?.projectId!=='demo-yushin'||functions.app?.options?.projectId!=='demo-yushin'
        ||!local(auth.emulatorConfig?.host)||auth.emulatorConfig?.port!==9099)
        throw Error('退貨實收只允許本機 demo-yushin Auth／Functions Emulator。');
    const check=()=>{
        if(!uid||auth.currentUser?.uid!==uid||currentUser?.uid!==uid||currentUserRole!==role
            ||!['admin','purchaser','warehouse'].includes(role)||!canReceiveInventoryCapability())
            throw Error('登入身分或退貨收貨權限已變更，請使用原帳號與角色確認。');
    };
    check();return {uid,role,functions,check};
}
function v2CustomerReturnPendingKey(uid,orderId){
    return 'v2-return-receipt:'+encodeURIComponent(uid)+':'+encodeURIComponent(orderId);
}
function normalizeV2CustomerReturnReceipt(input){
    const intent=globalThis.YushinFulfillment.normalizeLocationReturnIntent(input);
    if(!intent.requestId||intent.settlement!=='CLOSE')throw Error('退貨實收必須連結原申請並結案，不自動補送。');
    return intent;
}
function pendingV2CustomerReturnReceipt(orderId){
    if(globalThis.YUSHIN_V2_RETURN_RECEIPT_EMULATOR!==true)return null;
    const raw=sessionStorage.getItem(v2CustomerReturnPendingKey(currentUser?.uid||'',orderId));
    if(!raw)return null;
    try{
        const saved=JSON.parse(raw),intent=normalizeV2CustomerReturnReceipt(saved.intent);
        if(saved.actorUid!==currentUser?.uid||saved.actorRole!==currentUserRole||intent.orderId!==orderId
            ||JSON.stringify(saved.intent)!==JSON.stringify(intent))throw Error('invalid pending receipt');
        return {...saved,intent};
    }catch(_){throw Error('前次退貨收貨結果尚未確認，請保留暫存並使用原帳號與角色核對。');}
}
// This function never writes Firestore. The only writer is commitLocationReturn.
// Calling without input explicitly resumes the saved immutable intent.
async function receiveV2CustomerReturnEmulator(orderId,input){
    const {uid,role,functions,check}=v2CustomerReturnTransport();
    const key=v2CustomerReturnPendingKey(uid,orderId);
    let saved=pendingV2CustomerReturnReceipt(orderId);
    const proposed=input===undefined?null:normalizeV2CustomerReturnReceipt(input);
    if(proposed&&proposed.orderId!==orderId)throw Error('退貨來源訂單不一致。');
    if(saved){
        if(proposed&&JSON.stringify(proposed)!==JSON.stringify(saved.intent))
            throw Error('尚有未確認的退貨收貨，請使用原申請、出貨批次、數量、日期及操作編號確認。');
    }else{
        if(!proposed)throw Error('沒有待確認的退貨收貨。');
        const source=await db.collection('orders').doc(orderId).get({source:'server'});check();
        if(!source.exists)throw Error('找不到原始訂單。');
        const order=source.data(),request=(order.returnRequests||[]).find(r=>r.id===proposed.requestId);
        const concurrent=pendingV2CustomerReturnReceipt(orderId);
        if(concurrent&&JSON.stringify(concurrent.intent)!==JSON.stringify(proposed))
            throw Error('尚有未確認的退貨收貨，請先確認原操作。');
        if(!concurrent&&(order.inventoryReservationStatus!=='completed'||order.inventoryReservationAttemptId!==proposed.syncAttemptId
            ||!request||request.status!=='PENDING'||request.itemId!==proposed.itemId
            ||!(order.warehouseShipmentRecords||[]).some(r=>r.id===proposed.shipmentId
                &&r.itemId===proposed.itemId&&r.warehouseId===proposed.warehouseId)))
            throw Error('請重新確認原待收申請、實際出貨及原倉庫來源。');
        saved=concurrent||{actorUid:uid,actorRole:role,intent:proposed};
        const raw=JSON.stringify(saved);sessionStorage.setItem(key,raw);
        if(sessionStorage.getItem(key)!==raw)throw Error('無法保存退貨收貨意圖，尚未送出。');
    }
    check();functions.useEmulator('127.0.0.1',5001);
    const intent=saved.intent,response=await functions.httpsCallable('receiveV2CustomerReturn')(intent);check();
    const result=response?.data;
    if(!['applied','already-applied'].includes(result?.status)||result.orderId!==orderId
        ||result.itemId!==intent.itemId||result.shipmentId!==intent.shipmentId||result.warehouseId!==intent.warehouseId
        ||result.requestId!==intent.requestId||result.receiptId!==intent.operationId
        ||result.movementId!=='location-return-'+intent.operationId||result.settlement!=='CLOSE')
        throw Error('退貨收貨回覆無法核對，請保留原操作確認。');
    const receipt=await db.collection('customerReturnReceipts').doc(intent.operationId).get({source:'server'});check();
    const source=await db.collection('orders').doc(orderId).get({source:'server'});check();
    const proof=receipt.exists?receipt.data():null,order=source.exists?source.data():null,record=proof?.record;
    const qty=intent.selections.reduce((total,row)=>total+row.qty,0);
    const selections=record?.lotAllocations?.map(r=>({lotId:r.lotId,qty:r.qty})).sort((a,b)=>a.lotId.localeCompare(b.lotId));
    if(!proof||!order||result.qty!==qty||proof.orderId!==orderId||proof.requestId!==intent.requestId
        ||proof.itemId!==intent.itemId||proof.warehouseId!==intent.warehouseId||proof.qty!==qty
        ||proof.receivedBy!==uid||proof.receivedByRole!==role||proof.quality!=='SALEABLE'||proof.disposition!=='STOCK'
        ||proof.movementId!==result.movementId||!proof.intentHash||proof.intentHash!==record?.intentHash
        ||record?.id!==intent.operationId||record.orderId!==orderId||record.itemId!==intent.itemId
        ||record.shipmentId!==intent.shipmentId||record.requestId!==intent.requestId||record.warehouseId!==intent.warehouseId
        ||record.qty!==qty||record.date!==intent.date||record.reason!==intent.reason
        ||record.condition!==intent.condition||record.settlement!=='CLOSE'
        ||record.createdByUid!==uid||record.createdByRole!==role||record.movementId!==result.movementId
        ||JSON.stringify(selections)!==JSON.stringify(intent.selections)
        ||!(order.returnRequests||[]).some(r=>r.id===intent.requestId&&r.itemId===intent.itemId&&r.receivedQty>=qty)
        ||!(order.returnRecords||[]).some(r=>r.id===intent.operationId&&v2CustomerReturnProofEqual(r,record)))
        throw Error('退貨收貨已回覆，但原申請或實收憑證尚未核對，請以原操作再次確認。');
    // Do not erase a checkpoint replaced by another operation while awaiting reads.
    const remaining=sessionStorage.getItem(key);
    if(remaining!==null&&remaining!==JSON.stringify(saved))throw Error('退貨待確認資料已變更，請重新核對。');
    sessionStorage.removeItem(key);
    return {...order,id:orderId};
}
function v2CustomerReturnProofEqual(left,right){
    if(left===right)return true;
    if(!left||!right||typeof left!=='object'||typeof right!=='object'||Array.isArray(left)!==Array.isArray(right))return false;
    const a=Object.keys(left).sort(),b=Object.keys(right).sort();
    return JSON.stringify(a)===JSON.stringify(b)&&a.every(key=>v2CustomerReturnProofEqual(left[key],right[key]));
}
// The original receiving queue owns presentation; the receipt Service owns transmission.
let customerReturnReceiptView=null;
function customerReturnReceiptCurrent(view){
    if(!view||customerReturnReceiptView!==view||currentUser?.uid!==view.uid||currentUserRole!==view.role
        ||view.generation!==sessionDataGeneration||!canReceiveInventoryCapability())
        throw Error('登入身分或收貨畫面已變更，請重新開啟原操作。');
}
window.resetCustomerReturnReceiptView=function(){
    customerReturnReceiptView=null;
    document.getElementById('customerReturnReceiptOverlay')?.classList.remove('active');
    const body=document.getElementById('customerReturnReceiptBody');if(body)body.innerHTML='';
};
window.closeCustomerReturnReceipt=function(){
    if(customerReturnReceiptView?.busy)return;
    resetCustomerReturnReceiptView();
};
function customerReturnReceiptRecoveryHtml(){
    if(globalThis.YUSHIN_V2_RETURN_RECEIPT_EMULATOR!==true||!canReceiveInventoryCapability())return '';
    const prefix='v2-return-receipt:'+encodeURIComponent(currentUser?.uid||'')+':';
    try{
        const rows=[];
        for(let i=0;i<sessionStorage.length;i++){
            const key=sessionStorage.key(i);if(!key?.startsWith(prefix))continue;
            const orderId=decodeURIComponent(key.slice(prefix.length));
            try{
                const saved=pendingV2CustomerReturnReceipt(orderId);if(!saved)continue;
                rows.push(`<div class="inventory-return-card"><strong>退貨收貨結果待確認</strong><span>${escapeHtml(orderId)}｜${escapeHtml(saved.intent.date)}｜原申請 ${escapeHtml(saved.intent.requestId)}</span><button type="button" data-return-recovery="${escapeAttr(orderId)}" onclick="openCustomerReturnReceipt(${inlineJsValue(orderId)})">確認前次退貨收貨結果</button></div>`);
            }catch(error){rows.push(`<p role="alert">${escapeHtml(orderId)}：${escapeHtml(error.message)}</p>`);}
        }
        return rows.join('');
    }catch(error){return `<p role="alert">無法讀取退貨待確認資料：${escapeHtml(error.message)}；請保留原分頁並先核對，勿重新收貨。</p>`;}
}
function customerReturnReceiptQueueAction(order,request){
    if(globalThis.YUSHIN_V2_RETURN_RECEIPT_EMULATOR!==true)
        return '<span role="status">此出貨來源的退貨收貨尚未開放，申請保留待收。</span>';
    try{
        v2CustomerReturnTransport();
        if(pendingV2CustomerReturnReceipt(order.id))return '<span role="status">請先確認上方前次退貨收貨結果。</span>';
        return `<button type="button" onclick="receiveCustomerReturn(${inlineJsValue(order.id)},${inlineJsValue(request.id)},this)">確認退貨收貨</button>`;
    }catch(error){return `<span role="alert">${escapeHtml(error.message)}</span>`;}
}
window.openCustomerReturnReceipt=async function(orderId,requestId){
    let view;
    try{
        const {uid,role}=v2CustomerReturnTransport();
        if(customerReturnReceiptView?.busy)return;
        view={uid,role,generation:sessionDataGeneration,orderId,busy:false};customerReturnReceiptView=view;
        const pending=pendingV2CustomerReturnReceipt(orderId);
        if(pending){view.intent=pending.intent;renderCustomerReturnReceipt(view);return;}
        if(!requestId)throw Error('沒有待確認的退貨收貨。');
        const snap=await db.collection('orders').doc(orderId).get({source:'server'});customerReturnReceiptCurrent(view);
        if(!snap.exists)throw Error('找不到來源訂單。');
        view.order={...snap.data(),id:orderId};view.request=view.order.returnRequests?.find(r=>r.id===requestId);
        if(!view.request||view.request.status!=='PENDING')throw Error('退貨申請已撤回或完成，請重新載入。');
        view.projection=YushinFulfillment.projectOrderShipmentReturns({orderId,items:view.order.items,
            shipments:view.order.warehouseShipmentRecords||[],deliveries:view.order.deliveryRecords||[],returns:view.order.returnRecords||[]});
        view.shipments=view.projection.items.find(row=>row.itemId===view.request.itemId)?.shipments.filter(row=>row.confirmedQty>0)||[];
        if(!view.shipments.length)throw Error('此品項沒有已確認送達的出貨來源。');
        renderCustomerReturnReceipt(view);
    }catch(error){
        if(view&&customerReturnReceiptView!==view)return;
        if(view&&(view.uid!==currentUser?.uid||view.role!==currentUserRole||view.generation!==sessionDataGeneration))return;
        alert(error.message);
    }
};
function renderCustomerReturnReceipt(view){
    customerReturnReceiptCurrent(view);
    const body=document.getElementById('customerReturnReceiptBody'),pending=view.intent;
    if(pending){
        body.innerHTML=`<p>前次結果尚未確認，請以原資料核對。</p><p>訂單：${escapeHtml(pending.orderId)}<br>申請：${escapeHtml(pending.requestId)}<br>原出貨：${escapeHtml(pending.shipmentId)}<br>原倉：${escapeHtml(pending.warehouseId)}<br>日期：${escapeHtml(pending.date)}<br>原因：${escapeHtml(pending.reason)}</p><ul>${pending.selections.map(row=>`<li>批次 ${escapeHtml(row.lotId)}：${row.qty}</li>`).join('')}</ul>`;
    }else{
        body.innerHTML=`<p>${escapeHtml(view.order.customerName||view.order.orderNo||view.orderId)}｜申請 ${view.request.qty}／已收 ${view.request.receivedQty||0}</p><label for="customerReturnReceiptShipment">原出貨紀錄（收到原出貨倉）</label><select id="customerReturnReceiptShipment" onchange="changeCustomerReturnReceiptShipment()"><option value="">請選擇實際退回的出貨來源</option>${view.shipments.map(row=>{const source=view.order.warehouseShipmentRecords.find(s=>s.id===row.shipmentId);return `<option value="${escapeAttr(row.shipmentId)}">${escapeHtml(source.date)}｜${escapeHtml(source.warehouseId)}｜${escapeHtml(row.shipmentId)}</option>`;}).join('')}</select><div id="customerReturnReceiptLots"></div><label for="customerReturnReceiptDate">實收日期</label><input id="customerReturnReceiptDate" type="date" value="${escapeAttr(localDateString())}"><label for="customerReturnReceiptReason">退貨原因</label><textarea id="customerReturnReceiptReason" maxlength="1000">${escapeHtml(view.request.reason||'訂錯貨，退貨結案')}</textarea><label><input id="customerReturnReceiptSaleable" type="checkbox">已確認可再銷售，入庫後結案，不自動補送</label>`;
    }
    document.getElementById('customerReturnReceiptStatus').textContent='';
    const button=document.getElementById('customerReturnReceiptSave');button.disabled=false;button.textContent=pending?'確認前次退貨收貨結果':'確認實收並入庫';
    document.getElementById('customerReturnReceiptOverlay').classList.add('active');
}
window.changeCustomerReturnReceiptShipment=function(){
    const view=customerReturnReceiptView;
    try{
        customerReturnReceiptCurrent(view);if(view.busy||view.intent)return;
        const id=document.getElementById('customerReturnReceiptShipment').value;
        view.shipment=view.order.warehouseShipmentRecords.find(row=>row.id===id&&row.itemId===view.request.itemId);
        view.lots=view.shipment?YushinInventory.availableReturnAllocations([view.shipment],(view.order.returnRecords||[]).filter(row=>row.shipmentId===id)).filter(row=>row.qty>0):[];
        document.getElementById('customerReturnReceiptLots').innerHTML=view.lots.map((row,index)=>`<div class="inventory-return-card"><label for="customerReturnReceiptLot${index}">批號 ${escapeHtml(row.lotNo||row.lotId)}｜效期 ${escapeHtml(row.expiryDate||'未填')}｜原批次餘額 ${row.qty}</label><input id="customerReturnReceiptLot${index}" type="number" min="0" max="${row.qty}" step="1" value="0" aria-label="${escapeAttr('批號 '+(row.lotNo||row.lotId)+' 本次實收數量')}"></div>`).join('')||(view.shipment?'<p>此出貨沒有可退回的原批次。</p>':'');
    }catch(error){document.getElementById('customerReturnReceiptStatus').textContent=error.message;}
};
window.saveCustomerReturnReceipt=async function(){
    const view=customerReturnReceiptView;if(!view||view.busy||view.confirmed)return;
    const status=document.getElementById('customerReturnReceiptStatus'),button=document.getElementById('customerReturnReceiptSave');
    try{
        customerReturnReceiptCurrent(view);
        if(!view.intent){
            if(!view.shipment||!document.getElementById('customerReturnReceiptSaleable').checked)throw Error('請選擇原出貨及批次，並確認商品可再銷售。');
            const selections=(view.lots||[]).map((row,i)=>({lotId:row.lotId,qty:Number(document.getElementById('customerReturnReceiptLot'+i).value)}));
            if(selections.some(row=>!Number.isSafeInteger(row.qty)||row.qty<0))throw Error('實收數量須為非負整數。');
            const selected=selections.filter(row=>row.qty>0);
            const part=view.shipments.find(row=>row.shipmentId===view.shipment.id);
            const plan=YushinInventory.planExplicitShipmentReturn({shipment:view.shipment,confirmedQty:part.confirmedQty,selections:selected,
                priorReturns:(view.order.returnRecords||[]).filter(row=>row.shipmentId===view.shipment.id)});
            if(plan.returnQty>view.request.qty-Number(view.request.receivedQty||0))throw Error('本次實收數量超過申請待收量。');
            const intent=normalizeV2CustomerReturnReceipt({orderId:view.orderId,itemId:view.request.itemId,requestId:view.request.id,
                shipmentId:view.shipment.id,warehouseId:view.shipment.warehouseId,syncAttemptId:view.order.inventoryReservationAttemptId,
                selections:selected,operationId:lifecycleRecordId(),date:document.getElementById('customerReturnReceiptDate').value,
                reason:document.getElementById('customerReturnReceiptReason').value,condition:'RESTOCKABLE',settlement:'CLOSE'});
            // Freeze the visible form too; the Service persists before sending.
            view.intent=intent;renderCustomerReturnReceipt(view);
        }
        view.busy=true;button.disabled=true;status.textContent='正在確認退貨收貨…';
        const saved=await receiveV2CustomerReturnEmulator(view.orderId,view.intent);customerReturnReceiptCurrent(view);
        view.confirmed=true;
        // The receipt has been confirmed; refresh failures cannot turn it into an unknown commit.
        status.textContent='退貨已實收並入庫，不補送。';
        const item=saved.items.find(row=>row.itemId===view.intent.itemId);
        invalidateWarehouseStockCache(item.inventoryProductKey||item.productId,view.intent.warehouseId);markMainPageDirty('inventory','orders.list','orders.po','admin');
        try{
            await refreshAffectedOrderCaches([saved.id]);customerReturnReceiptCurrent(view);
            await loadCustomerReturnQueue();customerReturnReceiptCurrent(view);
            view.busy=false;closeCustomerReturnReceipt();showActionFeedback('退貨已實收並入庫，不補送。','success');
        }catch(refreshError){
            customerReturnReceiptCurrent(view);view.confirmed=true;
            status.textContent='退貨已實收並入庫；清單更新失敗，請關閉後重新開啟倉庫頁。';
        }
    }catch(error){
        if(customerReturnReceiptView!==view||view.uid!==currentUser?.uid||view.role!==currentUserRole||view.generation!==sessionDataGeneration)return;
        status.textContent=view.confirmed?'退貨已實收並入庫；畫面更新失敗，請關閉後重新開啟倉庫頁。':error.message+'；若結果尚未確認，請使用原資料再次確認。';
    }finally{
        if(customerReturnReceiptView===view){view.busy=false;button.disabled=!!view.confirmed;
            button.textContent=view.intent?'確認前次退貨收貨結果':'確認實收並入庫';}
    }
};
// Only the isolated demo Auth/Functions/Firestore Emulator can submit v2 shipments.
function pendingV2WarehouseShipment(orderId,itemId){
 if(globalThis.YUSHIN_V2_SHIPMENT_EMULATOR!==true)return null;
 const key='v2-shipment:'+encodeURIComponent(currentUser?.uid||'')+':'+encodeURIComponent(orderId)+':'+encodeURIComponent(itemId);
 const stored=sessionStorage.getItem(key);
 if(!stored)return null;
 try{
  const pending=JSON.parse(stored);
  if(pending.orderId!==orderId||pending.itemId!==itemId||pending.actorUid!==currentUser?.uid||pending.actorRole!==currentUserRole)throw Error('actor');
  return pending;
 }catch(_){throw Error('上次出貨尚未確認，請使用原帳號核對出貨識別資料。');}
}
async function commitV2WarehouseShipmentEmulator(input){
 const local=s=>s==='localhost'||s==='127.0.0.1';
 if(!local(globalThis.location?.hostname)||typeof firebase==='undefined'||!firebase.auth||!firebase.functions)
  throw Error('v2 出貨僅限本機 Emulator。');
 const auth=firebase.auth(),fn=firebase.app().functions('asia-east1'),uid=currentUser?.uid,role=currentUserRole;
 if(auth.app?.options?.projectId!=='demo-yushin'||fn.app?.options?.projectId!=='demo-yushin'
  ||!local(auth.emulatorConfig?.host)||auth.emulatorConfig?.port!==9099)
  throw Error('v2 出貨必須使用本機 demo-yushin 的 Auth 與 Functions。');
 const same=()=>{
  if(!uid||currentUser?.uid!==uid||currentUserRole!==role||auth.currentUser?.uid!==uid
    ||!canReceiveInventoryCapability()||!canAccessPage('inventory'))throw Error('登入帳號或權限已變更。');
 };
 same();
 const {orderId,itemId,qty,date,notes,operationId,expectedWarehouseId,expectedPlan}=input;
 if(!/^[-_a-zA-Z0-9]{12,96}$/.test(operationId||'')||!Number.isSafeInteger(qty)||qty<=0||!expectedWarehouseId
  ||typeof notes!=='string'||notes.length>1000||typeof date!=='string'
  ||!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date+'T00:00:00Z'))
  ||new Date(date+'T00:00:00Z').toISOString().slice(0,10)!==date)
  throw Error('v2 出貨識別碼、倉庫或數量不正確。');
 const plan=globalThis.YushinWarehouseLogistics.validatePlan(expectedPlan,true);
 if(plan.mode!=='CUSTOMER_SHIP')throw Error('v2 出貨目前僅支援直接寄客戶。');
 const key='v2-shipment:'+encodeURIComponent(uid)+':'+encodeURIComponent(orderId)+':'+encodeURIComponent(itemId);
 let pending=pendingV2WarehouseShipment(orderId,itemId);
 if(pending&&pending.operationId!==operationId)throw Error('前次出貨結果尚未確認，必須先重試原識別碼。');
 if(!pending){
  const doc=await db.collection('orders').doc(orderId).get();same();
  const order=doc.exists?doc.data():null;
  if(!order||order.inventoryReservationStatus!=='completed'||!order.inventoryReservationAttemptId
    ||!order.items?.some(x=>x.itemId===itemId))throw Error('來源訂單尚未完成 v2 同步。');
  pending={orderId,itemId,warehouseId:expectedWarehouseId,quantity:qty,date,notes,operationId,
   syncAttemptId:order.inventoryReservationAttemptId,expectedPlan:plan,actorUid:uid,actorRole:role};
  sessionStorage.setItem(key,JSON.stringify(pending));
 }else if(pending.quantity!==qty||pending.warehouseId!==expectedWarehouseId||pending.date!==date
   ||pending.notes!==notes||JSON.stringify(pending.expectedPlan)!==JSON.stringify(plan))
  throw Error('原出貨數量、倉庫及收件資訊已凍結，不得改變重送。');
 same();fn.useEmulator('127.0.0.1',5001);
 const {actorUid,actorRole,...request}=pending;
 const response=await fn.httpsCallable('shipV2WarehouseItem')(request);same();
 const data=response?.data;
 if(!['applied','already-applied'].includes(data?.status)||data.orderId!==orderId||data.itemId!==itemId
  ||data.warehouseId!==pending.warehouseId||data.qty!==pending.quantity||data.movementId!=='location-ship-'+operationId)
  throw Error('出貨回覆無法確認，保留原識別碼核對結果。');
 const refreshed=await db.collection('orders').doc(orderId).get();same();
 if(!refreshed.exists)throw Error('出貨已回覆，但訂單回讀失敗。');
 sessionStorage.removeItem(key);
 return refreshed.data();
}
// Warehouse shipment transaction service; single and batch UI share this entry.
async function commitInventoryShipment({orderId,itemId,qty,date,notes='',operationId,expectedWarehouseId='',expectedPlan=null}){
  if(globalThis.YUSHIN_V2_SHIPMENT_EMULATOR===true)return commitV2WarehouseShipmentEmulator({orderId,itemId,qty,date,notes,operationId,expectedWarehouseId,expectedPlan});
  if(!canReceiveInventoryCapability()||!canAccessPage('inventory'))throw new Error('無倉庫出貨權限。');
  if(typeof operationId!=='string'||!operationId.trim()||!Number.isFinite(qty)||qty<=0)throw new Error('出貨數量或操作識別碼不正確。');
  if(typeof date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date+'T00:00:00Z'))||new Date(date+'T00:00:00Z').toISOString().slice(0,10)!==date)throw new Error('請填寫有效的出貨日期。');
  const actor=deliveryActor(),actorUid=currentUser.uid,now=new Date().toISOString();
  let saved;
  await runRoleTransaction(async tx=>{
    const ref=db.collection('orders').doc(orderId),snapshot=await tx.get(ref);
    if(!snapshot.exists)throw new Error('找不到訂單。');
    const order=snapshot.data(),records=savedDeliveryRecords(order);
    const prior=records.find(r=>r.id===operationId);
    if(prior){
      if(prior.sourceType!=='INVENTORY_SHIPMENT'||prior.itemId!==itemId||Number(prior.qty)!==qty||prior.date!==date||String(prior.notes||'')!==notes
        ||(expectedWarehouseId&&prior.warehouseId!==expectedWarehouseId)
        ||(expectedPlan&&JSON.stringify(globalThis.YushinWarehouseLogistics.plan(prior.deliveryPlan||{}))!==JSON.stringify(expectedPlan)))
        throw new Error('出貨操作識別碼衝突。');
      saved=order;return;
    }
    if(deliveryRecordWasReversed(order,operationId)||order.inventoryShipmentRecordId===operationId)
      throw new Error('這筆出貨已更正撤銷，請重新核對後建立新的出貨作業。');
    if(normalizedOrderStatus(order)!=='normal'||orderInventorySyncIncomplete(order))throw new Error('訂單已取消或庫存尚未同步。');
    if(!Array.isArray(order.items))throw new Error('舊版訂單須先完成品項整理，才能由倉庫出貨。');
    const item=normalizedOrderItems(order).find(i=>i.itemId===itemId);
    if(item?.transferPendingId)throw new Error('此品項尚在調撥途中。');
    const plan=item?.deliveryPlan||order.shippingInstructions;
    if(plan&&plan.mode!=='CUSTOMER_SHIP')throw new Error('交付方式已變更，請重新確認。');
    if(plan)globalThis.YushinWarehouseLogistics.validatePlan(plan,true);
    if(!item||(item.fulfillmentType||'WAREHOUSE')==='DIRECT_SHIP')throw new Error('此品項不屬於倉庫出貨。');
    const state=assertOrderDeliveryIncrease(order,item,qty);
    const warehouseId=item.warehouseId||order.warehouseId||defaultWarehouse()?.id||'';
    if(!warehouseMasterCache.some(w=>w.id===warehouseId&&w.active!==false))throw new Error('出貨倉庫不存在或已停用。');
    if(expectedWarehouseId&&warehouseId!==expectedWarehouseId)throw new Error('出貨倉庫已變更，請重新核對。');
    if(expectedPlan&&JSON.stringify(globalThis.YushinWarehouseLogistics.plan(plan||{}))!==JSON.stringify(expectedPlan))throw new Error('寄送資訊已變更，請重新核對。');
    const result=await applyInventoryDeliveryDeltaInTransaction(tx,{...order,...item,itemId,warehouseId,isDelivered:false,requireStockReservation:true},qty,actor,orderId);
    const record={id:operationId,orderId,itemId,productKey:inventoryProductKey(item),itemIndex:order.items.findIndex(i=>i.itemId===itemId),warehouseId,date,qty,notes,...(plan?{deliveryPlan:globalThis.YushinWarehouseLogistics.plan(plan)}:{}),sourceType:'INVENTORY_SHIPMENT',createdBy:actor,createdByUid:actorUid,createdAt:now,movementId:result.movementId,lotAllocations:result.lotAllocations||[],cogs:0};
    const nextRecords=[...records,record],totalDelivered=nextRecords.reduce((sum,r)=>sum+Number(r.qty||0),0);
    const effectiveDelivered=orderDeliveryProjection({...order,deliveryRecords:nextRecords,isDelivered:false}).effectiveDelivered;
    const nextItems=order.items.map(i=>i.itemId===itemId?{...i,reservedQty:result.newReservedQty,warehouseShippedQty:state.grossDelivered+qty}:i);
    const history={action:'create',source:'inventory',recordId:operationId,before:null,after:record,by:actor,at:now};
    const updates={inventoryShipmentRecordId:operationId,items:nextItems,deliveryRecords:nextRecords,deliveredQty:totalDelivered,isDelivered:effectiveDelivered>=orderQuantity(order),deliveryHistory:firebase.firestore.FieldValue.arrayUnion(history),updatedAt:now};
    Object.assign(updates,orderWorkIndexFields({...order,...updates}));tx.update(ref,updates);saved={...order,...updates,deliveryHistory:[...(order.deliveryHistory||[]),history]};
  });
  return saved;
}
// Transfer dispatch and receipt are separate physical events, not customer deliveries.
